  (md5('answer:pharmacy-exam-prep:1:7:4')::uuid, md5('question:pharmacy-exam-prep:1:7')::uuid, 4, 'Advise that the buprenorphine patch can be added in any strength based on the patient''s chronic pain condition.', false),
