  (md5('answer:pharmacy-exam-prep:1:45:2')::uuid, md5('question:pharmacy-exam-prep:1:45')::uuid, 2, 'Empagliflozin', true),
  (md5('answer:pharmacy-exam-prep:1:45:3')::uuid, md5('question:pharmacy-exam-prep:1:45')::uuid, 3, 'Metformin', false),
  (md5('answer:pharmacy-exam-prep:1:45:4')::uuid, md5('question:pharmacy-exam-prep:1:45')::uuid, 4, 'Gliclazide', false),
  (md5('answer:pharmacy-exam-prep:1:45:5')::uuid, md5('question:pharmacy-exam-prep:1:45')::uuid, 5, 'Pioglitazone', false),
  (md5('answer:pharmacy-exam-prep:1:46:1')::uuid, md5('question:pharmacy-exam-prep:1:46')::uuid, 1, 'To prevent a sudden surge of calcium in the blood due to a reduction in bone resorption', false),
  (md5('answer:pharmacy-exam-prep:1:46:2')::uuid, md5('question:pharmacy-exam-prep:1:46')::uuid, 2, 'To prevent the occurrence of the patient''s GCA symptoms', false),
  (md5('answer:pharmacy-exam-prep:1:46:3')::uuid, md5('question:pharmacy-exam-prep:1:46')::uuid, 3, 'To prevent the development of Conn''s syndrome', false),
  (md5('answer:pharmacy-exam-prep:1:46:4')::uuid, md5('question:pharmacy-exam-prep:1:46')::uuid, 4, 'To prevent a sudden hypotensive event', true),
  (md5('answer:pharmacy-exam-prep:1:46:5')::uuid, md5('question:pharmacy-exam-prep:1:46')::uuid, 5, 'To prevent amaurosis fugax from occurring', false),
  (md5('answer:pharmacy-exam-prep:1:47:1')::uuid, md5('question:pharmacy-exam-prep:1:47')::uuid, 1, 'Suspect a diagnosis of constipation if an adult''s bowel movements occur less than once a week', false),
  (md5('answer:pharmacy-exam-prep:1:47:2')::uuid, md5('question:pharmacy-exam-prep:1:47')::uuid, 2, 'Suspect a diagnosis of constipation if an adult''s bowel movements occur less than twice a week', false),
  (md5('answer:pharmacy-exam-prep:1:47:3')::uuid, md5('question:pharmacy-exam-prep:1:47')::uuid, 3, 'Suspect a diagnosis of constipation if an adult''s bowel movements occur less than three times a week', true),
  (md5('answer:pharmacy-exam-prep:1:47:4')::uuid, md5('question:pharmacy-exam-prep:1:47')::uuid, 4, 'Suspect a diagnosis of constipation if an adult''s bowel movements occur less than four times a week', false),
  (md5('answer:pharmacy-exam-prep:1:47:5')::uuid, md5('question:pharmacy-exam-prep:1:47')::uuid, 5, 'Suspect a diagnosis of constipation if an adult''s bowel movements occur less than five times a week', false),
  (md5('answer:pharmacy-exam-prep:1:48:1')::uuid, md5('question:pharmacy-exam-prep:1:48')::uuid, 1, '0-30 minutes', false),
  (md5('answer:pharmacy-exam-prep:1:48:2')::uuid, md5('question:pharmacy-exam-prep:1:48')::uuid, 2, '3-6 hours', false),
  (md5('answer:pharmacy-exam-prep:1:48:3')::uuid, md5('question:pharmacy-exam-prep:1:48')::uuid, 3, '6-12 hours', true),
  (md5('answer:pharmacy-exam-prep:1:48:4')::uuid, md5('question:pharmacy-exam-prep:1:48')::uuid, 4, '12-48 hours', false),
  (md5('answer:pharmacy-exam-prep:1:48:5')::uuid, md5('question:pharmacy-exam-prep:1:48')::uuid, 5, 'up to 72 hours', false),
  (md5('answer:pharmacy-exam-prep:1:49:1')::uuid, md5('question:pharmacy-exam-prep:1:49')::uuid, 1, 'Bulk-forming', false),
  (md5('answer:pharmacy-exam-prep:1:49:2')::uuid, md5('question:pharmacy-exam-prep:1:49')::uuid, 2, 'Osmotic', false),
  (md5('answer:pharmacy-exam-prep:1:49:3')::uuid, md5('question:pharmacy-exam-prep:1:49')::uuid, 3, 'Stool softener', true),
  (md5('answer:pharmacy-exam-prep:1:49:4')::uuid, md5('question:pharmacy-exam-prep:1:49')::uuid, 4, 'Stimulating', false),
  (md5('answer:pharmacy-exam-prep:1:49:5')::uuid, md5('question:pharmacy-exam-prep:1:49')::uuid, 5, 'Lubricating', false),
  (md5('answer:pharmacy-exam-prep:1:50:1')::uuid, md5('question:pharmacy-exam-prep:1:50')::uuid, 1, 'Omeprazole + clarithromycin + metronidazole', true),
  (md5('answer:pharmacy-exam-prep:1:50:2')::uuid, md5('question:pharmacy-exam-prep:1:50')::uuid, 2, 'Omeprazole + bismuth subsalicylate + metronidazole + tetracycline', false),
  (md5('answer:pharmacy-exam-prep:1:50:3')::uuid, md5('question:pharmacy-exam-prep:1:50')::uuid, 3, 'Omeprazole + Amoxicillin + Clarithromycin', false),
  (md5('answer:pharmacy-exam-prep:1:50:4')::uuid, md5('question:pharmacy-exam-prep:1:50')::uuid, 4, 'Omeprazole + erythromycin + levofloxacin', false),
  (md5('answer:pharmacy-exam-prep:1:50:5')::uuid, md5('question:pharmacy-exam-prep:1:50')::uuid, 5, 'Omeprazole + bismuth subsalicylate + rifabutin', false),
  (md5('answer:pharmacy-exam-prep:1:51:1')::uuid, md5('question:pharmacy-exam-prep:1:51')::uuid, 1, 'Docusate works by increasing water absorption of the stools from the intestinal lumen', false),
  (md5('answer:pharmacy-exam-prep:1:51:2')::uuid, md5('question:pharmacy-exam-prep:1:51')::uuid, 2, 'Docusate works by increasing peristalsis', false),
  (md5('answer:pharmacy-exam-prep:1:51:3')::uuid, md5('question:pharmacy-exam-prep:1:51')::uuid, 3, 'Docusate works by increasing faecal mass', false),
  (md5('answer:pharmacy-exam-prep:1:51:4')::uuid, md5('question:pharmacy-exam-prep:1:51')::uuid, 4, 'Docusate works by softening the faecal matter', true),
  (md5('answer:pharmacy-exam-prep:1:51:5')::uuid, md5('question:pharmacy-exam-prep:1:51')::uuid, 5, 'Docusate coats the colon to prevent the absorption of water from the faecal matter', false),
  (md5('answer:pharmacy-exam-prep:1:52:1')::uuid, md5('question:pharmacy-exam-prep:1:52')::uuid, 1, 'Apixaban', false),
  (md5('answer:pharmacy-exam-prep:1:52:2')::uuid, md5('question:pharmacy-exam-prep:1:52')::uuid, 2, 'Verapamil', true),
  (md5('answer:pharmacy-exam-prep:1:52:3')::uuid, md5('question:pharmacy-exam-prep:1:52')::uuid, 3, 'Amlodipine', false),
  (md5('answer:pharmacy-exam-prep:1:52:4')::uuid, md5('question:pharmacy-exam-prep:1:52')::uuid, 4, 'Ramipril', false),
  (md5('answer:pharmacy-exam-prep:1:52:5')::uuid, md5('question:pharmacy-exam-prep:1:52')::uuid, 5, 'Digoxin', false),
  (md5('answer:pharmacy-exam-prep:1:53:1')::uuid, md5('question:pharmacy-exam-prep:1:53')::uuid, 1, '3 days', false),
  (md5('answer:pharmacy-exam-prep:1:53:2')::uuid, md5('question:pharmacy-exam-prep:1:53')::uuid, 2, '5 days', false),
  (md5('answer:pharmacy-exam-prep:1:53:3')::uuid, md5('question:pharmacy-exam-prep:1:53')::uuid, 3, '7 days', false),
  (md5('answer:pharmacy-exam-prep:1:53:4')::uuid, md5('question:pharmacy-exam-prep:1:53')::uuid, 4, '14 days', true),
  (md5('answer:pharmacy-exam-prep:1:53:5')::uuid, md5('question:pharmacy-exam-prep:1:53')::uuid, 5, '30 days', false),
  (md5('answer:pharmacy-exam-prep:1:54:1')::uuid, md5('question:pharmacy-exam-prep:1:54')::uuid, 1, 'The patient must lie flat on their back on the bed with their head hanging off whilst allowing the spray to leak into each nostril', false),
  (md5('answer:pharmacy-exam-prep:1:54:2')::uuid, md5('question:pharmacy-exam-prep:1:54')::uuid, 2, 'Look up while spraying the nasal spray into your nostrils to prevent the liquid from flowing out of your nostrils', false),
  (md5('answer:pharmacy-exam-prep:1:54:3')::uuid, md5('question:pharmacy-exam-prep:1:54')::uuid, 3, 'Look down and spray the nasal spray into each nostril in turn while keeping the other nostril shut with your finger', true),
  (md5('answer:pharmacy-exam-prep:1:54:4')::uuid, md5('question:pharmacy-exam-prep:1:54')::uuid, 4, 'Blow hard through each nostril after spraying the nasal spray in order to prevent accumulation of nasal spray liquid in your nostrils', false),
  (md5('answer:pharmacy-exam-prep:1:54:5')::uuid, md5('question:pharmacy-exam-prep:1:54')::uuid, 5, 'Never breathe in while squirting the nasal spray in through your nostril as this may result in accidental inhalation into the lungs', false),
  (md5('answer:pharmacy-exam-prep:1:55:1')::uuid, md5('question:pharmacy-exam-prep:1:55')::uuid, 1, 'Mebendazole is suitable for all family members over the age of 1 year', true),
  (md5('answer:pharmacy-exam-prep:1:55:2')::uuid, md5('question:pharmacy-exam-prep:1:55')::uuid, 2, 'Mebendazole is not suitable OTC for pregnant women', false),
  (md5('answer:pharmacy-exam-prep:1:55:3')::uuid, md5('question:pharmacy-exam-prep:1:55')::uuid, 3, 'Everyone in the family must be treated with mebendazole regardless of if they have symptoms', false),
  (md5('answer:pharmacy-exam-prep:1:55:4')::uuid, md5('question:pharmacy-exam-prep:1:55')::uuid, 4, 'If you are re-infected then re-treatment may take place after 14 days of initial treatment.', false),
  (md5('answer:pharmacy-exam-prep:1:55:5')::uuid, md5('question:pharmacy-exam-prep:1:55')::uuid, 5, 'Mebendazole is used to treat threadworm', false)
insert into public.chapters (id, course_id, position, title) values
  (md5('chapter:pharmacy-exam-prep:2')::uuid, md5('course:pharmacy-exam-prep')::uuid, 2, 'Cardiovascular System')
insert into public.quizzes (id, chapter_id, title, position, is_preview) values
  (md5('quiz:pharmacy-exam-prep:2')::uuid, md5('chapter:pharmacy-exam-prep:2')::uuid, 'Cardiovascular System', 1, false)
insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('question:pharmacy-exam-prep:2:1')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 1, 'Which drug is a first-line treatment for chronic heart failure?', 'Bisoprolol, a beta-blocker, is recommended as a first-line treatment for chronic heart failure.', null),
  (md5('question:pharmacy-exam-prep:2:2')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 2, 'Which antiarrhythmic is contraindicated in patients with asthma?', 'Propranolol, a non-selective beta-blocker, can exacerbate asthma and is contraindicated.', null),
  (md5('question:pharmacy-exam-prep:2:3')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 3, 'What is the primary side effect of digoxin toxicity?', 'Bradycardia is a primary side effect of digoxin toxicity.', null),
  (md5('question:pharmacy-exam-prep:2:4')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 4, 'Which antihypertensive is safe to use in pregnancy?', 'Methyldopa is considered safe in pregnancy, unlike ACE inhibitors or ARBs.', null),
  (md5('question:pharmacy-exam-prep:2:5')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 5, 'Which medication is indicated for rate control in atrial fibrillation?', 'Diltiazem is used for rate control in atrial fibrillation.', null),
  (md5('question:pharmacy-exam-prep:2:6')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 6, 'In the treatment of acute coronary syndrome, which drug is not typically used?', 'Phenytoin, an antiepileptic, is not used in the treatment of acute coronary syndrome.', null),
  (md5('question:pharmacy-exam-prep:2:7')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 7, 'A 67 year old patient has been prescribed ramipril by his GP. What is the main adverse effect of ACE inhibitors like ramipril?', 'Cough is a common adverse effect of ACE inhibitors.', null),
  (md5('question:pharmacy-exam-prep:2:8')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 8, 'Which statin has the least likelihood of causing muscle pain?', 'Pravastatin is generally associated with a lower risk of myopathy.', null),
  (md5('question:pharmacy-exam-prep:2:9')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 9, 'For a patient with a sulfa allergy, which diuretic should be avoided?', 'Bumetanide, a sulfonamide diuretic, should be avoided in patients with sulfa allergies.', null),
  (md5('question:pharmacy-exam-prep:2:10')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 10, 'What is a common side effect of calcium channel blockers like amlodipine?', 'Peripheral edema is a common side effect of amlodipine.', null),
  (md5('question:pharmacy-exam-prep:2:11')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 11, 'Which drug is not typically used for hypertension?', 'Nitroglycerin is primarily used for angina, not hypertension.', null),
  (md5('question:pharmacy-exam-prep:2:12')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 12, 'What is the major concern with the use of clopidogrel in cardiac patients?', 'Clopidogrel increases the risk of bleeding.', null),
  (md5('question:pharmacy-exam-prep:2:13')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 13, 'Which medication is an anticoagulant used for stroke prevention in non-valvular atrial fibrillation?', 'Apixaban is an anticoagulant indicated for stroke prevention in atrial fibrillation.', null),
  (md5('question:pharmacy-exam-prep:2:14')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 14, 'In treating angina, what is the mechanism of action of nitrates like nitroglycerin?', 'Nitrates decrease myocardial oxygen demand by dilating veins and reducing preload.', null),
  (md5('question:pharmacy-exam-prep:2:15')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 15, 'What is the primary reason for combining a beta-blocker with a diuretic in hypertension?', 'Combining these drugs improves blood pressure control.', null),
  (md5('question:pharmacy-exam-prep:2:16')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 16, 'Which drug is a direct thrombin inhibitor used in anticoagulation?', 'Dabigatran is a direct thrombin inhibitor.', null),
  (md5('question:pharmacy-exam-prep:2:17')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 17, 'For a patient with heart failure and renal impairment, which diuretic is preferred?', 'Torsemide is preferred in heart failure with renal impairment due to its better bioavailability.', null),
  (md5('question:pharmacy-exam-prep:2:18')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 18, 'What is a major side effect of beta-blockers like metoprolol in diabetes?', 'Hypoglycemia and masking of its symptoms are concerns with beta-blockers in diabetes.', null),
  (md5('question:pharmacy-exam-prep:2:19')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 19, 'Which is a common side effect of loop diuretics like furosemide?', 'Hypokalemia is a common side effect of loop diuretics. Other drugs, such as Spironolactone are potassium sparing and avoid this issue.', null),
  (md5('question:pharmacy-exam-prep:2:20')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 20, 'What is the primary benefit of using beta-blockers post-myocardial infarction?', 'Beta-blockers reduce mortality post-myocardial infarction.', null),
  (md5('question:pharmacy-exam-prep:2:21')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 21, 'Which drug increases the risk of hyperkalemia when used with ACE inhibitors?', 'Spironolactone can increase the risk of hyperkalemia, especially when used with ACE inhibitors.', null),
  (md5('question:pharmacy-exam-prep:2:22')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 22, 'A patient presents to you in the pharmacy stating that the medication she uses to manage her blood pressure is giving her ankle swelling. Which class of drugs does the patient''s medication belong to?', 'Calcium channel blockers, especially amlodipine, can cause ankle swelling.', null),
  (md5('question:pharmacy-exam-prep:2:23')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 23, 'What is the mechanism of action of warfarin?', 'Warfarin inhibits vitamin K-dependent clotting factors II, VII, IX, and X.', null),
  (md5('question:pharmacy-exam-prep:2:24')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 24, 'Which is not an indication for beta-blockers?', 'Asthma is a contraindication for beta-blockers due to the risk of bronchospasm.', null),
  (md5('question:pharmacy-exam-prep:2:25')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 25, 'Which drug should be avoided in patients taking simvastatin at high doses?', 'Grapefruit juice can increase the risk of myopathy when used with high doses of simvastatin.', null),
  (md5('question:pharmacy-exam-prep:2:26')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 26, 'Which of the following is an indication to use ivabradine?', 'Ivabradine is primarily indicated for chronic heart failure.', null),
  (md5('question:pharmacy-exam-prep:2:27')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 27, 'What is the mechanism of action of nitroglycerin in angina?', 'Nitroglycerin reduces venous return, decreasing myocardial oxygen demand.', null),
  (md5('question:pharmacy-exam-prep:2:28')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 28, 'In lipid management, what is the primary function of ezetimibe?', 'Ezetimibe lowers LDL cholesterol by inhibiting intestinal absorption of cholesterol.', null),
  (md5('question:pharmacy-exam-prep:2:29')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 29, 'What is a major adverse effect of clopidogrel and aspirin combination therapy?', 'The combination of clopidogrel and aspirin increases the bleeding risk.', null),
  (md5('question:pharmacy-exam-prep:2:30')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 30, 'Which drug is not a calcium channel blocker?', 'Ramipril is an ACE inhibitor, not a calcium channel blocker.', null),
  (md5('question:pharmacy-exam-prep:2:31')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 31, 'What is a common adverse effect of loop diuretics like furosemide in the elderly?', 'Dehydration is a common adverse effect of loop diuretics, especially in the elderly.', null),
  (md5('question:pharmacy-exam-prep:2:32')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 32, 'Which medication is an appropriate initial treatment for Raynaud''s phenomenon?', 'Amlodipine, a calcium channel blocker, is effective in treating Raynaud''s phenomenon.', null),
  (md5('question:pharmacy-exam-prep:2:33')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 33, 'Which beta-blocker is preferred in patients with chronic obstructive pulmonary disease (COPD)?', 'Metoprolol, a selective beta-1 blocker, is preferred in patients with COPD.', null),
  (md5('question:pharmacy-exam-prep:2:34')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 34, 'What is the major side effect of angiotensin receptor blockers (ARBs) like losartan?', 'ARBs can cause hypotension, particularly after the first dose.', null),
  (md5('question:pharmacy-exam-prep:2:35')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 35, 'Which medication is primarily used to prevent stroke in patients with atrial fibrillation?', 'Edoxaban is an anticoagulant used to prevent stroke in atrial fibrillation.', null),
  (md5('question:pharmacy-exam-prep:2:36')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 36, 'What is a risk associated with the use of non-dihydropyridine calcium channel blockers like verapamil in heart failure?', 'Non-dihydropyridine calcium channel blockers can worsen heart failure.', null),
  (md5('question:pharmacy-exam-prep:2:37')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 37, 'Which drug is used as a rate control agent in atrial fibrillation and can also cause thyroid dysfunction?', 'Amiodarone can be used for rate control in atrial fibrillation and may cause thyroid dysfunction.', null),
  (md5('question:pharmacy-exam-prep:2:38')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 38, 'What is a potential side effect of high-dose statins?', 'Myopathy is a potential side effect of high-dose statins.', null),
  (md5('question:pharmacy-exam-prep:2:39')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 39, 'Which antihypertensive medication is known to cause a dry, hacking cough?', 'Enalapril, an ACE inhibitor, can cause a dry, hacking cough.', null),
  (md5('question:pharmacy-exam-prep:2:40')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 40, 'Which medication is used for its anti-platelet properties in ischemic heart disease?', 'Aspirin has anti-platelet properties and is used in ischemic heart disease.', null),
  (md5('question:pharmacy-exam-prep:2:41')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 41, 'Which beta-blocker is known to have intrinsic sympathomimetic activity (ISA)?', 'Pindolol has intrinsic sympathomimetic activity (ISA).', null),
  (md5('question:pharmacy-exam-prep:2:42')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 42, 'In patients with high cardiovascular risk, which lipid-lowering drug class is preferred?', 'Statins are preferred for patients with high cardiovascular risk.', null),
  (md5('question:pharmacy-exam-prep:2:43')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 43, 'What is the main risk associated with the use of fibrinolytic therapy in myocardial infarction?', 'The main risk of fibrinolytic therapy is bleeding.', null),
  (md5('question:pharmacy-exam-prep:2:44')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 44, 'What is the primary action of ACE inhibitors in heart failure?', 'ACE inhibitors reduce afterload and preload in heart failure.', null),
  (md5('question:pharmacy-exam-prep:2:45')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 45, 'Which diuretic is most appropriate for a patient with heart failure and hyperkalemia?', 'Furosemide is appropriate for heart failure with hyperkalemia.', null),
  (md5('question:pharmacy-exam-prep:2:46')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 46, 'What is a common adverse effect of aldosterone antagonists in cardiac therapy?', 'Hyperkalemia is a common side effect of aldosterone antagonists.', null),
  (md5('question:pharmacy-exam-prep:2:47')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 47, 'Which drug class is most likely to cause a dry cough as a side effect?', 'ACE inhibitors are known to cause a dry cough.', null),
  (md5('question:pharmacy-exam-prep:2:48')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 48, 'For what purpose is digoxin used in atrial fibrillation?', 'Digoxin is used to reduce heart rate in atrial fibrillation.', null),
  (md5('question:pharmacy-exam-prep:2:49')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 49, 'Which antihypertensive class is associated with a risk of angioedema?', 'ACE inhibitors have a risk of causing angioedema.', null),
  (md5('question:pharmacy-exam-prep:2:50')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 50, 'What is the mechanism of action of dipyridamole?', 'Dipyridamole is a phosphodiesterase inhibitor with anti-platelet properties.', null),
  (md5('question:pharmacy-exam-prep:2:51')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 51, 'Which condition is a contraindication for the use of non-dihydropyridine calcium channel blockers?', 'Heart failure is a contraindication for non-dihydropyridine calcium channel blockers.', null),
  (md5('question:pharmacy-exam-prep:2:52')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 52, 'What is the primary indication for using beta-blockers in hypertension?', 'The primary indication is to reduce cardiac output in hypertension.', null),
  (md5('question:pharmacy-exam-prep:2:53')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 53, 'Which drug is an angiotensin receptor-neprilysin inhibitor (ARNI) used in heart failure?', 'Sacubitril/valsartan is an ARNI used in heart failure.', null),
  (md5('question:pharmacy-exam-prep:2:54')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 54, 'What is the primary adverse effect of long-term amiodarone use?', 'Pulmonary toxicity is a major concern with long-term amiodarone use.', null),
  (md5('question:pharmacy-exam-prep:2:55')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 55, 'Which medication is used as an anticoagulant in patients with a mechanical heart valve?', 'Warfarin is used in patients with mechanical heart valves.', null),
  (md5('question:pharmacy-exam-prep:2:56')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 56, 'What is the primary benefit of using nitrates in angina pectoris?', 'Nitrates reduce myocardial oxygen consumption in angina pectoris.', null),
  (md5('question:pharmacy-exam-prep:2:57')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 57, 'Which drug is a selective inhibitor of the sodium-glucose cotransporter 2 (SGLT2) with benefits in heart failure?', 'Canagliflozin is an SGLT2 inhibitor beneficial in heart failure.', null),
  (md5('question:pharmacy-exam-prep:2:58')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 58, 'What is the main risk associated with the chronic use of high-dose thiazide diuretics?', 'Hypokalemia is a risk with chronic high-dose thiazide diuretic use.', null),
  (md5('question:pharmacy-exam-prep:2:59')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 59, 'Which medication is indicated for the prevention of thromboembolism in atrial fibrillation?', 'Dabigatran is indicated for thromboembolism prevention in atrial fibrillation.', null),
  (md5('question:pharmacy-exam-prep:2:60')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 60, 'What is the primary action of sodium nitroprusside in hypertensive emergencies?', 'Sodium nitroprusside acts as a direct arterial vasodilator in hypertensive emergencies.', null),
  (md5('question:pharmacy-exam-prep:2:61')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 61, 'Which medication is a selective beta-1 blocker with renal protection benefits in diabetes?', 'Nebivolol is a selective beta-1 blocker with benefits in renal protection, especially in diabetic patients.', null),
  (md5('question:pharmacy-exam-prep:2:62')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 62, 'What is a key side effect of using ivabradine in cardiac therapy?', 'A key side effect of ivabradine is bradycardia.', null),
  (md5('question:pharmacy-exam-prep:2:63')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 63, 'Which class of antihypertensive drugs is known to precipitate bronchospasm in asthmatic patients?', 'Beta-blockers can precipitate bronchospasm in asthmatic patients.', null),
  (md5('question:pharmacy-exam-prep:2:64')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 64, 'What is the mechanism of action of ticagrelor in acute coronary syndrome?', 'Ticagrelor is an anti-platelet agent used in acute coronary syndrome.', null),
  (md5('question:pharmacy-exam-prep:2:65')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 65, 'Which medication is contraindicated in patients with bilateral renal artery stenosis?', 'Enalapril, an ACE inhibitor, is contraindicated in bilateral renal artery stenosis.', null),
  (md5('question:pharmacy-exam-prep:2:66')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 66, 'In congestive heart failure, why is spironolactone used?', 'Spironolactone is used to reduce aldosterone-mediated damage in congestive heart failure.', null),
  (md5('question:pharmacy-exam-prep:2:67')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 67, 'Which class of drugs is preferred in hypertensive patients with osteoporosis?', 'Thiazide diuretics are preferred in hypertensive patients with osteoporosis.', null),
  (md5('question:pharmacy-exam-prep:2:68')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 68, 'What is the primary benefit of using beta-blockers in patients post-myocardial infarction?', 'The primary benefit of beta-blockers post-MI is mortality reduction.', null),
  (md5('question:pharmacy-exam-prep:2:69')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 69, 'Which drug is used to manage hyperlipidemia and can cause flushing?', 'Niacin, used in hyperlipidemia, can cause flushing.', null),
  (md5('question:pharmacy-exam-prep:2:70')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 70, 'What is the mechanism of action of ranolazine in chronic angina?', 'Ranolazine works by inhibiting the late sodium current in chronic angina.', null),
  (md5('question:pharmacy-exam-prep:2:71')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 71, 'Which anticoagulant is preferred for patients with non-valvular atrial fibrillation and renal impairment?', 'Apixaban is preferred for patients with non-valvular atrial fibrillation and renal impairment.', null),
  (md5('question:pharmacy-exam-prep:2:72')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 72, 'What is the primary indication for using adenosine in cardiology?', 'Adenosine is primarily used for paroxysmal supraventricular tachycardia.', null),
  (md5('question:pharmacy-exam-prep:2:73')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 73, 'What is a common side effect of calcium channel blockers in the elderly?', 'Hypotension is a common side effect of calcium channel blockers in the elderly.', null),
  (md5('question:pharmacy-exam-prep:2:74')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 74, 'Which medication is indicated for reducing the risk of stroke in patients with peripheral arterial disease?', 'Clopidogrel is indicated for reducing the risk of stroke in patients with peripheral arterial disease.', null),
  (md5('question:pharmacy-exam-prep:2:75')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 75, 'What is a major side effect of using high-dose thiazide diuretics in diabetes?', 'Hyperglycemia is a major side effect of using high-dose thiazide diuretics in diabetes.', null),
  (md5('question:pharmacy-exam-prep:2:76')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 76, 'Which drug is a potassium-sparing diuretic often used in heart failure?', 'Spironolactone is a potassium-sparing diuretic used in heart failure.', null),
  (md5('question:pharmacy-exam-prep:2:77')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 77, 'What is the mechanism of action of verapamil in cardiac arrhythmias?', 'Verapamil acts as a calcium channel blocker in cardiac arrhythmias.', null),
  (md5('question:pharmacy-exam-prep:2:78')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 78, 'Which antihypertensive class is associated with a reduced risk of new-onset diabetes?', 'ACE inhibitors are associated with a reduced risk of new-onset diabetes.', null),
  (md5('question:pharmacy-exam-prep:2:79')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 79, 'What is the primary therapeutic use of loop diuretics like furosemide in cardiology?', 'Loop diuretics like furosemide are primarily used to reduce preload in heart failure.', null),
  (md5('question:pharmacy-exam-prep:2:80')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 80, 'Which of the following drugs is a beta-blocker used for chronic heart failure?', 'Bisoprolol is a beta-1 selective blocker indicated for chronic heart failure.', null),
  (md5('question:pharmacy-exam-prep:2:81')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 81, 'Which diuretic is most suitable for a patient with heart failure and renal impairment?', 'Furosemide is effective in renal impairment, often used in heart failure.', null),
  (md5('question:pharmacy-exam-prep:2:82')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 82, 'A patient on Warfarin should avoid which of the following due to increased bleeding risk?', 'Ibuprofen increases the risk of bleeding in patients on Warfarin.', null),
  (md5('question:pharmacy-exam-prep:2:83')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 83, 'Which drug is an angiotensin-converting enzyme (ACE) inhibitor used in hypertension?', 'Enalapril is an ACE inhibitor, commonly used in hypertension.', null),
  (md5('question:pharmacy-exam-prep:2:84')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 84, 'In acute coronary syndrome, which drug combination is commonly used?', 'Aspirin and Clopidogrel are often used together in acute coronary syndrome for their antiplatelet effects.', null),
  (md5('question:pharmacy-exam-prep:2:85')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 85, 'What is the primary side effect of Amiodarone?', 'Amiodarone can cause hypothyroidism due to its iodine content.', null),
  (md5('question:pharmacy-exam-prep:2:86')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 86, 'Which drug is contraindicated in a patient with a history of asthma and heart failure?', 'Propranolol, a non-selective beta-blocker, is contraindicated in asthma and heart failure.', null),
  (md5('question:pharmacy-exam-prep:2:87')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 87, 'Which of these is not a side effect of Digoxin?', 'Hyperkalemia is not a typical side effect of Digoxin.', null),
  (md5('question:pharmacy-exam-prep:2:88')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 88, 'For a patient with angina, which drug class is used to reduce myocardial oxygen demand?', 'Beta-blockers are used in angina to reduce heart rate and myocardial oxygen demand.', null),
  (md5('question:pharmacy-exam-prep:2:89')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 89, 'Which calcium channel blocker is preferred for rate control in atrial fibrillation?', 'Diltiazem is often used for rate control in atrial fibrillation.', null),
  (md5('question:pharmacy-exam-prep:2:90')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 90, 'What is the main risk associated with the use of Thiazide diuretics in the elderly?', 'Hyponatremia is a risk, especially in the elderly, with Thiazide diuretics.', null),
  (md5('question:pharmacy-exam-prep:2:91')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 91, 'In hypertensive emergency, which drug is preferred for immediate blood pressure reduction?', 'Nitroprusside is used for rapid blood pressure reduction in hypertensive emergencies.', null),
  (md5('question:pharmacy-exam-prep:2:92')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 92, 'What is a major side effect of ACE inhibitors like Lisinopril?', 'A persistent dry cough is a well-known side effect of ACE inhibitors.', null),
  (md5('question:pharmacy-exam-prep:2:93')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 93, 'Which drug is indicated for prevention of stroke in patients with atrial fibrillation and no other risk factors?', 'Aspirin may be used in patients with atrial fibrillation with no other risk factors for stroke prevention.', null),
  (md5('question:pharmacy-exam-prep:2:94')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 94, 'What is the mechanism of action of Statins like Atorvastatin?', 'Statins inhibit HMG-CoA reductase, reducing cholesterol synthesis.', null),
  (md5('question:pharmacy-exam-prep:2:95')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 95, 'For which condition is Eplerenone specifically indicated?', 'Eplerenone is indicated for heart failure post-myocardial infarction.', null),
  (md5('question:pharmacy-exam-prep:2:96')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 96, 'Which anti-arrhythmic drug increases the risk of torsades de pointes?', 'Sotalol can increase the risk of torsades de pointes, a type of ventricular tachycardia.', null),
  (md5('question:pharmacy-exam-prep:2:97')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 97, 'In a patient with Prinzmetal''s angina, which drug class is most effective?', 'Calcium channel blockers are effective in Prinzmetal''s (variant) angina.', null),
  (md5('question:pharmacy-exam-prep:2:98')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 98, 'Which is a common side effect of Nitrates like Nitroglycerin?', 'Headaches are a common side effect of nitrates due to vasodilation.', null),
  (md5('question:pharmacy-exam-prep:2:99')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 99, 'What is the primary action of Aldosterone antagonists in heart failure?', 'Aldosterone antagonists help in reducing myocardial fibrosis in heart failure.', null),
  (md5('question:pharmacy-exam-prep:2:100')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 100, 'A 63-year-old male with chronic heart failure is experiencing fatigue and shortness of breath. Which drug would be most appropriate to add to his regimen?', 'Carvedilol, a beta-blocker, is beneficial in chronic heart failure to improve symptoms and survival.', null),
  (md5('question:pharmacy-exam-prep:2:101')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 101, 'A 55-year-old female with hypertension and a history of asthma is seeking medication. Which antihypertensive should be avoided?', 'Atenolol, a beta-blocker, should be avoided in asthma as it can exacerbate the condition.', null),
  (md5('question:pharmacy-exam-prep:2:102')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 102, 'A 70-year-old male with atrial fibrillation and a prior stroke requires anticoagulation. What is the most appropriate choice?', 'Dabigatran, a direct thrombin inhibitor, is appropriate for stroke prevention in atrial fibrillation.', null),
  (md5('question:pharmacy-exam-prep:2:103')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 103, 'A 68-year-old female with stable angina requires additional medication. Which drug class is most effective for symptom control?', 'Calcium channel blockers are effective for symptom control in stable angina.', null),
  (md5('question:pharmacy-exam-prep:2:104')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 104, 'A 59-year-old male with hyperlipidemia is experiencing muscle pain. Which statin has a lower risk of myopathy?', 'Pravastatin is associated with a lower risk of myopathy compared to other statins.', null),
  (md5('question:pharmacy-exam-prep:2:105')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 105, 'A 72-year-old female with hypertension and chronic kidney disease needs a blood pressure medication. Which class should be preferred?', 'ACE inhibitors are preferred in chronic kidney disease for their renal protective effects.', null),
  (md5('question:pharmacy-exam-prep:2:106')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 106, 'A 65-year-old male with congestive heart failure and renal impairment requires diuretic therapy. Which drug should be chosen?', 'Torsemide is preferred in heart failure with renal impairment due to its better renal clearance.', null),
  (md5('question:pharmacy-exam-prep:2:107')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 107, 'A 60-year-old male with chronic stable angina is not achieving adequate symptom control. What medication could be added for better management?', 'Ivabradine can be added for better symptom control in chronic stable angina.', null),
  (md5('question:pharmacy-exam-prep:2:108')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 108, 'A 58-year-old female with a recent diagnosis of hypertension also has diabetes. Which antihypertensive drug class is beneficial for her?', 'ACE inhibitors are beneficial in hypertensive patients with diabetes due to renal protection.', null),
  (md5('question:pharmacy-exam-prep:2:109')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 109, 'A 75-year-old male with a history of myocardial infarction is on a statin. What is the primary goal of statin therapy in this patient?', 'The primary goal of statin therapy in post-myocardial infarction patients is to lower LDL cholesterol.', null),
  (md5('question:pharmacy-exam-prep:2:110')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 110, 'A 54-year-old male with peripheral arterial disease is at risk for stroke. What medication should be used for prophylaxis?', 'Clopidogrel is appropriate for stroke prophylaxis in peripheral arterial disease.', null),
  (md5('question:pharmacy-exam-prep:2:111')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 111, 'A 67-year-old female with atrial fibrillation and a high risk of bleeding requires anticoagulation. Which drug is preferred?', 'Apixaban is preferred due to its lower bleeding risk compared to other anticoagulants.', null),
  (md5('question:pharmacy-exam-prep:2:112')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 112, 'A 70-year-old male with chronic angina is experiencing bradycardia with his current medication. Which drug might be responsible?', 'Diltiazem, a calcium channel blocker, can cause bradycardia.', null),
  (md5('question:pharmacy-exam-prep:2:113')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 113, 'A 62-year-old female with heart failure is experiencing worsening renal function. Which medication might need adjustment?', 'Diuretics may need adjustment in the case of worsening renal function in heart failure.', null),
  (md5('question:pharmacy-exam-prep:2:114')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 114, 'A 56-year-old male with stable angina is not responding well to monotherapy. What combination therapy can be considered?', 'A combination of Beta-blocker and Calcium channel blocker can be considered for stable angina not responding to monotherapy.', null),
  (md5('question:pharmacy-exam-prep:2:115')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 115, 'A 69-year-old female with hypertension and osteoporosis needs a new antihypertensive. Which drug class can benefit her bone health?', 'Thiazide diuretics can be beneficial in patients with hypertension and osteoporosis.', null),
  (md5('question:pharmacy-exam-prep:2:116')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 116, 'A 77-year-old male with heart failure and frequent urination at night is on a diuretic. Which diuretic is less likely to cause nocturia?', 'Hydrochlorothiazide, with a shorter duration of action, may be less likely to cause nocturia.', null),
  (md5('question:pharmacy-exam-prep:2:117')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 117, 'A 64-year-old male with a history of myocardial infarction and depression needs lipid-lowering therapy. Which statin has fewer drug interactions with antidepressants?', 'Fluvastatin has fewer drug interactions compared to other statins and may be preferable in patients on antidepressants.', null),
  (md5('question:pharmacy-exam-prep:2:118')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 118, 'A 71-year-old female with hypertension and a history of cough with ACE inhibitors. Which alternative drug class is suitable?', 'ARBs are a suitable alternative for patients who develop a cough with ACE inhibitors.', null),
  (md5('question:pharmacy-exam-prep:2:119')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 119, 'A 66-year-old male with type 2 diabetes and hypertension is experiencing peripheral edema. Which antihypertensive drug could be causing this?', 'Amlodipine, a calcium channel blocker, can cause peripheral edema.', null),
  (md5('question:pharmacy-exam-prep:2:120')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 120, 'A 55-year-old female with rheumatoid arthritis and hypertension is seeking a new antihypertensive. Which drug should be avoided due to her condition?', 'Lisinopril, an ACE inhibitor, can exacerbate rheumatoid arthritis symptoms and should be avoided.', null),
  (md5('question:pharmacy-exam-prep:2:121')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 121, 'A 72-year-old male with heart failure and gout requires a diuretic. Which diuretic is least likely to exacerbate his gout?', 'Spironolactone is less likely to exacerbate gout compared to other diuretics.', null),
  (md5('question:pharmacy-exam-prep:2:122')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 122, 'A 68-year-old male with chronic kidney disease and hypertension needs medication adjustment. Which drug is beneficial for renal protection?', 'Lisinopril, an ACE inhibitor, provides renal protection in patients with chronic kidney disease.', null),
  (md5('question:pharmacy-exam-prep:2:123')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 123, 'A 60-year-old female with diabetes and hypertension is on a beta-blocker and needs a medication review. What is a potential issue with beta-blockers in this patient?', 'Beta-blockers can exacerbate diabetes by masking hypoglycemia symptoms.', null),
  (md5('question:pharmacy-exam-prep:2:124')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 124, 'A 74-year-old male with atrial fibrillation and a high bleeding risk needs an anticoagulant. Which drug is the safest option?', 'Apixaban has a lower bleeding risk compared to other anticoagulants, making it a safer option.', null),
  (md5('question:pharmacy-exam-prep:2:125')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 125, 'A 65-year-old female with stable angina and asthma requires additional medication. Which drug should be avoided?', 'Metoprolol, a beta-blocker, should be avoided in patients with asthma.', null),
  (md5('question:pharmacy-exam-prep:2:126')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 126, 'A 58-year-old male with hypertension and benign prostatic hyperplasia (BPH) needs a new antihypertensive. Which class can benefit his BPH?', 'Alpha-blockers can also help in managing symptoms of BPH.', null),
  (md5('question:pharmacy-exam-prep:2:127')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 127, 'A 77-year-old female with osteoporosis and hypertension is considering a diuretic. Which diuretic is preferred in her condition?', 'Hydrochlorothiazide is beneficial in patients with hypertension and osteoporosis due to its calcium-sparing effect.', null),
  (md5('question:pharmacy-exam-prep:2:128')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 128, 'A 69-year-old male with a history of myocardial infarction is considering a beta-blocker. What is the primary benefit in his case?', 'The primary benefit of beta-blockers in post-myocardial infarction patients is reduced mortality.', null),
  (md5('question:pharmacy-exam-prep:2:129')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 129, 'A 63-year-old female with hyperlipidemia reports muscle pain. Which non-statin medication can be considered?', 'Ezetimibe can be considered for patients with hyperlipidemia who experience muscle pain with statins.', null),
  (md5('question:pharmacy-exam-prep:2:130')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 130, 'A 70-year-old male with chronic angina and erectile dysfunction is on a nitrate. Why must phosphodiesterase type 5 inhibitors be avoided?', 'Phosphodiesterase type 5 inhibitors can potentiate the hypotensive effects of nitrates.', null),
  (md5('question:pharmacy-exam-prep:2:131')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 131, 'A 66-year-old male with atrial fibrillation and chronic kidney disease requires anticoagulation. Which drug should be used with caution?', 'Dabigatran requires cautious use in patients with chronic kidney disease due to renal clearance.', null),
  (md5('question:pharmacy-exam-prep:2:132')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 132, 'A 56-year-old female with hypertension and a history of depression requires medication adjustment. Which antihypertensive can exacerbate depression?', 'Clonidine can exacerbate symptoms of depression.', null),
  (md5('question:pharmacy-exam-prep:2:133')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 133, 'A 62-year-old male with heart failure and gout is considering spironolactone. What is a major concern with this drug?', 'Hyperkalemia is a major concern when using spironolactone, especially in patients with heart failure.', null),
  (md5('question:pharmacy-exam-prep:2:134')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 134, 'A 53-year-old female with chronic stable angina and hypothyroidism needs angina management. Which drug class is preferred?', 'Calcium channel blockers are preferred for angina management in patients with hypothyroidism.', null),
  (md5('question:pharmacy-exam-prep:2:135')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 135, 'A 78-year-old male with hypertension and chronic obstructive pulmonary disease (COPD) needs a new antihypertensive. Which class should be avoided?', 'Beta-blockers should be avoided in patients with COPD due to the risk of bronchospasm.', null),
  (md5('question:pharmacy-exam-prep:2:136')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 136, 'A 64-year-old female with hypertension and a history of angioedema on ACE inhibitors needs medication review. Which alternative is appropriate?', 'ARBs are an appropriate alternative for patients who have experienced angioedema on ACE inhibitors.', null),
  (md5('question:pharmacy-exam-prep:2:137')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 137, 'A 71-year-old male with diabetes, hypertension, and nephropathy requires a medication adjustment. Which antihypertensive class provides renal protection?', 'Sartans (ARBs) provide renal protection and are suitable for patients with diabetes and nephropathy.', null),
  (md5('question:pharmacy-exam-prep:2:138')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 138, 'A 59-year-old female with heart failure and atrial fibrillation is considering rate control medication. What is a suitable choice?', 'Diltiazem is suitable for rate control in patients with heart failure and atrial fibrillation.', null),
  (md5('question:pharmacy-exam-prep:2:139')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 139, 'A 68-year-old male with hyperlipidemia and liver disease is reviewing his medication. Which statin should be used with caution?', 'Atorvastatin should be used with caution in patients with liver disease due to potential hepatotoxicity.', null),
  (md5('question:pharmacy-exam-prep:2:140')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 140, 'A 67-year-old male with stable ischemic heart disease and a sulfa allergy needs a diuretic. Which medication should be avoided?', 'Hydrochlorothiazide, a sulfonamide diuretic, should be avoided in patients with sulfa allergies.', null),
  (md5('question:pharmacy-exam-prep:2:141')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 141, 'A 54-year-old female with hypertension and chronic kidney disease is considering an ARB. What is a major benefit of this class in her condition?', 'ARBs can decrease proteinuria, which is beneficial in chronic kidney disease.', null),
  (md5('question:pharmacy-exam-prep:2:142')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 142, 'A 59-year-old male with atrial fibrillation and a previous GI bleed requires anticoagulation. Which medication has the lowest risk of gastrointestinal bleeding?', 'Apixaban has a relatively lower risk of gastrointestinal bleeding compared to other anticoagulants.', null),
  (md5('question:pharmacy-exam-prep:2:143')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 143, 'A 73-year-old female with heart failure and diabetes needs a beta-blocker. Which one is preferred due to its metabolic neutrality?', 'Carvedilol is preferred in heart failure patients with diabetes due to its metabolic neutrality.', null),
  (md5('question:pharmacy-exam-prep:2:144')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 144, 'A 60-year-old male with angina and erectile dysfunction is on a PDE5 inhibitor. What class of angina medication should be avoided?', 'Nitrates should be avoided due to the risk of severe hypotension when combined with PDE5 inhibitors.', null),
  (md5('question:pharmacy-exam-prep:2:145')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 145, 'A 70-year-old female with hypertension and a history of hyperkalemia is considering an antihypertensive adjustment. Which drug should be used cautiously?', 'ACE inhibitors should be used cautiously in patients with a history of hyperkalemia.', null),
  (md5('question:pharmacy-exam-prep:2:146')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 146, 'A 55-year-old male with chronic heart failure and a cough is reviewing his medication. Which drug might be contributing to his cough?', 'Lisinopril, an ACE inhibitor, can cause a persistent dry cough.', null),
  (md5('question:pharmacy-exam-prep:2:147')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 147, 'A 63-year-old female with hypertension and asthma needs a new antihypertensive. What is the best choice for her?', 'Calcium channel blockers are a good choice for patients with hypertension and asthma.', null),
  (md5('question:pharmacy-exam-prep:2:148')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 148, 'A 72-year-old male with atrial fibrillation and renal impairment needs anticoagulation. Which drug requires careful monitoring of renal function?', 'Dabigatran requires careful monitoring of renal function, especially in renal impairment.', null),
  (md5('question:pharmacy-exam-prep:2:149')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 149, 'A 58-year-old female with hypertension and peripheral edema is on amlodipine. What medication could be added to reduce edema?', 'A diuretic can be added to manage peripheral edema caused by amlodipine.', null),
  (md5('question:pharmacy-exam-prep:2:150')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 150, 'A 69-year-old male with stable angina and gout is considering a nitrate. What is an important consideration regarding his gout?', 'Nitrates can increase uric acid levels and might exacerbate gout.', null),
  (md5('question:pharmacy-exam-prep:2:151')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 151, 'A 56-year-old male with heart failure and chronic obstructive pulmonary disease (COPD) is evaluating his beta-blocker therapy. Which beta-blocker is safer for COPD patients?', 'Bisoprolol, a cardioselective beta-blocker, is generally safer for patients with COPD.', null),
  (md5('question:pharmacy-exam-prep:2:152')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 152, 'A 74-year-old female with hypertension and osteoporosis is on hydrochlorothiazide. What additional benefit does this medication provide for her osteoporosis?', 'Hydrochlorothiazide decreases calcium excretion, which can be beneficial in osteoporosis.', null),
  (md5('question:pharmacy-exam-prep:2:153')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 153, 'A 65-year-old male with diabetes and hypertension is on an ACE inhibitor. He complains of a persistent dry cough. What is a suitable alternative medication?', 'An ARB is a suitable alternative for patients who develop a cough with ACE inhibitors.', null),
  (md5('question:pharmacy-exam-prep:2:154')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 154, 'A 77-year-old female with atrial fibrillation and a history of falls requires anticoagulation. Which medication might be a safer choice considering her fall risk?', 'Apixaban might be a safer choice due to its lower risk of major bleeding, which is important in patients with a history of falls.', null),
  (md5('question:pharmacy-exam-prep:2:155')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 155, 'A 60-year-old male with hyperlipidemia and a recent episode of acute pancreatitis is on atorvastatin. What is an important consideration for his medication?', 'Atorvastatin should be discontinued in the case of acute pancreatitis.', null),
  (md5('question:pharmacy-exam-prep:2:156')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 156, 'A 71-year-old female with chronic kidney disease and hypertension is on lisinopril. What is a key benefit of this medication in her condition?', 'Lisinopril can decrease the progression of kidney disease in patients with chronic kidney disease.', null),
  (md5('question:pharmacy-exam-prep:2:157')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 157, 'A 66-year-old male with stable angina and reflux esophagitis is considering anti-anginal therapy. Which medication might exacerbate his reflux?', 'Isosorbide mononitrate and other nitrates can exacerbate reflux esophagitis.', null),
  (md5('question:pharmacy-exam-prep:2:158')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 158, 'A 54-year-old female with hypertension and a history of depression is on a beta-blocker. What potential issue should be monitored?', 'Beta-blockers can sometimes worsen depression, so this should be monitored.', null),
  (md5('question:pharmacy-exam-prep:2:159')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 159, 'A 62-year-old male with diabetes and hypertension is on metoprolol. He reports frequent episodes of hypoglycemia. What is a concern with metoprolol in this patient?', 'Metoprolol can mask hypoglycemia symptoms, which is a concern in diabetic patients.', null),
  (md5('question:pharmacy-exam-prep:2:160')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 160, 'A 70-year-old male with heart failure and chronic renal failure is on enalapril. He has elevated potassium levels. What medication adjustment is needed?', 'Discontinuing enalapril may be necessary due to its potential to increase potassium levels.', null),
  (md5('question:pharmacy-exam-prep:2:161')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 161, 'A 65-year-old female with hypertension and bradycardia is being evaluated for a new antihypertensive. Which class should be avoided?', 'Beta-blockers should be avoided due to their potential to exacerbate bradycardia.', null),
  (md5('question:pharmacy-exam-prep:2:162')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 162, 'A 58-year-old male with a history of gout and hypertension is on hydrochlorothiazide. He reports a recent gout flare. What is the best course of action?', 'Switching to a loop diuretic is advisable, as hydrochlorothiazide can exacerbate gout.', null),
  (md5('question:pharmacy-exam-prep:2:163')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 163, 'A 72-year-old female with atrial fibrillation and a history of intestinal bleeding is on warfarin. Which alternative anticoagulant is preferable?', 'Apixaban is preferable due to its lower risk of gastrointestinal bleeding compared to warfarin.', null),
  (md5('question:pharmacy-exam-prep:2:164')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 164, 'A 55-year-old male with stable angina and hypotension is being reviewed for medication adjustment. Which medication might need to be reduced or discontinued?', 'Isosorbide mononitrate may need to be reduced or discontinued due to its hypotensive effects.', null),
  (md5('question:pharmacy-exam-prep:2:165')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 165, 'A 63-year-old female with diabetes, hypertension, and peripheral neuropathy is on lisinopril. What additional benefit does lisinopril provide for her diabetes?', 'Lisinopril offers protection against diabetic nephropathy.', null),
  (md5('question:pharmacy-exam-prep:2:166')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 166, 'A 60-year-old male with chronic kidney disease and hypertension is on losartan. He has a high serum creatinine level. What should be monitored closely?', 'Renal function should be closely monitored in patients on losartan, especially with high serum creatinine levels.', null),
  (md5('question:pharmacy-exam-prep:2:167')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 167, 'A 67-year-old female with osteoporosis and hypertension is on a calcium channel blocker. She is concerned about her bone health. What should be advised?', 'Switching to a thiazide diuretic can be beneficial for bone health due to its calcium-sparing effect.', null),
  (md5('question:pharmacy-exam-prep:2:168')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 168, 'A 75-year-old male with atrial fibrillation and mild cognitive impairment is on dabigatran. What is important to monitor in this patient?', 'Renal function should be monitored in patients on dabigatran, especially in the elderly with cognitive impairment.', null),
  (md5('question:pharmacy-exam-prep:2:169')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 169, 'A 54-year-old female with hypertension and asthma is on a beta-blocker. She reports increased wheezing. What medication adjustment is indicated?', 'Switching to a calcium channel blocker is indicated, as beta-blockers can exacerbate asthma.', null),
  (md5('question:pharmacy-exam-prep:2:170')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 170, 'A 69-year-old male with stable ischemic heart disease and erectile dysfunction is seeking medication advice. Which anti-anginal medication should be used cautiously?', 'Nitrates should be used cautiously, especially if the patient is using medications for erectile dysfunction.', null),
  (md5('question:pharmacy-exam-prep:2:171')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 171, 'A 62-year-old female with heart failure and a history of depression is on carvedilol. What potential side effect should be monitored?', 'Carvedilol can potentially exacerbate depression, so this should be closely monitored.', null),
  (md5('question:pharmacy-exam-prep:2:172')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 172, 'A 77-year-old male with hypertension and benign prostatic hyperplasia is on doxazosin. What is a key benefit of this medication for his BPH?', 'Doxazosin can improve urinary flow, which is beneficial for patients with BPH.', null),
  (md5('question:pharmacy-exam-prep:2:173')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 173, 'A 68-year-old female with diabetes and hypertension is on an ACE inhibitor. She experiences facial swelling. What is the next step?', 'Discontinuing the ACE inhibitor is crucial in the case of facial swelling, a sign of angioedema.', null),
  (md5('question:pharmacy-exam-prep:2:174')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 174, 'A 57-year-old male with chronic stable angina and gastroesophageal reflux disease (GERD) is on a nitrate. What concern should be addressed?', 'Nitrates can potentiate GERD symptoms, so this should be closely monitored.', null),
  (md5('question:pharmacy-exam-prep:2:175')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 175, 'A 71-year-old female with atrial fibrillation and a high stroke risk is on aspirin. What medication is more appropriate for stroke prevention?', 'Apixaban is more appropriate for stroke prevention in atrial fibrillation compared to aspirin.', null),
  (md5('question:pharmacy-exam-prep:2:176')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 176, 'A 64-year-old male with hypertension and chronic obstructive pulmonary disease (COPD) is on metoprolol. What is a potential risk with this medication?', 'Metoprolol can exacerbate COPD, so an alternative medication might be needed.', null),
  (md5('question:pharmacy-exam-prep:2:177')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 177, 'A 59-year-old female with heart failure and diabetes is considering spironolactone. What should be monitored due to her diabetes?', 'Potassium levels should be closely monitored in patients on spironolactone, especially those with diabetes.', null),
  (md5('question:pharmacy-exam-prep:2:178')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 178, 'A 66-year-old male with hypertension and a history of peptic ulcer disease is on aspirin for primary prevention. What is an important consideration?', 'Discontinuing aspirin might be necessary due to its potential to exacerbate peptic ulcer disease.', null),
  (md5('question:pharmacy-exam-prep:2:179')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 179, 'A 73-year-old female with chronic kidney disease and hypertension is on losartan. She complains of dizziness. What should be evaluated?', 'Blood pressure should be evaluated, as losartan can cause hypotension leading to dizziness.', null),
  (md5('question:pharmacy-exam-prep:2:180')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 180, 'A 59-year-old male with hypertension and chronic kidney disease is experiencing hyperkalemia. Which antihypertensive should be reconsidered?', 'Lisinopril, an ACE inhibitor, can cause hyperkalemia and should be reconsidered in patients with chronic kidney disease.', null),
  (md5('question:pharmacy-exam-prep:2:181')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 181, 'A 68-year-old female with atrial fibrillation and a history of major bleeding is under anticoagulation therapy. Which anticoagulant is most appropriate?', 'Apixaban has a lower bleeding risk compared to other anticoagulants, making it appropriate for patients with a history of major bleeding.', null),
  (md5('question:pharmacy-exam-prep:2:182')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 182, 'A 70-year-old male with stable ischemic heart disease is experiencing dizziness and fatigue. He is on atenolol. What might be the cause?', 'Dizziness and fatigue can be normal side effects of atenolol, a beta-blocker.', null),
  (md5('question:pharmacy-exam-prep:2:183')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 183, 'A 62-year-old female with hypertension and type 2 diabetes is considering an ARB. Which ARB is beneficial for her diabetic nephropathy?', 'Irbesartan is beneficial for its protective effects in diabetic nephropathy.', null),
  (md5('question:pharmacy-exam-prep:2:184')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 184, 'A 56-year-old male with chronic heart failure is experiencing worsening renal function. He is on enalapril and spironolactone. What should be the focus of medication review?', 'Both enalapril and spironolactone can impact renal function and should be the focus of the medication review.', null),
  (md5('question:pharmacy-exam-prep:2:185')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 185, 'A 73-year-old female with atrial fibrillation and moderate renal impairment requires anticoagulation. Which medication requires dose adjustment or monitoring?', 'Dabigatran requires careful dose adjustment and monitoring in patients with renal impairment.', null),
  (md5('question:pharmacy-exam-prep:2:186')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 186, 'A 65-year-old male with stable angina and erectile dysfunction is on isosorbide mononitrate. He is considering a PDE5 inhibitor. What is a major concern?', 'The combination of isosorbide mononitrate and a PDE5 inhibitor can lead to severe hypotension.', null),
  (md5('question:pharmacy-exam-prep:2:187')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 187, 'A 60-year-old female with hypertension and history of angioedema on ACE inhibitors is on losartan. What should be monitored due to her history?', 'Signs of angioedema should be monitored, as it can rarely occur with ARBs in patients with a history of angioedema on ACE inhibitors.', null),
  (md5('question:pharmacy-exam-prep:2:188')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 188, 'A 57-year-old male with heart failure and COPD is on carvedilol. He reports increased shortness of breath. What might be the cause?', 'Heart failure exacerbation could be a cause, as carvedilol can impact lung function and heart failure symptoms.', null),
  (md5('question:pharmacy-exam-prep:2:189')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 189, 'A 71-year-old female with chronic kidney disease and heart failure is on furosemide. She is experiencing decreased urine output. What is the most likely cause?', 'Heart failure exacerbation could lead to decreased urine output despite furosemide use.', null),
  (md5('question:pharmacy-exam-prep:2:190')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 190, 'A 66-year-old male with atrial fibrillation and a high stroke risk is on aspirin. Is aspirin monotherapy sufficient for stroke prevention?', 'In atrial fibrillation with high stroke risk, aspirin monotherapy is generally not sufficient; an anticoagulant is typically recommended.', null),
  (md5('question:pharmacy-exam-prep:2:191')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 191, 'A 58-year-old female with hypertension and recent onset of type 2 diabetes is on metoprolol. She reports frequent hypoglycemic episodes. What should be considered?', 'Reducing the dose of metoprolol or considering a different antihypertensive might be necessary due to the risk of masking hypoglycemic symptoms.', null),
  (md5('question:pharmacy-exam-prep:2:192')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 192, 'A 69-year-old male with stable ischemic heart disease and chronic renal failure is on atorvastatin. What is important to monitor?', 'Liver function tests are important to monitor in patients on atorvastatin, particularly with chronic renal failure.', null),
  (md5('question:pharmacy-exam-prep:2:193')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 193, 'A 75-year-old female with hypertension and glaucoma is on a thiazide diuretic. What potential complication should be monitored?', 'Increased risk of acute glaucoma is a concern with thiazide diuretics in patients with glaucoma.', null),
  (md5('question:pharmacy-exam-prep:2:194')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 194, 'A 54-year-old male with atrial fibrillation and a prior GI bleed is on rivaroxaban. What is an alternative anticoagulant with a potentially lower GI bleeding risk?', 'Apixaban may have a lower GI bleeding risk compared to rivaroxaban and could be a safer alternative.', null),
  (md5('question:pharmacy-exam-prep:2:195')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 195, 'A 67-year-old female with heart failure and diabetes is on amlodipine. She reports swelling in her legs. What should be the first step in management?', 'Reducing the dose of amlodipine or considering an alternative antihypertensive might help manage the leg swelling.', null),
  (md5('question:pharmacy-exam-prep:2:196')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 196, 'A 70-year-old male with chronic kidney disease and hypertension is on lisinopril. His serum creatinine has increased. What action is needed?', 'Switching to a different class of antihypertensive, such as a calcium channel blocker, may be necessary if lisinopril is affecting renal function.', null),
  (md5('question:pharmacy-exam-prep:2:197')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 197, 'A 59-year-old female with hypertension and a history of depression is on a beta-blocker. She reports worsening mood. What should be considered?', 'Switching to a different antihypertensive class may be necessary if the beta-blocker is exacerbating depression.', null),
  (md5('question:pharmacy-exam-prep:2:198')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 198, 'A 64-year-old male with stable angina and a peptic ulcer is on aspirin. What is an important consideration for his medication regimen?', 'Adding a proton pump inhibitor (PPI) can help protect against peptic ulcer exacerbation while on aspirin.', null),
  (md5('question:pharmacy-exam-prep:2:199')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 199, 'A 72-year-old female with heart failure and asthma is on enalapril. She reports a persistent dry cough. What is a suitable alternative medication?', 'An ARB is a suitable alternative for patients who develop a cough with ACE inhibitors.', null),
  (md5('question:pharmacy-exam-prep:2:200')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 200, 'A 64-year-old female with hypertension and chronic bronchitis is on a beta-blocker. She reports increased coughing. What medication adjustment is indicated?', 'Discontinuing the beta-blocker may be necessary if it exacerbates chronic bronchitis symptoms.', null),
  (md5('question:pharmacy-exam-prep:2:201')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 201, 'A 75-year-old male with atrial fibrillation and a history of renal impairment is on dabigatran. What is a key consideration for his medication?', 'Frequent monitoring of renal function is essential for patients on dabigatran, especially with a history of renal impairment.', null),
  (md5('question:pharmacy-exam-prep:2:202')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 202, 'A 57-year-old female with hypertension and osteoporosis is on a thiazide diuretic. What is a beneficial effect of this medication for her osteoporosis?', 'Thiazide diuretics can decrease bone resorption, which is beneficial for patients with osteoporosis.', null),
  (md5('question:pharmacy-exam-prep:2:203')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 203, 'A 69-year-old male with stable angina is considering adding a PDE5 inhibitor for erectile dysfunction. He is currently on a nitrate. What is the primary concern?', 'The combination of nitrates and PDE5 inhibitors can lead to severe hypotension and is contraindicated.', null),
  (md5('question:pharmacy-exam-prep:2:204')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 204, 'A 60-year-old female with heart failure and diabetes is on a beta-blocker. She experiences frequent hypoglycemic episodes. What should be considered?', 'Changing the beta-blocker to a different type or class may help manage the hypoglycemic episodes.', null),
  (md5('question:pharmacy-exam-prep:2:205')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 205, 'A 71-year-old male with chronic kidney disease and atrial fibrillation is on rivaroxaban. What is important to monitor in this patient?', 'Monitoring renal function is important in patients on rivaroxaban, especially those with chronic kidney disease.', null),
  (md5('question:pharmacy-exam-prep:2:206')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 206, 'A 53-year-old female with hypertension and a history of angioedema with ACE inhibitors is on an ARB. She reports facial swelling. What is the best course of action?', 'Discontinuing the ARB is necessary if angioedema occurs, as it can be a serious side effect.', null),
  (md5('question:pharmacy-exam-prep:2:207')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 207, 'A 67-year-old male with heart failure and COPD is on carvedilol. He reports worsening shortness of breath. What might be the cause?', 'Carvedilol, a beta-blocker, can exacerbate COPD symptoms, potentially causing shortness of breath.', null),
  (md5('question:pharmacy-exam-prep:2:208')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 208, 'A 62-year-old female with chronic kidney disease and heart failure is on enalapril and furosemide. She has increasing edema. What should be evaluated first?', 'Evaluating and possibly adjusting the dose of furosemide, a diuretic, may be necessary to manage edema.', null),
  (md5('question:pharmacy-exam-prep:2:209')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 209, 'A 58-year-old male with hypertension and a history of gout is on hydrochlorothiazide. He reports a recent gout attack. What modification is needed?', 'Switching to a loop diuretic may be beneficial, as hydrochlorothiazide can exacerbate gout.', null),
  (md5('question:pharmacy-exam-prep:2:210')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 210, 'A 73-year-old female with hypertension and chronic anxiety is on a beta-blocker. She reports increased anxiety. What is the appropriate action?', 'Discontinuing or switching to a different class of antihypertensive may be necessary if the beta-blocker exacerbates anxiety.', null),
  (md5('question:pharmacy-exam-prep:2:211')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 211, 'A 65-year-old male with atrial fibrillation and moderate renal dysfunction is on apixaban. What is important regarding his medication regimen?', 'Regular renal function tests are important for patients on apixaban, especially those with renal dysfunction.', null),
  (md5('question:pharmacy-exam-prep:2:212')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 212, 'A 60-year-old female with stable ischemic heart disease and a history of peptic ulcer disease is on low-dose aspirin. What additional medication might be beneficial?', 'A proton pump inhibitor (PPI) may be beneficial to mitigate the risk of peptic ulcer disease exacerbated by aspirin.', null),
  (md5('question:pharmacy-exam-prep:2:213')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 213, 'A 70-year-old male with heart failure and a history of asthma is on lisinopril. He reports wheezing and shortness of breath. What should be the focus of medication review?', 'Lisinopril may need to be reviewed, as ACE inhibitors can cause cough and potentially exacerbate asthma symptoms.', null),
  (md5('question:pharmacy-exam-prep:2:214')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 214, 'A 54-year-old male with hypertension and erectile dysfunction is considering sildenafil. He is currently on amlodipine. What should be monitored?', 'Blood pressure should be monitored, as sildenafil can cause hypotension, especially in patients on antihypertensives like amlodipine.', null),
  (md5('question:pharmacy-exam-prep:2:215')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 215, 'A 77-year-old female with chronic kidney disease and heart failure is on spironolactone. She reports muscle weakness. What should be checked first?', 'Potassium levels should be checked first, as spironolactone can cause hyperkalemia, leading to muscle weakness.', null),
  (md5('question:pharmacy-exam-prep:2:216')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 216, 'A 59-year-old male with atrial fibrillation and diabetes is on warfarin. He has inconsistent INR levels. What might improve INR control?', 'More frequent INR monitoring may be necessary to achieve better control in patients on warfarin, especially with fluctuating levels.', null),
  (md5('question:pharmacy-exam-prep:2:217')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 217, 'A 68-year-old female with hypertension and a history of high cholesterol is on atorvastatin. She reports muscle pain. What is the first step in management?', 'Changing to a different statin or adjusting the dose might be necessary if muscle pain is a side effect of atorvastatin.', null),
  (md5('question:pharmacy-exam-prep:2:218')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 218, 'A 71-year-old male with stable angina and peripheral artery disease is on clopidogrel. What is a key benefit of this medication for him?', 'Clopidogrel reduces the risk of arterial thrombosis, which is beneficial for patients with peripheral artery disease.', null),
  (md5('question:pharmacy-exam-prep:2:219')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 219, 'A 66-year-old female with heart failure and renal impairment is on a high dose of furosemide. She has decreasing urine output. What should be considered?', 'Switching to torsemide, which may be more effective in renal impairment, could be considered if furosemide is less effective.', null),
  (md5('question:pharmacy-exam-prep:2:220')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 220, 'A 63-year-old male with hypertension and a history of hyperkalemia is on lisinopril. What medication change is advisable?', 'Changing to a calcium channel blocker would be safer due to the risk of hyperkalemia with lisinopril.', null),
  (md5('question:pharmacy-exam-prep:2:221')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 221, 'A 57-year-old female with chronic heart failure and renal impairment is on furosemide. She has worsening renal function. What action is recommended?', 'Evaluating alternative diuretics may be necessary due to worsening renal function with furosemide.', null),
  (md5('question:pharmacy-exam-prep:2:222')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 222, 'A 70-year-old male with atrial fibrillation and a high stroke risk is on aspirin. What is a more suitable anticoagulant?', 'Apixaban is more suitable for stroke prevention in atrial fibrillation compared to aspirin.', null),
  (md5('question:pharmacy-exam-prep:2:223')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 223, 'A 68-year-old female with hypertension and osteoporosis is on a beta-blocker. What alternative antihypertensive could also benefit her osteoporosis?', 'A thiazide diuretic could benefit both hypertension and osteoporosis by reducing calcium excretion.', null),
  (md5('question:pharmacy-exam-prep:2:224')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 224, 'A 55-year-old male with stable ischemic heart disease and diabetes is on metformin and atorvastatin. He reports muscle pain. What might be the cause?', 'Muscle pain can be a side effect of atorvastatin, especially in patients also taking metformin.', null),
  (md5('question:pharmacy-exam-prep:2:225')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 225, 'A 72-year-old female with atrial fibrillation and chronic kidney disease is on warfarin. What is an important aspect of her care?', 'Regular INR monitoring is crucial for a patient on warfarin, especially with chronic kidney disease.', null),
  (md5('question:pharmacy-exam-prep:2:226')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 226, 'A 60-year-old male with hypertension and a recent stroke is on losartan. What additional medication could benefit his stroke prevention?', 'Adding an antiplatelet agent could be beneficial for stroke prevention in addition to losartan.', null),
  (md5('question:pharmacy-exam-prep:2:227')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 227, 'A 67-year-old female with stable angina and hypothyroidism is on levothyroxine and isosorbide mononitrat What is a concern with this combination?', 'The combination might affect the effectiveness of levothyroxine, requiring monitoring of thyroid function.', null),
  (md5('question:pharmacy-exam-prep:2:228')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 228, 'A 73-year-old male with chronic heart failure and gout is on allopurinol and enalapril. He reports increased frequency of gout attacks. What should be considered?', 'Switching from enalapril to an ARB may help reduce the frequency of gout attacks.', null),
  (md5('question:pharmacy-exam-prep:2:229')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 229, 'A 58-year-old female with atrial fibrillation and a history of GI bleed is on dabigatran. What anticoagulant could be safer?', 'Apixaban may be a safer alternative due to a lower risk of GI bleeding compared to dabigatran.', null),
  (md5('question:pharmacy-exam-prep:2:230')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 230, 'A 62-year-old male with diabetes and hypertension is on an ACE inhibitor and reports persistent cough. What is an appropriate alternative?', 'Switching to an ARB is appropriate for patients who develop a cough with ACE inhibitors.', null),
  (md5('question:pharmacy-exam-prep:2:231')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 231, 'A 66-year-old female with hypertension and asthma is considering a beta-blocker. Why should this be avoided?', 'Beta-blockers should be avoided due to the risk of bronchospasm in patients with asthma.', null),
  (md5('question:pharmacy-exam-prep:2:232')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 232, 'A 71-year-old male with chronic kidney disease and heart failure is on spironolacton What should be closely monitored?', 'Potassium levels should be closely monitored due to the risk of hyperkalemia with spironolactone, especially in chronic kidney disease.', null),
  (md5('question:pharmacy-exam-prep:2:233')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 233, 'A 59-year-old female with atrial fibrillation and a history of peptic ulcer is on rivaroxaban. What alternative medication could be considered?', 'Apixaban might be a better alternative due to a potentially lower risk of peptic ulcer exacerbation.', null),
  (md5('question:pharmacy-exam-prep:2:234')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 234, 'A 54-year-old male with stable angina and erectile dysfunction is using sildenafil. What angina medication should he avoid?', 'Nitrates should be avoided as they can cause severe hypotension when combined with sildenafil.', null),
  (md5('question:pharmacy-exam-prep:2:235')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 235, 'A 75-year-old female with hypertension and chronic obstructive pulmonary disease (COP is on amlodipin She reports ankle swelling. What should be the first step in management?', 'Reducing the dose of amlodipine or considering an alternative antihypertensive might help manage the ankle swelling.', null),
  (md5('question:pharmacy-exam-prep:2:236')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 236, 'A 68-year-old male with heart failure and renal impairment is on lisinopril. He has worsening renal function. What is an advisable medication change?', 'Discontinuing lisinopril might be necessary due to its potential impact on renal function.', null),
  (md5('question:pharmacy-exam-prep:2:237')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 237, 'A 60-year-old female with hypertension and a history of depression is on propranolol. She reports mood worsening. What is a suitable alternative medication?', 'A calcium channel blocker might be a suitable alternative if propranolol is worsening her mood.', null),
  (md5('question:pharmacy-exam-prep:2:238')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 238, 'A 77-year-old male with stable ischemic heart disease and a history of liver disease is on simvastatin. What should be monitored?', 'Liver function tests should be monitored due to the potential hepatotoxic effects of simvastatin, especially in patients with pre-existing liver disease.', null),
  (md5('question:pharmacy-exam-prep:2:239')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 239, 'A 53-year-old female with heart failure and diabetes is on metformin and carvedilol. She reports hypoglycemia. What should be considered?', 'Monitoring blood glucose more frequently is important as carvedilol can mask hypoglycemic symptoms.', null),
  (md5('question:pharmacy-exam-prep:2:240')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 240, 'A 60-year-old male with hypertension and chronic kidney disease is on lisinopril. He experiences a persistent dry cough. What is a suitable alternative medication?', 'Candesartan, an ARB, is a suitable alternative to lisinopril, especially if the patient is experiencing a cough.', null),
  (md5('question:pharmacy-exam-prep:2:241')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 241, 'A 72-year-old female with atrial fibrillation and a history of falls is on warfarin. Considering her fall risk, what medication adjustment is advisable?', 'Switching to a direct oral anticoagulant, like apixaban, may be safer considering her risk of falls and potential for bleeding.', null),
  (md5('question:pharmacy-exam-prep:2:242')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 242, 'A 55-year-old male with stable angina and erectile dysfunction is considering a medication for angina. What should be avoided?', 'Nitrates should be avoided as they can cause severe hypotension when used with medications for erectile dysfunction.', null),
  (md5('question:pharmacy-exam-prep:2:243')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 243, 'A 67-year-old female with hypertension and osteoporosis is on hydrochlorothiazide. She is concerned about her bone health. What advice is appropriate?', 'Continuing hydrochlorothiazide is beneficial for her bone health as it helps reduce calcium excretion.', null),
  (md5('question:pharmacy-exam-prep:2:244')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 244, 'A 58-year-old male with heart failure and renal impairment is on enalapril. He reports worsening renal function. What should be considered?', 'Adjusting or discontinuing enalapril should be considered due to its potential to worsen renal function.', null),
  (md5('question:pharmacy-exam-prep:2:245')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 245, 'A 63-year-old female with atrial fibrillation and a high bleeding risk is on rivaroxaban. What is a safer anticoagulation strategy?', 'Switching to apixaban may be safer, as it has a lower bleeding risk compared to rivaroxaban.', null),
  (md5('question:pharmacy-exam-prep:2:246')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 246, 'A 70-year-old male with stable ischemic heart disease and type 2 diabetes is on metformin and atorvastatin. He reports muscle cramps. What should be evaluated?', 'The atorvastatin dosage should be evaluated, as statins can cause muscle cramps.', null),
  (md5('question:pharmacy-exam-prep:2:247')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 247, 'A 74-year-old female with hypertension and a history of bronchospasm is on a beta-blocker. What is a more suitable medication?', 'A calcium channel blocker would be more suitable, as beta-blockers can exacerbate bronchospasm.', null),
  (md5('question:pharmacy-exam-prep:2:248')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 248, 'A 59-year-old male with heart failure and COPD is on carvedilol. He reports worsening of respiratory symptoms. What is the best course of action?', 'Switching to a cardioselective beta-blocker like bisoprolol may help reduce respiratory symptoms in a patient with COPD.', null),
  (md5('question:pharmacy-exam-prep:2:249')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 249, 'A 68-year-old female with chronic kidney disease and atrial fibrillation is on dabigatran. She has deteriorating renal function. What adjustment is necessary?', 'Switching to a different anticoagulant that is less dependent on renal excretion might be necessary.', null),
  (md5('question:pharmacy-exam-prep:2:250')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 250, 'A 57-year-old female with hypertension and a history of angioedema with ACE inhibitors is on losartan. She reports facial swelling. What action should be taken?', 'Discontinuing losartan is necessary due to the risk of angioedema, even though it''s rare with ARBs.', null),
  (md5('question:pharmacy-exam-prep:2:251')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 251, 'A 66-year-old male with stable angina and a history of liver disease is on isosorbide mononitrate. He reports dizziness. What should be evaluated?', 'Blood pressure should be evaluated as isosorbide mononitrate can cause hypotension leading to dizziness.', null),
  (md5('question:pharmacy-exam-prep:2:252')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 252, 'A 60-year-old female with heart failure and diabetes is on a thiazide diuretic. She has persistent hyperglycemia. What medication adjustment might help?', 'Switching to a loop diuretic might help, as thiazide diuretics can worsen blood glucose control.', null),
  (md5('question:pharmacy-exam-prep:2:253')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 253, 'A 73-year-old male with hypertension and chronic obstructive pulmonary disease (COPD) is on amlodipine. He reports ankle edema. What should be considered?', 'Reducing the dose of amlodipine or considering a different antihypertensive may help manage the ankle edema.', null),
  (md5('question:pharmacy-exam-prep:2:254')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 254, 'A 54-year-old male with atrial fibrillation and a high stroke risk is on aspirin. What is a more effective stroke prevention strategy?', 'Switching to an anticoagulant is generally more effective for stroke prevention in atrial fibrillation.', null),
  (md5('question:pharmacy-exam-prep:2:255')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 255, 'A 67-year-old female with stable ischemic heart disease and hypothyroidism is on levothyroxine and a beta-blocker. What should be monitored?', 'Thyroid function tests should be monitored as beta-blockers can interact with thyroid hormone metabolism.', null),
  (md5('question:pharmacy-exam-prep:2:256')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 256, 'A 71-year-old male with chronic kidney disease and heart failure is on spironolactone. He reports muscle weakness. What should be checked?', 'Potassium levels should be checked as spironolactone can cause hyperkalemia, leading to muscle weakness.', null),
  (md5('question:pharmacy-exam-prep:2:257')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 257, 'A 62-year-old female with hypertension and a history of depression is on an ACE inhibitor. She reports worsening depression. What could be a suitable alternative?', 'An ARB could be a suitable alternative if the ACE inhibitor is contributing to her depression.', null),
  (md5('question:pharmacy-exam-prep:2:258')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 258, 'A 58-year-old male with stable angina and erectile dysfunction is on sildenafil. He requires additional anti-anginal therapy. What should be avoided?', 'Nitrates should be avoided due to the risk of severe hypotension when used with sildenafil.', null),
  (md5('question:pharmacy-exam-prep:2:259')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 259, 'A 75-year-old female with hypertension and chronic bronchitis is on a non-selective beta-blocker. She reports increased coughing and wheezing. What is the best course of action?', 'Switching to a cardioselective beta-blocker like bisoprolol may reduce respiratory symptoms in a patient with chronic bronchitis.', null),
  (md5('question:pharmacy-exam-prep:2:260')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 260, 'A 64-year-old male with heart failure and gout is on lisinopril and experiences frequent gout flares. What medication adjustment is advisable?', 'Changing to an ARB might reduce the frequency of gout flares associated with lisinopril.', null),
  (md5('question:pharmacy-exam-prep:2:261')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 261, 'A 59-year-old female with atrial fibrillation and chronic kidney disease is on apixaban. Given her kidney condition, what is important?', 'Regular monitoring of renal function is important to adjust apixaban dosing appropriately.', null),
  (md5('question:pharmacy-exam-prep:2:262')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 262, 'A 72-year-old male with hypertension and type 2 diabetes is on a beta-blocker. He reports episodes of hypoglycemia. What should be considered?', 'Switching to a calcium channel blocker might be safer, as beta-blockers can mask hypoglycemia symptoms.', null),
  (md5('question:pharmacy-exam-prep:2:263')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 263, 'A 68-year-old female with stable ischemic heart disease is on aspirin and reports gastrointestinal discomfort. What is an appropriate action?', 'Adding a proton pump inhibitor can help manage gastrointestinal discomfort associated with aspirin.', null),
  (md5('question:pharmacy-exam-prep:2:264')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 264, 'A 55-year-old male with chronic kidney disease and heart failure is on furosemide and reports decreased urination. What should be evaluated?', 'Renal function should be evaluated, as decreased urination could indicate worsening renal function in this context.', null),
  (md5('question:pharmacy-exam-prep:2:265')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 265, 'A 63-year-old female with hypertension and a history of bronchial asthma is on an ACE inhibitor. She reports worsening asthma symptoms. What is a suitable alternative?', 'A calcium channel blocker could be a suitable alternative, as ACE inhibitors may worsen asthma symptoms.', null),
  (md5('question:pharmacy-exam-prep:2:266')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 266, 'A 70-year-old male with stable angina and reflux disease is on nitrates. He reports increased reflux symptoms. What could be a suitable management strategy?', 'Adding a proton pump inhibitor can help manage increased reflux symptoms associated with nitrates.', null),
  (md5('question:pharmacy-exam-prep:2:267')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 267, 'A 58-year-old female with heart failure and diabetes is on a thiazide diuretic and experiences persistent hyperglycemia. What adjustment might help?', 'Switching to a loop diuretic might be beneficial, as thiazide diuretics can worsen glucose control.', null),
  (md5('question:pharmacy-exam-prep:2:268')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 268, 'A 66-year-old male with atrial fibrillation and a previous ischemic stroke is on aspirin. What is a more effective anticoagulation therapy?', 'Switching to a direct oral anticoagulant, such as apixaban, would be more effective for stroke prevention.', null),
  (md5('question:pharmacy-exam-prep:2:269')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 269, 'A 75-year-old female with hypertension and osteoarthritis is on a non-selective NSAID. She reports increased blood pressure. What should be considered?', 'Switching to a selective NSAID might help manage increased blood pressure associated with non-selective NSAIDs.', null),
  (md5('question:pharmacy-exam-prep:2:270')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 270, 'A 57-year-old male with stable ischemic heart disease and peptic ulcer disease is on low-dose aspirin. What gastroprotective strategy is advisable?', 'Adding a proton pump inhibitor can provide gastroprotection while continuing low-dose aspirin therapy.', null),
  (md5('question:pharmacy-exam-prep:2:271')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 271, 'A 69-year-old female with atrial fibrillation and renal impairment is on dabigatran. Given her renal condition, what is a key consideration?', 'Regular monitoring of renal function is crucial to adjust dabigatran dosing appropriately.', null),
  (md5('question:pharmacy-exam-prep:2:272')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 272, 'A 60-year-old male with hypertension and gout is on hydrochlorothiazide. He experiences frequent gout attacks. What change in therapy could help?', 'Switching to a loop diuretic might be beneficial, as hydrochlorothiazide can exacerbate gout.', null),
  (md5('question:pharmacy-exam-prep:2:273')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 273, 'A 74-year-old female with chronic kidney disease and heart failure is on lisinopril. She reports increased serum creatinine levels. What action is recommended?', 'Adjusting or discontinuing lisinopril might be necessary due to its potential impact on renal function.', null),
  (md5('question:pharmacy-exam-prep:2:274')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 274, 'A 53-year-old male with stable angina and erectile dysfunction is on sildenafil. He needs additional anti-anginal medication. What should be avoided?', 'Nitrates should be avoided due to the risk of severe hypotension when used with medications like sildenafil.', null),
  (md5('question:pharmacy-exam-prep:2:275')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 275, 'A 67-year-old female with hypertension and chronic bronchitis is on a beta-blocker. She reports increased cough and wheezing. What is a more suitable medication?', 'A calcium channel blocker would be a more suitable choice, as beta-blockers can exacerbate bronchitis symptoms.', null),
  (md5('question:pharmacy-exam-prep:2:276')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 276, 'A 71-year-old male with heart failure and diabetes is on carvedilol. He reports episodes of hypoglycemia. What should be considered?', 'Adjusting diabetes medication is important, as carvedilol can mask hypoglycemic symptoms.', null),
  (md5('question:pharmacy-exam-prep:2:277')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 277, 'A 62-year-old female with atrial fibrillation and mild renal impairment is on rivaroxaban. What is important to monitor?', 'Renal function should be closely monitored, as rivaroxaban dosing may need adjustment in renal impairment.', null),
  (md5('question:pharmacy-exam-prep:2:278')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 278, 'A 56-year-old male with stable angina and gastroesophageal reflux disease (GERD) is on a nitrate. He reports worsening reflux. What adjustment might help?', 'Adding a proton pump inhibitor can help manage increased reflux symptoms associated with nitrates.', null),
  (md5('question:pharmacy-exam-prep:2:279')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 279, 'A 77-year-old female with hypertension and chronic kidney disease is on amlodipine. She experiences peripheral edema. What is an appropriate action?', 'Reducing the dose of amlodipine or switching to a different antihypertensive might help manage peripheral edema.', null),
  (md5('question:pharmacy-exam-prep:2:280')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 280, 'A 61-year-old male with hypertension and a history of asthma is on an ACE inhibitor and reports worsening asthma symptoms. What medication adjustment should be considered?', 'Switching to an ARB may be beneficial, as ACE inhibitors can exacerbate asthma symptoms.', null),
  (md5('question:pharmacy-exam-prep:2:281')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 281, 'A 75-year-old female with chronic heart failure and renal impairment is on digoxin. She has symptoms of digoxin toxicity. What should be done?', 'Reducing the dose of digoxin or discontinuing it may be necessary in case of toxicity, especially in renal impairment.', null),
  (md5('question:pharmacy-exam-prep:2:282')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 282, 'A 67-year-old male with stable ischemic heart disease and type 2 diabetes is on a statin. He reports muscle pain. What is a suitable alternative?', 'Switching to a different statin or considering CoQ10 supplementation might help manage muscle pain.', null),
  (md5('question:pharmacy-exam-prep:2:283')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 283, 'A 70-year-old female with hypertension and chronic kidney disease is on a calcium channel blocker. She reports swollen ankles. What medication change could help?', 'Adding a diuretic may help manage the peripheral edema associated with calcium channel blockers.', null),
  (md5('question:pharmacy-exam-prep:2:284')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 284, 'A 54-year-old male with atrial fibrillation and a prior history of peptic ulcer is on warfarin. He experiences gastrointestinal discomfort. What action is advisable?', 'Switching to a direct oral anticoagulant may reduce the risk of gastrointestinal discomfort.', null),
  (md5('question:pharmacy-exam-prep:2:285')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 285, 'A 63-year-old female with heart failure and diabetes is on metformin and a beta-blocker. She reports frequent hypoglycemic episodes. What should be considered?', 'Adjusting her diabetes medication or switching to a different beta-blocker may be necessary to manage hypoglycemia.', null),
  (md5('question:pharmacy-exam-prep:2:286')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 286, 'A 58-year-old male with chronic kidney disease and hypertension is on an ARB. He reports increased serum potassium. What is the best course of action?', 'Switching to a calcium channel blocker may be safer due to the risk of hyperkalemia with ARBs in chronic kidney disease.', null),
  (md5('question:pharmacy-exam-prep:2:287')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 287, 'A 69-year-old female with stable angina and gastroesophageal reflux disease (GERD) is on nitrates. She reports increased reflux symptoms. What adjustment might help?', 'Adding a proton pump inhibitor may help manage increased reflux symptoms caused by nitrates.', null),
  (md5('question:pharmacy-exam-prep:2:288')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 288, 'A 77-year-old male with atrial fibrillation and mild renal impairment is on dabigatran. Given his renal condition, what is important?', 'Regular monitoring of renal function is important to adjust the dosing of dabigatran appropriately.', null),
  (md5('question:pharmacy-exam-prep:2:289')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 289, 'A 56-year-old female with hypertension and type 2 diabetes is on an ACE inhibitor. She experiences facial swelling. What action should be taken?', 'Discontinuing the ACE inhibitor is necessary, as facial swelling could indicate angioedema.', null),
  (md5('question:pharmacy-exam-prep:2:290')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 290, 'A 65-year-old male with stable angina and hypothyroidism is on levothyroxine and a beta-blocker. What potential interaction should be monitored?', 'The efficacy of levothyroxine may be reduced due to the beta-blocker, so thyroid function tests should be monitored.', null),
  (md5('question:pharmacy-exam-prep:2:291')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 291, 'A 60-year-old female with atrial fibrillation and a history of GI bleed is on rivaroxaban. What should be closely monitored?', 'Renal function should be closely monitored, as rivaroxaban dosing may need adjustment in renal impairment.', null),
  (md5('question:pharmacy-exam-prep:2:292')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 292, 'A 71-year-old male with heart failure and COPD is on carvedilol. He reports increased shortness of breath. What should be considered?', 'Switching to a different, more cardioselective beta-blocker may help reduce respiratory symptoms in a patient with COPD.', null),
  (md5('question:pharmacy-exam-prep:2:293')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 293, 'A 74-year-old female with chronic kidney disease and diabetes is on an ACE inhibitor. She has elevated serum creatinine. What action is advisable?', 'Adjusting or discontinuing the ACE inhibitor may be necessary due to its impact on renal function.', null),
  (md5('question:pharmacy-exam-prep:2:294')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 294, 'A 67-year-old male with hypertension and a history of gout is on hydrochlorothiazide. He experiences recurrent gout attacks. What is an appropriate medication change?', 'Switching to a loop diuretic may reduce the frequency of gout attacks compared to hydrochlorothiazide.', null),
  (md5('question:pharmacy-exam-prep:2:295')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 295, 'A 59-year-old female with stable ischemic heart disease and a history of liver disease is on atorvastatin. What should be closely monitored?', 'Liver function tests should be closely monitored due to the potential hepatotoxic effects of atorvastatin, especially in patients with pre-existing liver disease.', null),
  (md5('question:pharmacy-exam-prep:2:296')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 296, 'A 53-year-old male with atrial fibrillation and a high stroke risk is on aspirin. What is a more effective anticoagulation strategy?', 'Switching to a direct oral anticoagulant, such as apixaban, is generally more effective for stroke prevention in atrial fibrillation.', null),
  (md5('question:pharmacy-exam-prep:2:297')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 297, 'A 62-year-old female with hypertension and chronic obstructive pulmonary disease (COP) is on a non-selective beta-blocker. She reports increased breathlessness. What is a more suitable medication?', 'A cardioselective beta-blocker, like bisoprolol, is generally safer for patients with COP.', null),
  (md5('question:pharmacy-exam-prep:2:298')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 298, 'A 70-year-old male with stable angina and a history of peptic ulcer disease is on low-dose aspirin. What gastroprotective strategy is advisable?', 'Adding a proton pump inhibitor can help protect the gastrointestinal tract from the effects of aspirin.', null),
  (md5('question:pharmacy-exam-prep:2:299')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 299, 'A 55-year-old female with chronic heart failure and diabetes is on metformin and a thiazide diuretic. She experiences frequent hypoglycemic episodes. What should be considered?', 'Adjusting her diabetes medication is important, as thiazide diuretics can affect blood glucose levels.', null),
  (md5('question:pharmacy-exam-prep:2:300')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 300, 'A 58-year-old female with hypertension and chronic kidney disease is on losartan. She experiences elevated potassium levels. What is an appropriate adjustment?', 'Switching to a calcium channel blocker may be safer due to the risk of hyperkalemia with losartan in chronic kidney disease.', null),
  (md5('question:pharmacy-exam-prep:2:301')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 301, 'A 67-year-old male with heart failure and diabetes is on metoprolol. He reports worsening blood glucose control. What should be considered?', 'Adjusting his diabetes medication might be necessary, as beta-blockers can affect blood glucose control.', null),
  (md5('question:pharmacy-exam-prep:2:302')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 302, 'A 60-year-old female with atrial fibrillation and a history of gastrointestinal bleeding is on dabigatran. What alternative anticoagulant could be safer?', 'Apixaban may be a safer alternative due to its relatively lower risk of gastrointestinal bleeding compared to dabigatran.', null),
  (md5('question:pharmacy-exam-prep:2:303')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 303, 'A 72-year-old male with stable ischemic heart disease and a peptic ulcer is on aspirin. He reports gastrointestinal discomfort. What is an advisable action?', 'Adding a proton pump inhibitor can help manage gastrointestinal discomfort associated with aspirin use.', null),
  (md5('question:pharmacy-exam-prep:2:304')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 304, 'A 55-year-old male with chronic kidney disease and hypertension is on enalapril. He has increasing serum creatinine levels. What action is recommended?', 'Adjusting or discontinuing enalapril may be necessary due to its potential impact on renal function.', null),
  (md5('question:pharmacy-exam-prep:2:305')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 305, 'A 63-year-old female with heart failure and COPD is on carvedilol. She reports increased shortness of breath. What should be considered?', 'Switching to a different, more cardioselective beta-blocker may help reduce respiratory symptoms in a patient with COPD.', null),
  (md5('question:pharmacy-exam-prep:2:306')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 306, 'A 70-year-old male with atrial fibrillation and renal impairment is on warfarin. He has unstable INR levels. What is an alternative anticoagulation strategy?', 'Switching to a direct oral anticoagulant might be more manageable and safer than warfarin, especially with unstable INR levels.', null),
  (md5('question:pharmacy-exam-prep:2:307')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 307, 'A 59-year-old female with stable angina and reflux disease is on nitrates. She reports increased reflux symptoms. What adjustment might help?', 'Adding a proton pump inhibitor may help manage increased reflux symptoms caused by nitrates.', null),
  (md5('question:pharmacy-exam-prep:2:308')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 308, 'A 54-year-old male with hypertension and type 2 diabetes is on a thiazide diuretic. He experiences persistent hyperglycemia. What adjustment might help?', 'Adjusting his diabetes medication or considering a different class of diuretic might help manage hyperglycemia.', null),
  (md5('question:pharmacy-exam-prep:2:309')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 309, 'A 68-year-old female with atrial fibrillation and a history of bleeding is on apixaban. What should be monitored closely?', 'Monitoring for signs of bleeding is important in patients on apixaban, especially those with a history of bleeding.', null),
  (md5('question:pharmacy-exam-prep:2:310')::uuid, md5('quiz:pharmacy-exam-prep:2')::uuid, 310, 'A patient of afro-caribbean origin has recently come back from her gp after being diagnosed with hypertension, with a blood pressure of 153/98. The doctor has recommended that she starts with lifestyle advice and has also asked her to start on antihypertensive therapy. The patient is 45 and has no other medical conditions or allergies. Which one of the following options is the most appropriate first-line antihypertensive that the doctor has initiated?', 'A CCB (calcium channel blocker) such as amlodipine is started first in patients who are 55 or above or of Afro-Caribbean origin.', null)
