insert into public.chapters (id, course_id, position, title) values
  (md5('chapter:pharmacy-exam-prep:4')::uuid, md5('course:pharmacy-exam-prep')::uuid, 4, 'Central Nervous System')
insert into public.quizzes (id, chapter_id, title, position, is_preview) values
  (md5('quiz:pharmacy-exam-prep:4')::uuid, md5('chapter:pharmacy-exam-prep:4')::uuid, 'Central Nervous System', 1, false)
insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('question:pharmacy-exam-prep:4:1')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 1, 'A 55-year-old male patient with chronic neuropathic pain is prescribed pregabalin. What is the primary mechanism of action of pregabalin?', 'Pregabalin primarily works by inhibiting calcium channels, which reduces the release of various neurotransmitters and thereby alleviates neuropathic pain.', null),
  (md5('question:pharmacy-exam-prep:4:2')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 2, 'A patient on amitriptyline for depression reports dry mouth and blurred vision. Which side effect is this indicative of?', 'Dry mouth and blurred vision are typical anticholinergic side effects, commonly seen with tricyclic antidepressants like amitriptyline.', null),
  (md5('question:pharmacy-exam-prep:4:3')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 3, 'A 70-year-old female with epilepsy is on carbamazepine therapy. She is prescribed doxycycline for a respiratory infection. What potential interaction should be monitored?', 'Carbamazepine is a potent inducer of cytochrome P450 enzymes, which can reduce the efficacy of other drugs metabolized by these enzymes, such as doxycycline.', null),
  (md5('question:pharmacy-exam-prep:4:4')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 4, 'A patient on phenytoin for seizure control has erratic blood levels. They do not have any other significant drug history. Which factor is most likely to contribute to this issue?', 'Phenytoin has a narrow therapeutic index, meaning small changes in dose or blood levels can lead to toxicity or loss of efficacy.', null),
  (md5('question:pharmacy-exam-prep:4:5')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 5, 'A 40-year-old patient with acute migraine is prescribed sumatriptan. What is the primary action of sumatriptan in treating migraines?', 'Sumatriptan relieves migraine by agonizing serotonin (5-HT1) receptors, leading to vasoconstriction of intracranial blood vessels.', null),
  (md5('question:pharmacy-exam-prep:4:6')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 6, 'A 45-year-old patient on levodopa for Parkinson’s disease complains of nausea and vomiting. What is the likely cause?', 'Levodopa is converted to dopamine in the periphery as well as in the CNS, which can cause nausea and vomiting due to its action on the chemoreceptor trigger zone.', null),
  (md5('question:pharmacy-exam-prep:4:7')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 7, 'Which of the following is a common side effect of SSRIs like sertraline in the initial weeks of treatment and thus must you counsel the patient on?', 'Sexual dysfunction is a common side effect of SSRIs, often occurring in the initial weeks of treatment and may persist.', null),
  (md5('question:pharmacy-exam-prep:4:8')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 8, 'A patient on lithium therapy for bipolar disorder has developed tremors and ataxia. What does this indicate?', 'Tremors and ataxia are signs of lithium toxicity, which requires immediate attention to adjust the dose or discontinue the drug.', null),
  (md5('question:pharmacy-exam-prep:4:9')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 9, 'For a patient on warfarin, what is the risk of co-prescribing phenobarbital?', 'Phenobarbital induces liver enzymes and can reduce the effectiveness of warfarin, leading to a risk of thrombosis. This can be seen on bloods as a reduced INR level.', null),
  (md5('question:pharmacy-exam-prep:4:10')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 10, 'A patient with schizophrenia is prescribed clozapine. What unique monitoring parameter is essential for this medication?', 'Clozapine can cause agranulocytosis, so regular monitoring of white blood cell count is essential.', null),
  (md5('question:pharmacy-exam-prep:4:11')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 11, 'In a patient with multiple sclerosis, what is the primary action of interferon beta-1a?', 'Interferon beta-1a acts by inhibiting immune cell migration across the blood-brain barrier, reducing inflammation and the frequency of relapses.', null),
  (md5('question:pharmacy-exam-prep:4:12')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 12, 'You are a pharmacist working in the community pharmacy when one of your more senior patients walks in having been newly prescribed a new antidepressant. What is the primary concern when prescribing tricyclic antidepressants (TCAs) like amitriptyline to elderly patients?', 'TCAs can cause sedation and orthostatic hypotension, increasing the risk of falls, especially in elderly patients.', null),
  (md5('question:pharmacy-exam-prep:4:13')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 13, 'A patient on monoamine oxidase inhibitors (MAOIs) for depression should avoid which type of food to prevent a hypertensive crisis?', 'Tyramine-rich foods like aged cheese and cured meats can cause a hypertensive crisis when consumed by patients on MAOIs.', null),
  (md5('question:pharmacy-exam-prep:4:14')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 14, 'A patient on antipsychotic therapy with risperidone presents with muscle rigidity and fever. What is the most likely diagnosis?', 'Neuroleptic malignant syndrome is a serious side effect of antipsychotics, characterized by muscle rigidity, fever, and autonomic instability.', null),
  (md5('question:pharmacy-exam-prep:4:15')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 15, 'In treating status epilepticus, which medication is preferred for initial management?', 'Diazepam is commonly used for the initial management of status epilepticus due to its rapid onset of action.', null),
  (md5('question:pharmacy-exam-prep:4:16')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 16, 'A patient on haloperidol therapy develops restlessness and an inability to sit still. Which side effect is this indicative of?', 'Akathisia, a state of restlessness and inability to stay still, is a common side effect of haloperidol and other antipsychotics.', null),
  (md5('question:pharmacy-exam-prep:4:17')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 17, 'For a patient with a history of seizures, which of the following antidepressants should be used with caution?', 'Bupropion has a lower seizure threshold compared to other antidepressants and should be used with caution in patients with a history of seizures.', null),
  (md5('question:pharmacy-exam-prep:4:18')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 18, 'Which drug interaction should be monitored when a patient is co-prescribed citalopram and omeprazole?', 'The combination of citalopram and omeprazole can increase the risk of QT prolongation, requiring careful monitoring.', null),
  (md5('question:pharmacy-exam-prep:4:19')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 19, 'A patient taking amitriptyline for neuropathic pain shows signs of confusion and hallucinations. What is the likely cause?', 'Amitriptyline can cause anticholinergic toxicity, especially in the elderly, leading to confusion and hallucinations.', null),
  (md5('question:pharmacy-exam-prep:4:20')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 20, 'What is the mechanism of action of memantine used in Alzheimer''s disease?', 'Memantine works by antagonizing NMDA receptors, which modulates the effects of glutamate in the brain, involved in Alzheimer''s disease.', null),
  (md5('question:pharmacy-exam-prep:4:21')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 21, 'A patient on valproate for bipolar disorder is found to have elevated liver enzymes. What is the recommended action?', 'Elevated liver enzymes can indicate hepatotoxicity, a serious side effect of valproate, warranting its discontinuation.', null),
  (md5('question:pharmacy-exam-prep:4:22')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 22, 'A patient on escitalopram for anxiety reports persistent headaches. Which action should be taken?', 'Headaches are a common initial side effect of SSRIs that often resolve with time. Monitoring and reassessment are advised.', null),
  (md5('question:pharmacy-exam-prep:4:23')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 23, 'Which medication increases the risk of serotonin syndrome when combined with SSRIs?', 'St. John''s Wort can increase serotonin levels, risking serotonin syndrome when combined with SSRIs.', null),
  (md5('question:pharmacy-exam-prep:4:24')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 24, 'In managing ADHD, what is the primary action of methylphenidate?', 'Methylphenidate primarily inhibits the reuptake of norepinephrine, improving attention and focus in ADHD.', null),
  (md5('question:pharmacy-exam-prep:4:25')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 25, 'A patient on phenytoin for seizure control has a concurrent infection treated with ciprofloxacin. What concern arises from this combination?', 'Ciprofloxacin can inhibit the metabolism of phenytoin, leading to increased levels and potential toxicity.', null),
  (md5('question:pharmacy-exam-prep:4:26')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 26, 'A 60-year-old patient on alprazolam for anxiety wants to discontinue the medication. What is the best approach?', 'Gradual tapering of alprazolam is recommended to avoid withdrawal symptoms.', null),
  (md5('question:pharmacy-exam-prep:4:27')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 27, 'For a patient with acute manic episodes in bipolar disorder, which medication is most appropriate?', 'Risperidone is effective in managing acute mania in bipolar disorder.', null),
  (md5('question:pharmacy-exam-prep:4:28')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 28, 'For a patient on clozapine, what blood test is mandatory due to the risk of a serious side effect?', 'Regular complete blood count is required for patients on clozapine due to the risk of agranulocytosis.', null),
  (md5('question:pharmacy-exam-prep:4:29')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 29, 'What is a potential adverse effect of chronic use of opioid analgesics like morphine?', 'Constipation is a common and persistent side effect of chronic opioid use.', null),
  (md5('question:pharmacy-exam-prep:4:30')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 30, 'A patient on gabapentin for neuropathic pain reports swelling in the legs. What is the most likely cause?', 'Peripheral edema is a known side effect of gabapentin and should be monitored.', null),
  (md5('question:pharmacy-exam-prep:4:31')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 31, 'A patient on SSRIs for depression develops restlessness, confusion, and rapid heart rate. Which condition should be suspected?', 'These symptoms are indicative of serotonin syndrome, a potentially life-threatening condition caused by excess serotonin activity.', null),
  (md5('question:pharmacy-exam-prep:4:32')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 32, 'Which antipsychotic is known for its lower risk of extrapyramidal side effects?', 'Olanzapine, an atypical antipsychotic, has a lower risk of extrapyramidal side effects compared to typical antipsychotics.', null),
  (md5('question:pharmacy-exam-prep:4:33')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 33, 'In a patient with anxiety, which benzodiazepine characteristic is important for reducing the risk of dependence?', 'A long half-life in benzodiazepines reduces the risk of dependence and withdrawal symptoms, making it a preferable characteristic in managing anxiety.', null),
  (md5('question:pharmacy-exam-prep:4:34')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 34, 'In a patient with Alzheimer''s, what is a potential side effect of using acetylcholinesterase inhibitors like donepezil?', 'Bradycardia can occur with acetylcholinesterase inhibitors due to increased vagal tone.', null),
  (md5('question:pharmacy-exam-prep:4:35')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 35, 'A patient on methadone for opioid dependence presents with prolonged QT interval. What action should be taken?', 'Monitoring cardiac function closely is important as methadone can prolong the QT interval.', null),
  (md5('question:pharmacy-exam-prep:4:36')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 36, 'Which antidepressant is associated with a high risk of weight gain?', 'Mirtazapine is known to cause significant weight gain compared to other antidepressants.', null),
  (md5('question:pharmacy-exam-prep:4:37')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 37, 'What is the primary action of modafinil in treating narcolepsy?', 'Modafinil primarily acts by inhibiting dopamine reuptake, promoting wakefulness in narcolepsy.', null),
  (md5('question:pharmacy-exam-prep:4:38')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 38, 'A patient on antipsychotic therapy develops high fever and altered mental status. What is the first step in management?', 'Discontinuing the antipsychotic is crucial in managing neuroleptic malignant syndrome, a serious side effect.', null),
  (md5('question:pharmacy-exam-prep:4:39')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 39, 'For a patient with chronic pain on high-dose opioids, what is an important consideration to prevent opioid-induced hyperalgesia?', 'Rotating opioids can help manage opioid-induced hyperalgesia, a condition where high opioid doses paradoxically increase pain sensitivity.', null),
  (md5('question:pharmacy-exam-prep:4:40')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 40, 'In a patient with depression, what is a common side effect of trazodone?', 'Sedation is a common side effect of trazodone due to its sedative properties.', null),
  (md5('question:pharmacy-exam-prep:4:41')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 41, 'What is the mechanism of action of baclofen in muscle spasticity?', 'Baclofen acts as a GABA-B receptor agonist, reducing muscle spasticity.', null),
  (md5('question:pharmacy-exam-prep:4:42')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 42, 'In treating acute migraine, what is the primary action of triptans like sumatriptan?', 'Triptans act as serotonin (5-HT1) receptor agonists, leading to vasoconstriction and relief from migraine.', null),
  (md5('question:pharmacy-exam-prep:4:43')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 43, 'Which symptom is indicative of lithium toxicity?', 'Tremors are a common sign of lithium toxicity, along with other symptoms like nausea, diarrhea, and ataxia.', null),
  (md5('question:pharmacy-exam-prep:4:44')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 44, 'What is the risk of combining SSRIs with NSAIDs?', 'The combination of SSRIs and NSAIDs increases the risk of gastrointestinal bleeding.', null),
  (md5('question:pharmacy-exam-prep:4:45')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 45, 'For a patient on clozapine, what is a common metabolic side effect?', 'Clozapine is associated with metabolic side effects, including hyperglycemia and weight gain.', null),
  (md5('question:pharmacy-exam-prep:4:46')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 46, 'A patient on carbamazepine for trigeminal neuralgia develops a skin rash. What is the immediate action?', 'Discontinuing carbamazepine is important if a skin rash develops, as it can be a sign of a serious reaction.', null),
  (md5('question:pharmacy-exam-prep:4:47')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 47, 'Which antiepileptic drug requires regular monitoring of serum levels to ensure therapeutic efficacy and avoid toxicity?', 'Regular monitoring of serum levels is essential for phenytoin due to its narrow therapeutic index and variable pharmacokinetics.', null),
  (md5('question:pharmacy-exam-prep:4:48')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 48, 'A patient with bipolar disorder on lamotrigine therapy presents with a skin rash. What is the recommended action?', 'Discontinuing lamotrigine is crucial if a skin rash develops, as it can be a sign of serious adverse reactions like Stevens-Johnson syndrome.', null),
  (md5('question:pharmacy-exam-prep:4:49')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 49, 'What is a common side effect of the anticholinergic drug benztropine used in Parkinson''s disease?', 'Dry mouth is a common side effect of benztropine due to its anticholinergic properties.', null),
  (md5('question:pharmacy-exam-prep:4:50')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 50, 'In an elderly patient with dementia, what is a concern when prescribing antipsychotics for agitation?', 'Antipsychotics in elderly dementia patients are associated with increased risks of falls, reduced cognitive function, and stroke.', null),
  (md5('question:pharmacy-exam-prep:4:51')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 51, 'Which side effect is commonly associated with the use of SSRIs like fluoxetine in the elderly?', 'Hyponatremia is a notable side effect in the elderly using SSRIs due to SIADH (Syndrome of Inappropriate Antidiuretic Hormone Secretion).', null),
  (md5('question:pharmacy-exam-prep:4:52')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 52, 'A patient with depression is prescribed venlafaxin What is an important consideration regarding blood pressure?', 'Venlafaxine, especially at higher doses, can cause hypertension and requires monitoring of blood pressure.', null),
  (md5('question:pharmacy-exam-prep:4:53')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 53, 'What is a major side effect of atypical antipsychotics like olanzapine in terms of metabolic health?', 'Atypical antipsychotics like olanzapine can cause metabolic side effects such as hyperlipidemia and weight gain.', null),
  (md5('question:pharmacy-exam-prep:4:54')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 54, 'A patient on long-term corticosteroid therapy for multiple sclerosis experiences bone pain. What is a likely cause?', 'Long-term corticosteroid use can lead to osteoporosis, increasing the risk of bone pain and fractures.', null),
  (md5('question:pharmacy-exam-prep:4:55')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 55, 'What is the primary mechanism of action of topiramate used in migraine prophylaxis?', 'Topiramate modulates GABA receptors and blocks calcium channels, contributing to its efficacy in migraine prophylaxis.', null),
  (md5('question:pharmacy-exam-prep:4:56')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 56, 'A patient on lithium therapy for bipolar disorder presents with tremors and slurred speech. What should be the immediate action?', 'Checking lithium serum levels is crucial as tremors and slurred speech can be signs of lithium toxicity.', null),
  (md5('question:pharmacy-exam-prep:4:57')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 57, 'For a patient with Parkinson''s disease, what is a common side effect of dopamine agonists like pramipexole?', 'Orthostatic hypotension is a common side effect of dopamine agonists used in Parkinson''s disease.', null),
  (md5('question:pharmacy-exam-prep:4:58')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 58, 'What is a significant concern when using clozapine in the treatment of schizophrenia?', 'Agranulocytosis, a potentially life-threatening decrease in white blood cells, is a significant risk associated with clozapine.', null),
  (md5('question:pharmacy-exam-prep:4:59')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 59, 'In a patient with epilepsy, what is the main concern with the use of enzyme-inducing antiepileptics like carbamazepine during pregnancy?', 'Enzyme-inducing antiepileptics like carbamazepine have teratogenic risks and require careful management during pregnancy.', null),
  (md5('question:pharmacy-exam-prep:4:60')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 60, 'In managing a patient with generalized anxiety disorder, which type of medication is preferred for long-term treatment?', 'SSRIs are preferred for long-term management of generalized anxiety disorder due to their safety profile and lower risk of dependence.', null),
  (md5('question:pharmacy-exam-prep:4:61')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 61, 'What is the mechanism of action of buspirone used in anxiety disorders?', 'Buspirone primarily acts as a serotonin receptor agonist, which helps in reducing anxiety.', null),
  (md5('question:pharmacy-exam-prep:4:62')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 62, 'A patient with schizophrenia is prescribed aripiprazol What is a key benefit of this medication over older antipsychotics?', 'Aripiprazole has a lower risk of extrapyramidal side effects compared to older antipsychotics.', null),
  (md5('question:pharmacy-exam-prep:4:63')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 63, 'Which medication used in Alzheimer''s disease can cause vivid dreams or insomnia?', 'Donepezil, an acetylcholinesterase inhibitor, can cause vivid dreams or insomnia as a side effect.', null),
  (md5('question:pharmacy-exam-prep:4:64')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 64, 'In bipolar disorder, what is a common side effect of valproate?', 'Hair loss is a common side effect of valproate, along with other effects like weight gain and tremors.', null),
  (md5('question:pharmacy-exam-prep:4:65')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 65, 'What is a risk associated with the abrupt discontinuation of antiepileptic drugs?', 'Abrupt discontinuation of antiepileptic drugs can lead to rebound seizures, which can be more severe.', null),
  (md5('question:pharmacy-exam-prep:4:66')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 66, 'In treating a patient with epilepsy, what is a concern with the use of lamotrigine during pregnancy?', 'Lamotrigine use during pregnancy is associated with an increased risk of cleft lip and palate in the newborn.', null),
  (md5('question:pharmacy-exam-prep:4:67')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 67, 'A patient on risperidone for schizophrenia experiences breast enlargement and lactation. What is this condition known as?', 'Hyperprolactinemia, an increase in prolactin levels often caused by risperidone, can lead to breast enlargement and lactation.', null),
  (md5('question:pharmacy-exam-prep:4:68')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 68, 'Which medication is preferred for the acute treatment of a migraine headache?', 'Sumatriptan is a first-line medication for the acute treatment of migraine headaches due to its efficacy in relieving symptoms.', null),
  (md5('question:pharmacy-exam-prep:4:69')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 69, 'A 68-year-old man with Alzheimer''s is prescribed donepezil. He later presents with bradycardi What is the likely cause?', 'Bradycardia in this patient is likely due to the cholinergic effects of donepezil, which can slow heart rate.', null),
  (md5('question:pharmacy-exam-prep:4:70')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 70, 'A 50-year-old man with chronic back pain is prescribed oxycodon He later develops constipation. What is the best management approach?', 'Constipation is a common side effect of oxycodon Starting a stimulant laxative can help manage this issue.', null),
  (md5('question:pharmacy-exam-prep:4:71')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 71, 'A 72-year-old man with Parkinson''s disease starts taking levodopa and later experiences nause What is the likely cause?', 'Nausea is a common side effect of levodopa, as it can stimulate the chemoreceptor trigger zone in the brain.', null),
  (md5('question:pharmacy-exam-prep:4:72')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 72, 'A 28-year-old woman with epilepsy on valproate plans to conceiv What is an important consideration?', 'Valproate poses risks of congenital malformations. The patient should be counseled on these risks and possibly switched to a safer antiepileptic.', null),
  (md5('question:pharmacy-exam-prep:4:73')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 73, 'A 60-year-old man on risperidone for schizophrenia experiences restlessness and an urge to move constantly. What is this condition?', 'This patient is likely experiencing akathisia, a common side effect of antipsychotics like risperidone, characterized by restlessness.', null),
  (md5('question:pharmacy-exam-prep:4:74')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 74, 'A 22-year-old woman with migraines is prescribed sumatriptan. She has a history of Raynaud''s phenomenon. What is a concern?', 'Sumatriptan, a vasoconstrictor, can exacerbate conditions like Raynaud''s phenomenon, which involves reduced blood flow to extremities.', null),
  (md5('question:pharmacy-exam-prep:4:75')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 75, 'A 55-year-old man with depression and alcohol dependence starts bupropion. What is a significant risk?', 'Bupropion lowers the seizure threshold and can be risky, especially in individuals with alcohol dependence.', null),
  (md5('question:pharmacy-exam-prep:4:76')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 76, 'A 45-year-old woman on clozapine for treatment-resistant schizophrenia presents with fever and sore throat. What is the immediate action?', 'Fever and sore throat in a patient on clozapine could indicate agranulocytosis. Checking the white blood cell count is essential.', null),
  (md5('question:pharmacy-exam-prep:4:77')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 77, 'A 70-year-old woman with a history of stroke is prescribed amitriptyline for neuropathic pain. She later reports dry mouth and blurred vision. What is the likely cause?', 'Dry mouth and blurred vision are typical anticholinergic side effects of amitriptyline.', null),
  (md5('question:pharmacy-exam-prep:4:78')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 78, 'A 25-year-old woman with generalized anxiety disorder is treated with buspiron She reports minimal relief after 2 weeks. What is an appropriate action?', 'It may take several weeks for the full effect of buspiron Continuing the current dose and reassessment is appropriate.', null),
  (md5('question:pharmacy-exam-prep:4:79')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 79, 'A 65-year-old man with chronic pain is on high-dose opioids and reports increased sensitivity to pain. What could this indicate?', 'Increased pain sensitivity in this context suggests opioid-induced hyperalgesia, a paradoxical response to long-term opioid use.', null),
  (md5('question:pharmacy-exam-prep:4:80')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 80, 'A 33-year-old woman with schizophrenia on aripiprazole presents with involuntary facial movements. What is the most likely diagnosis?', 'Involuntary facial movements in a patient on antipsychotics like aripiprazole suggest tardive dyskinesia.', null),
  (md5('question:pharmacy-exam-prep:4:81')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 81, 'A 58-year-old woman on topiramate for migraine prophylaxis reports tingling in her hands and feet. What does this indicate?', 'Tingling in extremities is a known side effect of topiramate due to its effects on nerve conduction.', null),
  (md5('question:pharmacy-exam-prep:4:82')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 82, 'A 58-year-old man with Parkinson''s disease on selegiline presents with a severe headache after consuming aged chees What is the most likely cause?', 'Tyramine in aged cheese can cause a hypertensive crisis in patients taking MAO-B inhibitors like selegiline.', null),
  (md5('question:pharmacy-exam-prep:4:83')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 83, 'A patient on long-term lithium therapy for bipolar disorder develops polyuria and polydipsi What is the underlying mechanism?', 'Lithium can cause nephrogenic diabetes insipidus, leading to polyuria (excessive urination) and polydipsia (excessive thirst).', null),
  (md5('question:pharmacy-exam-prep:4:84')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 84, 'A 50-year-old woman with migraine headaches starts topiramate and experiences cognitive dulling. What pharmacological property of topiramate is likely responsible?', 'Carbonic anhydrase inhibition by topiramate can lead to cognitive side effects like dulling of mental alertness.', null),
  (md5('question:pharmacy-exam-prep:4:85')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 85, 'A 40-year-old man with ADHD taking atomoxetine reports erectile dysfunction. What is the likely pharmacodynamic explanation?', 'Atomoxetine''s mechanism as a norepinephrine reuptake inhibitor can impact erectile function due to its effects on the sympathetic nervous system.', null),
  (md5('question:pharmacy-exam-prep:4:86')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 86, 'A patient on warfarin and newly prescribed carbamazepine for trigeminal neuralgia shows a reduced INR. What is the probable interaction?', 'Carbamazepine induces CYP450 enzymes, leading to increased metabolism of warfarin, thus reducing its anticoagulant effect (lowering INR).', null),
  (md5('question:pharmacy-exam-prep:4:87')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 87, 'A 55-year-old man with chronic neuropathic pain is prescribed pregabalin. He has a history of congestive heart failur What is a key concern with pregabalin in this patient?', 'Pregabalin can cause fluid retention, which might exacerbate congestive heart failur', null),
  (md5('question:pharmacy-exam-prep:4:88')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 88, 'A patient with bipolar disorder treated with valproate shows elevated ammonia levels and altered mental status. What is the likely cause?', 'Valproate can cause hyperammonemic encephalopathy, leading to elevated ammonia levels and altered mental status, independent of liver function.', null),
  (md5('question:pharmacy-exam-prep:4:89')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 89, 'A 30-year-old woman on fluoxetine for major depressive disorder plans to conceiv What is a crucial consideration regarding fluoxetine?', 'SSRIs like fluoxetine can lead to withdrawal symptoms in the newborn if used late in pregnancy.', null),
  (md5('question:pharmacy-exam-prep:4:90')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 90, 'A patient on methadone maintenance therapy presents with QTc prolongation. What is the recommended management?', 'Switching to buprenorphine, which has a lower risk of QTc prolongation, is recommended in patients with significant QTc prolongation on methadon', null),
  (md5('question:pharmacy-exam-prep:4:91')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 91, 'A 47-year-old man with treatment-resistant depression is prescribed ketamine infusion. What is a key short-term adverse effect to monitor?', 'Dissociative symptoms are a known short-term adverse effect of ketamine infusion therapy for depression.', null),
  (md5('question:pharmacy-exam-prep:4:92')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 92, 'A 65-year-old woman with Alzheimer''s disease on memantine presents with dizziness and confusion. What is the likely pharmacological cause?', 'Memantine''s action as an NMDA receptor antagonist can cause CNS effects such as dizziness and confusion.', null),
  (md5('question:pharmacy-exam-prep:4:93')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 93, 'A 34-year-old woman on lamotrigine for bipolar disorder develops a rash. What distinguishes a benign rash from one indicative of Stevens-Johnson Syndrome?', 'In Stevens-Johnson Syndrome, the rash typically spreads to mucosal surfaces, distinguishing it from more benign rashes.', null),
  (md5('question:pharmacy-exam-prep:4:94')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 94, 'A 40-year-old man with chronic migraine is prescribed a CGRP antagonist. What is a unique consideration in the use of this class of drugs?', 'Development of antibodies against CGRP antagonists can reduce their efficacy over tim', null),
  (md5('question:pharmacy-exam-prep:4:95')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 95, 'A patient on antipsychotics presents with high fever, muscle rigidity, and altered consciousness. What is the most likely diagnosis?', 'These symptoms are indicative of neuroleptic malignant syndrome, a serious reaction to antipsychotics.', null),
  (md5('question:pharmacy-exam-prep:4:96')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 96, 'A 56-year-old woman on escitalopram for anxiety develops hyponatremi What is the underlying mechanism?', 'Escitalopram can induce SIADH (Syndrome of Inappropriate Antidiuretic Hormone Secretion), leading to hyponatremi', null),
  (md5('question:pharmacy-exam-prep:4:97')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 97, 'A patient with epilepsy on multiple antiepileptics develops a rash, fever, and lymphadenopathy. What is the primary concern?', 'The symptoms suggest DRESS syndrome (Drug Reaction with Eosinophilia and Systemic Symptoms), a serious drug-induced condition.', null),
  (md5('question:pharmacy-exam-prep:4:98')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 98, 'In a patient with major depression, which factor suggests a potential benefit from augmentation with lithium?', 'Non-response to two different antidepressants can indicate the potential benefit of augmentation therapy with lithium.', null),
  (md5('question:pharmacy-exam-prep:4:99')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 99, 'In a patient with refractory epilepsy, what is a key consideration when using the ketogenic diet as an adjunctive treatment?', 'The ketogenic diet can cause vitamin deficiencies due to its restrictive nature, requiring close monitoring and supplementation.', null),
  (md5('question:pharmacy-exam-prep:4:100')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 100, 'A patient with narcolepsy is prescribed sodium oxybat What is a critical safety concern with this medication?', 'Sodium oxybate has a high potential for abuse and misuse due to its CNS depressant effects and is tightly regulate', null),
  (md5('question:pharmacy-exam-prep:4:101')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 101, 'In a patient with Parkinson''s disease experiencing "off" episodes, what is a consideration for the use of apomorphine?', 'Apomorphine can cause hypotension and nausea, especially at the initiation of therapy, requiring careful monitoring.', null),
  (md5('question:pharmacy-exam-prep:4:102')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 102, 'A 30-year-old woman with migraines and a history of stroke is prescribed a triptan. What is a major contraindication for this prescription?', 'Triptans are contraindicated in patients with a history of stroke due to their vasoconstrictive properties.', null),
  (md5('question:pharmacy-exam-prep:4:103')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 103, 'A patient with schizophrenia on long-term olanzapine therapy shows elevated HbA1c levels. What is the most likely cause?', 'Olanzapine can impair insulin sensitivity, leading to elevated HbA1c levels and increased risk of type 2 diabetes.', null),
  (md5('question:pharmacy-exam-prep:4:104')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 104, 'In a patient with opioid use disorder, what is a consideration when prescribing methadone?', 'Methadone can prolong the QTc interval, which requires careful ECG monitoring, especially at higher doses or in patients with cardiac risk factors.', null),
  (md5('question:pharmacy-exam-prep:4:105')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 105, 'A 50-year-old man with alcohol use disorder is prescribed disulfiram. What is a critical counseling point for this patient?', 'Patients on disulfiram must be counseled to avoid all forms of alcohol due to the risk of a severe disulfiram-alcohol reaction.', null),
  (md5('question:pharmacy-exam-prep:4:106')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 106, 'A patient with bipolar disorder experiences a manic episode while on lamotrigine monotherapy. What is the most appropriate pharmacological adjustment?', 'Adding lithium or an antipsychotic is often necessary for managing acute manic episodes in bipolar disorder, as lamotrigine is more effective in preventing depressive episodes.', null),
  (md5('question:pharmacy-exam-prep:4:107')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 107, 'In an elderly patient with glaucoma, which antidepressant should be prescribed with caution due to the risk of increasing intraocular pressure?', 'Amitriptyline, a tricyclic antidepressant, can increase intraocular pressure due to its anticholinergic effects and should be used with caution in glaucom', null),
  (md5('question:pharmacy-exam-prep:4:108')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 108, 'A patient on quetiapine for schizophrenia presents with diabetic ketoacidosis (DK. What is the likely link between the medication and this condition?', 'Quetiapine can cause weight gain and insulin resistance, increasing the risk of type 2 diabetes and potentially leading to DK', null),
  (md5('question:pharmacy-exam-prep:4:109')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 109, 'A patient with epilepsy is prescribed phenytoin and develops gingival hyperplasi What is an appropriate management strategy?', 'Management of phenytoin-induced gingival hyperplasia includes dental referral, good oral hygiene, and potentially switching to another antiepileptic if sever', null),
  (md5('question:pharmacy-exam-prep:4:110')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 110, 'A 55-year-old woman on a high dose of venlafaxine for severe depression presents with hypertension. What pharmacological property of venlafaxine is responsible?', 'Venlafaxine, particularly at higher doses, can cause hypertension due to its serotonin-norepinephrine reuptake inhibition.', null),
  (md5('question:pharmacy-exam-prep:4:111')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 111, 'A patient on long-term corticosteroid therapy for multiple sclerosis (MS) develops Cushing''s syndrom What is the best approach to manage this iatrogenic condition?', 'Gradually tapering the corticosteroid dose can help manage iatrogenic Cushing''s syndrome while avoiding adrenal insufficiency.', null),
  (md5('question:pharmacy-exam-prep:4:112')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 112, 'In a patient with a history of peptic ulcer disease, which antipsychotic medication requires caution due to its potential for gastrointestinal bleeding?', 'Clozapine can increase the risk of gastrointestinal bleeding, particularly in patients with a history of peptic ulcer diseas', null),
  (md5('question:pharmacy-exam-prep:4:113')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 113, 'A 40-year-old woman with a history of migraine headaches is prescribed propranolol. She has asthm What is a major concern with propranolol in this patient?', 'Propranolol, a non-selective beta-blocker, can exacerbate asthma and should be used cautiously in patients with a history of respiratory issues.', null),
  (md5('question:pharmacy-exam-prep:4:114')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 114, 'A patient with refractory partial seizures is started on levetiracetam. They have a history of psychiatric illness. What is a key adverse effect to monitor in this patient?', 'Levetiracetam can cause behavioral changes, including aggression and irritability, particularly in patients with a history of psychiatric illness.', null),
  (md5('question:pharmacy-exam-prep:4:115')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 115, 'A 70-year-old patient with Alzheimer''s disease is prescribed memantin They have a history of cardiac arrhythmias. What is a critical monitoring point for this medication?', 'Memantine can cause QT prolongation, which is of particular concern in patients with a history of cardiac arrhythmias.', null),
  (md5('question:pharmacy-exam-prep:4:116')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 116, 'A patient with HIV and tuberculosis (T is being treated with rifampin and antiretrovirals. What is a major concern with this combination?', 'Rifampin is a potent inducer of the CYP450 enzyme system and can reduce the plasma concentrations and effectiveness of many antiretrovirals.', null),
  (md5('question:pharmacy-exam-prep:4:117')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 117, 'A patient on methotrexate for rheumatoid arthritis develops macrocytic anemi What is a likely cause?', 'Methotrexate is a folic acid antagonist, which can lead to macrocytic anemia due to inhibition of DNA synthesis in red blood cells.', null),
  (md5('question:pharmacy-exam-prep:4:118')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 118, 'A 50-year-old woman with major depressive disorder is treated with a high dose of tricyclic antidepressants (TCAs). She presents with tachycardia, dry mouth, and urinary retention. What is the likely cause?', 'The symptoms are indicative of the anticholinergic side effects of TCAs, which can be prominent, especially at higher doses.', null),
  (md5('question:pharmacy-exam-prep:4:119')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 119, 'A patient with epilepsy on phenobarbital therapy shows decreased efficacy of their oral contraceptiv What is the likely explanation?', 'Phenobarbital induces hepatic enzymes that can increase the metabolism of oral contraceptives, reducing their efficacy.', null),
  (md5('question:pharmacy-exam-prep:4:120')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 120, 'A patient with a history of myocardial infarction is prescribed citalopram for depression. What is an important cardiac consideration for citalopram?', 'Citalopram can cause QT interval prolongation, which is a concern in patients with a history of myocardial infarction.', null),
  (md5('question:pharmacy-exam-prep:4:121')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 121, 'In treating a patient with Parkinson''s disease, what is the primary reason for combining levodopa with carbidopa?', 'Carbidopa is combined with levodopa to reduce peripheral side effects, as it inhibits the decarboxylation of levodopa in the periphery.', null),
  (md5('question:pharmacy-exam-prep:4:122')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 122, 'A patient on antipsychotic therapy develops acute dystoni Which medication is most appropriate for immediate treatment?', 'An anticholinergic agent, such as benztropine or diphenhydramine, is effective for the immediate treatment of antipsychotic-induced acute dystoni', null),
  (md5('question:pharmacy-exam-prep:4:123')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 123, 'A patient with chronic pain and a history of opioid dependence is being considered for tramadol therapy. What is a crucial concern with this medication?', 'Tramadol''s opioid-like effects present a risk of exacerbating opioid dependence in individuals with a history of opioid use disorder.', null),
  (md5('question:pharmacy-exam-prep:4:124')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 124, 'A 55-year-old woman with breast cancer is started on tamoxifen. What is a key risk associated with tamoxifen therapy?', 'Tamoxifen therapy increases the risk of thromboembolic events, necessitating monitoring and preventive measures in at-risk patients.', null),
  (md5('question:pharmacy-exam-prep:4:125')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 125, 'In Parkinson''s disease, which medication is a COMT inhibitor used to prolong the effect of levodopa?', 'Entacapone is a COMT inhibitor that extends the effect of levodopa by inhibiting its metabolism.', null),
  (md5('question:pharmacy-exam-prep:4:126')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 126, 'Which antiepileptic drug is known for its enzyme-inducing properties that can reduce the efficacy of oral contraceptives?', 'Carbamazepine is a potent enzyme inducer that can decrease the effectiveness of oral contraceptives.', null),
  (md5('question:pharmacy-exam-prep:4:127')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 127, 'In multiple sclerosis, which medication is a disease-modifying therapy that requires monitoring for macular edema?', 'Fingolimod requires monitoring for macular edema as a potential side effect.', null),
  (md5('question:pharmacy-exam-prep:4:128')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 128, 'Which benzodiazepine is commonly used for the emergency treatment of seizures?', 'Lorazepam is commonly used for the emergency treatment of seizures due to its rapid onset of action.', null),
  (md5('question:pharmacy-exam-prep:4:129')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 129, 'For a patient with a known history of substance misuse, which of the following would be a less preferable choice for anxiety management?', 'Diazepam, a benzodiazepine, is less preferable due to its potential for misuse and dependence.', null),
  (md5('question:pharmacy-exam-prep:4:130')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 130, 'Which drug is a selective monoamine oxidase B inhibitor used in Parkinson''s disease?', 'Selegiline is a selective MAO-B inhibitor used adjunctively in Parkinson''s disease.', null),
  (md5('question:pharmacy-exam-prep:4:131')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 131, 'Which medication is considered a first-line treatment for major depressive disorder?', 'Sertraline, an SSRI, is often considered a first-line treatment for major depressive disorder.', null),
  (md5('question:pharmacy-exam-prep:4:132')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 132, 'Which antiepileptic drug has a unique mechanism of action involving sodium channel slow inactivation?', 'Lacosamide uniquely promotes slow inactivation of sodium channels.', null),
  (md5('question:pharmacy-exam-prep:4:133')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 133, 'What is the primary risk associated with the use of tricyclic antidepressants in overdose?', 'Cardiotoxicity, including arrhythmias, is a major risk with TCA overdose.', null),
  (md5('question:pharmacy-exam-prep:4:134')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 134, 'Which medication is a first-line treatment for neuropathic pain in diabetic neuropathy?', 'Gabapentin is a first-line treatment for neuropathic pain in diabetic neuropathy.', null),
  (md5('question:pharmacy-exam-prep:4:135')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 135, 'What is the most common side effect of levodopa in the treatment of Parkinson''s disease?', 'Dyskinesia is a common side effect of levodopa therapy in Parkinson''s disease.', null),
  (md5('question:pharmacy-exam-prep:4:136')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 136, 'Which antipsychotic has the highest risk for causing tardive dyskinesia?', 'Haloperidol, a typical antipsychotic, has a higher risk of causing tardive dyskinesia.', null),
  (md5('question:pharmacy-exam-prep:4:137')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 137, 'In migraine prophylaxis, which of the following is a mechanism of action of topiramate?', 'Topiramate acts in part by modulating GABAergic activity.', null),
  (md5('question:pharmacy-exam-prep:4:138')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 138, 'Which medication is considered the gold standard for treating trigeminal neuralgia?', 'Carbamazepine is the gold standard treatment for trigeminal neuralgia.', null),
  (md5('question:pharmacy-exam-prep:4:139')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 139, 'Which antiepileptic drug is known for causing hyponatremia?', 'Carbamazepine can cause hyponatremia, particularly in elderly patients.', null),
  (md5('question:pharmacy-exam-prep:4:140')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 140, 'For the management of restless legs syndrome, which drug class is commonly used?', 'Dopamine agonists are commonly used in the management of restless legs syndrome.', null),
  (md5('question:pharmacy-exam-prep:4:141')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 141, 'In bipolar disorder, what is the primary use of lamotrigine?', 'Lamotrigine is primarily used for maintenance therapy to prevent mood episodes.', null),
  (md5('question:pharmacy-exam-prep:4:142')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 142, 'What is a major side effect of lithium therapy requiring regular monitoring?', 'Thyroid dysfunction, particularly hypothyroidism, is a major side effect of lithium.', null),
  (md5('question:pharmacy-exam-prep:4:143')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 143, 'In Alzheimer''s disease, what is the mechanism of action of donepezil?', 'Donepezil acts as an acetylcholinesterase inhibitor to increase acetylcholine levels.', null),
  (md5('question:pharmacy-exam-prep:4:144')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 144, 'What is the primary mechanism of action of antipsychotic drugs?', 'The primary mechanism of most antipsychotics is dopamine receptor antagonism.', null),
  (md5('question:pharmacy-exam-prep:4:145')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 145, 'What is a major adverse effect of long-term use of levodopa/carbidopa in Parkinson''s disease?', 'Long-term use of levodopa/carbidopa often leads to motor fluctuations in Parkinson''s disease.', null),
  (md5('question:pharmacy-exam-prep:4:146')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 146, 'Which medication is an effective prophylactic treatment for cluster headaches?', 'Verapamil is effective for the prophylactic treatment of cluster headaches.', null),
  (md5('question:pharmacy-exam-prep:4:147')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 147, 'In epilepsy, what is the primary concern with the use of phenytoin?', 'Gingival hyperplasia is a well-known side effect of phenytoin use.', null),
  (md5('question:pharmacy-exam-prep:4:148')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 148, 'Which drug class is most appropriate for the treatment of acute mania in bipolar disorder?', 'Antipsychotics are commonly used for the treatment of acute mania in bipolar disorder.', null),
  (md5('question:pharmacy-exam-prep:4:149')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 149, 'What is the primary effect of naltrexone in the treatment of alcohol dependence?', 'Naltrexone works primarily through opioid receptor blockade to reduce the rewarding effects of alcohol.', null),
  (md5('question:pharmacy-exam-prep:4:150')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 150, 'Which antiepileptic drug is associated with a risk of Stevens-Johnson syndrome, especially in patients with a certain HLA-B allele?', 'Carbamazepine is associated with a risk of Stevens-Johnson syndrome, particularly in patients with the HLA-B*1502 allele.', null),
  (md5('question:pharmacy-exam-prep:4:151')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 151, 'In the management of acute migraine, which medication is used for its antiemetic and prokinetic properties?', 'Metoclopramide is used in acute migraine for its antiemetic and prokinetic effects.', null),
  (md5('question:pharmacy-exam-prep:4:152')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 152, 'For a patient with treatment-resistant depression, which medication could be considered?', 'Ketamine, an NMDA receptor antagonist, is being explored for treatment-resistant depression.', null),
  (md5('question:pharmacy-exam-prep:4:153')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 153, 'Which benzodiazepine has the shortest half-life and is commonly used for procedures requiring brief sedation?', 'Midazolam has a short half-life and is often used for brief procedural sedation.', null),
  (md5('question:pharmacy-exam-prep:4:154')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 154, 'What is the primary concern with the use of risperidone in elderly patients with dementia?', 'Risperidone in elderly patients with dementia is associated with an increased risk of stroke.', null),
  (md5('question:pharmacy-exam-prep:4:155')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 155, 'Which drug is used as an adjunct in Parkinson''s disease for its ability to inhibit catechol-O-methyltransferase (COMT)?', 'Entacapone is a COMT inhibitor used adjunctively in Parkinson''s disease to enhance the effect of levodopa.', null),
  (md5('question:pharmacy-exam-prep:4:156')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 156, 'For acute pain management in opioid-naïve patients, which opioid is commonly preferred due to its lower risk of dependence?', 'Tramadol is often preferred for its lower risk of dependence in opioid-naïve patients.', null),
  (md5('question:pharmacy-exam-prep:4:157')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 157, 'In treating neuropathic pain, which medication''s mechanism of action involves blocking voltage-gated calcium channels?', 'Gabapentin acts by blocking voltage-gated calcium channels.', null),
  (md5('question:pharmacy-exam-prep:4:158')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 158, 'In the treatment of depression, bupropion is unique because it does not typically cause which side effect?', 'Bupropion is less likely to cause sexual dysfunction compared to other antidepressants.', null),
  (md5('question:pharmacy-exam-prep:4:159')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 159, 'Which medication is an alpha-2 delta ligand used in the treatment of generalized anxiety disorder?', 'Pregabalin, an alpha-2 delta ligand, is used in the treatment of generalized anxiety disorder.', null),
  (md5('question:pharmacy-exam-prep:4:160')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 160, 'What is a potential adverse effect of long-term use of antipsychotic medications in treating schizophrenia?', 'Tardive dyskinesia is a potential long-term adverse effect of antipsychotic medications.', null),
  (md5('question:pharmacy-exam-prep:4:161')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 161, 'In the treatment of major depressive disorder, what is the primary advantage of vortioxetine?', 'Vortioxetine is chosen for its lower risk of sexual dysfunction compared to other antidepressants.', null),
  (md5('question:pharmacy-exam-prep:4:162')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 162, 'Which medication is preferred for the prophylactic treatment of migraines in patients with comorbid hypertension?', 'Propranolol, a beta-blocker, is preferred for migraine prophylaxis in patients with comorbid hypertension.', null),
  (md5('question:pharmacy-exam-prep:4:163')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 163, 'In treating schizophrenia, what is the primary benefit of using clozapine?', 'Clozapine is highly effective in treatment-resistant schizophrenia and has a lower risk of extrapyramidal symptoms.', null),
  (md5('question:pharmacy-exam-prep:4:164')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 164, 'What is the primary action of antipsychotics in treating bipolar mania?', 'In bipolar mania, antipsychotics primarily act through dopamine receptor antagonism.', null),
  (md5('question:pharmacy-exam-prep:4:165')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 165, 'In Parkinson''s disease, what is the primary role of MAO-B inhibitors like selegiline and rasagiline?', 'MAO-B inhibitors like selegiline and rasagiline enhance dopamine availability by inhibiting its breakdown.', null),
  (md5('question:pharmacy-exam-prep:4:166')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 166, 'Which antiepileptic drug is specifically known for causing visual field defects?', 'Topiramate is associated with the risk of causing visual field defects.', null),
  (md5('question:pharmacy-exam-prep:4:167')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 167, 'What is a common side effect of antipsychotic medication, characterized by restlessness and an urge to move?', 'Akathisia, a feeling of restlessness and a compelling need to move, is a common side effect of antipsychotic medication.', null),
  (md5('question:pharmacy-exam-prep:4:168')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 168, 'Which medication is primarily used for its neuroprotective effects in amyotrophic lateral sclerosis (ALS)?', 'Riluzole is used for its neuroprotective effects in ALS, potentially slowing disease progression.', null),
  (md5('question:pharmacy-exam-prep:4:169')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 169, 'Which benzodiazepine is preferred for long-term treatment of anxiety due to its lower potential for dependence?', 'Clonazepam is often preferred for long-term treatment of anxiety due to its lower potential for dependence compared to other benzodiazepines.', null),
  (md5('question:pharmacy-exam-prep:4:170')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 170, 'In migraine prophylaxis, what is the mechanism of action of CGRP (calcitonin gene-related peptid antagonists)?', 'CGRP antagonists work by inhibiting CGRP receptors, which play a role in migraine pathophysiology.', null),
  (md5('question:pharmacy-exam-prep:4:171')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 171, 'In Parkinson''s disease, which drug is used for its antiviral properties and also provides mild symptomatic relief?', 'Amantadine, originally an antiviral, is used in Parkinson''s disease for mild symptomatic relief.', null),
  (md5('question:pharmacy-exam-prep:4:172')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 172, 'What is the primary risk associated with the abrupt discontinuation of SSRI medications?', 'Abrupt discontinuation of SSRIs can lead to a withdrawal syndrome.', null),
  (md5('question:pharmacy-exam-prep:4:173')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 173, 'Which antipsychotic medication is most likely to cause metabolic syndrome, including weight gain and diabetes?', 'Olanzapine is associated with a high risk of metabolic syndrome, including weight gain and diabetes.', null),
  (md5('question:pharmacy-exam-prep:4:174')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 174, 'What is a major advantage of second-generation over first-generation antipsychotics in the treatment of schizophrenia?', 'Second-generation antipsychotics have a lower risk of extrapyramidal symptoms.', null),
  (md5('question:pharmacy-exam-prep:4:175')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 175, 'In the treatment of bipolar disorder, what is the primary benefit of using lithium?', 'One of the key benefits of lithium in bipolar disorder is the reduction of suicidal behavior.', null),
  (md5('question:pharmacy-exam-prep:4:176')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 176, 'What is a potential adverse effect of the long-term use of stimulant medications in the treatment of ADHD?', 'Growth suppression is a potential long-term adverse effect of stimulant medications used in ADHD.', null),
  (md5('question:pharmacy-exam-prep:4:177')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 177, 'In managing major depressive disorder, what is a significant advantage of bupropion over other antidepressants?', 'Bupropion has the advantage of a lower incidence of sexual side effects compared to other antidepressants.', null),
  (md5('question:pharmacy-exam-prep:4:178')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 178, 'For the treatment of restless legs syndrome, which medication can cause augmentation of symptoms over time?', 'Ropinirole, a dopamine agonist, can cause augmentation of symptoms in restless legs syndrome over time.', null),
  (md5('question:pharmacy-exam-prep:4:179')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 179, 'In the treatment of epilepsy, which antiepileptic drug is particularly effective in absence seizures?', 'Ethosuximide is particularly effective in treating absence seizures.', null),
  (md5('question:pharmacy-exam-prep:4:180')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 180, 'What is the primary mechanism of action of drugs used in the management of overactive bladder, such as oxybutynin?', 'Drugs like oxybutynin act by antagonizing muscarinic receptors to reduce bladder overactivity.', null),
  (md5('question:pharmacy-exam-prep:4:181')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 181, 'In the treatment of Parkinson''s disease, which of the following is a common side effect of dopamine agonists like pramipexole?', 'Orthostatic hypotension is a common side effect of dopamine agonists like pramipexole.', null),
  (md5('question:pharmacy-exam-prep:4:182')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 182, 'Which medication is used in opioid overdose and works as an opioid receptor antagonist?', 'Naloxone is used in opioid overdose and works as an opioid receptor antagonist.', null),
  (md5('question:pharmacy-exam-prep:4:183')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 183, 'What is the main benefit of using second-generation antipsychotics in schizophrenia compared to first-generation antipsychotics?', 'Second-generation antipsychotics have a lower risk of extrapyramidal side effects compared to first-generation antipsychotics.', null),
  (md5('question:pharmacy-exam-prep:4:184')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 184, 'Which medication, used in bipolar disorder, is known for its risk of causing life-threatening rashes, such as Stevens-Johnson syndrome?', 'Lamotrigine is associated with a risk of life-threatening rashes, including Stevens-Johnson syndrome.', null),
  (md5('question:pharmacy-exam-prep:4:185')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 185, 'What is a primary advantage of newer SSRIs over older antidepressants like TCAs and MAOIs?', 'Newer SSRIs have fewer cardiovascular side effects compared to older antidepressants like TCAs and MAOIs.', null),
  (md5('question:pharmacy-exam-prep:4:186')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 186, 'Which medication is an NMDA receptor antagonist used in the treatment of moderate to severe Alzheimer''s disease?', 'Memantine is an NMDA receptor antagonist used in moderate to severe Alzheimer''s disease.', null),
  (md5('question:pharmacy-exam-prep:4:187')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 187, 'In the treatment of ADHD, what is a common side effect of stimulant medications like amphetamine and methylphenidate?', 'Appetite suppression is a common side effect of stimulant medications used in ADHD.', null),
  (md5('question:pharmacy-exam-prep:4:188')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 188, 'What is the primary therapeutic use of benzodiazepines in the management of epilepsy?', 'Benzodiazepines are primarily used for the acute termination of seizures.', null),
  (md5('question:pharmacy-exam-prep:4:189')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 189, 'Which antidepressant is known for its dual action on both serotonin and norepinephrine reuptake?', 'Venlafaxine is known for its dual action on both serotonin and norepinephrine reuptake.', null),
  (md5('question:pharmacy-exam-prep:4:190')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 190, 'What is the primary advantage of using atypical antipsychotics in the treatment of psychosis in Parkinson''s disease?', 'Atypical antipsychotics are preferred in Parkinson''s disease psychosis due to a reduced risk of worsening parkinsonism.', null),
  (md5('question:pharmacy-exam-prep:4:191')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 191, 'In the management of chronic pain, which medication is used for its ability to inhibit the reuptake of both serotonin and norepinephrine?', 'Duloxetine inhibits the reuptake of both serotonin and norepinephrine, making it effective in chronic pain management.', null),
  (md5('question:pharmacy-exam-prep:4:192')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 192, 'Which medication is commonly used in the treatment of narcolepsy for its ability to increase wakefulness?', 'Modafinil is used in narcolepsy to increase wakefulness.', null),
  (md5('question:pharmacy-exam-prep:4:193')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 193, 'Which medication is used for its neuroprotective effects in multiple sclerosis?', 'Fingolimod is used in multiple sclerosis for its neuroprotective effects. Fingolimod helps to prevent episodes of symptoms and slow the worsening of disability in patients with relapsing-remitting forms of multiple sclerosis.', null),
  (md5('question:pharmacy-exam-prep:4:194')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 194, 'What is the primary mechanism of action of antipsychotics in treating Tourette syndrome?', 'Antipsychotics treat Tourette syndrome primarily through dopamine receptor antagonism.', null),
  (md5('question:pharmacy-exam-prep:4:195')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 195, 'What is a common adverse effect of long-term use of lithium in bipolar disorder?', 'Long-term use of lithium can lead to thyroid dysfunction.', null),
  (md5('question:pharmacy-exam-prep:4:196')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 196, 'Which antiepileptic drug is preferred for use in pregnancy due to lower teratogenic risk?', 'Lamotrigine is preferred in pregnancy due to its relatively lower teratogenic risk.', null),
  (md5('question:pharmacy-exam-prep:4:197')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 197, 'Which medication is often used in the management of myoclonic seizures?', 'Valproate is commonly used in the management of myoclonic seizures. The other options are indicated to be used in other types of seizures, or all types of seizures and are not limited to only being used in myoclonic presentations of epilepsy.', null),
  (md5('question:pharmacy-exam-prep:4:198')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 198, 'What is a significant risk of using tricyclic antidepressants (TCAs) in overdose?', 'Cardiotoxicity is a significant risk in the overdose of TCAs.', null),
  (md5('question:pharmacy-exam-prep:4:199')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 199, 'In the treatment of ADHD, what is the mechanism of action of non-stimulant medications like atomoxetine?', 'Atomoxetine, a non-stimulant used in ADHD, works by inhibiting norepinephrine reuptake.', null),
  (md5('question:pharmacy-exam-prep:4:200')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 200, 'Which medication is used as a first-line treatment for prophylaxis of migraine headaches?', 'Propranolol is commonly used as a first-line treatment for migraine prophylaxis.', null),
  (md5('question:pharmacy-exam-prep:4:201')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 201, 'What is the primary action of benzodiazepines in the treatment of muscle spasticity?', 'Benzodiazepines modulate GABA-A receptors, which can help in reducing muscle spasticity.', null),
  (md5('question:pharmacy-exam-prep:4:202')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 202, 'Which antiepileptic drug is associated with the risk of causing hyponatremia?', 'Carbamazepine is associated with the risk of hyponatremia, particularly in elderly patients.', null),
  (md5('question:pharmacy-exam-prep:4:203')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 203, 'Which medication is used in bipolar disorder for its mood-stabilizing properties and also requires monitoring for hepatotoxicity?', 'Valproate is used for its mood-stabilizing properties in bipolar disorder and requires monitoring for hepatotoxicity.', null),
  (md5('question:pharmacy-exam-prep:4:204')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 204, 'In the treatment of depression, what is the primary benefit of using SSRIs over TCAs?', 'SSRIs are preferred over TCAs due to their fewer side effects. Both SSRIs and TCAs impact serotonin; however, TCAs have lower selectivity than SSRIs and act on receptors throughout the body, giving patients a higher risk of having side effects.', null),
  (md5('question:pharmacy-exam-prep:4:205')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 205, 'Which antipsychotic medication is known for a lower risk of metabolic syndrome but a higher risk of extrapyramidal symptoms?', 'Haloperidol has a lower risk of metabolic syndrome but a higher risk of extrapyramidal symptoms.', null),
  (md5('question:pharmacy-exam-prep:4:206')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 206, 'What is the mechanism of action of modafinil in the treatment of narcolepsy?', 'Modafinil promotes wakefulness in narcolepsy primarily through increasing histamine release in the brain.', null),
  (md5('question:pharmacy-exam-prep:4:207')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 207, 'Which medication is used in opioid dependence and works as a partial opioid agonist?', 'Buprenorphine is used in opioid dependence as a partial opioid agonist.', null),
  (md5('question:pharmacy-exam-prep:4:208')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 208, 'In migraine treatment, what is the primary action of serotonin agonists like sumatriptan?', 'Sumatriptan and similar drugs act by causing vasoconstriction, which is beneficial in treating migraines.', null),
  (md5('question:pharmacy-exam-prep:4:209')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 209, 'What is the primary risk associated with the use of antipsychotic medication in elderly patients with dementia?', 'Antipsychotic medication in elderly patients with dementia is associated with an increased risk of stroke.', null),
  (md5('question:pharmacy-exam-prep:4:210')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 210, 'In the management of chronic pain, what is the mechanism of action of SNRIs like duloxetine?', 'SNRIs like duloxetine work by inhibiting the reuptake of both serotonin and norepinephrine. By activating several cerebral prefrontal areas and influencing the spinal pain pathways, duloxetine modulates pain.', null),
  (md5('question:pharmacy-exam-prep:4:211')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 211, 'Which medication, used in the treatment of bipolar disorder, is known for its risk of causing rash and requires a slow titration?', 'Lamotrigine is known for its risk of causing rash and requires slow titration to minimize this risk.', null),
  (md5('question:pharmacy-exam-prep:4:212')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 212, 'A junior doctor has approached you having prescribed medication for myasthenia gravis asking you, as the pharmacist, what the mechanism of action is and how it works. What is the primary action of acetylcholinesterase inhibitors in the management of myasthenia gravis?', 'Acetylcholinesterase inhibitors enhance cholinergic transmission, which is beneficial in myasthenia gravis.', null),
  (md5('question:pharmacy-exam-prep:4:213')::uuid, md5('quiz:pharmacy-exam-prep:4')::uuid, 213, 'In treating epilepsy, what is the primary benefit of using newer antiepileptics like levetiracetam over older drugs like phenytoin?', 'Newer antiepileptics like levetiracetam generally have fewer drug interactions compared to older drugs like phenytoin.', null)
insert into public.quiz_answers (id, question_id, position, text, is_correct) values
  (md5('answer:pharmacy-exam-prep:4:1:1')::uuid, md5('question:pharmacy-exam-prep:4:1')::uuid, 1, 'Inhibition of sodium channels', false),
