insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('question:pharmacy-exam-prep:5:1')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 1, 'A 45-year-old male with a history of penicillin allergy presents with severe cellulitis. Which antibiotic should be avoided in this patient?', null, null),
  (md5('question:pharmacy-exam-prep:5:2')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 2, 'A pregnant woman with a urinary tract infection requires antibiotic treatment. Which antibiotic should be avoided due to potential teratogenic effects?', null, null),
  (md5('question:pharmacy-exam-prep:5:3')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 3, 'A patient is prescribed linezolid for a serious Gram-positive infection. Which adverse effect should be monitored closely?', null, null),
  (md5('question:pharmacy-exam-prep:5:4')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 4, 'A 30-year-old male with a confirmed diagnosis of tuberculosis is started on a multidrug regimen. What should be co-prescribed to prevent peripheral neuropathy?', null, null),
  (md5('question:pharmacy-exam-prep:5:5')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 5, 'A patient with a history of methicillin-resistant Staphylococcus aureus (MRSA) infection requires oral therapy. Which agent is effective against MRSA?', null, null),
  (md5('question:pharmacy-exam-prep:5:6')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 6, 'A 55-year-old patient is diagnosed with a urinary tract infection, and their urine culture reveals Escherichia coli. Which antibiotic is the best choice for empiric therapy?', null, null),
  (md5('question:pharmacy-exam-prep:5:7')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 7, 'A 60-year-old patient with a history of Clostridium difficile infection (CDI) needs treatment for a skin abscess. Which antibiotic should be avoided due to a higher risk of CDI recurrence?', null, null),
  (md5('question:pharmacy-exam-prep:5:8')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 8, 'A patient is prescribed metronidazole for a bacterial vaginosis (BV) infection. What should be avoided while on this medication?', null, null),
  (md5('question:pharmacy-exam-prep:5:9')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 9, 'A 70-year-old patient with a history of chronic kidney disease (CKD) requires treatment for a urinary tract infection. Which antibiotic should be dose-adjusted in this patient?', null, null),
  (md5('question:pharmacy-exam-prep:5:10')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 10, 'A patient is on long-term therapy with amphotericin B for a fungal infection. Which electrolyte imbalance should be closely monitored?', null, null),
  (md5('question:pharmacy-exam-prep:5:11')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 11, 'A 25-year-old female presents with a severe skin infection caused by Pseudomonas aeruginosa. Which antibiotic is typically reserved for Pseudomonas infections?', null, null),
  (md5('question:pharmacy-exam-prep:5:12')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 12, 'A patient on long-term antifungal therapy with ketoconazole complains of erectile dysfunction. What is the most likely cause of this adverse effect?', null, null),
  (md5('question:pharmacy-exam-prep:5:13')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 13, 'A 40-year-old patient is diagnosed with a skin infection caused by a β-lactamase-producing organism. Which antibiotic is the best choice in this scenario?', null, null),
  (md5('question:pharmacy-exam-prep:5:14')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 14, 'A 60-year-old male with chronic obstructive pulmonary disease (COP is prescribed prophylactic antibiotics during exacerbations. Which antibiotic is recommended for this purpose?', null, null),
  (md5('question:pharmacy-exam-prep:5:15')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 15, 'A patient with severe sepsis is started on an empiric antibiotic regimen. Which antibiotic combination covers both Gram-negative and Gram-positive organisms effectively?', null, null),
  (md5('question:pharmacy-exam-prep:5:16')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 16, 'A patient develops severe diarrhea after taking an antibiotic. What is the most likely causative agent of antibiotic-associated diarrhea (AA?', null, null),
  (md5('question:pharmacy-exam-prep:5:17')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 17, 'A 35-year-old patient with a history of liver cirrhosis requires empiric antibiotic therapy for an abdominal infection. Which antibiotic should be used with caution due to hepatotoxicity risk?', null, null),
  (md5('question:pharmacy-exam-prep:5:18')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 18, 'A 28-year-old female presents with a severe skin infection, and her medical history includes recent use of oral contraceptives. Which antibiotic may reduce contraceptive effectiveness?', null, null),
  (md5('question:pharmacy-exam-prep:5:19')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 19, 'A patient with a history of drug-resistant tuberculosis (T is started on a second-line TB regimen. Which antibiotic is commonly used in such regimens for drug-resistant TB?', null, null),
  (md5('question:pharmacy-exam-prep:5:20')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 20, 'A 50-year-old male with a history of myasthenia gravis is prescribed an antibiotic for a respiratory infection. Which antibiotic should be avoided due to potential exacerbation of myasthenia gravis symptoms?', null, null),
  (md5('question:pharmacy-exam-prep:5:21')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 21, 'Which antibiotics inhibit bacterial protein synthesis by binding to the 30S ribosomal subunit?', null, null),
  (md5('question:pharmacy-exam-prep:5:22')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 22, 'What is the primary mechanism of action of β-lactam antibiotics like penicillin?', null, null),
  (md5('question:pharmacy-exam-prep:5:23')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 23, 'Which antifungal agents inhibit ergosterol synthesis in fungal cell membranes?', null, null),
  (md5('question:pharmacy-exam-prep:5:24')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 24, 'Which class of antibiotics interferes with bacterial DNA replication by targeting DNA gyrase?', null, null),
  (md5('question:pharmacy-exam-prep:5:25')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 25, 'What is the primary mechanism of action of metronidazole in treating anaerobic bacterial infections?', null, null),
  (md5('question:pharmacy-exam-prep:5:26')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 26, 'Which antiviral drug inhibits the activity of the viral enzyme reverse transcriptase in the treatment of HIV?', null, null),
  (md5('question:pharmacy-exam-prep:5:27')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 27, 'What is the primary mechanism of action of sulfonamide antibiotics?', null, null),
  (md5('question:pharmacy-exam-prep:5:28')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 28, 'Which class of antifungal drugs interferes with fungal cell membrane function by binding to ergosterol?', null, null),
  (md5('question:pharmacy-exam-prep:5:29')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 29, 'Which antibiotic class inhibits bacterial cell wall synthesis by binding to penicillin-binding proteins (PBPs)?', null, null),
  (md5('question:pharmacy-exam-prep:5:30')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 30, 'What is the primary mechanism of action of oseltamivir in the treatment of influenza?', null, null),
  (md5('question:pharmacy-exam-prep:5:31')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 31, 'Which antiviral drug inhibits the synthesis of viral DNA by acting as a nucleoside analog?', null, null),
  (md5('question:pharmacy-exam-prep:5:32')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 32, 'What is the primary mechanism of action of amphotericin B in the treatment of fungal infections?', null, null),
  (md5('question:pharmacy-exam-prep:5:33')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 33, 'Which class of antibiotics inhibits bacterial protein synthesis by binding to the 50S ribosomal subunit?', null, null),
  (md5('question:pharmacy-exam-prep:5:34')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 34, 'Which antifungal drug class interferes with fungal cell wall synthesis by inhibiting β-(1,3)-D-glucan synthesis?', null, null),
  (md5('question:pharmacy-exam-prep:5:35')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 35, 'Which antiviral drug inhibits the synthesis of viral RNA by blocking RNA-dependent RNA polymerase?', null, null),
  (md5('question:pharmacy-exam-prep:5:36')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 36, 'What is the primary mechanism of action of daptomycin, an antibiotic used to treat Gram-positive bacterial infections?', null, null),
  (md5('question:pharmacy-exam-prep:5:37')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 37, 'Which class of antibiotics inhibits bacterial protein synthesis by binding to the 50S ribosomal subunit and disrupting peptide bond formation?', null, null),
  (md5('question:pharmacy-exam-prep:5:38')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 38, 'What is the primary mechanism of action of acyclovir, an antiviral medication used to treat herpes virus infections?', null, null),
  (md5('question:pharmacy-exam-prep:5:39')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 39, 'Which antifungal drug class inhibits fungal cell wall synthesis by inhibiting the enzyme 1,3-β-D-glucan synthase?', null, null),
  (md5('question:pharmacy-exam-prep:5:40')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 40, 'What is the primary mechanism of action of rifampicin, an antibiotic commonly used to treat tuberculosis?', null, null),
  (md5('question:pharmacy-exam-prep:5:41')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 41, 'A 55-year-old patient with type 2 diabetes is taking metformin for glycemic control. The patient develops a urinary tract infection and is prescribed ciprofloxacin. What potential drug interaction should the pharmacist warn the patient about?', null, null),
  (md5('question:pharmacy-exam-prep:5:42')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 42, 'A 70-year-old patient with hypertension and osteoarthritis is taking warfarin for anticoagulation. The patient develops a skin infection and is prescribed trimethoprim/sulfamethoxazole. Which potential drug interaction should be addressed?', null, null),
  (md5('question:pharmacy-exam-prep:5:43')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 43, 'A 40-year-old patient with epilepsy is on long-term phenytoin therapy. The patient contracts a respiratory infection and is prescribed erythromycin. What potential drug interaction is a concern with this combination?', null, null),
  (md5('question:pharmacy-exam-prep:5:44')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 44, 'A 65-year-old patient with chronic kidney disease is prescribed gentamicin for a severe urinary tract infection. The patient is also taking furosemide for edema. What potential drug interaction should be considered in this case?', null, null),
  (md5('question:pharmacy-exam-prep:5:45')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 45, 'A 50-year-old patient with depression is taking sertraline, an SSRI antidepressant. The patient develops a respiratory infection and is prescribed linezolid. What potential drug interaction should be communicated to the patient?', null, null),
  (md5('question:pharmacy-exam-prep:5:46')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 46, 'A 30-year-old patient with asthma is prescribed theophylline for bronchodilation. The patient develops a skin infection and is prescribed clarithromycin. What potential drug interaction should be discussed with the patient?', null, null),
  (md5('question:pharmacy-exam-prep:5:47')::uuid, md5('quiz:pharmacy-exam-prep:5')::uuid, 47, 'A 60-year-old patient with chronic pain is taking oxycodone for pain management. The patient develops a urinary tract infection and is prescribed ciprofloxacin. What potential drug interaction should be discussed with the patient?', null, null),
