insert into public.chapters (id, course_id, position, title) values
  (md5('chapter:pharmacy-exam-prep:6')::uuid, md5('course:pharmacy-exam-prep')::uuid, 6, 'Endocrine')
insert into public.quizzes (id, chapter_id, title, position, is_preview) values
  (md5('quiz:pharmacy-exam-prep:6')::uuid, md5('chapter:pharmacy-exam-prep:6')::uuid, 'Endocrine', 1, false)
insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('question:pharmacy-exam-prep:6:1')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 1, 'What is the primary mechanism of action of metformin in type 2 diabetes?', 'Metformin primarily decreases hepatic glucose production, thus lowering blood glucose levels.', null),
  (md5('question:pharmacy-exam-prep:6:2')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 2, 'How does levothyroxine work in hypothyroidism?', 'Levothyroxine acts as a synthetic form of thyroxine (T4), replacing the hormone that is deficient in hypothyroidism.', null),
  (md5('question:pharmacy-exam-prep:6:3')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 3, 'What is the mechanism of action of pioglitazone in diabetes management?', 'Pioglitazone is a PPAR-gamma agonist which increases insulin sensitivity in peripheral tissue, particularly in muscle and fat.', null),
  (md5('question:pharmacy-exam-prep:6:4')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 4, 'How does exenatide function in the treatment of type 2 diabetes?', 'Exenatide enhances glucose-dependent insulin secretion, suppresses inappropriately elevated glucagon secretion, and slows gastric emptying.', null),
  (md5('question:pharmacy-exam-prep:6:5')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 5, 'What is the main action of spironolactone in primary hyperaldosteronism?', 'Spironolactone acts as an aldosterone antagonist, blocking aldosterone receptors, primarily in the kidneys.', null),
  (md5('question:pharmacy-exam-prep:6:6')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 6, 'Which mechanism of action best describes metformin?', 'Metformin activates AMPK in hepatocytes, leading to reduced hepatic glucose production.', null),
  (md5('question:pharmacy-exam-prep:6:7')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 7, 'What is the primary mechanism of action of thyroxine (levothyroxin)?', 'Levothyroxine acts as a synthetic thyroid hormone that binds to thyroid hormone receptors, mimicking the action of endogenous thyroxin.', null),
  (md5('question:pharmacy-exam-prep:6:8')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 8, 'Which of the following best describes the mechanism of action of a somatostatin analog like octreotide?', 'Octreotide inhibits the secretion of growth hormone and other peptides by binding to somatostatin receptors.', null),
  (md5('question:pharmacy-exam-prep:6:9')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 9, 'What is the primary mechanism of action of glucagon-like peptide-1 (GLP-1) agonists, such as exenatide?', 'GLP-1 agonists stimulate insulin secretion and inhibit glucagon secretion, among other effects.', null),
  (md5('question:pharmacy-exam-prep:6:10')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 10, 'How do thiazolidinediones (e.g., pioglitazone) primarily exert their therapeutic effects in diabetes management?', 'Thiazolidinediones activate PPAR-gamma, which regulates genes involved in glucose and lipid metabolism.', null),
  (md5('question:pharmacy-exam-prep:6:11')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 11, 'Which of the following best represents the mechanism of action of propylthiouracil (PTU) in the treatment of hyperthyroidism?', 'PTU inhibits the synthesis of thyroid hormones by inhibiting thyroid peroxidase.', null),
  (md5('question:pharmacy-exam-prep:6:12')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 12, 'What is the primary mechanism of action of desmopressin (DDAVP) in the treatment of diabetes insipidus?', 'Desmopressin is a synthetic analog of ADH (vasopressin) that acts on ADH receptors to promote water reabsorption in the kidneys.', null),
  (md5('question:pharmacy-exam-prep:6:13')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 13, 'Which of the following describes the mechanism of action of calcitonin in the treatment of osteoporosis?', 'Calcitonin inhibits bone resorption by osteoclasts, leading to decreased bone turnover.', null),
  (md5('question:pharmacy-exam-prep:6:14')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 14, 'How do sulfonylureas (e.g., glibenclamide) primarily lower blood glucose levels in diabetes?', 'Sulfonylureas stimulate insulin secretion from pancreatic beta cells.', null),
  (md5('question:pharmacy-exam-prep:6:15')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 15, 'Which mechanism of action best describes the effect of alendronate in the treatment of osteoporosis?', 'Alendronate inhibits bone resorption by osteoclasts, leading to increased bone density.', null),
  (md5('question:pharmacy-exam-prep:6:16')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 16, 'What is the primary mechanism of action of acarbose in the management of diabetes?', 'Acarbose inhibits alpha-glucosidase enzymes in the intestine, reducing glucose absorption after meals.', null),
  (md5('question:pharmacy-exam-prep:6:17')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 17, 'How do somatropin and other growth hormone (GH) replacement therapies primarily function in patients with GH deficiency?', 'GH replacement therapies like somatropin stimulate GH receptors to promote growth and metabolic effects.', null),
  (md5('question:pharmacy-exam-prep:6:18')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 18, 'Which mechanism of action best describes the effect of metyrapone in the treatment of Cushing''s syndrome?', 'Metyrapone inhibits cortisol synthesis by blocking 11-beta-hydroxylase enzyme.', null),
  (md5('question:pharmacy-exam-prep:6:19')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 19, 'How does leuprorelin (a GnRH agonist) primarily influence the secretion of gonadotropins (LH and FSH)?', 'Leuprorelin initially stimulates, but ultimately inhibits, gonadotropin release when used continuously.', null),
  (md5('question:pharmacy-exam-prep:6:20')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 20, 'Which mechanism of action best characterizes the effect of levothyroxine on the thyroid gland?', 'Levothyroxine acts as a synthetic thyroid hormone, stimulating the synthesis of thyroid hormones in the thyroid gland.', null),
  (md5('question:pharmacy-exam-prep:6:21')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 21, 'How do glucocorticoids, like prednisolone, primarily exert their anti-inflammatory effects?', 'Glucocorticoids primarily inhibit the synthesis of prostaglandins, which are pro-inflammatory mediators.', null),
  (md5('question:pharmacy-exam-prep:6:22')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 22, 'What is the primary mechanism of action of desmopressin in the treatment of nocturnal enuresis (bedwetting)?', 'Desmopressin stimulates ADH receptors, leading to increased water reabsorption in the kidneys and reduced nocturnal urine production.', null),
  (md5('question:pharmacy-exam-prep:6:23')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 23, 'How do selective estrogen receptor modulators (SERMs) like tamoxifen primarily affect estrogen signaling?', 'Tamoxifen acts as an estrogen receptor agonist in certain tissues and antagonist in others, depending on the tissue type.', null),
  (md5('question:pharmacy-exam-prep:6:24')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 24, 'Which mechanism of action best describes how alendronate reduces the risk of osteoporotic fractures?', 'Alendronate primarily inhibits bone resorption, helping to increase bone density and reduce the risk of fractures.', null),
  (md5('question:pharmacy-exam-prep:6:25')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 25, 'How does metformin primarily affect glucose metabolism in patients with type 2 diabetes?', 'Metformin primarily inhibits hepatic glucose production, reducing blood glucose levels in type 2 diabetes.', null),
  (md5('question:pharmacy-exam-prep:6:26')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 26, 'What is the primary mechanism of action of recombinant human insulin, such as insulin lispro?', 'Insulin lispro stimulates insulin receptors, allowing glucose uptake into cells and lowering blood glucose levels.', null),
  (md5('question:pharmacy-exam-prep:6:27')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 27, 'How do thiazolidinediones (e.g., pioglitazone) primarily improve insulin sensitivity in diabetes?', 'Thiazolidinediones activate PPAR-gamma, improving insulin sensitivity and regulating glucose metabolism.', null),
  (md5('question:pharmacy-exam-prep:6:28')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 28, 'Which of the following best describes the mechanism of action of somatropin (recombinant human growth hormone)?', 'Somatropin stimulates growth hormone receptors, promoting growth and metabolic effects in patients with growth hormone deficiency.', null),
  (md5('question:pharmacy-exam-prep:6:29')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 29, 'How does propylthiouracil (PTU) primarily reduce thyroid hormone levels in hyperthyroidism?', 'PTU inhibits thyroid hormone synthesis by blocking thyroid peroxidase enzyme activity.', null),
  (md5('question:pharmacy-exam-prep:6:30')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 30, 'What is the primary mechanism of action of recombinant parathyroid hormone (teriparatide) in the treatment of osteoporosis?', 'Teriparatide stimulates bone formation and increases bone density in osteoporotic patients.', null),
  (md5('question:pharmacy-exam-prep:6:31')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 31, 'How do aromatase inhibitors, like anastrozole, primarily affect estrogen levels in breast cancer treatment?', 'Aromatase inhibitors block the synthesis of estrogen by inhibiting the aromatase enzyme.', null),
  (md5('question:pharmacy-exam-prep:6:32')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 32, 'Which mechanism of action best characterizes the effect of prednisolone in the treatment of autoimmune diseases?', 'Prednisolone primarily inhibits prostaglandin synthesis, reducing inflammation in autoimmune diseases.', null),
  (md5('question:pharmacy-exam-prep:6:33')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 33, 'What is the primary mechanism of action of exenatide in the management of type 2 diabetes?', 'Exenatide stimulates insulin secretion and inhibits glucagon secretion, helping to lower blood glucose levels in type 2 diabetes.', null),
  (md5('question:pharmacy-exam-prep:6:34')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 34, 'How does metyrapone primarily influence cortisol levels in patients with Cushing''s syndrome?', 'Metyrapone inhibits cortisol synthesis by blocking 11-beta-hydroxylase enzyme.', null),
  (md5('question:pharmacy-exam-prep:6:35')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 35, 'Which of the following best describes the mechanism of action of leuprorelin in the treatment of prostate cancer?', 'Leuprorelin initially stimulates, but ultimately inhibits, gonadotropin release, reducing testosterone levels in prostate cancer therapy.', null),
  (md5('question:pharmacy-exam-prep:6:36')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 36, 'What is the primary mechanism of action of levothyroxine in the treatment of hypothyroidism?', 'Levothyroxine is a synthetic form of thyroid hormone that binds to and activates thyroid hormone receptors, compensating for low endogenous thyroid hormone levels.', null),
  (md5('question:pharmacy-exam-prep:6:37')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 37, 'How do glucocorticoids, such as prednisolone, primarily influence inflammation and immune responses?', 'Glucocorticoids primarily inhibit cytokine production, leading to reduced inflammation and immune responses.', null),
  (md5('question:pharmacy-exam-prep:6:38')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 38, 'What is the primary mechanism of action of desmopressin (DDAVP) in the treatment of diabetes insipidus?', 'Desmopressin binds to and activates ADH receptors in the renal tubules, promoting water reabsorption and reducing urine volume in diabetes insipidus.', null),
  (md5('question:pharmacy-exam-prep:6:39')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 39, 'How do somatostatin analogs like octreotide primarily affect hormone secretion in acromegaly and neuroendocrine tumors?', 'Octreotide binds to somatostatin receptors and inhibits the secretion of growth hormone and other peptides, reducing hormonal excess in acromegaly and neuroendocrine tumors.', null),
  (md5('question:pharmacy-exam-prep:6:40')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 40, 'What is the primary mechanism of action of glucagon-like peptide-1 (GLP-1) agonists like exenatide in the treatment of type 2 diabetes?', 'GLP-1 agonists like exenatide bind to and activate GLP-1 receptors, stimulating insulin secretion and inhibiting glucagon release in type 2 diabetes.', null),
  (md5('question:pharmacy-exam-prep:6:41')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 41, 'How do thiazolidinediones (e.g., pioglitazone) primarily improve insulin sensitivity in type 2 diabetes?', 'Thiazolidinediones activate PPAR-gamma, which regulates genes involved in glucose and lipid metabolism, improving insulin sensitivity in type 2 diabetes.', null),
  (md5('question:pharmacy-exam-prep:6:42')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 42, 'What is the primary mechanism of action of propylthiouracil (PTU) in the treatment of hyperthyroidism?', 'PTU inhibits thyroid hormone synthesis by blocking thyroid peroxidase enzyme activity, reducing excessive thyroid hormone production in hyperthyroidism.', null),
  (md5('question:pharmacy-exam-prep:6:43')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 43, 'How does calcitonin primarily affect bone metabolism and calcium homeostasis?', 'Calcitonin inhibits bone resorption by osteoclasts, helping to maintain bone density and calcium homeostasis.', null),
  (md5('question:pharmacy-exam-prep:6:44')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 44, 'What is the primary mechanism of action of sulfonylureas (e.g., glibenclamide) in the treatment of type 2 diabetes?', 'Sulfonylureas stimulate insulin secretion from pancreatic beta cells, which helps lower blood glucose levels in type 2 diabetes.', null),
  (md5('question:pharmacy-exam-prep:6:45')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 45, 'How do alpha-glucosidase inhibitors like acarbose primarily affect postprandial blood glucose levels in diabetes management?', 'Acarbose inhibits alpha-glucosidase enzymes in the intestine, delaying carbohydrate digestion and reducing post-meal glucose spikes.', null),
  (md5('question:pharmacy-exam-prep:6:46')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 46, 'What is the primary mechanism of action of somatropin (recombinant human growth hormone) in growth hormone deficiency?', 'Somatropin binds to and stimulates growth hormone receptors, promoting growth and metabolic effects in patients with growth hormone deficiency.', null),
  (md5('question:pharmacy-exam-prep:6:47')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 47, 'How does metyrapone primarily affect cortisol levels in the treatment of Cushing''s syndrome?', 'Metyrapone inhibits cortisol synthesis by blocking the 11-beta-hydroxylase enzyme, reducing cortisol levels in Cushing''s syndrome.', null),
  (md5('question:pharmacy-exam-prep:6:48')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 48, 'What is the primary mechanism of action of leuprorelin (a GnRH agonist) in the treatment of hormone-sensitive prostate cancer?', 'Leuprorelin initially stimulates, but ultimately inhibits, gonadotropin release, reducing testosterone levels in hormone-sensitive prostate cancer.', null),
  (md5('question:pharmacy-exam-prep:6:49')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 49, 'How do bisphosphonates like alendronate primarily reduce the risk of osteoporotic fractures?', 'Bisphosphonates like alendronate primarily inhibit bone resorption, increasing bone density and reducing the risk of fractures in osteoporosis.', null),
  (md5('question:pharmacy-exam-prep:6:50')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 50, 'What is the primary mechanism of action of recombinant insulin lispro in the management of diabetes mellitus?', 'Insulin lispro stimulates insulin receptors, promoting glucose uptake into cells and lowering blood glucose levels in diabetes.', null),
  (md5('question:pharmacy-exam-prep:6:51')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 51, 'How does prednisolone primarily exert its anti-inflammatory effects in the treatment of autoimmune diseases?', 'Prednisolone primarily inhibits prostaglandin synthesis, reducing inflammation in autoimmune diseases.', null),
  (md5('question:pharmacy-exam-prep:6:52')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 52, 'What is the primary mechanism of action of exenatide in the management of type 2 diabetes?', 'Exenatide stimulates insulin secretion and inhibits glucagon secretion, helping to lower blood glucose levels in type 2 diabetes.', null),
  (md5('question:pharmacy-exam-prep:6:53')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 53, 'How does metyrosine primarily influence catecholamine levels in the treatment of pheochromocytoma?', 'Metyrosine inhibits catecholamine synthesis by blocking tyrosine hydroxylase, reducing excessive catecholamine production in pheochromocytoma.', null),
  (md5('question:pharmacy-exam-prep:6:54')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 54, 'What is the primary mechanism of action of insulin in the management of diabetes mellitus?', 'Insulin binds to and stimulates insulin receptors, facilitating glucose uptake into cells and lowering blood glucose levels in diabetes.', null),
  (md5('question:pharmacy-exam-prep:6:55')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 55, 'How do thiazide diuretics like hydrochlorothiazide primarily reduce blood pressure in hypertension treatment?', 'Thiazide diuretics inhibit sodium reabsorption in the renal tubules, leading to increased water and salt excretion, reducing blood volume and lowering blood pressure.', null),
  (md5('question:pharmacy-exam-prep:6:56')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 56, 'What is the primary mechanism of action of methimazole in the treatment of hyperthyroidism?', 'Methimazole inhibits thyroid hormone synthesis by blocking the thyroid peroxidase enzyme, reducing excessive thyroid hormone production in hyperthyroidism.', null),
  (md5('question:pharmacy-exam-prep:6:57')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 57, 'How does calcitonin primarily affect bone metabolism and calcium homeostasis?', 'Calcitonin inhibits bone resorption by osteoclasts, helping to maintain bone density and calcium homeostasis.', null),
  (md5('question:pharmacy-exam-prep:6:58')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 58, 'What is the primary mechanism of action of recombinant parathyroid hormone (teriparatide) in the treatment of osteoporosis?', 'Teriparatide stimulates bone formation and increases bone density in osteoporotic patients.', null),
  (md5('question:pharmacy-exam-prep:6:59')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 59, 'How do angiotensin II receptor blockers (ARBs) like losartan primarily lower blood pressure in hypertensive patients?', 'ARBs block angiotensin II receptors, preventing angiotensin II''s effects and lowering blood pressure.', null),
  (md5('question:pharmacy-exam-prep:6:60')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 60, 'What is the primary mechanism of action of recombinant human growth hormone (somatropin) in the treatment of growth hormone deficiency?', 'Somatropin binds to and stimulates growth hormone receptors, promoting growth and metabolic effects in patients with growth hormone deficiency.', null),
  (md5('question:pharmacy-exam-prep:6:61')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 61, 'How does metyrapone primarily affect cortisol levels in the treatment of Cushing''s syndrome?', 'Metyrapone inhibits cortisol synthesis by blocking the 11-beta-hydroxylase enzyme, reducing cortisol levels in Cushing''s syndrome.', null),
  (md5('question:pharmacy-exam-prep:6:62')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 62, 'What is the primary mechanism of action of leuprorelin (a GnRH agonist) in the treatment of hormone-sensitive prostate cancer?', 'Leuprorelin initially stimulates, but ultimately inhibits, gonadotropin release, reducing testosterone levels in hormone-sensitive prostate cancer.', null),
  (md5('question:pharmacy-exam-prep:6:63')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 63, 'How do bisphosphonates like alendronate primarily reduce the risk of osteoporotic fractures?', 'Bisphosphonates like alendronate primarily inhibit bone resorption, increasing bone density and reducing the risk of fractures in osteoporosis.', null),
  (md5('question:pharmacy-exam-prep:6:64')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 64, 'What is the primary mechanism of action of recombinant insulin lispro in the management of diabetes mellitus?', 'Insulin lispro stimulates insulin receptors, promoting glucose uptake into cells and lowering blood glucose levels in diabetes.', null),
  (md5('question:pharmacy-exam-prep:6:65')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 65, 'How do dopamine agonists like bromocriptine primarily influence prolactin levels in the treatment of hyperprolactinemia?', 'Dopamine agonists like bromocriptine bind to and stimulate dopamine receptors, inhibiting prolactin release in hyperprolactinemia.', null),
  (md5('question:pharmacy-exam-prep:6:66')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 66, 'What is the primary mechanism of action of aromatase inhibitors like anastrozole in the treatment of breast cancer?', 'Aromatase inhibitors like anastrozole block the conversion of androgens to estrogen, reducing estrogen levels in breast cancer treatment.', null),
  (md5('question:pharmacy-exam-prep:6:67')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 67, 'What is the primary mechanism of action of metformin in the management of type 2 diabetes?', 'Metformin primarily inhibits hepatic glucose production, improving insulin sensitivity in type 2 diabetes.', null),
  (md5('question:pharmacy-exam-prep:6:68')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 68, 'How do angiotensin-converting enzyme (ACE) inhibitors like enalapril primarily reduce blood pressure in hypertension management?', 'ACE inhibitors block the ACE enzyme, preventing the conversion of angiotensin I to angiotensin II and reducing blood pressure.', null),
  (md5('question:pharmacy-exam-prep:6:69')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 69, 'What is the primary mechanism of action of liraglutide (a GLP-1 agonist) in the treatment of type 2 diabetes?', 'Liraglutide stimulates insulin secretion and inhibits glucagon secretion, helping to lower blood glucose levels in type 2 diabetes.', null),
  (md5('question:pharmacy-exam-prep:6:70')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 70, 'How does cabergoline primarily influence prolactin levels in the treatment of hyperprolactinemia?', 'Cabergoline is a dopamine receptor agonist, which inhibits prolactin secretion by stimulating dopamine receptors in the pituitary gland.', null),
  (md5('question:pharmacy-exam-prep:6:71')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 71, 'What is the primary mechanism of action of pioglitazone (a thiazolidinedione) in the management of type 2 diabetes?', 'Pioglitazone activates PPAR-gamma, a nuclear receptor that regulates genes involved in glucose and lipid metabolism, improving insulin sensitivity in type 2 diabetes.', null),
  (md5('question:pharmacy-exam-prep:6:72')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 72, 'How do anticoagulants like warfarin primarily reduce the risk of blood clot formation?', 'Warfarin inhibits the synthesis of vitamin K-dependent clotting factors, reducing blood clot formation.', null),
  (md5('question:pharmacy-exam-prep:6:73')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 73, 'What is the primary mechanism of action of recombinant human erythropoietin (epoetin alfa) in the treatment of anemia?', 'Epoetin alfa stimulates the production of red blood cells in the bone marrow, alleviating anemia.', null),
  (md5('question:pharmacy-exam-prep:6:74')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 74, 'How does denosumab primarily reduce the risk of fractures in osteoporosis?', 'Denosumab primarily inhibits bone resorption by binding to RANKL, a protein involved in osteoclast activation, leading to increased bone density.', null),
  (md5('question:pharmacy-exam-prep:6:75')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 75, 'What is the primary mechanism of action of anastrozole (an aromatase inhibitor) in the treatment of breast cancer?', 'Aromatase inhibitors like anastrozole block the conversion of androgens to estrogen, reducing estrogen levels in breast cancer treatment.', null),
  (md5('question:pharmacy-exam-prep:6:76')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 76, 'How does desmopressin (DDAVP) primarily affect urine volume and concentration in the treatment of diabetes insipidus?', 'Desmopressin binds to and activates vasopressin receptors in the renal tubules, promoting water reabsorption and reducing urine volume in diabetes insipidus.', null),
  (md5('question:pharmacy-exam-prep:6:77')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 77, 'What is the primary mechanism of action of recombinant parathyroid hormone (teriparatide) in the treatment of osteoporosis?', 'Teriparatide stimulates bone formation and increases bone density in osteoporotic patients.', null),
  (md5('question:pharmacy-exam-prep:6:78')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 78, 'How do alpha-glucosidase inhibitors like acarbose primarily affect postprandial blood glucose levels in diabetes management?', 'Acarbose inhibits alpha-glucosidase enzymes in the intestine, delaying carbohydrate digestion and reducing post-meal glucose spikes.', null),
  (md5('question:pharmacy-exam-prep:6:79')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 79, 'What is the primary mechanism of action of recombinant human growth hormone (somatropin) in the treatment of growth hormone deficiency?', 'Somatropin binds to and stimulates growth hormone receptors, promoting growth and metabolic effects in patients with growth hormone deficiency.', null),
  (md5('question:pharmacy-exam-prep:6:80')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 80, 'How does cabergoline primarily influence prolactin levels in the treatment of hyperprolactinemia?', 'Cabergoline is a dopamine receptor agonist, which inhibits prolactin secretion by stimulating dopamine receptors in the pituitary gland.', null),
  (md5('question:pharmacy-exam-prep:6:81')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 81, 'What is the primary mechanism of action of pioglitazone (a thiazolidinedione) in the management of type 2 diabetes?', 'Pioglitazone activates PPAR-gamma, a nuclear receptor that regulates genes involved in glucose and lipid metabolism, improving insulin sensitivity in type 2 diabetes.', null),
  (md5('question:pharmacy-exam-prep:6:82')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 82, 'How do anticoagulants like warfarin primarily reduce the risk of blood clot formation?', 'Warfarin inhibits the synthesis of vitamin K-dependent clotting factors, reducing blood clot formation.', null),
  (md5('question:pharmacy-exam-prep:6:83')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 83, 'What is the primary mechanism of action of recombinant human erythropoietin (epoetin alfa) in the treatment of anemia?', 'Epoetin alfa stimulates the production of red blood cells in the bone marrow, alleviating anemia.', null),
  (md5('question:pharmacy-exam-prep:6:84')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 84, 'A 55-year-old patient with type 2 diabetes is taking metformin for glycemic control. The physician prescribes gemfibrozil for hyperlipidemia. What is the most likely drug interaction between metformin and gemfibrozil?', 'Gemfibrozil can increase the risk of lactic acidosis when combined with metformin, particularly in patients with renal impairment. Patients should be closely monitored for signs of lactic acidosis.', null),
  (md5('question:pharmacy-exam-prep:6:85')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 85, 'A 45-year-old patient with hypertension is prescribed lisinopril for blood pressure control. The patient is also taking allopurinol for gout. What is the potential drug interaction between lisinopril and allopurinol?', 'Lisinopril can increase potassium levels, and allopurinol may exacerbate hyperkalemia. Regular monitoring of potassium levels is essential when these drugs are used together.', null),
  (md5('question:pharmacy-exam-prep:6:86')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 86, 'A 60-year-old patient with hypothyroidism takes levothyroxine daily. The patient develops constipation and is started on calcium carbonate for calcium supplementation. What is the potential drug interaction between levothyroxine and calcium carbonate?', 'Calcium supplements, including calcium carbonate, can impair the absorption of levothyroxine. These medications should be taken at different times to avoid interference with levothyroxine absorption.', null),
  (md5('question:pharmacy-exam-prep:6:87')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 87, 'A 50-year-old patient with type 2 diabetes is on insulin therapy. The patient develops an infection and is prescribed ciprofloxacin. What is the potential drug interaction between insulin and ciprofloxacin?', 'Ciprofloxacin can increase the risk of hypoglycemia when used with insulin. Close monitoring of blood glucose levels is essential, and insulin dosage adjustments may be necessary during antibiotic therapy.', null),
  (md5('question:pharmacy-exam-prep:6:88')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 88, 'A 35-year-old patient with hyperthyroidism takes methimazole to manage the condition. The patient develops a skin infection and is prescribed warfarin for anticoagulation. What is the potential drug interaction between methimazole and warfarin?', 'Methimazole may enhance the anticoagulant effect of warfarin, leading to an increased risk of bleeding. Close monitoring of INR and possible warfarin dosage adjustment is necessary.', null),
  (md5('question:pharmacy-exam-prep:6:89')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 89, 'A 55-year-old patient with primary hyperaldosteronism is treated with spironolactone. The patient develops a urinary tract infection and is prescribed trimethoprim-sulfamethoxazole. What is the potential drug interaction between spironolactone and trimethoprim-sulfamethoxazole?', 'Trimethoprim-sulfamethoxazole can increase potassium levels and enhance the risk of hyperkalemia when used with spironolactone. Close monitoring of potassium levels is essential.', null),
  (md5('question:pharmacy-exam-prep:6:90')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 90, 'A 40-year-old patient with type 1 diabetes uses an insulin pump for glycemic control. The patient develops a respiratory infection and is prescribed azithromycin. What is the potential drug interaction between insulin and azithromycin?', 'Azithromycin can enhance the risk of hypoglycemia when used with insulin. Patients on insulin therapy should monitor their blood glucose levels closely during antibiotic therapy.', null),
  (md5('question:pharmacy-exam-prep:6:91')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 91, 'A 45-year-old patient with hypothyroidism takes levothyroxine daily. The patient starts a new medication for seizures, phenytoin. What is the potential drug interaction between levothyroxine and phenytoin?', 'Phenytoin can increase the metabolism of levothyroxine, potentially leading to reduced thyroid hormone levels and an increased risk of hypothyroidism. Monitoring thyroid function is important.', null),
  (md5('question:pharmacy-exam-prep:6:92')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 92, 'A 60-year-old patient with hypertension takes lisinopril and hydrochlorothiazide. The patient is prescribed ibuprofen for pain relief. What is the potential drug interaction between lisinopril/hydrochlorothiazide and ibuprofen?', 'Ibuprofen can reduce the effectiveness of ACE inhibitors like lisinopril, potentially increasing the risk of angioedema. Patients should be monitored for signs of angioedema when these drugs are used together.', null),
  (md5('question:pharmacy-exam-prep:6:93')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 93, 'A 65-year-old patient with hypertension is on amlodipine therapy. The patient is diagnosed with primary hyperaldosteronism and is started on spironolacton What is the potential drug interaction between amlodipine and spironolactone?', 'Spironolactone can increase potassium levels, potentially leading to hypokalemia when used with amlodipine. Monitoring of potassium levels and blood pressure is necessary.', null),
  (md5('question:pharmacy-exam-prep:6:94')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 94, 'A 50-year-old patient with type 2 diabetes is taking metformin for glycemic control. The patient develops a respiratory infection and is prescribed clarithromycin. What is the potential drug interaction between metformin and clarithromycin?', 'Clarithromycin can enhance the risk of hypoglycemia when used with metformin. Patients should monitor their blood glucose levels closely during antibiotic therapy.', null),
  (md5('question:pharmacy-exam-prep:6:95')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 95, 'A 55-year-old patient with hypothyroidism takes levothyroxine daily. The patient is diagnosed with iron-deficiency anemia and is prescribed ferrous sulfate. What is the potential drug interaction between levothyroxine and ferrous sulfate?', 'Ferrous sulfate can impair the absorption of levothyroxine. These medications should be taken at different times to avoid interference with levothyroxine absorption.', null),
  (md5('question:pharmacy-exam-prep:6:96')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 96, 'A 60-year-old patient with type 2 diabetes is on insulin therapy. The patient is diagnosed with a urinary tract infection and is prescribed ciprofloxacin. What is the potential drug interaction between insulin and ciprofloxacin?', 'Ciprofloxacin can increase the risk of hypoglycemia when used with insulin. Close monitoring of blood glucose levels is essential, and insulin dosage adjustments may be necessary during antibiotic therapy.', null),
  (md5('question:pharmacy-exam-prep:6:97')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 97, 'A 45-year-old patient with hyperthyroidism takes methimazole for disease management. The patient develops a skin infection and is prescribed amoxicillin. What is the potential drug interaction between methimazole and amoxicillin?', 'Methimazole may reduce its antithyroid effect when used concurrently with amoxicillin. Close monitoring of thyroid function is necessary.', null),
  (md5('question:pharmacy-exam-prep:6:98')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 98, 'A 70-year-old patient with type 2 diabetes is taking glipizide for glycemic control. The patient is diagnosed with a urinary tract infection and is prescribed trimethoprim-sulfamethoxazole. What is the potential drug interaction between glipizide and trimethoprim-sulfamethoxazole?', 'Trimethoprim-sulfamethoxazole can increase the risk of hypoglycemia when used with glipizide. Patients should monitor their blood glucose levels closely during antibiotic therapy.', null),
  (md5('question:pharmacy-exam-prep:6:99')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 99, 'A 50-year-old patient with type 1 diabetes uses an insulin pump for glycemic control. The patient is diagnosed with a sinus infection and is prescribed clarithromycin. What is the potential drug interaction between insulin and clarithromycin?', 'Clarithromycin can enhance the risk of hypoglycemia when used with insulin. Patients on insulin therapy should monitor their blood glucose levels closely during antibiotic therapy.', null),
  (md5('question:pharmacy-exam-prep:6:100')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 100, 'A 65-year-old patient with primary hyperaldosteronism is treated with spironolacton. The patient develops an infection and is prescribed doxycycline. What is the potential drug interaction between spironolactone and doxycycline?', 'Spironolactone can increase potassium levels, potentially leading to hyperkalemia when used with doxycycline. Monitoring of potassium levels is necessary.', null),
  (md5('question:pharmacy-exam-prep:6:101')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 101, 'A 40-year-old patient with type 2 diabetes is on insulin therapy. The patient is diagnosed with pneumonia and is prescribed azithromycin. What is the potential drug interaction between insulin and azithromycin?', 'Azithromycin can enhance the risk of hypoglycemia when used with insulin. Patients should monitor their blood glucose levels closely during antibiotic therapy.', null),
  (md5('question:pharmacy-exam-prep:6:102')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 102, 'A 55-year-old patient with hypertension is on lisinopril therapy. The patient is diagnosed with gout and is prescribed allopurinol. What is the potential drug interaction between lisinopril and allopurinol?', 'Lisinopril can increase the risk of angioedema, particularly when used with allopurinol. Close monitoring for signs of angioedema is essential.', null),
  (md5('question:pharmacy-exam-prep:6:103')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 103, 'A 60-year-old patient with primary hypothyroidism takes levothyroxine daily. The patient is diagnosed with Helicobacter pylori infection and is prescribed omeprazole, amoxicillin, and clarithromycin. What is the potential drug interaction between levothyroxine and this antibiotic regimen?', 'The simultaneous use of omeprazole, amoxicillin, and clarithromycin can impair the absorption of levothyroxine. These medications should be taken at different times to avoid interference with levothyroxine absorption.', null),
  (md5('question:pharmacy-exam-prep:6:104')::uuid, md5('quiz:pharmacy-exam-prep:6')::uuid, 104, 'A 45-year-old patient with primary hyperaldosteronism is treated with spironolactone. The patient is diagnosed with a skin infection and is prescribed cephalexin. What is the potential drug interaction between spironolactone and cephalexin?', 'Cephalexin may increase potassium levels and enhance the risk of hyperkalemia when used with spironolactone. Monitoring of potassium levels is necessary.', null),
