  (md5('answer:pharmacy-exam-prep:7:2:2')::uuid, md5('question:pharmacy-exam-prep:7:2')::uuid, 2, 'Lansoprazole', false),
  (md5('answer:pharmacy-exam-prep:7:2:3')::uuid, md5('question:pharmacy-exam-prep:7:2')::uuid, 3, 'Pantoprazole', true),
  (md5('answer:pharmacy-exam-prep:7:2:4')::uuid, md5('question:pharmacy-exam-prep:7:2')::uuid, 4, 'Rabeprazole', false),
  (md5('answer:pharmacy-exam-prep:7:2:5')::uuid, md5('question:pharmacy-exam-prep:7:2')::uuid, 5, 'Omeprazole', false),
  (md5('answer:pharmacy-exam-prep:7:3:1')::uuid, md5('question:pharmacy-exam-prep:7:3')::uuid, 1, 'Docusate sodium', false),
  (md5('answer:pharmacy-exam-prep:7:3:2')::uuid, md5('question:pharmacy-exam-prep:7:3')::uuid, 2, 'Magnesium hydroxide', false),
  (md5('answer:pharmacy-exam-prep:7:3:3')::uuid, md5('question:pharmacy-exam-prep:7:3')::uuid, 3, 'Polyethylene glycol', true),
  (md5('answer:pharmacy-exam-prep:7:3:4')::uuid, md5('question:pharmacy-exam-prep:7:3')::uuid, 4, 'Bisacodyl', false),
  (md5('answer:pharmacy-exam-prep:7:3:5')::uuid, md5('question:pharmacy-exam-prep:7:3')::uuid, 5, 'Mineral oil', false),
  (md5('answer:pharmacy-exam-prep:7:4:1')::uuid, md5('question:pharmacy-exam-prep:7:4')::uuid, 1, 'QT interval prolongation', true),
  (md5('answer:pharmacy-exam-prep:7:4:2')::uuid, md5('question:pharmacy-exam-prep:7:4')::uuid, 2, 'Hypoglycemia', false),
  (md5('answer:pharmacy-exam-prep:7:4:3')::uuid, md5('question:pharmacy-exam-prep:7:4')::uuid, 3, 'Photosensitivity reactions', false),
  (md5('answer:pharmacy-exam-prep:7:4:4')::uuid, md5('question:pharmacy-exam-prep:7:4')::uuid, 4, 'Myelosuppression', false),
  (md5('answer:pharmacy-exam-prep:7:4:5')::uuid, md5('question:pharmacy-exam-prep:7:4')::uuid, 5, 'Clostridium difficile infection', false),
