  (md5('answer:pharmacy-exam-prep:7:143:5')::uuid, md5('question:pharmacy-exam-prep:7:143')::uuid, 5, '72 hours', false),
  (md5('answer:pharmacy-exam-prep:7:144:1')::uuid, md5('question:pharmacy-exam-prep:7:144')::uuid, 1, 'Stir the contents of the sachet with a full glass of water (150ml) and drink straight after mixing', false),
  (md5('answer:pharmacy-exam-prep:7:144:2')::uuid, md5('question:pharmacy-exam-prep:7:144')::uuid, 2, 'Try to eat a healthy diet, and drink plenty of water to prevent constipation', false),
  (md5('answer:pharmacy-exam-prep:7:144:3')::uuid, md5('question:pharmacy-exam-prep:7:144')::uuid, 3, 'It may take one or two days before you feel the full benefits of taking fyboel', false),
  (md5('answer:pharmacy-exam-prep:7:144:4')::uuid, md5('question:pharmacy-exam-prep:7:144')::uuid, 4, 'Fybogel should be taken just before bed as it takes 6-12 hours to take full effect', true),
  (md5('answer:pharmacy-exam-prep:7:144:5')::uuid, md5('question:pharmacy-exam-prep:7:144')::uuid, 5, 'Do not drink fybogel straight before going bed as it can cause obstruction in the throat', false),
