  (md5('answer:pharmacy-exam-prep:7:154:5')::uuid, md5('question:pharmacy-exam-prep:7:154')::uuid, 5, 'Biscodyl', true),
  (md5('answer:pharmacy-exam-prep:7:155:1')::uuid, md5('question:pharmacy-exam-prep:7:155')::uuid, 1, 'Senna should not be taken immediately before bed, and you should have plenty of water to avoid gut obstruction', false),
  (md5('answer:pharmacy-exam-prep:7:155:2')::uuid, md5('question:pharmacy-exam-prep:7:155')::uuid, 2, 'Senna can affect the PH of the intestine and can therefore affect the absorption of modified release preparations', false),
  (md5('answer:pharmacy-exam-prep:7:155:3')::uuid, md5('question:pharmacy-exam-prep:7:155')::uuid, 3, 'If you take excessive amounts of senna it can lead to dangerous hyperkalemia', false),
  (md5('answer:pharmacy-exam-prep:7:155:4')::uuid, md5('question:pharmacy-exam-prep:7:155')::uuid, 4, 'Senna should be taken at night time', true),
  (md5('answer:pharmacy-exam-prep:7:155:5')::uuid, md5('question:pharmacy-exam-prep:7:155')::uuid, 5, 'Senna can lead to anal seepage and lipoid pneumonia when taken in excess', false)
insert into public.chapters (id, course_id, position, title) values
  (md5('chapter:pharmacy-exam-prep:8')::uuid, md5('course:pharmacy-exam-prep')::uuid, 8, 'Malignant Disease and Immunosuppression')
insert into public.quizzes (id, chapter_id, title, position, is_preview) values
  (md5('quiz:pharmacy-exam-prep:8')::uuid, md5('chapter:pharmacy-exam-prep:8')::uuid, 'Malignant Disease and Immunosuppression', 1, false)
insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('question:pharmacy-exam-prep:8:1')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 1, 'Which immunosuppressant inhibits calcineurin?', 'Calcineurin inhibitors include Tacrolimus and Cyclosporine, commonly used in transplant medicine.', null),
  (md5('question:pharmacy-exam-prep:8:2')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 2, 'What is the mechanism of action of Rituximab?', 'Rituximab targets CD20 antigen on B cells, used in conditions like non-Hodgkin''s lymphoma and rheumatoid arthritis.', null),
  (md5('question:pharmacy-exam-prep:8:3')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 3, 'Which drug is a monoclonal antibody against EGFR?', 'Cetuximab is a monoclonal antibody against EGFR, used in colorectal and head/neck cancers.', null),
  (md5('question:pharmacy-exam-prep:8:4')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 4, 'Which drug inhibits microtubule formation?', 'Vinblastine disrupts microtubule formation, used in treating various cancers.', null),
  (md5('question:pharmacy-exam-prep:8:5')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 5, 'Which drug is a proteasome inhibitor?', 'Bortezomib inhibits the proteasome, commonly used in multiple myeloma therapy.', null),
  (md5('question:pharmacy-exam-prep:8:6')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 6, 'What is the primary mechanism of action of Interferon-α?', 'Interferon-α exhibits antiviral, anti-neoplastic, and immunomodulatory effects.', null),
  (md5('question:pharmacy-exam-prep:8:7')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 7, 'Which drug inhibits tyrosine kinase activity?', 'Imatinib inhibits tyrosine kinase, used in chronic myeloid leukemia and gastrointestinal stromal tumors.', null),
  (md5('question:pharmacy-exam-prep:8:8')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 8, 'What is the primary action of Alemtuzumab?', 'Alemtuzumab targets CD52, used in chronic lymphocytic leukemia and multiple sclerosis.', null),
  (md5('question:pharmacy-exam-prep:8:9')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 9, 'Which drug is an anti-CD20 monoclonal antibody?', 'Rituximab is an anti-CD20 monoclonal antibody, used in B-cell non-Hodgkin''s lymphoma and rheumatoid arthritis.', null),
  (md5('question:pharmacy-exam-prep:8:10')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 10, 'Which drug inhibits dihydrofolate reductase?', 'Methotrexate inhibits dihydrofolate reductase, used in various cancers and autoimmune conditions.', null),
  (md5('question:pharmacy-exam-prep:8:11')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 11, 'What is the mechanism of action of Bevacizumab?', 'Bevacizumab is an anti-angiogenic monoclonal antibody, used in cancers to inhibit angiogenesis.', null),
  (md5('question:pharmacy-exam-prep:8:12')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 12, 'Which drug is a topoisomerase inhibitor?', 'Etoposide is a topoisomerase inhibitor used in various cancers.', null),
  (md5('question:pharmacy-exam-prep:8:13')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 13, 'What is the primary mechanism of action of Trastuzumab?', 'Trastuzumab targets HER2, used in HER2-positive breast cancer.', null),
  (md5('question:pharmacy-exam-prep:8:14')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 14, 'Which drug is an antimetabolite?', 'Methotrexate is an antimetabolite used in cancer and autoimmune diseases.', null),
  (md5('question:pharmacy-exam-prep:8:15')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 15, 'What is the primary mechanism of action of Pembrolizumab?', 'Pembrolizumab is a PD-1 inhibitor, used in various cancers as immunotherapy.', null),
  (md5('question:pharmacy-exam-prep:8:16')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 16, 'Which drug inhibits ribonucleotide reductase?', 'Hydroxyurea inhibits ribonucleotide reductase, used in myeloproliferative disorders and certain cancers.', null),
  (md5('question:pharmacy-exam-prep:8:17')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 17, 'What is the mechanism of action of Lenalidomide?', 'Lenalidomide has immunomodulatory effects, used in multiple myeloma and myelodysplastic syndromes.', null),
  (md5('question:pharmacy-exam-prep:8:18')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 18, 'Which drug is a DNA alkylating agent?', 'Cyclophosphamide is a DNA alkylating agent, used in various cancers.', null),
  (md5('question:pharmacy-exam-prep:8:19')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 19, 'What is the primary action of Dasatinib?', 'Dasatinib inhibits multiple tyrosine kinases, used in chronic myeloid leukemia and acute lymphoblastic leukemia.', null),
  (md5('question:pharmacy-exam-prep:8:20')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 20, 'Which drug is a BRAF inhibitor?', 'Vemurafenib is a BRAF inhibitor used in melanoma with BRAF mutations.', null),
  (md5('question:pharmacy-exam-prep:8:21')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 21, 'A 45-year-old female presents with rheumatoid arthritis unresponsive to methotrexate. Which drug with TNF-α inhibitory properties is most suitable?', 'Adalimumab is a TNF-α inhibitor used in rheumatoid arthritis patients unresponsive to methotrexate.', null),
  (md5('question:pharmacy-exam-prep:8:22')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 22, 'A 65-year-old male is diagnosed with chronic lymphocytic leukemia. Which drug, targeting CD52, is recommended as a first-line treatment?', 'Alemtuzumab targets CD52 and is used in chronic lymphocytic leukemia.', null),
  (md5('question:pharmacy-exam-prep:8:23')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 23, 'A 50-year-old woman with HER2-positive breast cancer requires adjuvant therapy post-surgery. Which medication is specifically indicated in this case?', 'Trastuzumab is used in HER2-positive breast cancer as adjuvant therapy.', null),
  (md5('question:pharmacy-exam-prep:8:24')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 24, 'A 30-year-old man with multiple myeloma experiences neuropathy due to chemotherapy. Which proteasome inhibitor should be avoided to minimize this side effect?', 'Bortezomib is associated with peripheral neuropathy; others have different side effect profiles.', null),
  (md5('question:pharmacy-exam-prep:8:25')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 25, 'A 60-year-old woman presents with psoriasis unresponsive to conventional therapies. Which IL-17 inhibitor is most suitable for her condition?', 'Secukinumab is an IL-17 inhibitor used in psoriasis treatment.', null),
  (md5('question:pharmacy-exam-prep:8:26')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 26, 'A 55-year-old male diagnosed with non-Hodgkin''s lymphoma is prescribed a monoclonal antibody that binds to CD20. Which drug matches this description?', 'Rituximab specifically targets CD20 in non-Hodgkin''s lymphoma.', null),
  (md5('question:pharmacy-exam-prep:8:27')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 27, 'A 70-year-old patient with chronic myeloid leukemia requires a drug inhibiting BCR-ABL tyrosine kinase. Which medication is the standard of care in this scenario?', 'Imatinib is a standard BCR-ABL tyrosine kinase inhibitor in chronic myeloid leukemia.', null),
  (md5('question:pharmacy-exam-prep:8:28')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 28, 'A 40-year-old male with ulcerative colitis needs a TNF-α inhibitor. Which drug should be avoided due to its potential for worsening colitis?', 'Infliximab may worsen ulcerative colitis symptoms.', null),
  (md5('question:pharmacy-exam-prep:8:29')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 29, 'A 25-year-old female with systemic lupus erythematosus is prescribed an immunosuppressant targeting mTOR. Which drug should be chosen?', 'Sirolimus inhibits mTOR and is used in systemic lupus erythematosus.', null),
  (md5('question:pharmacy-exam-prep:8:30')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 30, 'A 50-year-old male with advanced melanoma and BRAF mutation needs a targeted therapy. Which drug specifically targets mutated BRAF proteins?', 'Vemurafenib targets mutated BRAF proteins in advanced melanoma.', null),
  (md5('question:pharmacy-exam-prep:8:31')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 31, 'A 65-year-old female with renal cell carcinoma requires an anti-VEGF agent. Which medication primarily inhibits vascular endothelial growth factor?', 'Bevacizumab primarily inhibits VEGF and is used in renal cell carcinoma.', null),
  (md5('question:pharmacy-exam-prep:8:32')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 32, 'A 55-year-old male with ankylosing spondylitis requires a TNF-α inhibitor. Which medication should be avoided due to its ineffectiveness in this condition?', 'Etanercept is less effective in ankylosing spondylitis compared to others.', null),
  (md5('question:pharmacy-exam-prep:8:33')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 33, 'A 70-year-old male diagnosed with mantle cell lymphoma needs a drug targeting BTK. Which medication specifically inhibits Bruton''s tyrosine kinase?', 'Ibrutinib targets BTK and is used in mantle cell lymphoma.', null),
  (md5('question:pharmacy-exam-prep:8:34')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 34, 'A 40-year-old female with Crohn''s disease needs an anti-integrin therapy. Which medication primarily targets integrins in this condition?', 'Vedolizumab specifically targets integrins in Crohn''s disease treatment.', null),
  (md5('question:pharmacy-exam-prep:8:35')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 35, 'A 60-year-old male with advanced non-small cell lung cancer requires an immunotherapy targeting PD-1. Which drug should be prescribed in this scenario?', 'Pembrolizumab targets PD-1 in advanced non-small cell lung cancer.', null),
  (md5('question:pharmacy-exam-prep:8:36')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 36, 'A 45-year-old female with relapsing-remitting multiple sclerosis requires an anti-CD25 monoclonal antibody. Which medication should be chosen?', 'Daclizumab targets CD25 and is used in multiple sclerosis.', null),
  (md5('question:pharmacy-exam-prep:8:37')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 37, 'A 30-year-old male with acute lymphoblastic leukemia requires a drug targeting CD19. Which medication specifically targets CD19-expressing cells?', 'Blinatumomab targets CD19 and is used in acute lymphoblastic leukemia.', null),
  (md5('question:pharmacy-exam-prep:8:38')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 38, 'A 55-year-old male with rheumatoid arthritis needs an anti-IL-6 receptor antibody. Which medication primarily blocks IL-6 signaling?', 'Tocilizumab blocks IL-6 signaling and is used in rheumatoid arthritis.', null),
  (md5('question:pharmacy-exam-prep:8:39')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 39, 'A 65-year-old female with metastatic colorectal cancer needs an EGFR inhibitor. Which medication specifically targets the epidermal growth factor receptor?', 'Cetuximab specifically targets EGFR in metastatic colorectal cancer.', null),
  (md5('question:pharmacy-exam-prep:8:40')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 40, 'A 50-year-old male with advanced renal cell carcinoma needs an mTOR inhibitor. Which medication primarily inhibits the mammalian target of rapamycin?', 'Everolimus inhibits mTOR and is used in advanced renal cell carcinoma.', null),
  (md5('question:pharmacy-exam-prep:8:41')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 41, 'A 30-year-old female with severe hepatic impairment requires an immunosuppressant. Which drug is contraindicated due to its hepatotoxicity?', 'Methotrexate is contraindicated in severe hepatic impairment due to its potential hepatotoxicity.', null),
  (md5('question:pharmacy-exam-prep:8:42')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 42, 'A 50-year-old male with a history of congestive heart failure needs an immunosuppressant post-organ transplant. Which medication should be avoided due to its adverse effects on cardiac function?', 'Cyclosporine should be avoided due to its potential adverse effects on cardiac function.', null),
  (md5('question:pharmacy-exam-prep:8:43')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 43, 'A 40-year-old female with a history of active tuberculosis requires an immunosuppressant for autoimmune hepatitis. Which drug is contraindicated due to its risk of reactivating tuberculosis?', 'Infliximab is contraindicated in active tuberculosis due to the risk of reactivation.', null),
  (md5('question:pharmacy-exam-prep:8:44')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 44, 'A 60-year-old male with a history of seizures due to brain metastases needs an immunosuppressant post-kidney transplant. Which drug should be avoided due to its potential to lower seizure threshold?', 'Mycophenolate may lower the seizure threshold and should be avoided in patients with a history of seizures.', null),
  (md5('question:pharmacy-exam-prep:8:45')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 45, 'A 35-year-old male with a history of recurrent infections requires an immunosuppressant for ulcerative colitis. Which medication should be avoided due to its increased risk of infections?', 'Infliximab increases the risk of infections and should be avoided in patients prone to recurrent infections.', null),
  (md5('question:pharmacy-exam-prep:8:46')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 46, 'A 55-year-old female with severe renal impairment needs an immunosuppressant for lupus nephritis. Which drug is contraindicated due to its risk of nephrotoxicity?', 'Sirolimus should be avoided due to its potential nephrotoxic effects in severe renal impairment.', null),
  (md5('question:pharmacy-exam-prep:8:47')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 47, 'A 45-year-old male with a history of severe cytopenias requires an immunosuppressant for psoriasis. Which medication should be avoided due to its potential to exacerbate cytopenias?', 'Methotrexate should be avoided due to its potential to exacerbate cytopenias in certain patients.', null),
  (md5('question:pharmacy-exam-prep:8:48')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 48, 'A 60-year-old female with a history of demyelinating disorders needs an immunosuppressant for rheumatoid arthritis. Which drug is contraindicated due to its risk of exacerbating demyelination?', 'Rituximab is contraindicated in patients with a history of demyelinating disorders due to the risk of exacerbation.', null),
  (md5('question:pharmacy-exam-prep:8:49')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 49, 'A 50-year-old male with a history of malignancies needs an immunosuppressant post-kidney transplant. Which drug should be avoided due to its potential to increase the risk of malignancies?', 'Mycophenolate should be avoided due to its potential association with an increased risk of malignancies.', null),
