  (md5('question:pharmacy-exam-prep:8:51')::uuid, md5('quiz:pharmacy-exam-prep:8')::uuid, 51, 'A 35-year-old male with a history of gastrointestinal bleeding needs an immunosuppressant for Crohn''s disease. Which medication should be avoided due to its potential to exacerbate bleeding?', 'Infliximab should be avoided due to its potential to exacerbate gastrointestinal bleeding.', null),
