  (md5('answer:pharmacy-exam-prep:8:121:1')::uuid, md5('question:pharmacy-exam-prep:8:121')::uuid, 1, 'Azathioprine', false),
  (md5('answer:pharmacy-exam-prep:8:121:2')::uuid, md5('question:pharmacy-exam-prep:8:121')::uuid, 2, 'Methotrexate', false),
  (md5('answer:pharmacy-exam-prep:8:121:3')::uuid, md5('question:pharmacy-exam-prep:8:121')::uuid, 3, 'Cyclosporine', false),
  (md5('answer:pharmacy-exam-prep:8:121:4')::uuid, md5('question:pharmacy-exam-prep:8:121')::uuid, 4, 'Tacrolimus', false),
  (md5('answer:pharmacy-exam-prep:8:121:5')::uuid, md5('question:pharmacy-exam-prep:8:121')::uuid, 5, 'Mycophenolate', true),
  (md5('answer:pharmacy-exam-prep:8:122:1')::uuid, md5('question:pharmacy-exam-prep:8:122')::uuid, 1, 'Panadol (paracetamol)', false),
  (md5('answer:pharmacy-exam-prep:8:122:2')::uuid, md5('question:pharmacy-exam-prep:8:122')::uuid, 2, 'Nurofen express (ibuprofen)', true),
  (md5('answer:pharmacy-exam-prep:8:122:3')::uuid, md5('question:pharmacy-exam-prep:8:122')::uuid, 3, 'Co-codamol 8mg/500mg tablets', false),
  (md5('answer:pharmacy-exam-prep:8:122:4')::uuid, md5('question:pharmacy-exam-prep:8:122')::uuid, 4, 'Oil of cloves', false),
  (md5('answer:pharmacy-exam-prep:8:122:5')::uuid, md5('question:pharmacy-exam-prep:8:122')::uuid, 5, 'Orajel (benzocaine)', false)
insert into public.chapters (id, course_id, position, title) values
  (md5('chapter:pharmacy-exam-prep:9')::uuid, md5('course:pharmacy-exam-prep')::uuid, 9, 'Nutrition and Blood')
insert into public.quizzes (id, chapter_id, title, position, is_preview) values
  (md5('quiz:pharmacy-exam-prep:9')::uuid, md5('chapter:pharmacy-exam-prep:9')::uuid, 'Nutrition and Blood', 1, false)
insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('question:pharmacy-exam-prep:9:1')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 1, 'What is the main indication for Ferrous Sulfate?', 'Ferrous Sulfate is primarily used to treat iron-deficiency anemia.', null),
  (md5('question:pharmacy-exam-prep:9:2')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 2, 'Which vitamin is primarily involved in blood coagulation?', 'Vitamin K is essential for the synthesis of factors necessary for blood coagulation.', null),
  (md5('question:pharmacy-exam-prep:9:3')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 3, 'Cyanocobalamin is a form of which vitamin?', 'Cyanocobalamin is a synthetic form of Vitamin B12 used in supplements and for treatment.', null),
  (md5('question:pharmacy-exam-prep:9:4')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 4, 'What is a common side effect of oral iron supplements like Ferrous Fumarate?', 'Oral iron supplements, including Ferrous Fumarate, often cause gastrointestinal side effects like constipation.', null),
  (md5('question:pharmacy-exam-prep:9:5')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 5, 'Folic acid supplementation is most critical during which phase of life?', 'Folic acid is crucial during pregnancy to prevent neural tube defects in the developing fetus.', null),
  (md5('question:pharmacy-exam-prep:9:6')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 6, 'Which nutrient deficiency is primarily associated with Scurvy?', 'Scurvy is caused by a deficiency of Vitamin C.', null),
  (md5('question:pharmacy-exam-prep:9:7')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 7, 'What is the main therapeutic use of Hydroxocobalamin?', 'Hydroxocobalamin is used to treat Vitamin B12 deficiency.', null),
  (md5('question:pharmacy-exam-prep:9:8')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 8, 'Which mineral is essential for thyroid hormone synthesis?', 'Iodine is crucial for the synthesis of thyroid hormones.', null),
  (md5('question:pharmacy-exam-prep:9:9')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 9, 'What is the recommended dietary supplement for someone with osteoporosis?', 'Calcium and Vitamin D are recommended for individuals with osteoporosis to strengthen bones.', null),
  (md5('question:pharmacy-exam-prep:9:10')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 10, 'Which of the following is a sign of Vitamin B12 deficiency?', 'Pernicious anemia is a classic sign of Vitamin B12 deficiency.', null),
  (md5('question:pharmacy-exam-prep:9:11')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 11, 'A 55-year-old woman with chronic kidney disease is prescribed calcium acetate for hyperphosphatemia. Which mechanism best describes its action?', 'Calcium acetate binds dietary phosphate in the gut, reducing its absorption, which is beneficial in hyperphosphatemia associated with kidney disease.', null),
  (md5('question:pharmacy-exam-prep:9:12')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 12, 'A 30-year-old man with a history of alcoholism presents with Wernicke’s encephalopathy. Which treatment is most appropriate?', 'Thiamine is the treatment of choice for Wernicke’s encephalopathy, commonly seen in alcoholism due to thiamine deficiency.', null),
  (md5('question:pharmacy-exam-prep:9:13')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 13, 'A pregnant woman is advised to start folic acid supplements. What is the primary reason for this recommendation?', 'Folic acid supplementation in pregnancy is primarily to reduce the risk of neural tube defects in the developing fetus.', null),
  (md5('question:pharmacy-exam-prep:9:14')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 14, 'A patient on warfarin therapy has started taking high doses of Vitamin E supplements. What is a potential risk of this combination?', 'High doses of Vitamin E can potentiate the effects of warfarin, increasing the risk of bleeding.', null),
  (md5('question:pharmacy-exam-prep:9:15')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 15, 'A 45-year-old woman with iron-deficiency anemia is prescribed oral ferrous sulfate. Which side effect should she be informed about?', 'Constipation is a common side effect of oral iron supplements like ferrous sulfate.', null),
  (md5('question:pharmacy-exam-prep:9:16')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 16, 'A patient with pernicious anemia is prescribed hydroxocobalamin. What is the mechanism of action of this treatment?', 'Hydroxocobalamin provides a source of Vitamin B12, which is deficient in pernicious anemia.', null),
  (md5('question:pharmacy-exam-prep:9:17')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 17, 'A patient on long-term corticosteroid therapy is advised to take calcium and vitamin D supplements. This is primarily to prevent:', 'Calcium and vitamin D supplementation in patients on long-term corticosteroids is to prevent osteoporosis, a known side effect of corticosteroids.', null),
  (md5('question:pharmacy-exam-prep:9:18')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 18, 'A patient with CKD is prescribed sevelamer. What is the primary action of this drug in CKD?', 'Sevelamer is used in CKD to bind dietary phosphate, reducing its absorption and thus serum levels.', null),
  (md5('question:pharmacy-exam-prep:9:19')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 19, 'A 60-year-old man on antihypertensive medication develops gout. Which medication could have contributed to this condition?', 'Hydrochlorothiazide, a diuretic used in hypertension, can increase uric acid levels and contribute to the development of gout.', null),
  (md5('question:pharmacy-exam-prep:9:20')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 20, 'A patient with a history of epilepsy is prescribed phenytoin. Which nutrient deficiency should be regularly monitored in this patient?', 'Long-term use of phenytoin can lead to Vitamin D deficiency, which should be monitored and supplemented as needed.', null),
  (md5('question:pharmacy-exam-prep:9:21')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 21, 'A 65-year-old man with a history of stroke is prescribed alendronate. What is the primary purpose of this medication?', 'Alendronate is used primarily to increase bone density and prevent osteoporosis-related fractures.', null),
  (md5('question:pharmacy-exam-prep:9:22')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 22, 'A 40-year-old woman complains of fatigue and hair loss. Blood tests reveal iron-deficiency anemia. Which of the following should be avoided with her iron supplement?', 'Green tea can inhibit the absorption of iron and should be avoided around the time of taking an iron supplement.', null),
  (md5('question:pharmacy-exam-prep:9:23')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 23, 'A patient with celiac disease requires vitamin supplementation. Which vitamin is most likely to be deficient?', 'Vitamin D deficiency is common in celiac disease due to malabsorption in the damaged small intestine.', null),
  (md5('question:pharmacy-exam-prep:9:24')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 24, 'A patient on dialysis is given erythropoietin. What is the primary purpose of this treatment?', 'Erythropoietin stimulates red blood cell production, often necessary in patients on dialysis with anemia.', null),
  (md5('question:pharmacy-exam-prep:9:25')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 25, 'A 50-year-old woman with breast cancer is prescribed calcium and vitamin D supplements along with her treatment. What is the rationale for this?', 'Calcium and vitamin D supplements are often prescribed to prevent osteoporosis, especially in patients undergoing cancer treatment.', null),
  (md5('question:pharmacy-exam-prep:9:26')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 26, 'A patient with hypertension is advised to reduce sodium intake. This dietary change primarily helps to:', 'Reducing sodium intake is a key dietary modification to help lower blood pressure in hypertensive patients.', null),
  (md5('question:pharmacy-exam-prep:9:27')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 27, 'A patient taking warfarin is found to have a Vitamin K deficiency. How does this affect their treatment?', 'Vitamin K deficiency increases the risk of bleeding in patients taking warfarin, a Vitamin K antagonist.', null),
  (md5('question:pharmacy-exam-prep:9:28')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 28, 'A diabetic patient has been prescribed thiamin. What is the primary benefit of thiamine supplementation in diabetes?', 'Thiamine can help prevent diabetic neuropathy, a common complication of diabetes.', null),
  (md5('question:pharmacy-exam-prep:9:29')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 29, 'A patient with hyperparathyroidism is prescribed cinacalcet. What is the mechanism of action of this drug?', 'Cinacalcet decreases parathyroid hormone levels, which is beneficial in treating hyperparathyroidism.', null),
  (md5('question:pharmacy-exam-prep:9:30')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 30, 'A patient with a peptic ulcer is on long-term omeprazole therapy. Which nutrient should be monitored?', 'Long-term use of omeprazole, a proton pump inhibitor, can lead to Vitamin B12 deficiency due to reduced stomach acidity.', null),
  (md5('question:pharmacy-exam-prep:9:31')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 31, 'A 70-year-old with osteoporosis is prescribed risedronate. What is the most important advice regarding its administration?', 'Risedronate should be taken with a full glass of water, and the patient should remain upright for at least 30 minutes to prevent esophageal irritation.', null),
  (md5('question:pharmacy-exam-prep:9:32')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 32, 'A patient on ferrous sulfate reports black stools. What is your advice?', 'Black stools are a common and harmless side effect of ferrous sulfate due to iron.', null),
  (md5('question:pharmacy-exam-prep:9:33')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 33, 'A patient with renal failure is prescribed epoetin alfa. What is a potential side effect of this medication?', 'Epoetin alfa can increase the risk of thromboembolic events, particularly in patients with renal failure.', null),
  (md5('question:pharmacy-exam-prep:9:34')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 34, 'A patient with B12 deficiency is advised to avoid alcohol. Why?', 'Alcohol consumption can decrease the absorption of Vitamin B12, worsening the deficiency.', null),
  (md5('question:pharmacy-exam-prep:9:35')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 35, 'A 55-year-old woman is diagnosed with iron-deficiency anemia and is prescribed oral iron. She is also taking levothyroxine. What should she be aware of?', 'Iron supplements can decrease the absorption and effectiveness of levothyroxine, and they should be taken a few hours apart.', null),
  (md5('question:pharmacy-exam-prep:9:36')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 36, 'A patient with gout is advised to limit intake of which nutrient?', 'Fructose can increase uric acid levels and exacerbate gout.', null),
  (md5('question:pharmacy-exam-prep:9:37')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 37, 'What is a major side effect of long-term use of proton pump inhibitors like omeprazole on nutrition?', 'Long-term use of proton pump inhibitors can lead to Vitamin B12 deficiency due to reduced gastric acidity.', null),
  (md5('question:pharmacy-exam-prep:9:38')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 38, 'A patient on methotrexate for rheumatoid arthritis is prescribed folic acid. What is the reason for this?', 'Folic acid is prescribed to prevent methotrexate-induced folate deficiency, which can cause side effects like mouth ulcers and gastrointestinal upset.', null),
  (md5('question:pharmacy-exam-prep:9:39')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 39, 'A 60-year-old man with heart failure is advised to take thiamine supplements. What is the reason?', 'Thiamine can improve cardiac function, as its deficiency can exacerbate heart failure symptoms.', null),
  (md5('question:pharmacy-exam-prep:9:40')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 40, 'A patient with hemochromatosis is advised to avoid which type of supplement?', 'Patients with hemochromatosis should avoid iron supplements due to the risk of iron overload.', null),
  (md5('question:pharmacy-exam-prep:9:41')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 41, 'A patient with Zollinger-Ellison syndrome is on high-dose proton pump inhibitors. Which nutrient deficiency should be closely monitored?', 'Long-term use of high-dose PPIs can lead to Vitamin B12 deficiency due to reduced gastric acid secretion.', null),
  (md5('question:pharmacy-exam-prep:9:42')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 42, 'A diabetic patient is prescribed an ACE inhibitor and notices a cough. What vitamin is sometimes used to mitigate this side effect?', 'Vitamin C has been suggested to help reduce the cough associated with ACE inhibitor therapy.', null),
  (md5('question:pharmacy-exam-prep:9:43')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 43, 'A patient with a history of gastric bypass surgery is likely to require supplementation with which vitamin?', 'Patients with gastric bypass surgery are at risk of Vitamin B12 deficiency due to altered gastrointestinal anatomy affecting absorption.', null),
  (md5('question:pharmacy-exam-prep:9:44')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 44, 'A patient on long-term aspirin therapy for cardiovascular disease prevention is advised to monitor for deficiency in which vitamin?', 'Aspirin can interfere with Vitamin K metabolism, potentially leading to deficiency.', null),
  (md5('question:pharmacy-exam-prep:9:45')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 45, 'In a patient with chronic liver disease, which vitamin supplementation might be necessary due to impaired storage and metabolism?', 'Vitamin A supplementation might be necessary in chronic liver disease due to its impaired storage and metabolism in the liver.', null),
  (md5('question:pharmacy-exam-prep:9:46')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 46, 'A patient with celiac disease is at increased risk of deficiency in which of the following due to malabsorption?', 'Patients with celiac disease are at risk of multiple nutrient deficiencies, including iron, calcium, and vitamin B6, due to malabsorption.', null),
  (md5('question:pharmacy-exam-prep:9:47')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 47, 'A patient on chemotherapy is experiencing severe nausea and vomiting. What vitamin might help alleviate these symptoms?', 'Vitamin B6 can be effective in reducing nausea and vomiting, which are common side effects of chemotherapy.', null),
  (md5('question:pharmacy-exam-prep:9:48')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 48, 'A patient with osteoporosis is advised to increase intake of which mineral to aid in bone health?', 'Calcium intake is crucial in managing osteoporosis to maintain bone health.', null),
  (md5('question:pharmacy-exam-prep:9:49')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 49, 'A patient with atrial fibrillation is on warfarin and reports eating large amounts of green leafy vegetables. What might be a concern with this diet?', 'Green leafy vegetables are high in Vitamin K, which can decrease the effectiveness of warfarin, a Vitamin K antagonist.', null),
  (md5('question:pharmacy-exam-prep:9:50')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 50, 'A patient with rheumatoid arthritis on methotrexate therapy is experiencing fatigue and mouth ulcers. Which nutrient deficiency should be considered?', 'Folic acid deficiency can occur with methotrexate therapy, leading to symptoms like fatigue and mouth ulcers.', null),
  (md5('question:pharmacy-exam-prep:9:51')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 51, 'A patient with chronic heart failure is advised to restrict dietary intake of which mineral?', 'Sodium restriction is important in heart failure management to reduce fluid retention and manage symptoms.', null),
  (md5('question:pharmacy-exam-prep:9:52')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 52, 'Which vitamin deficiency is most likely in a patient with chronic alcoholism and poor diet?', 'Chronic alcoholism and poor diet often lead to thiamine (Vitamin B1) deficiency.', null),
  (md5('question:pharmacy-exam-prep:9:53')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 53, 'A patient undergoing hemodialysis is found to have elevated phosphate levels. Which medication class is commonly used to treat this?', 'Phosphate binders are used to control hyperphosphatemia in patients undergoing hemodialysis.', null),
  (md5('question:pharmacy-exam-prep:9:54')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 54, 'A patient on long-term corticosteroid therapy is at risk of deficiency in which vitamin?', 'Long-term corticosteroid use can lead to Vitamin D deficiency due to effects on calcium metabolism.', null),
  (md5('question:pharmacy-exam-prep:9:55')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 55, 'In a patient with peripheral neuropathy, which vitamin deficiency should be considered?', 'Vitamin B12 deficiency can lead to peripheral neuropathy, characterized by tingling and numbness in the extremities.', null),
  (md5('question:pharmacy-exam-prep:9:56')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 56, 'A patient with chronic kidney disease is prescribed calcitriol. What is the primary purpose of this medication?', 'Calcitriol, an active form of Vitamin D, is used in CKD to help maintain calcium levels and manage secondary hyperparathyroidism.', null),
  (md5('question:pharmacy-exam-prep:9:57')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 57, 'A patient with a new diagnosis of epilepsy is started on phenytoin. Which nutrient interaction is important to monitor?', 'Phenytoin can interfere with folic acid metabolism, leading to deficiency, and folic acid levels should be monitored.', null),
  (md5('question:pharmacy-exam-prep:9:58')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 58, 'A pregnant woman is advised to take which supplement to prevent neural tube defects?', 'Folic acid supplementation is recommended in pregnancy to prevent neural tube defects in the developing fetus.', null),
  (md5('question:pharmacy-exam-prep:9:59')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 59, 'A patient with chronic pancreatitis might require supplementation with which vitamin?', 'Patients with chronic pancreatitis may require Vitamin A supplementation due to malabsorption issues.', null),
  (md5('question:pharmacy-exam-prep:9:60')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 60, 'A patient with a history of gastric ulcers is prescribed a proton pump inhibitor (PPI). What is a potential long-term side effect of PPIs?', 'Long-term use of PPIs can lead to Vitamin B12 deficiency due to reduced stomach acidity affecting its absorption.', null),
  (md5('question:pharmacy-exam-prep:9:61')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 61, 'A patient with a history of renal stones is advised to moderate intake of which nutrient?', 'Calcium intake should be moderated in patients with a history of renal stones to prevent recurrence.', null),
  (md5('question:pharmacy-exam-prep:9:62')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 62, 'A patient with gluten-sensitive enteropathy (celiac disease) is most likely to be deficient in which nutrient?', 'Patients with celiac disease are often deficient in iron due to malabsorption in the damaged gut.', null),
  (md5('question:pharmacy-exam-prep:9:63')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 63, 'Which medication is likely to be prescribed to a patient with osteomalacia?', 'Vitamin D supplements are commonly prescribed in osteomalacia to correct the deficiency and improve bone mineralization.', null),
  (md5('question:pharmacy-exam-prep:9:64')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 64, 'A patient with rheumatoid arthritis on long-term NSAID therapy should be monitored for deficiency in which vitamin?', 'Long-term NSAID use can impair vitamin D metabolism, leading to deficiency and potential bone health issues.', null),
  (md5('question:pharmacy-exam-prep:9:65')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 65, 'In a patient with macrocytic anemia, which vitamin deficiency should be considered?', 'Vitamin B12 deficiency should be considered in patients with macrocytic anemia, as it can lead to the development of large, immature red blood cells.', null),
  (md5('question:pharmacy-exam-prep:9:66')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 66, 'A patient on antiepileptic drugs such as carbamazepine should be monitored for deficiency in which nutrient?', 'Antiepileptic drugs like carbamazepine can lead to folic acid deficiency, which should be monitored and supplemented as necessary.', null),
  (md5('question:pharmacy-exam-prep:9:67')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 67, 'What is the primary reason for administering Vitamin K to a newborn?', 'Vitamin K is administered to newborns to prevent hemorrhagic disease due to low Vitamin K levels at birth.', null),
  (md5('question:pharmacy-exam-prep:9:68')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 68, 'A patient with a history of bariatric surgery is at increased risk of deficiency in which vitamin?', 'Patients who have undergone bariatric surgery are at increased risk of Vitamin B1 (thiamin) deficiency due to altered absorption.', null),
  (md5('question:pharmacy-exam-prep:9:69')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 69, 'A patient on long-term bisphosphonate therapy for osteoporosis should be advised to monitor for which side effect?', 'Long-term bisphosphonate therapy can cause esophageal irritation, and patients should be advised about proper medication administration to minimize this risk.', null),
  (md5('question:pharmacy-exam-prep:9:70')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 70, 'A patient with chronic obstructive pulmonary disease (COPD) is advised to increase intake of which nutrient?', 'Increased intake of Vitamin C is often recommended for patients with COPD to help manage oxidative stress and inflammation associated with the disease.', null),
  (md5('question:pharmacy-exam-prep:9:71')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 71, 'A patient with chronic kidney disease is prescribed calcitriol. What is the primary purpose of this medication?', 'Calcitriol, an active form of Vitamin D, is used in CKD to help maintain calcium levels and manage secondary hyperparathyroidism.', null),
  (md5('question:pharmacy-exam-prep:9:72')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 72, 'Which vitamin supplementation is recommended for a patient with alcoholic liver disease to prevent Wernicke-Korsakoff syndrome?', 'Thiamine supplementation is crucial in patients with alcoholic liver disease to prevent Wernicke-Korsakoff syndrome.', null),
  (md5('question:pharmacy-exam-prep:9:73')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 73, 'A patient with inflammatory bowel disease (IBD) is likely to be deficient in which vitamin?', 'Vitamin D deficiency is common in IBD due to malabsorption and reduced sunlight exposure.', null),
  (md5('question:pharmacy-exam-prep:9:74')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 74, 'A patient on long-term proton pump inhibitor (PPI) therapy should be monitored for deficiency in which mineral?', 'Long-term PPI therapy can lead to iron deficiency due to reduced stomach acid affecting iron absorption.', null),
  (md5('question:pharmacy-exam-prep:9:75')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 75, 'In a patient with pernicious anemia, which vitamin is typically supplemented?', 'Vitamin B12 supplementation is necessary in pernicious anemia due to the inability to absorb B12 from the diet.', null),
  (md5('question:pharmacy-exam-prep:9:76')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 76, 'A patient with hemochromatosis should avoid supplements containing which mineral?', 'Patients with hemochromatosis should avoid iron supplements due to the risk of iron overload.', null),
  (md5('question:pharmacy-exam-prep:9:77')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 77, 'A pregnant woman is found to have iron-deficiency anemia. What is the most appropriate first-line treatment?', 'Oral iron supplements are the first-line treatment for iron-deficiency anemia in pregnancy.', null),
  (md5('question:pharmacy-exam-prep:9:78')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 78, 'What is a potential side effect of high-dose calcium supplementation?', 'High doses of calcium supplements can cause constipation, a common side effect.', null),
  (md5('question:pharmacy-exam-prep:9:79')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 79, 'A patient with a history of gastric bypass surgery is at increased risk of deficiency in which mineral?', 'Patients who have undergone gastric bypass surgery are at increased risk of iron deficiency due to reduced absorption.', null),
  (md5('question:pharmacy-exam-prep:9:80')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 80, 'Which nutrient deficiency is a common side effect of metformin therapy in diabetes management?', 'Metformin therapy can lead to Vitamin B12 deficiency, which should be monitored in patients with long-term use.', null),
  (md5('question:pharmacy-exam-prep:9:81')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 81, 'A patient with chronic obstructive pulmonary disease (COPD) is found to have a Vitamin D deficiency. What is the significance of this finding?', 'Vitamin D deficiency in COPD patients can worsen lung function and increase the risk of infections.', null),
  (md5('question:pharmacy-exam-prep:9:82')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 82, 'A patient with hypercalcemia is prescribed a bisphosphonate. What is the mechanism of action of bisphosphonates in this condition?', 'Bisphosphonates decrease bone resorption, helping to lower serum calcium levels in hypercalcemia.', null),
  (md5('question:pharmacy-exam-prep:9:83')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 83, 'A patient on warfarin therapy has started taking fish oil supplements. What potential interaction should be monitored?', 'Fish oil supplements can increase the risk of bleeding, especially when taken with anticoagulants like warfarin.', null),
  (md5('question:pharmacy-exam-prep:9:84')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 84, 'In a patient with iron overload due to repeated blood transfusions, which medication might be prescribed?', 'Chelation therapy is used to treat iron overload in patients who have had multiple blood transfusions.', null),
  (md5('question:pharmacy-exam-prep:9:85')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 85, 'A patient with a history of peptic ulcer disease is on long-term omeprazole therapy. Which nutrient should be closely monitored?', 'Long-term use of omeprazole can lead to Vitamin B12 deficiency, which should be monitored in patients.', null),
  (md5('question:pharmacy-exam-prep:9:86')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 86, 'A patient with osteoporosis is advised to take which supplement to aid in bone health?', 'Calcium and Vitamin D supplements are crucial for patients with osteoporosis to maintain bone health.', null),
  (md5('question:pharmacy-exam-prep:9:87')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 87, 'Which vitamin is essential for the synthesis of clotting factors and is often given to newborns?', 'Vitamin K is essential for the synthesis of clotting factors and is routinely given to newborns to prevent bleeding disorders.', null),
  (md5('question:pharmacy-exam-prep:9:88')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 88, 'A patient with chronic renal failure is at risk of developing which type of anemia?', 'Patients with chronic renal failure often develop anemia of chronic disease due to reduced erythropoietin production.', null),
  (md5('question:pharmacy-exam-prep:9:89')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 89, 'What is a common side effect of high-dose niacin therapy used in lipid control?', 'High-dose niacin is often associated with flushing and itching, a common side effect.', null),
  (md5('question:pharmacy-exam-prep:9:90')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 90, 'A patient with a history of hypertension is prescribed a diuretic and develops hypokalemia. Which supplement should be considered?', 'Potassium supplements are often needed when patients on diuretics develop hypokalemia.', null),
  (md5('question:pharmacy-exam-prep:9:91')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 91, 'A patient with megaloblastic anemia is found to have a folic acid deficiency. What could be a possible cause of this condition?', 'Folic acid deficiency leading to megaloblastic anemia can be caused by poor diet or excessive alcohol consumption.', null),
  (md5('question:pharmacy-exam-prep:9:92')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 92, 'A patient on long-term prednisone therapy should be counseled about the risk of deficiency in which nutrient?', 'Long-term prednisone use can lead to Vitamin D deficiency, affecting bone health.', null),
  (md5('question:pharmacy-exam-prep:9:93')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 93, 'Which mineral is crucial in the synthesis of thyroid hormones and should be monitored in patients with thyroid disorders?', 'Iodine is essential for the synthesis of thyroid hormones, and its deficiency can exacerbate thyroid disorders.', null),
  (md5('question:pharmacy-exam-prep:9:94')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 94, 'A patient with chronic liver disease should be monitored for deficiency in which vitamin, considering the liver’s role in storage and metabolism?', 'Vitamin A is stored in the liver, and patients with chronic liver disease are at risk of its deficiency.', null),
  (md5('question:pharmacy-exam-prep:9:95')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 95, 'What is the primary dietary advice for a patient with hyperuricemia and gout?', 'Patients with hyperuricemia and gout are advised to decrease fructose intake to reduce uric acid levels.', null),
  (md5('question:pharmacy-exam-prep:9:96')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 96, 'A patient on chemotherapy for breast cancer is advised to supplement with which vitamin to help with bone health?', 'Vitamin D supplementation is important for maintaining bone health, especially in patients undergoing chemotherapy.', null),
  (md5('question:pharmacy-exam-prep:9:97')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 97, 'In a patient with renal insufficiency, which vitamin should be used cautiously due to the risk of accumulation and toxicity?', 'Vitamin A should be used cautiously in patients with renal insufficiency due to the risk of accumulation and toxicity.', null),
  (md5('question:pharmacy-exam-prep:9:98')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 98, 'A patient with a recent diagnosis of celiac disease should be screened for deficiency in which of the following?', 'Patients with celiac disease should be screened for deficiencies in iron, folic acid, and Vitamin B12 due to malabsorption.', null),
  (md5('question:pharmacy-exam-prep:9:99')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 99, 'A patient taking a proton pump inhibitor (PPI) long-term is at risk of developing a deficiency in which mineral, potentially leading to anemia?', 'Long-term PPI use can lead to iron deficiency, potentially causing anemia, due to reduced stomach acid.', null),
  (md5('question:pharmacy-exam-prep:9:100')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 100, 'A patient with chronic pancreatitis is likely to be deficient in which of the following due to malabsorption?', 'Chronic pancreatitis can lead to malabsorption, causing deficiencies in iron, Vitamin A, and Vitamin D.', null),
  (md5('question:pharmacy-exam-prep:9:101')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 101, 'A patient on anticoagulant therapy with warfarin should be counseled about dietary intake of which vitamin?', 'Vitamin K intake should be consistent in patients on warfarin, as it can affect the drug''s anticoagulant effect.', null),
  (md5('question:pharmacy-exam-prep:9:102')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 102, 'Which mineral''s supplementation is crucial for a patient with hypoparathyroidism to maintain normal physiological function?', 'Calcium supplementation is crucial in hypoparathyroidism to maintain normal blood calcium levels.', null),
  (md5('question:pharmacy-exam-prep:9:103')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 103, 'In a patient with chronic renal failure, which vitamin should not be supplemented in high doses due to the risk of toxicity?', 'In patients with chronic renal failure, Vitamin A should not be given in high doses due to the risk of toxicity.', null),
  (md5('question:pharmacy-exam-prep:9:104')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 104, 'A patient with malabsorption syndrome is at increased risk of deficiency in which vitamin, leading to neurological symptoms?', 'Vitamin B12 deficiency, common in malabsorption syndrome, can lead to neurological symptoms.', null),
  (md5('question:pharmacy-exam-prep:9:105')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 105, 'Which vitamin deficiency is associated with beriberi and should be supplemented in patients with a history of chronic alcohol use?', 'Vitamin B1 (Thiamin) deficiency is associated with beriberi and is common in chronic alcohol users.', null),
  (md5('question:pharmacy-exam-prep:9:106')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 106, 'A patient undergoing bariatric surgery is at increased risk of deficiency in which of the following due to reduced absorption?', 'Patients undergoing bariatric surgery are at risk of deficiencies in iron, folic acid, and Vitamin B12.', null),
  (md5('question:pharmacy-exam-prep:9:107')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 107, 'What is the primary concern with excessive intake of vitamin A in a pregnant woman?', 'Excessive Vitamin A intake in pregnancy is associated with teratogenic effects and should be avoided.', null),
  (md5('question:pharmacy-exam-prep:9:108')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 108, 'A patient with a history of heart failure is prescribed spironolacton What electrolyte imbalance should be closely monitored?', 'Hyperkalemia should be monitored in patients taking spironolactone, a potassium-sparing diuretic.', null),
  (md5('question:pharmacy-exam-prep:9:109')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 109, 'A patient with sickle cell disease is often supplemented with which vitamin to reduce complications?', 'Vitamin E supplementation in sickle cell disease can help reduce oxidative stress and related complications.', null),
  (md5('question:pharmacy-exam-prep:9:110')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 110, 'A patient with gluten-sensitive enteropathy (celiac diseas is at risk for deficiency in which of the following due to malabsorption?', 'Celiac disease can lead to malabsorption of various nutrients, including iron, calcium, and Vitamin D.', null),
  (md5('question:pharmacy-exam-prep:9:111')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 111, 'A patient with osteoporosis is advised to take a bisphosphonat What is an important counseling point for this medication?', 'Bisphosphonates should be taken with a full glass of water, and the patient should remain upright for at least 30 minutes to prevent esophageal irritation.', null),
  (md5('question:pharmacy-exam-prep:9:112')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 112, 'In a patient with atrial fibrillation on dabigatran, a direct thrombin inhibitor, what nutrient interaction is less of a concern compared to warfarin therapy?', 'Vitamin K intake does not affect dabigatran efficacy, unlike warfarin, where consistent intake is necessary.', null),
  (md5('question:pharmacy-exam-prep:9:113')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 113, 'A patient with chronic liver disease is at risk of deficiency in which vitamin due to impaired storage and metabolism?', 'Vitamin A deficiency is a concern in chronic liver disease due to impaired storage and metabolism in the liver.', null),
  (md5('question:pharmacy-exam-prep:9:114')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 114, 'Which mineral is essential for oxygen transport and is often deficient in chronic kidney disease leading to anemia?', 'Iron is essential for oxygen transport in the blood, and its deficiency is common in chronic kidney disease, contributing to anemia.', null),
  (md5('question:pharmacy-exam-prep:9:115')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 115, 'A patient taking a loop diuretic like furosemide should be monitored for deficiency in which electrolyte?', 'Loop diuretics like furosemide can lead to potassium deficiency, which needs to be monitored.', null),
  (md5('question:pharmacy-exam-prep:9:116')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 116, 'What is the most common nutritional deficiency worldwide, often seen in women of childbearing age?', 'Iron deficiency anemia is the most common nutritional deficiency globally, especially among women of childbearing age.', null),
  (md5('question:pharmacy-exam-prep:9:117')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 117, 'A patient with pernicious anemia requires supplementation with which vitamin?', 'Vitamin B12 supplementation is necessary in pernicious anemia due to the lack of intrinsic factor needed for its absorption.', null),
  (md5('question:pharmacy-exam-prep:9:118')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 118, 'A patient with a malabsorptive disorder is at increased risk for deficiency in which fat-soluble vitamin?', 'Fat-soluble vitamins (A, D, E, K) are at risk of deficiency in malabsorptive disorders due to impaired fat absorption.', null),
  (md5('question:pharmacy-exam-prep:9:119')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 119, 'Which vitamin deficiency is associated with night blindness and dry eyes, and is often seen in patients with cystic fibrosis?', 'Vitamin A deficiency, which can lead to night blindness and dry eyes, is common in conditions like cystic fibrosis due to malabsorption.', null),
  (md5('question:pharmacy-exam-prep:9:120')::uuid, md5('quiz:pharmacy-exam-prep:9')::uuid, 120, 'Mrs M has walked into your pharmacy looking to buy multivitamin supplements. As Mrs M is one of your regular patients, you look on her records to find out that she regularly takes orlistat 120mg TDS. You realise that this can somewhat impair the absorption of fat-soluble vitamins and you would like to make him aware of this. Which one of the following vitamins is NOT fat-soluble?', 'Vitamin B is the only water-soluble vitamin here, all others (ADEK) being fat-soluble. We advise patients to have the fat-soluble vitamins with their largest meal of the day to promote absorption.', null)
