  (md5('question:pharmacy-exam-prep:10:117')::uuid, md5('quiz:pharmacy-exam-prep:10')::uuid, 117, 'Which TNF-α inhibitor is contraindicated in patients with a known allergy to latex?', 'Vedolizumab should be avoided in patients with a known allergy to latex.', null),
