insert into public.chapters (id, course_id, position, title) values
  (md5('chapter:pharmacy-exam-prep:11')::uuid, md5('course:pharmacy-exam-prep')::uuid, 11, 'Obstetrics, Gynaecology and Genitourinary tract')
insert into public.quizzes (id, chapter_id, title, position, is_preview) values
  (md5('quiz:pharmacy-exam-prep:11')::uuid, md5('chapter:pharmacy-exam-prep:11')::uuid, 'Obstetrics, Gynaecology and Genitourinary tract', 1, false)
insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('question:pharmacy-exam-prep:11:1')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 1, 'Which drug is contraindicated in pregnancy due to its teratogenic effects?', 'Isotretinoin is contraindicated in pregnancy due to its high teratogenic risk, causing severe birth defects.', null),
  (md5('question:pharmacy-exam-prep:11:2')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 2, 'What is the first-line treatment for gestational diabetes?', 'Insulin remains the primary therapy for managing gestational diabetes due to its safety and efficacy in pregnancy.', null),
  (md5('question:pharmacy-exam-prep:11:3')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 3, 'Which antibiotic is considered safe during lactation?', 'Amoxicillin is generally considered safe during lactation with minimal risk to the breastfed infant.', null),
  (md5('question:pharmacy-exam-prep:11:4')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 4, 'Which contraceptive method is the most effective in preventing pregnancy?', 'The intrauterine device (IUD) is one of the most effective methods with a very low failure rate in preventing pregnancy.', null),
  (md5('question:pharmacy-exam-prep:11:5')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 5, 'What is the primary action of oxytocin in obstetrics?', 'Oxytocin primarily induces uterine contractions during labor and delivery.', null),
  (md5('question:pharmacy-exam-prep:11:6')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 6, 'Which drug is indicated for the treatment of recurrent urinary tract infections?', 'Nitrofurantoin is often used for the prophylactic treatment of recurrent urinary tract infections.', null),
  (md5('question:pharmacy-exam-prep:11:7')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 7, 'What is the mechanism of action of mifepristone in medical termination of pregnancy?', 'Mifepristone acts as a progesterone receptor antagonist leading to endometrial breakdown and termination of pregnancy.', null),
  (md5('question:pharmacy-exam-prep:11:8')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 8, 'Which antiviral medication is used as prophylaxis for genital herpes during pregnancy?', 'Acyclovir is commonly used for prophylaxis against genital herpes during pregnancy to reduce transmission to the baby.', null),
  (md5('question:pharmacy-exam-prep:11:9')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 9, 'Which hormone is responsible for stimulating milk production during breastfeeding?', 'Prolactin is the primary hormone responsible for stimulating milk production in the mammary glands.', null),
  (md5('question:pharmacy-exam-prep:11:10')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 10, 'Which drug is contraindicated in patients with a history of cholestasis of pregnancy?', 'Ursodeoxycholic acid can exacerbate cholestasis of pregnancy and is contraindicated in such cases.', null),
  (md5('question:pharmacy-exam-prep:11:11')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 11, 'What is the primary mechanism of action of misoprostol in obstetrics?', 'Misoprostol primarily induces uterine contractions, aiding in cervical dilation and uterine expulsion in obstetrics.', null),
  (md5('question:pharmacy-exam-prep:11:12')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 12, 'Which antibiotic is associated with a risk of causing gray baby syndrome in neonates?', 'Chloramphenicol use in neonates has been linked to the development of gray baby syndrome.', null),
  (md5('question:pharmacy-exam-prep:11:13')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 13, 'Which drug is a selective estrogen receptor modulator used in the treatment of infertility?', 'Clomiphene is a selective estrogen receptor modulator commonly used in the treatment of infertility.', null),
  (md5('question:pharmacy-exam-prep:11:14')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 14, 'Which class of drugs is contraindicated in pregnancy due to a potential risk of causing fetal harm?', 'ACE inhibitors are contraindicated in pregnancy due to their potential teratogenic effects.', null),
  (md5('question:pharmacy-exam-prep:11:15')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 15, 'Which drug is used for emergency contraception within 72 hours of unprotected intercourse?', 'Levonorgestrel is a common emergency contraceptive used within 72 hours of unprotected intercourse.', null),
  (md5('question:pharmacy-exam-prep:11:16')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 16, 'Which drug is a first-line treatment for endometriosis?', 'Gonadotropin-releasing hormone agonists are often used as the first-line treatment for endometriosis.', null),
  (md5('question:pharmacy-exam-prep:11:17')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 17, 'Which medication is used to prevent preterm labor in women at risk?', 'Magnesium sulfate is often used to prevent preterm labor in high-risk women due to its tocolytic properties.', null),
  (md5('question:pharmacy-exam-prep:11:18')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 18, 'Which medication is used for the medical management of early pregnancy loss?', 'Misoprostol is commonly used for medical management in cases of early pregnancy loss.', null),
  (md5('question:pharmacy-exam-prep:11:19')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 19, 'Which drug is a selective serotonin reuptake inhibitor (SSRI) commonly used in pregnancy?', 'Sertraline is often preferred among SSRIs due to its safety profile in pregnancy.', null),
  (md5('question:pharmacy-exam-prep:11:20')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 20, 'Which medication is used for the treatment of polycystic ovary syndrome (PCOS) to induce ovulation?', 'Clomiphene is commonly used to induce ovulation in women with PCOS.', null),
  (md5('question:pharmacy-exam-prep:11:21')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 21, 'What is the primary mechanism of action of finasteride in BPH?', 'Finasteride inhibits 5-alpha reductase, decreasing the conversion of testosterone to dihydrotestosterone in BPH.', null),
  (md5('question:pharmacy-exam-prep:11:22')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 22, 'Which mechanism best describes the action of tolterodine in OAB?', 'Tolterodine acts as a competitive muscarinic receptor antagonist, reducing bladder contractions in overactive bladder.', null),
  (md5('question:pharmacy-exam-prep:11:23')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 23, 'What is the primary mechanism of action of sildenafil in ED?', 'Sildenafil primarily works by inhibiting phosphodiesterase-5, leading to increased cGMP and smooth muscle relaxation.', null),
  (md5('question:pharmacy-exam-prep:11:24')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 24, 'Which mechanism best describes the action of oxybutynin in OAB?', 'Oxybutynin acts as a muscarinic receptor antagonist, reducing bladder contractions in overactive bladder.', null),
  (md5('question:pharmacy-exam-prep:11:25')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 25, 'What is the primary mechanism of action of terazosin in BPH?', 'Terazosin primarily works by blocking alpha-1 adrenergic receptors, relaxing smooth muscles in the prostate and bladder.', null),
  (md5('question:pharmacy-exam-prep:11:26')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 26, 'Which mechanism best describes the action of raloxifene in osteoporosis?', 'Raloxifene acts as a selective estrogen receptor modulator (SERM), mimicking estrogen''s beneficial effects on bone.', null),
  (md5('question:pharmacy-exam-prep:11:27')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 27, 'What is the primary mechanism of action of tamsulosin in BPH?', 'Tamsulosin primarily targets alpha-1 adrenergic receptors, relaxing smooth muscles in the prostate and bladder.', null),
  (md5('question:pharmacy-exam-prep:11:28')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 28, 'Which mechanism best describes the action of clomiphene in fertility treatments?', 'Clomiphene acts as a selective estrogen receptor modulator (SERM), stimulating ovulation by blocking estrogen receptors.', null),
  (md5('question:pharmacy-exam-prep:11:29')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 29, 'What is the primary mechanism of action of alfuzosin in BPH?', 'Alfuzosin primarily works by blocking alpha-1 adrenergic receptors, reducing smooth muscle tone in the prostate.', null),
  (md5('question:pharmacy-exam-prep:11:30')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 30, 'Which mechanism best describes the action of letrozole in breast cancer treatment?', 'Letrozole inhibits aromatase, reducing estrogen production and thereby suppressing estrogen-dependent tumor growth.', null),
  (md5('question:pharmacy-exam-prep:11:31')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 31, 'What is the primary mechanism of action of darifenacin in OAB?', 'Darifenacin primarily acts as a competitive antagonist at muscarinic receptors, reducing bladder muscle contractions.', null),
  (md5('question:pharmacy-exam-prep:11:32')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 32, 'Which mechanism best describes the action of dutasteride in BPH?', 'Dutasteride inhibits both Type I and Type II 5-alpha reductase, reducing dihydrotestosterone levels in BPH.', null),
  (md5('question:pharmacy-exam-prep:11:33')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 33, 'What is the primary mechanism of action of fosfomycin in UTIs?', 'Fosfomycin inhibits bacterial cell wall synthesis by blocking MurA, an enzyme involved in peptidoglycan production.', null),
  (md5('question:pharmacy-exam-prep:11:34')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 34, 'Which mechanism best describes the action of bicalutamide in prostate cancer treatment?', 'Bicalutamide competitively inhibits androgen receptors, preventing androgen-mediated tumor growth in prostate cancer.', null),
  (md5('question:pharmacy-exam-prep:11:35')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 35, 'What is the primary mechanism of action of solifenacin in OAB?', 'Solifenacin primarily acts as a competitive muscarinic receptor antagonist, reducing bladder muscle contractions.', null),
  (md5('question:pharmacy-exam-prep:11:36')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 36, 'Which mechanism best describes the action of fulvestrant in breast cancer treatment?', 'Fulvestrant acts as a pure estrogen receptor antagonist, blocking estrogen binding and leading to receptor degradation.', null),
  (md5('question:pharmacy-exam-prep:11:37')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 37, 'What is the primary mechanism of action of risedronate in osteoporosis?', 'Risedronate primarily inhibits osteoclast-mediated bone resorption, slowing down bone loss in osteoporosis.', null),
  (md5('question:pharmacy-exam-prep:11:38')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 38, 'Which mechanism best describes the action of solifenacin in OAB?', 'Solifenacin primarily acts as a competitive muscarinic receptor antagonist, reducing bladder muscle contractions.', null),
  (md5('question:pharmacy-exam-prep:11:39')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 39, 'What is the primary mechanism of action of pamidronate in osteoporosis?', 'Pamidronate primarily inhibits osteoclast activity, reducing bone resorption and improving bone density in osteoporosis.', null),
  (md5('question:pharmacy-exam-prep:11:40')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 40, 'Which mechanism best describes the action of enzalutamide in prostate cancer treatment?', 'Enzalutamide inhibits androgen receptor signaling, suppressing tumor growth in prostate cancer cells dependent on androgens.', null),
  (md5('question:pharmacy-exam-prep:11:41')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 41, 'A 65-year-old male presents with BPH. Which mechanism best describes the action of dutasteride, which has been prescribed to him?', 'Dutasteride inhibits 5-alpha reductase, reducing the conversion of testosterone to dihydrotestosterone in BPH.', null),
  (md5('question:pharmacy-exam-prep:11:42')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 42, 'A 45-year-old female is diagnosed with hormone receptor-positive breast cancer. What is the primary mechanism of action of tamoxifen, which has been prescribed as part of her treatment?', 'Tamoxifen acts as a selective estrogen receptor modulator (SERM), competitively blocking estrogen receptors in breast tissue.', null),
  (md5('question:pharmacy-exam-prep:11:43')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 43, 'A 50-year-old male is prescribed tadalafil for erectile dysfunction. What is the primary mechanism of action of tadalafil?', 'Tadalafil primarily works by inhibiting phosphodiesterase-5, enhancing the effects of nitric oxide and improving erectile function.', null),
  (md5('question:pharmacy-exam-prep:11:44')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 44, 'A 30-year-old female with polycystic ovary syndrome (PCOS) is prescribed metformin. Which mechanism best describes the action of metformin in PCOS?', 'Metformin primarily works by activating insulin receptors, improving insulin sensitivity in PCOS.', null),
  (md5('question:pharmacy-exam-prep:11:45')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 45, 'A 70-year-old male is prescribed sildenafil for the management of pulmonary arterial hypertension (PAH). What is the primary mechanism of action of sildenafil in PAH?', 'Sildenafil primarily works by inhibiting phosphodiesterase-5, increasing cGMP levels and vasodilation in PAH.', null),
  (md5('question:pharmacy-exam-prep:11:46')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 46, 'A 25-year-old female with endometriosis is prescribed leuprolid. Which mechanism best describes the action of leuprolide in endometriosis?', 'Leuprolide acts as a gonadotropin-releasing hormone agonist, suppressing ovarian function and estrogen production in endometriosis.', null),
  (md5('question:pharmacy-exam-prep:11:47')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 47, 'A 60-year-old male with prostate cancer is prescribed bicalutamide. What is the primary mechanism of action of bicalutamide in prostate cancer?', 'Bicalutamide competitively inhibits androgen receptors, suppressing androgen-dependent tumor growth in prostate cancer.', null),
  (md5('question:pharmacy-exam-prep:11:48')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 48, 'A 40-year-old female is prescribed clomiphene for infertility. Which mechanism best describes the action of clomiphene in inducing ovulation?', 'Clomiphene acts as a selective estrogen receptor modulator (SERM), stimulating ovulation by blocking estrogen receptors.', null),
  (md5('question:pharmacy-exam-prep:11:49')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 49, 'A 55-year-old male with BPH is prescribed alfuzosin. What is the primary mechanism of action of alfuzosin in BPH?', 'Alfuzosin primarily works by blocking alpha-1 adrenergic receptors, reducing smooth muscle tone in the prostate.', null),
  (md5('question:pharmacy-exam-prep:11:50')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 50, 'A 30-year-old female with breast cancer is prescribed anastrozole. Which mechanism best describes the action of anastrozole in breast cancer treatment?', 'Anastrozole inhibits aromatase, reducing estrogen production and suppressing estrogen-dependent tumor growth in breast cancer.', null),
  (md5('question:pharmacy-exam-prep:11:51')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 51, 'A pregnant patient with epilepsy is taking phenytoin. Which drug used in pregnancy may interact with phenytoin, leading to reduced serum levels of phenytoin?', 'Aspirin can induce hepatic microsomal enzymes, potentially decreasing phenytoin levels.', null),
  (md5('question:pharmacy-exam-prep:11:52')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 52, 'In a pregnant patient receiving methotrexate for ectopic pregnancy, which drug interaction might lead to methotrexate toxicity?', 'NSAIDs can decrease renal clearance and increase methotrexate levels, leading to toxicity.', null),
  (md5('question:pharmacy-exam-prep:11:53')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 53, 'A woman taking oral contraceptives is prescribed rifampicin for tuberculosis. What is the most likely consequence of this drug interaction?', 'Rifampicin induces hepatic enzymes, reducing the effectiveness of oral contraceptives.', null),
  (md5('question:pharmacy-exam-prep:11:54')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 54, 'A pregnant patient on warfarin therapy requires treatment with an antibiotic. Which antibiotic poses the highest risk of increasing the anticoagulant effect of warfarin?', 'Co-trimoxazole can potentiate the anticoagulant effect of warfarin by inhibiting its metabolism.', null),
  (md5('question:pharmacy-exam-prep:11:55')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 55, 'A pregnant woman on levothyroxine for hypothyroidism develops a urinary tract infection. Which antibiotic should be cautiously prescribed due to its potential to decrease levothyroxine absorption?', 'Nitrofurantoin can reduce levothyroxine absorption when taken concurrently.', null),
  (md5('question:pharmacy-exam-prep:11:56')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 56, 'A patient with recurrent urinary tract infections is prescribed methenamine. Which medication should be avoided due to the potential for decreasing the effectiveness of methenamine?', 'Ciprofloxacin increases urinary pH, potentially reducing methenamine efficacy.', null),
  (md5('question:pharmacy-exam-prep:11:57')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 57, 'A pregnant patient on lithium for bipolar disorder develops a urinary tract infection. Which antibiotic should be avoided due to potential interactions with lithium leading to increased lithium levels?', 'Trimethoprim can increase lithium levels by inhibiting its renal excretion.', null),
  (md5('question:pharmacy-exam-prep:11:58')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 58, 'A pregnant woman with a history of renal stones is prescribed acetazolamide for glaucoma. Which medication may interact with acetazolamide, potentially reducing its efficacy in preventing stone formation?', 'Sodium bicarbonate can alkalinize urine, reducing the effectiveness of acetazolamide in preventing stone formation.', null),
  (md5('question:pharmacy-exam-prep:11:59')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 59, 'A pregnant patient on enoxaparin for deep vein thrombosis prophylaxis is diagnosed with a urinary tract infection. Which antibiotic should be cautiously prescribed to avoid potential interactions with enoxaparin?', 'Gentamicin might increase the risk of bleeding when used concomitantly with enoxaparin.', null),
  (md5('question:pharmacy-exam-prep:11:60')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 60, 'A woman on hormonal replacement therapy is prescribed ketoconazole for a fungal infection. Which statement about this drug interaction is accurate?', 'Ketoconazole inhibits cytochrome P450 enzymes, potentially increasing hormonal therapy levels.', null),
  (md5('question:pharmacy-exam-prep:11:61')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 61, 'A pregnant patient on atenolol for hypertension develops a urinary tract infection. Which antibiotic should be avoided due to potential interactions with atenolol, leading to increased atenolol levels?', 'Trimethoprim can increase atenolol levels by inhibiting its renal excretion.', null),
  (md5('question:pharmacy-exam-prep:11:62')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 62, 'A pregnant patient on heparin therapy for thrombosis prophylaxis is prescribed an antibiotic. Which antibiotic might increase the risk of bleeding when used concomitantly with heparin?', 'Erythromycin might increase the risk of bleeding when used with heparin due to potential interactions.', null),
  (md5('question:pharmacy-exam-prep:11:63')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 63, 'A woman on oral contraceptives is prescribed rifampicin for an infection. What advice should be given regarding contraception while on rifampicin therapy?', 'Rifampicin reduces the effectiveness of oral contraceptives; therefore, additional barrier methods are recommended.', null),
  (md5('question:pharmacy-exam-prep:11:64')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 64, 'A pregnant patient on metformin for gestational diabetes is prescribed an antibiotic. Which antibiotic might lead to an increased risk of lactic acidosis when used concomitantly with metformin?', 'Trimethoprim can increase the risk of lactic acidosis when used with metformin by inhibiting its renal excretion.', null),
  (md5('question:pharmacy-exam-prep:11:65')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 65, 'A pregnant patient on amitriptyline for depression develops a urinary tract infection. Which antibiotic should be avoided due to potential interactions with amitriptyline, leading to increased amitriptyline levels?', 'Trimethoprim can increase amitriptyline levels by inhibiting its renal excretion.', null),
  (md5('question:pharmacy-exam-prep:11:66')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 66, 'A woman on hormonal contraception is prescribed phenytoin for seizures. What advice should be given regarding contraception while on phenytoin therapy?', 'Phenytoin reduces the effectiveness of hormonal contraception, so additional barrier methods are recommended.', null),
  (md5('question:pharmacy-exam-prep:11:67')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 67, 'A pregnant patient on nifedipine for hypertension develops a urinary tract infection. Which antibiotic should be avoided due to potential interactions with nifedipine, leading to increased nifedipine levels?', 'Ciprofloxacin can increase nifedipine levels by inhibiting its metabolism.', null),
  (md5('question:pharmacy-exam-prep:11:68')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 68, 'A woman on hormonal replacement therapy is prescribed rifampicin for an infection. What advice should be given regarding hormonal therapy while on rifampicin therapy?', 'Rifampicin decreases hormonal therapy efficacy; therefore, switching to non-hormonal options is recommended.', null),
  (md5('question:pharmacy-exam-prep:11:69')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 69, 'A pregnant patient on insulin for gestational diabetes is prescribed an antibiotic. Which antibiotic might require adjustments in insulin dosage due to potential interactions?', 'Ciprofloxacin might affect blood glucose levels, necessitating adjustments in insulin dosage.', null),
  (md5('question:pharmacy-exam-prep:11:70')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 70, 'A woman on hormonal contraception is prescribed rifampicin for an infection. What advice should be given regarding contraception while on rifampicin therapy?', 'Rifampicin reduces the effectiveness of hormonal contraception; therefore, additional barrier methods are recommended.', null),
  (md5('question:pharmacy-exam-prep:11:71')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 71, 'A patient taking finasteride for benign prostatic hyperplasia experiences breast tenderness and enlargement. Which statement accurately explains these side effects?', 'Finasteride inhibits the conversion of testosterone to dihydrotestosterone, leading to increased estrogen levels and resulting in gynecomastia.', null),
  (md5('question:pharmacy-exam-prep:11:72')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 72, 'A patient using oxybutynin for overactive bladder complains of dry mouth, constipation, and blurred vision. Which physiological effect of oxybutynin contributes to these side effects?', 'Oxybutynin, as an anticholinergic agent, leads to dry mouth, constipation, and blurred vision due to its action on blocking cholinergic receptors.', null),
  (md5('question:pharmacy-exam-prep:11:73')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 73, 'A woman undergoing chemotherapy with cisplatin develops severe nausea and vomiting. Which medication would be most effective in preventing these side effects?', 'Ondansetron, a serotonin receptor antagonist, is highly effective in preventing chemotherapy-induced nausea and vomiting.', null),
  (md5('question:pharmacy-exam-prep:11:74')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 74, 'A patient receiving intravenous vancomycin for a severe infection develops redness and swelling at the infusion site. Which physiological effect of vancomycin may cause this reaction?', 'Vancomycin can cause direct mast cell degranulation, leading to bradykinin release and subsequent redness and swelling at the infusion site.', null),
  (md5('question:pharmacy-exam-prep:11:75')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 75, 'A woman using clomiphene for ovulation induction reports visual disturbances and flashes of light. Which side effect of clomiphene is likely responsible for these symptoms?', 'Clomiphene can increase the risk of retinal detachment, which presents with symptoms like visual disturbances and flashes of light.', null),
  (md5('question:pharmacy-exam-prep:11:76')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 76, 'A patient receiving a prostaglandin analogue for glaucoma treatment experiences iris discoloration. Which mechanism contributes to this side effect?', 'Prostaglandin analogues can increase melanin production, leading to iris discoloration or darkening.', null),
  (md5('question:pharmacy-exam-prep:11:77')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 77, 'A woman taking oral contraceptives presents with sudden leg pain and swelling. Which side effect of oral contraceptives might cause these symptoms?', 'Oral contraceptives can increase the risk of thrombosis, resulting in symptoms like leg pain and swelling due to deep vein thrombosis.', null),
  (md5('question:pharmacy-exam-prep:11:78')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 78, 'A patient prescribed methotrexate for ectopic pregnancy develops mouth ulcers and nausea. Which mechanism contributes to these side effects of methotrexate?', 'Methotrexate inhibits dihydrofolate reductase, leading to folic acid depletion and subsequent side effects like mouth ulcers and nausea.', null),
  (md5('question:pharmacy-exam-prep:11:79')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 79, 'A woman on tamoxifen therapy for breast cancer complains of hot flashes and vaginal dryness. Which statement accurately describes the cause of these symptoms?', 'Tamoxifen acts as an estrogen receptor antagonist, causing side effects like hot flashes and vaginal dryness due to its action on estrogen receptors.', null),
  (md5('question:pharmacy-exam-prep:11:80')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 80, 'A patient receiving allopurinol for gout develops a severe skin rash and fever. Which adverse effect of allopurinol is most likely responsible for these symptoms?', 'Allopurinol is known to cause severe hypersensitivity reactions, presenting as skin rash and fever in some cases.', null),
  (md5('question:pharmacy-exam-prep:11:81')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 81, 'A woman taking metronidazole for bacterial vaginosis complains of a metallic taste in her mouth. Which mechanism contributes to this common side effect of metronidazole?', 'Metronidazole can alter the oral flora, leading to a metallic taste sensation in the mouth.', null),
  (md5('question:pharmacy-exam-prep:11:82')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 82, 'A patient prescribed spironolactone for heart failure develops gynecomastia and erectile dysfunction. Which action of spironolactone contributes to these side effects?', 'Spironolactone can act as an androgen receptor agonist, leading to side effects like gynecomastia and erectile dysfunction.', null),
  (md5('question:pharmacy-exam-prep:11:83')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 83, 'A woman using leuprolide for endometriosis experiences hot flashes, vaginal dryness, and mood swings. Which physiological effect of leuprolide contributes to these side effects?', 'Leuprolide suppresses estrogen production, leading to side effects like hot flashes, vaginal dryness, and mood swings due to estrogen depletion.', null),
  (md5('question:pharmacy-exam-prep:11:84')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 84, 'A patient on phenytoin for seizures develops gum hyperplasia. Which mechanism contributes to this side effect of phenytoin?', 'Phenytoin can stimulate fibroblasts, leading to excessive collagen synthesis and subsequent gum hyperplasia.', null),
  (md5('question:pharmacy-exam-prep:11:85')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 85, 'A woman using danazol for endometriosis presents with voice deepening and clitoral enlargement. Which action of danazol contributes to these masculinizing side effects?', 'Danazol can increase androgen production, leading to masculinizing side effects like voice deepening and clitoral enlargement.', null),
  (md5('question:pharmacy-exam-prep:11:86')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 86, 'A patient taking furosemide for heart failure develops low potassium levels and muscle weakness. Which mechanism contributes to these side effects of furosemide?', 'Furosemide''s action as a loop diuretic leads to sodium and potassium excretion, causing low potassium levels and subsequent muscle weakness.', null),
  (md5('question:pharmacy-exam-prep:11:87')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 87, 'A woman using misoprostol for medical abortion reports severe abdominal pain and vaginal bleeding. Which side effect of misoprostol is responsible for these symptoms?', 'Misoprostol induces uterine contractions, leading to abdominal pain and vaginal bleeding during medical abortion.', null),
  (md5('question:pharmacy-exam-prep:11:88')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 88, 'A patient prescribed tamsulosin for benign prostatic hyperplasia experiences dizziness and orthostatic hypotension. Which pharmacological effect of tamsulosin contributes to these side effects?', 'Tamsulosin, as an alpha-adrenergic blocker, can cause dizziness and orthostatic hypotension by relaxing smooth muscle in blood vessels.', null),
  (md5('question:pharmacy-exam-prep:11:89')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 89, 'A woman using mifepristone for medical termination of pregnancy develops heavy vaginal bleeding. Which mechanism contributes to this side effect of mifepristone?', 'Mifepristone induces uterine contractions, leading to heavy vaginal bleeding during medical termination of pregnancy.', null),
  (md5('question:pharmacy-exam-prep:11:90')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 90, 'A patient prescribed sildenafil for erectile dysfunction complains of headache and flushing. Which physiological effect of sildenafil contributes to these side effects?', 'Sildenafil, as a phosphodiesterase inhibitor, causes vasodilation, resulting in side effects like headache and flushing due to increased blood flow.', null),
  (md5('question:pharmacy-exam-prep:11:91')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 91, 'A patient prescribed metformin for type 2 diabetes presents with lactic acidosis. Which factor contributes to this rare but serious side effect of metformin?', 'Metformin-associated lactic acidosis is primarily linked to impaired renal function, leading to its accumulation and subsequent lactic acidosis.', null),
  (md5('question:pharmacy-exam-prep:11:92')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 92, 'A woman taking valproate for epilepsy experiences weight gain, alopecia, and tremors. Which mechanism contributes to these side effects of valproate?', 'Valproate enhances GABAergic transmission, leading to side effects like weight gain, alopecia, and tremors.', null),
  (md5('question:pharmacy-exam-prep:11:93')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 93, 'A patient using warfarin for anticoagulation develops purple discoloration of the toes and severe pain. Which side effect of warfarin is most likely responsible for these symptoms?', 'Warfarin-induced purple toe syndrome is characterized by purple discoloration and severe pain due to microembolization.', null),
  (md5('question:pharmacy-exam-prep:11:94')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 94, 'A woman using bisphosphonates for osteoporosis complains of heartburn and difficulty swallowing. Which side effect of bisphosphonates might cause these symptoms?', 'Bisphosphonates can cause esophageal ulceration, leading to symptoms like heartburn and difficulty swallowing.', null),
  (md5('question:pharmacy-exam-prep:11:95')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 95, 'A patient prescribed fluoxetine for depression experiences sexual dysfunction, drowsiness, and weight gain. Which mechanism contributes to these side effects of fluoxetine?', 'Fluoxetine, as an SSRI, blocks serotonin reuptake, leading to side effects like sexual dysfunction, drowsiness, and weight gain.', null),
  (md5('question:pharmacy-exam-prep:11:96')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 96, 'A woman on atenolol for hypertension develops bronchospasm and worsening of asthma symptoms. Which pharmacological effect of atenolol contributes to these side effects?', 'Atenolol''s beta-1 receptor blockade can lead to bronchospasm and worsen asthma symptoms due to beta-2 receptor antagonism in the lungs.', null),
  (md5('question:pharmacy-exam-prep:11:97')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 97, 'A patient using alendronate for osteoporosis experiences jaw pain and osteonecrosis of the jaw. Which mechanism contributes to these side effects of alendronate?', 'Alendronate inhibits osteoclasts, potentially leading to jaw pain and osteonecrosis of the jaw.', null),
  (md5('question:pharmacy-exam-prep:11:98')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 98, 'A woman taking carbamazepine for epilepsy develops a skin rash and fever. Which side effect of carbamazepine is most likely responsible for these symptoms?', 'Carbamazepine can induce severe hypersensitivity reactions, presenting as skin rash and fever.', null),
  (md5('question:pharmacy-exam-prep:11:99')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 99, 'A patient using tadalafil for erectile dysfunction complains of sudden vision loss in one eye. Which side effect of tadalafil is most likely responsible for this symptom?', 'Tadalafil use has been associated with non-arteritic anterior ischemic optic neuropathy (NAION), leading to sudden vision loss.', null),
  (md5('question:pharmacy-exam-prep:11:100')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 100, 'A woman using levothyroxine for hypothyroidism reports palpitations and excessive sweating. Which side effect of levothyroxine might cause these symptoms?', 'Excessive doses of levothyroxine can induce symptoms of thyrotoxicosis, including palpitations and excessive sweating.', null),
  (md5('question:pharmacy-exam-prep:11:101')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 101, 'A patient on ciprofloxacin for a urinary tract infection experiences tendon pain and swelling. Which side effect of ciprofloxacin is most likely responsible for these symptoms?', 'Ciprofloxacin can cause tendonitis or tendon rupture as an adverse effect, leading to tendon pain and swelling.', null),
  (md5('question:pharmacy-exam-prep:11:102')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 102, 'A woman using medroxyprogesterone acetate for contraception develops irregular menstrual bleeding and amenorrhea. Which mechanism contributes to these side effects of medroxyprogesterone acetate?', 'Medroxyprogesterone acetate can cause endometrial atrophy, leading to irregular bleeding and amenorrhea.', null),
  (md5('question:pharmacy-exam-prep:11:103')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 103, 'A patient taking hydrochlorothiazide for hypertension develops hypokalemia and muscle cramps. Which mechanism contributes to these side effects of hydrochlorothiazide?', 'Hydrochlorothiazide increases potassium excretion, causing hypokalemia and subsequent muscle cramps.', null),
  (md5('question:pharmacy-exam-prep:11:104')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 104, 'A woman using sertraline for depression experiences serotonin syndrome with symptoms of agitation, hyperthermia, and tremors. Which action of sertraline contributes to these side effects?', 'Sertraline''s action of blocking serotonin reuptake can lead to serotonin syndrome with symptoms like agitation, hyperthermia, and tremors.', null),
  (md5('question:pharmacy-exam-prep:11:105')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 105, 'A patient on lisinopril for hypertension develops a dry cough. Which mechanism contributes to this side effect of lisinopril?', 'Lisinopril can increase bradykinin levels, leading to a dry, persistent cough as a side effect.', null),
  (md5('question:pharmacy-exam-prep:11:106')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 106, 'A woman using mirtazapine for depression reports increased appetite and weight gain. Which action of mirtazapine contributes to these side effects?', 'Mirtazapine''s action of histamine release can lead to increased appetite and weight gain as side effects.', null),
  (md5('question:pharmacy-exam-prep:11:107')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 107, 'A patient taking amitriptyline for neuropathic pain develops urinary retention and constipation. Which pharmacological effect of amitriptyline contributes to these side effects?', 'Amitriptyline''s anticholinergic activity can cause urinary retention and constipation as side effects.', null),
  (md5('question:pharmacy-exam-prep:11:108')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 108, 'A woman on estradiol therapy for menopausal symptoms experiences breast tenderness and vaginal bleeding. Which mechanism contributes to these side effects of estradiol?', 'Estradiol therapy can lead to breast tenderness and vaginal bleeding due to estrogenic effects on breast tissue and the endometrium.', null),
  (md5('question:pharmacy-exam-prep:11:109')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 109, 'A patient using amoxicillin-clavulanate for a respiratory infection develops jaundice and elevated liver enzymes. Which side effect of amoxicillin-clavulanate is most likely responsible for these symptoms?', 'Amoxicillin-clavulanate can cause cholestatic hepatitis, presenting as jaundice and elevated liver enzymes.', null),
  (md5('question:pharmacy-exam-prep:11:110')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 110, 'A woman on desmopressin for diabetes insipidus develops headache and hyponatremia. Which side effect of desmopressin might cause these symptoms?', 'Desmopressin, a synthetic form of vasopressin, can cause excess water retention and subsequent hyponatremia, leading to headache.', null),
  (md5('question:pharmacy-exam-prep:11:111')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 111, 'A patient using phenazopyridine for urinary tract pain develops orange discoloration of urine and nausea. Which mechanism contributes to these side effects of phenazopyridine?', 'Phenazopyridine increases urinary pH, causing orange discoloration of urine and potential gastrointestinal irritation leading to nausea.', null),
  (md5('question:pharmacy-exam-prep:11:112')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 112, 'A woman taking duloxetine for depression experiences dry mouth, constipation, and increased sweating. Which mechanism contributes to these side effects of duloxetine?', 'Duloxetine''s blockade of cholinergic receptors contributes to side effects like dry mouth, constipation, and increased sweating.', null),
  (md5('question:pharmacy-exam-prep:11:114')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 114, 'A woman using norgestimate-ethinyl estradiol for contraception reports breast tenderness and breakthrough bleeding. Which mechanism contributes to these side effects of the combined oral contraceptive?', 'Norgestimate-ethinyl estradiol can cause breast tenderness and breakthrough bleeding due to elevated estrogen levels.', null),
  (md5('question:pharmacy-exam-prep:11:115')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 115, 'A patient taking hydroxychloroquine for rheumatoid arthritis develops visual disturbances and difficulty focusing. Which mechanism contributes to these side effects of hydroxychloroquine?', 'Hydroxychloroquine can cause retinal toxicity, leading to visual disturbances and difficulty focusing.', null),
  (md5('question:pharmacy-exam-prep:11:116')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 116, 'A woman using clindamycin for a vaginal infection reports severe diarrhea and abdominal cramps. Which mechanism contributes to these side effects of clindamycin?', 'Clindamycin disrupts normal intestinal flora, leading to severe diarrhea and abdominal cramps.', null),
  (md5('question:pharmacy-exam-prep:11:117')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 117, 'A patient on atorvastatin for hypercholesterolemia develops muscle pain and weakness. Which mechanism contributes to these side effects of atorvastatin?', 'Atorvastatin can cause muscle pain and weakness due to increased levels of creatinine kinase associated with muscle damage.', null),
  (md5('question:pharmacy-exam-prep:11:118')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 118, 'A woman using fluconazole for a vaginal yeast infection complains of headache and dizziness. Which side effect of fluconazole might cause these symptoms?', 'Fluconazole can cause central nervous system toxicity, presenting as headache and dizziness.', null),
  (md5('question:pharmacy-exam-prep:11:119')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 119, 'A patient prescribed levetiracetam for seizures develops mood swings and irritability. Which mechanism contributes to these side effects of levetiracetam?', 'Levetiracetam''s action in potentiating GABAergic transmission can lead to mood swings and irritability as side effects.', null),
  (md5('question:pharmacy-exam-prep:11:120')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 120, 'A woman using isoniazid for tuberculosis develops peripheral neuropathy and liver dysfunction. Which mechanism contributes to these side effects of isoniazid?', 'Isoniazid can lead to pyridoxine (vitamin B6) depletion, causing peripheral neuropathy and liver dysfunction as side effects.', null),
  (md5('question:pharmacy-exam-prep:11:121')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 121, 'A patient on cimetidine for peptic ulcer disease develops gynecomastia and impotence. Which mechanism contributes to these side effects of cimetidine?', 'Cimetidine can act as an androgen receptor antagonist, leading to side effects like gynecomastia and impotence.', null),
  (md5('question:pharmacy-exam-prep:11:122')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 122, 'A woman using tamoxifen for breast cancer treatment reports hot flashes and mood swings. Which mechanism contributes to these side effects of tamoxifen?', 'Tamoxifen''s action as an estrogen receptor blocker can cause side effects like hot flashes and mood swings due to estrogen blockade.', null),
  (md5('question:pharmacy-exam-prep:11:123')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 123, 'A patient taking pioglitazone for type 2 diabetes develops peripheral edema and weight gain. Which mechanism contributes to these side effects of pioglitazone?', 'Pioglitazone can cause adipose tissue expansion, leading to side effects like peripheral edema and weight gain.', null),
  (md5('question:pharmacy-exam-prep:11:124')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 124, 'A woman using levonorgestrel-releasing intrauterine device for contraception reports irregular menstrual bleeding and amenorrhea. Which mechanism contributes to these side effects of the levonorgestrel-releasing IUD?', 'The levonorgestrel-releasing IUD can cause endometrial atrophy, leading to irregular bleeding and amenorrhea.', null),
  (md5('question:pharmacy-exam-prep:11:125')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 125, 'A patient prescribed quetiapine for schizophrenia experiences sedation, dry mouth, and weight gain. Which mechanism contributes to these side effects of quetiapine?', 'Quetiapine''s antagonism of histamine receptors can lead to side effects like sedation, dry mouth, and weight gain.', null),
  (md5('question:pharmacy-exam-prep:11:126')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 126, 'A woman using isotretinoin for severe acne complains of dry skin, mucosal dryness, and joint pain. Which mechanism contributes to these side effects of isotretinoin?', 'Isotretinoin inhibits sebaceous gland function, leading to dry skin and mucosal dryness as side effects.', null),
  (md5('question:pharmacy-exam-prep:11:127')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 127, 'A patient on metronidazole for bacterial vaginosis develops metallic taste and nausea. Which mechanism contributes to these side effects of metronidazole?', 'Metronidazole disrupts oral flora, leading to side effects like metallic taste and nausea.', null),
  (md5('question:pharmacy-exam-prep:11:128')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 128, 'A woman using medroxyprogesterone acetate for contraception develops depression and irritability. Which mechanism contributes to these side effects of medroxyprogesterone acetate?', 'Medroxyprogesterone acetate can cause side effects like depression and irritability due to progesterone depletion.', null),
  (md5('question:pharmacy-exam-prep:11:129')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 129, 'A patient taking aripiprazole for bipolar disorder develops akathisia and restlessness. Which mechanism contributes to these side effects of aripiprazole?', 'Aripiprazole''s action as a partial dopamine agonist can cause side effects like akathisia and restlessness.', null),
  (md5('question:pharmacy-exam-prep:11:130')::uuid, md5('quiz:pharmacy-exam-prep:11')::uuid, 130, 'A woman on metformin for type 2 diabetes complains of gastrointestinal upset and diarrhea. Which mechanism contributes to these side effects of metformin?', 'Metformin''s inhibition of glucose metabolism can lead to gastrointestinal upset and diarrhea as side effects.', null)
insert into public.quiz_answers (id, question_id, position, text, is_correct) values
  (md5('answer:pharmacy-exam-prep:11:1:1')::uuid, md5('question:pharmacy-exam-prep:11:1')::uuid, 1, 'Atenolol', false),
  (md5('answer:pharmacy-exam-prep:11:1:2')::uuid, md5('question:pharmacy-exam-prep:11:1')::uuid, 2, 'Lisinopril', false),
  (md5('answer:pharmacy-exam-prep:11:1:3')::uuid, md5('question:pharmacy-exam-prep:11:1')::uuid, 3, 'Warfarin', false),
  (md5('answer:pharmacy-exam-prep:11:1:4')::uuid, md5('question:pharmacy-exam-prep:11:1')::uuid, 4, 'Fluoxetine', false),
  (md5('answer:pharmacy-exam-prep:11:1:5')::uuid, md5('question:pharmacy-exam-prep:11:1')::uuid, 5, 'Isotretinoin', true),
  (md5('answer:pharmacy-exam-prep:11:2:1')::uuid, md5('question:pharmacy-exam-prep:11:2')::uuid, 1, 'Metformin', false),
  (md5('answer:pharmacy-exam-prep:11:2:2')::uuid, md5('question:pharmacy-exam-prep:11:2')::uuid, 2, 'Insulin', true),
  (md5('answer:pharmacy-exam-prep:11:2:3')::uuid, md5('question:pharmacy-exam-prep:11:2')::uuid, 3, 'Glyburide', false),
  (md5('answer:pharmacy-exam-prep:11:2:4')::uuid, md5('question:pharmacy-exam-prep:11:2')::uuid, 4, 'Pioglitazone', false),
