insert into public.chapters (id, course_id, position, title) values
  (md5('chapter:pharmacy-exam-prep:12')::uuid, md5('course:pharmacy-exam-prep')::uuid, 12, 'Skin')
insert into public.quizzes (id, chapter_id, title, position, is_preview) values
  (md5('quiz:pharmacy-exam-prep:12')::uuid, md5('chapter:pharmacy-exam-prep:12')::uuid, 'Skin', 1, false)
insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('question:pharmacy-exam-prep:12:1')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 1, 'Which systemic antifungal medication, used for severe dermatophyte infections, functions by inhibiting fungal ergosterol synthesis via inhibition of squalene epoxidase?', 'Terbinafine inhibits squalene epoxidase, disrupting fungal ergosterol synthesis in severe dermatophyte infections.', null),
  (md5('question:pharmacy-exam-prep:12:2')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 2, 'Among the listed medications used for psoriasis, which one is a biologic agent that targets interleukin-17A, reducing inflammation and plaque formation in psoriatic skin lesions?', 'Secukinumab targets IL-17A, reducing inflammation and plaque formation in psoriatic skin lesions as a biologic agent.', null),
  (md5('question:pharmacy-exam-prep:12:3')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 3, 'Which topical corticosteroid, classified as a potent corticosteroid, is often avoided in the treatment of facial dermatoses due to the risk of atrophy and telangiectasia in thin skin areas?', 'Clobetasol, a potent corticosteroid, carries a higher risk of atrophy and telangiectasia in thin facial skin areas.', null),
  (md5('question:pharmacy-exam-prep:12:4')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 4, 'Among the listed topical antiviral medications, which one is a nucleoside analogue that inhibits viral DNA polymerase and is used in the treatment of herpes simplex infections?', 'Acyclovir inhibits viral DNA polymerase, acting against herpes simplex infections as a nucleoside analogue.', null),
  (md5('question:pharmacy-exam-prep:12:5')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 5, 'Which systemic medication used for severe nodular cystic acne carries a significant risk of teratogenicity and requires strict contraceptive measures in female patients due to its potential to cause severe birth defects?', 'Isotretinoin poses a significant risk of teratogenicity, necessitating strict contraceptive measures due to its potential to cause severe birth defects in pregnancy.', null),
  (md5('question:pharmacy-exam-prep:12:6')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 6, 'Among the listed topical antifungal medications, which one is a polyene antifungal agent used to treat candidiasis and dermatophyte infections by binding to ergosterol, disrupting fungal cell membranes?', 'Nystatin binds to ergosterol, disrupting fungal cell membranes in candidiasis and dermatophyte infections as a polyene antifungal agent.', null),
  (md5('question:pharmacy-exam-prep:12:7')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 7, 'Which systemic immunosuppressant, used for severe eczema, functions by inhibiting calcineurin and suppressing T-cell activation, thereby reducing inflammation in the skin?', 'Tacrolimus inhibits calcineurin, suppressing T-cell activation and reducing skin inflammation in severe eczema as a systemic immunosuppressant.', null),
  (md5('question:pharmacy-exam-prep:12:8')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 8, 'Among the listed topical antibiotics used in skin infections, which one is a lincosamide antibiotic often combined with benzoyl peroxide in the treatment of acne vulgaris, targeting Propionibacterium acnes?', 'Clindamycin, a lincosamide antibiotic, is combined with benzoyl peroxide for acne vulgaris, targeting Propionibacterium acnes.', null),
  (md5('question:pharmacy-exam-prep:12:9')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 9, 'Which topical calcineurin inhibitor, used in the treatment of atopic dermatitis, is indicated for short-term and intermittent long-term treatment due to concerns about potential malignancy risk?', 'Tacrolimus is indicated for short-term and intermittent long-term treatment in atopic dermatitis due to potential malignancy risk associated with topical calcineurin inhibitors.', null),
  (md5('question:pharmacy-exam-prep:12:10')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 10, 'Among the listed medications used for severe chronic plaque psoriasis, which one is a biologic agent that targets the p40 subunit shared by interleukin-12 and interleukin-23, reducing inflammation and plaque formation?', 'Ustekinumab targets the p40 subunit shared by IL-12 and IL-23, reducing inflammation and plaque formation in severe chronic plaque psoriasis as a biologic agent.', null),
  (md5('question:pharmacy-exam-prep:12:11')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 11, 'Which topical antifungal medication, used in the treatment of dermatophyte infections, functions by inhibiting the biosynthesis of ergosterol, disrupting fungal cell membranes?', 'Terbinafine inhibits ergosterol biosynthesis, disrupting fungal cell membranes in dermatophyte infections.', null),
  (md5('question:pharmacy-exam-prep:12:12')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 12, 'Among the listed topical corticosteroids, which one is classified as a moderate-strength corticosteroid and is commonly used in the treatment of inflammatory skin conditions, particularly eczema?', 'Mometasone is a moderate-strength corticosteroid used for inflammatory skin conditions, especially eczema.', null),
  (md5('question:pharmacy-exam-prep:12:13')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 13, 'Which topical antiviral medication, used in the treatment of herpes simplex infections, is a nucleoside analogue that inhibits viral DNA polymerase?', 'Acyclovir inhibits viral DNA polymerase in the treatment of herpes simplex infections as a nucleoside analogue.', null),
  (md5('question:pharmacy-exam-prep:12:14')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 14, 'Among the listed systemic antibiotics used in skin infections, which one is a tetracycline antibiotic that functions by inhibiting bacterial protein synthesis and is commonly used in acne vulgaris treatment?', 'Doxycycline inhibits bacterial protein synthesis, commonly used in acne vulgaris treatment as a tetracycline antibiotic.', null),
  (md5('question:pharmacy-exam-prep:12:15')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 15, 'Which systemic immunosuppressant, used in severe psoriasis, acts by inhibiting dihydrofolate reductase, leading to decreased DNA synthesis and cell proliferation?', 'Methotrexate inhibits dihydrofolate reductase, decreasing DNA synthesis and cell proliferation in severe psoriasis as a systemic immunosuppressant.', null),
  (md5('question:pharmacy-exam-prep:12:16')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 16, 'Among the listed topical antibiotics used in skin infections, which one is a topical antibiotic derived from fusidic acid and is effective against Staphylococcus aureus?', 'Fusidic acid, a derivative, is effective against Staphylococcus aureus in skin infections as a topical antibiotic.', null),
  (md5('question:pharmacy-exam-prep:12:17')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 17, 'Which topical calcineurin inhibitor, used in the management of atopic dermatitis, carries a black box warning due to its potential association with lymphoma and skin cancer risks?', 'Tacrolimus carries a black box warning due to potential lymphoma and skin cancer risks in atopic dermatitis management as a topical calcineurin inhibitor.', null),
  (md5('question:pharmacy-exam-prep:12:18')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 18, 'Among the listed medications used for severe chronic plaque psoriasis, which one is a biologic agent that targets interleukin-23, reducing inflammation and plaque formation?', 'Guselkumab targets IL-23, reducing inflammation and plaque formation in severe chronic plaque psoriasis as a biologic agent.', null),
  (md5('question:pharmacy-exam-prep:12:19')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 19, 'Which systemic antifungal medication, used in the treatment of systemic Candida infections, functions by inhibiting fungal cell wall synthesis via inhibition of beta (1,3)-D-glucan synthase?', 'Caspofungin inhibits beta (1,3)-D-glucan synthase, disrupting fungal cell wall synthesis in systemic Candida infections.', null),
  (md5('question:pharmacy-exam-prep:12:20')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 20, 'Among the listed medications used for psoriasis, which one is a biologic agent that targets T-cell activation by binding to CD2, thereby reducing inflammation and plaque formation?', 'Alefacept targets T-cell activation by binding to CD2, reducing inflammation and plaque formation in psoriasis as a biologic agent.', null),
  (md5('question:pharmacy-exam-prep:12:21')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 21, 'Which topical antiviral medication, used in the treatment of herpes simplex infections, is a nucleoside analogue that inhibits viral DNA polymerase and is available in a cream formulation?', 'Penciclovir inhibits viral DNA polymerase and is available in cream formulation for herpes simplex infections as a nucleoside analogue.', null),
  (md5('question:pharmacy-exam-prep:12:22')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 22, 'Among the listed topical corticosteroids, which one is classified as a potent corticosteroid and is known to be absorbed systemically in high amounts, raising concerns about adverse effects particularly in children?', 'Clobetasol, a potent corticosteroid, is absorbed systemically in high amounts, raising concerns about adverse effects, especially in children.', null),
  (md5('question:pharmacy-exam-prep:12:23')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 23, 'Which systemic immunosuppressant, used in severe eczema, functions by inhibiting inosine monophosphate dehydrogenase, thus suppressing T-cell and B-cell proliferation and reducing inflammation in the skin?', 'Mycophenolate inhibits inosine monophosphate dehydrogenase, suppressing T-cell and B-cell proliferation in severe eczema as a systemic immunosuppressant.', null),
  (md5('question:pharmacy-exam-prep:12:24')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 24, 'Among the listed topical antibiotics used in skin infections, which one is a bacteriostatic antibiotic often used in the treatment of acne vulgaris, acting by inhibiting bacterial protein synthesis?', 'Erythromycin, a bacteriostatic antibiotic, inhibits bacterial protein synthesis, commonly used in acne vulgaris treatment.', null),
  (md5('question:pharmacy-exam-prep:12:25')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 25, 'Which systemic medication used in severe nodular cystic acne is a retinoid that acts by normalizing keratinization and reducing sebum production while having a significant risk of teratogenicity?', 'Isotretinoin, a retinoid, normalizes keratinization and reduces sebum production but carries a significant risk of teratogenicity in severe acne.', null),
  (md5('question:pharmacy-exam-prep:12:26')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 26, 'Among the listed topical antifungal medications, which one is an azole antifungal agent used in the treatment of candidiasis and dermatophyte infections by inhibiting fungal cytochrome P450-dependent enzymes?', 'Ketoconazole inhibits fungal cytochrome P450-dependent enzymes in candidiasis and dermatophyte infections as an azole antifungal agent.', null),
  (md5('question:pharmacy-exam-prep:12:27')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 27, 'Which topical calcineurin inhibitor, used in atopic dermatitis, is associated with a black box warning due to its potential risk of skin cancer, limiting its use to second-line treatment in patients unresponsive to other therapies?', 'Tacrolimus carries a black box warning for potential skin cancer risk, limiting its use to second-line treatment in atopic dermatitis as a topical calcineurin inhibitor.', null),
  (md5('question:pharmacy-exam-prep:12:28')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 28, 'Among the listed medications used for severe chronic plaque psoriasis, which one is a biologic agent that targets interleukin-17 receptor A, reducing inflammation and plaque formation?', 'Brodalumab targets IL-17 receptor A, reducing inflammation and plaque formation in severe chronic plaque psoriasis as a biologic agent.', null),
  (md5('question:pharmacy-exam-prep:12:29')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 29, 'Which systemic antifungal medication, used in the treatment of systemic Aspergillus infections, functions by inhibiting fungal cell wall synthesis via inhibition of beta (1,3)-D-glucan synthase?', 'Caspofungin inhibits beta (1,3)-D-glucan synthase, disrupting fungal cell wall synthesis in systemic Aspergillus infections.', null),
  (md5('question:pharmacy-exam-prep:12:30')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 30, 'Among the listed medications used in psoriasis, which one is a biologic agent that targets the p19 subunit of interleukin-23, reducing inflammation and plaque formation?', 'Risankizumab targets the p19 subunit of IL-23, reducing inflammation and plaque formation in psoriasis as a biologic agent.', null),
  (md5('question:pharmacy-exam-prep:12:31')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 31, 'Which topical antiviral medication, used in the treatment of herpes simplex infections, is a nucleoside analogue that inhibits viral DNA polymerase and is available in an ointment formulation?', 'Acyclovir inhibits viral DNA polymerase and is available in ointment formulation for herpes simplex infections as a nucleoside analogue.', null),
  (md5('question:pharmacy-exam-prep:12:32')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 32, 'Among the listed topical corticosteroids, which one is classified as a mild corticosteroid and is commonly used for mild inflammatory skin conditions due to its lower potency and reduced risk of adverse effects?', 'Hydrocortisone, a mild corticosteroid, is commonly used for mild inflammatory skin conditions due to its lower potency and reduced risk of adverse effects.', null),
  (md5('question:pharmacy-exam-prep:12:33')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 33, 'Which systemic immunosuppressant, used in severe eczema, functions by inhibiting mammalian target of rapamycin (mTOR), thereby suppressing T-cell and B-cell proliferation and reducing inflammation in the skin?', 'Sirolimus inhibits mTOR, suppressing T-cell and B-cell proliferation in severe eczema as a systemic immunosuppressant.', null),
  (md5('question:pharmacy-exam-prep:12:34')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 34, 'Among the listed topical antibiotics used in skin infections, which one is a bactericidal antibiotic often combined with neomycin in the treatment of infected wounds, targeting Gram-positive organisms?', 'Fusidic acid, often combined with neomycin, targets Gram-positive organisms in infected wounds as a bactericidal antibiotic.', null),
  (md5('question:pharmacy-exam-prep:12:35')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 35, 'Which systemic medication used in severe nodular cystic acne is a retinoid that functions by normalizing keratinization and reducing sebum production while requiring strict contraceptive measures due to teratogenicity risks?', 'Isotretinoin normalizes keratinization and reduces sebum production but necessitates strict contraceptive measures due to teratogenicity risks in severe acne treatment.', null),
  (md5('question:pharmacy-exam-prep:12:36')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 36, 'Among the listed topical antifungal medications, which one is an imidazole antifungal agent used in the treatment of candidiasis and dermatophyte infections by disrupting fungal ergosterol synthesis?', 'Clotrimazole disrupts fungal ergosterol synthesis in candidiasis and dermatophyte infections as an imidazole antifungal agent.', null),
  (md5('question:pharmacy-exam-prep:12:37')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 37, 'Which topical calcineurin inhibitor, used in the management of atopic dermatitis, has a black box warning due to potential lymphoma and skin cancer risks, limiting its use to second-line treatment?', 'Pimecrolimus has a black box warning for potential lymphoma and skin cancer risks, limiting its use to second-line treatment in atopic dermatitis as a topical calcineurin inhibitor.', null),
  (md5('question:pharmacy-exam-prep:12:38')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 38, 'Among the listed medications used for severe chronic plaque psoriasis, which one is a biologic agent that targets interleukin-23p19, reducing inflammation and plaque formation?', 'Tildrakizumab targets interleukin-23p19, reducing inflammation and plaque formation in severe chronic plaque psoriasis as a biologic agent.', null),
  (md5('question:pharmacy-exam-prep:12:39')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 39, 'Which systemic antifungal medication, used in the treatment of systemic Candida infections, functions by inhibiting fungal cell wall synthesis via inhibition of beta (1,3)-D-glucan synthase?', 'Caspofungin inhibits beta (1,3)-D-glucan synthase, disrupting fungal cell wall synthesis in systemic Candida infections.', null),
  (md5('question:pharmacy-exam-prep:12:40')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 40, 'Among the listed medications used for psoriasis, which one is a biologic agent that targets interleukin-12 and interleukin-23, reducing inflammation and plaque formation?', 'Ustekinumab targets IL-12 and IL-23, reducing inflammation and plaque formation in psoriasis as a biologic agent.', null),
  (md5('question:pharmacy-exam-prep:12:41')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 41, 'Which topical antiviral medication, used in the treatment of herpes simplex infections, is a nucleoside analogue that inhibits viral DNA polymerase and is available as a patch for recurrent cold sores?', 'Penciclovir inhibits viral DNA polymerase and is available as a patch for recurrent cold sores in herpes simplex infections as a nucleoside analogue.', null),
  (md5('question:pharmacy-exam-prep:12:42')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 42, 'Among the listed topical corticosteroids, which one is classified as a potent corticosteroid and is associated with a higher risk of systemic absorption and adverse effects, especially in children and thin-skinned areas?', 'Clobetasol, a potent corticosteroid, has a higher risk of systemic absorption and adverse effects, particularly in children and thin-skinned areas.', null),
  (md5('question:pharmacy-exam-prep:12:43')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 43, 'Which systemic immunosuppressant, used in severe eczema, functions by inhibiting Janus kinases (JAK), thereby suppressing cytokine signaling and reducing inflammation in the skin?', 'Baricitinib inhibits Janus kinases (JAK), suppressing cytokine signaling and reducing inflammation in severe eczema as a systemic immunosuppressant.', null),
  (md5('question:pharmacy-exam-prep:12:44')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 44, 'Among the listed topical antibiotics used in skin infections, which one is a bactericidal antibiotic effective against MRSA and is frequently used in nasal decolonization and skin infections?', 'Mupirocin is a bactericidal antibiotic effective against MRSA, commonly used in nasal decolonization and skin infections.', null),
  (md5('question:pharmacy-exam-prep:12:45')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 45, 'Which systemic medication used in severe nodular cystic acne is a retinoid that functions by normalizing keratinization and reducing sebum production while having a significant risk of teratogenicity?', 'Isotretinoin, a retinoid, normalizes keratinization and reduces sebum production but has a significant risk of teratogenicity in severe acne.', null),
  (md5('question:pharmacy-exam-prep:12:46')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 46, 'Among the listed topical antifungal medications, which one is an allylamine antifungal agent used in the treatment of dermatophyte infections by inhibiting ergosterol biosynthesis?', 'Terbinafine inhibits ergosterol biosynthesis in the treatment of dermatophyte infections as an allylamine antifungal agent.', null),
  (md5('question:pharmacy-exam-prep:12:47')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 47, 'Which topical calcineurin inhibitor, used in atopic dermatitis, is associated with a black box warning due to potential lymphoma and skin cancer risks, limiting its use to second-line treatment?', 'Tacrolimus has a black box warning for potential lymphoma and skin cancer risks, limiting its use to second-line treatment in atopic dermatitis as a topical calcineurin inhibitor.', null),
  (md5('question:pharmacy-exam-prep:12:48')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 48, 'Among the listed medications used for severe chronic plaque psoriasis, which one is a biologic agent that targets interleukin-23p19, reducing inflammation and plaque formation?', 'Tildrakizumab targets interleukin-23p19, reducing inflammation and plaque formation in severe chronic plaque psoriasis as a biologic agent.', null),
  (md5('question:pharmacy-exam-prep:12:49')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 49, 'Which systemic antifungal medication, used in the treatment of systemic Candida infections, functions by inhibiting fungal cell wall synthesis via inhibition of beta (1,3)-D-glucan synthase?', 'Caspofungin inhibits beta (1,3)-D-glucan synthase, disrupting fungal cell wall synthesis in systemic Candida infections.', null),
  (md5('question:pharmacy-exam-prep:12:50')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 50, 'Among the listed medications used in psoriasis, which one is a biologic agent that targets the p40 subunit of interleukin-12 and interleukin-23, reducing inflammation and plaque formation?', 'Ustekinumab targets the p40 subunit of IL-12 and IL-23, reducing inflammation and plaque formation in psoriasis as a biologic agent.', null),
  (md5('question:pharmacy-exam-prep:12:51')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 51, 'Which topical antiviral medication, used in the treatment of herpes simplex infections, is a nucleoside analogue that inhibits viral DNA polymerase and is available as a cream formulation?', 'Acyclovir inhibits viral DNA polymerase and is available as a cream formulation for herpes simplex infections as a nucleoside analogue.', null),
  (md5('question:pharmacy-exam-prep:12:52')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 52, 'Among the listed topical corticosteroids, which one is classified as a mild corticosteroid and is frequently used for mild inflammatory skin conditions due to its lower potency and reduced risk of adverse effects?', 'Hydrocortisone, a mild corticosteroid, is frequently used for mild inflammatory skin conditions due to its lower potency and reduced risk of adverse effects.', null),
  (md5('question:pharmacy-exam-prep:12:53')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 53, 'Which systemic immunosuppressant, used in severe eczema, functions by inhibiting phosphodiesterase-4 (PDE-4), thereby reducing cytokine production and inflammation in the skin?', 'Apremilast inhibits phosphodiesterase-4 (PDE-4), reducing cytokine production and inflammation in severe eczema as a systemic immunosuppressant.', null),
  (md5('question:pharmacy-exam-prep:12:54')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 54, 'Among the listed topical antibiotics used in skin infections, which one is a bacteriostatic antibiotic commonly used in the treatment of acne vulgaris, acting by inhibiting bacterial protein synthesis?', 'Erythromycin, a bacteriostatic antibiotic, inhibits bacterial protein synthesis, commonly used in acne vulgaris treatment.', null),
  (md5('question:pharmacy-exam-prep:12:55')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 55, 'Which systemic medication used in severe nodular cystic acne is a retinoid that functions by normalizing keratinization and reducing sebum production while requiring strict contraceptive measures due to teratogenicity risks?', 'Isotretinoin, a retinoid, normalizes keratinization and reduces sebum production but necessitates strict contraceptive measures due to teratogenicity risks in severe acne treatment.', null),
  (md5('question:pharmacy-exam-prep:12:56')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 56, 'Among the listed topical antifungal medications, which one is a triazole antifungal agent used in the treatment of candidiasis and dermatophyte infections by inhibiting ergosterol biosynthesis?', 'Ketoconazole inhibits ergosterol biosynthesis in candidiasis and dermatophyte infections as a triazole antifungal agent.', null),
  (md5('question:pharmacy-exam-prep:12:57')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 57, 'Which topical calcineurin inhibitor, used in the management of atopic dermatitis, has a black box warning due to potential lymphoma and skin cancer risks, limiting its use to second-line treatment?', 'Tacrolimus has a black box warning for potential lymphoma and skin cancer risks, limiting its use to second-line treatment in atopic dermatitis as a topical calcineurin inhibitor.', null),
  (md5('question:pharmacy-exam-prep:12:58')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 58, 'Among the listed medications used for severe chronic plaque psoriasis, which one is a biologic agent that targets interleukin-23p19, reducing inflammation and plaque formation?', 'Tildrakizumab targets interleukin-23p19, reducing inflammation and plaque formation in severe chronic plaque psoriasis as a biologic agent.', null),
  (md5('question:pharmacy-exam-prep:12:59')::uuid, md5('quiz:pharmacy-exam-prep:12')::uuid, 59, 'Which systemic antifungal medication, used in the treatment of systemic Candida infections, functions by inhibiting fungal cell wall synthesis via inhibition of beta (1,3)-D-glucan synthase?', 'Caspofungin inhibits beta (1,3)-D-glucan synthase, disrupting fungal cell wall synthesis in systemic Candida infections.', null)
