insert into public.chapters (id, course_id, position, title) values
  (md5('chapter:pharmacy-exam-prep:13')::uuid, md5('course:pharmacy-exam-prep')::uuid, 13, 'Ophthalmology')
insert into public.quizzes (id, chapter_id, title, position, is_preview) values
  (md5('quiz:pharmacy-exam-prep:13')::uuid, md5('chapter:pharmacy-exam-prep:13')::uuid, 'Ophthalmology', 1, false)
insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('question:pharmacy-exam-prep:13:1')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 1, 'Which drug is a selective alpha-2 adrenergic receptor agonist used in glaucoma management that can cause a paradoxical increase in intraocular pressure (IOP) in some individuals?', 'Brimonidine, though effective, can cause an initial increase in IOP due to vasoconstriction.', null),
  (md5('question:pharmacy-exam-prep:13:2')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 2, 'What is the mechanism of action of Methazolamide, a carbonic anhydrase inhibitor used in glaucoma treatment?', 'Methazolamide inhibits carbonic anhydrase in the ciliary body, reducing aqueous humor production.', null),
  (md5('question:pharmacy-exam-prep:13:3')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 3, 'Which medication is a prostaglandin analog used to lower IOP by enhancing uveoscleral outflow and may cause a change in iris pigmentation and eyelash growth?', 'Travoprost, a prostaglandin analog, can alter iris pigmentation and promote eyelash growth as side effects.', null),
  (md5('question:pharmacy-exam-prep:13:4')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 4, 'Among the beta-blockers used in ophthalmology, which drug can potentially cause bronchospasm in patients with a history of asthma?', 'Timolol is a non-selective beta-blocker that can cause bronchospasm due to its beta-2 blockade effects.', null),
  (md5('question:pharmacy-exam-prep:13:5')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 5, 'What is the primary action of Pilocarpine, a muscarinic receptor agonist used in glaucoma treatment?', 'Pilocarpine primarily enhances trabecular meshwork outflow, aiding in lowering IOP.', null),
  (md5('question:pharmacy-exam-prep:13:6')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 6, 'Which drug inhibits histamine release and exerts an anti-allergic effect when applied topically in the eye?', 'Lodoxamide inhibits histamine release, aiding in the management of ocular allergies.', null),
  (md5('question:pharmacy-exam-prep:13:7')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 7, 'Which medication functions by reducing aqueous humor production and is contraindicated in patients with sulfa allergy due to its chemical structure?', 'Dorzolamide, a carbonic anhydrase inhibitor, is a sulfa-based drug used in glaucoma but contraindicated in sulfa-allergic individuals.', null),
  (md5('question:pharmacy-exam-prep:13:8')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 8, 'What is the mechanism of action of Brinzolamide, a carbonic anhydrase inhibitor used in glaucoma treatment?', 'Brinzolamide inhibits carbonic anhydrase, decreasing aqueous humor production in the eye.', null),
  (md5('question:pharmacy-exam-prep:13:9')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 9, 'Among the following drugs, which one acts as a reversible acetylcholinesterase inhibitor used in the treatment of glaucoma?', 'Echothiophate is a reversible acetylcholinesterase inhibitor employed in glaucoma management.', null),
  (md5('question:pharmacy-exam-prep:13:10')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 10, 'Which medication works by stimulating alpha-2 adrenergic receptors, leading to a reduction in aqueous humor production and an increase in uveoscleral outflow?', 'Brimonidine''s primary action involves stimulating alpha-2 adrenergic receptors to lower IOP.', null),
  (md5('question:pharmacy-exam-prep:13:11')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 11, 'Among the following prostaglandin analogs, which one has a dosing schedule requiring administration only once daily due to its longer duration of action?', 'Travoprost''s extended duration of action allows for once-daily dosing in glaucoma treatment.', null),
  (md5('question:pharmacy-exam-prep:13:12')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 12, 'Which medication is a sympathomimetic agent used in ophthalmology that can potentially cause systemic side effects such as hypertension and tachycardia?', 'Epinephrine, a sympathomimetic drug, can lead to systemic side effects when used in the eye.', null),
  (md5('question:pharmacy-exam-prep:13:13')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 13, 'Among the following alpha-agonists used in glaucoma, which one has the highest affinity for alpha-2 adrenergic receptors?', 'Brimonidine has a high affinity for alpha-2 adrenergic receptors compared to other options listed.', null),
  (md5('question:pharmacy-exam-prep:13:14')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 14, 'Which medication, when used in ophthalmology, acts by increasing outflow of aqueous humor through the uveoscleral pathway rather than affecting conventional outflow pathways?', 'Latanoprost primarily enhances aqueous humor outflow via the uveoscleral pathway.', null),
  (md5('question:pharmacy-exam-prep:13:15')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 15, 'Among the following, which medication is a prodrug that gets converted into its active metabolite, timolol, after topical application in the eye?', 'Dipivefrin is a prodrug converted to its active form, timolol, after ocular administration.', null),
  (md5('question:pharmacy-exam-prep:13:16')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 16, 'Which drug, used in glaucoma treatment, is a selective alpha-1 adrenergic receptor agonist that enhances trabecular and uveoscleral outflow?', 'Dipivefrin is a selective alpha-1 adrenergic receptor agonist aiding in enhancing outflow in glaucoma.', null),
  (md5('question:pharmacy-exam-prep:13:17')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 17, 'Among the following, which medication is an irreversible acetylcholinesterase inhibitor used in the management of glaucoma?', 'Echothiophate is an irreversible acetylcholinesterase inhibitor employed in glaucoma therapy.', null),
  (md5('question:pharmacy-exam-prep:13:18')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 18, 'What is the primary action of Carteolol, a non-selective beta-blocker used in ophthalmology?', 'Carteolol mainly reduces aqueous humor production as a non-selective beta-blocker.', null),
  (md5('question:pharmacy-exam-prep:13:19')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 19, 'Which medication, among the listed beta-blockers, is more cardioselective and is considered safer for patients with respiratory conditions like asthma?', 'Betaxolol is relatively cardioselective, making it a safer choice for patients with respiratory conditions.', null),
  (md5('question:pharmacy-exam-prep:13:20')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 20, 'Among the following drugs, which one is a sympathomimetic agent used in ophthalmology that gets metabolized into epinephrine in the eye, thereby reducing IOP?', 'Dipivefrin is metabolized into epinephrine in the eye, leading to its IOP-lowering effects.', null),
  (md5('question:pharmacy-exam-prep:13:21')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 21, 'Which drug, belonging to the group of carbonic anhydrase inhibitors, is available in a sustained-release formulation for twice-daily dosing in the management of glaucoma?', 'Dorzolamide is available in a sustained-release formulation for twice-daily dosing.', null),
  (md5('question:pharmacy-exam-prep:13:22')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 22, 'Among the listed drugs used in glaucoma treatment, which one can cause blurred vision and should be used cautiously in patients operating heavy machinery or driving due to its potential to impair visual acuity?', 'Brimonidine can cause blurred vision, impacting activities requiring clear vision.', null),
  (md5('question:pharmacy-exam-prep:13:23')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 23, 'What is the primary mechanism of action of Latanoprostene bunod, a newer agent used in glaucoma management?', 'Latanoprostene bunod releases nitric oxide, aiding in enhancing aqueous humor outflow.', null),
  (md5('question:pharmacy-exam-prep:13:24')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 24, 'Among the listed medications, which one is a direct cholinergic agonist that also has a mydriatic effect due to its action on the iris sphincter muscle?', 'Pilocarpine acts as a direct cholinergic agonist with mydriatic effects.', null),
  (md5('question:pharmacy-exam-prep:13:25')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 25, 'Which drug used in glaucoma management has a primary action involving the stimulation of beta-2 adrenergic receptors, potentially leading to systemic cardiovascular effects?', 'Dipivefrin stimulates beta-2 adrenergic receptors, leading to systemic cardiovascular effects.', null),
  (md5('question:pharmacy-exam-prep:13:26')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 26, 'Among the following, which medication works by inhibiting histamine release and is used for its anti-allergic effects in ophthalmology?', 'Lodoxamide inhibits histamine release, aiding in managing ocular allergies.', null),
  (md5('question:pharmacy-exam-prep:13:27')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 27, 'Which medication, when used in glaucoma, primarily acts by reducing aqueous humor production through the inhibition of carbonic anhydrase enzymes?', 'Dorzolamide reduces aqueous humor production by inhibiting carbonic anhydrase.', null),
  (md5('question:pharmacy-exam-prep:13:28')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 28, 'What is the primary pharmacological effect of Betaxolol, a beta-blocker used in ophthalmology, compared to non-selective beta-blockers?', 'Betaxolol primarily reduces aqueous humor production as a cardioselective beta-blocker.', null),
  (md5('question:pharmacy-exam-prep:13:29')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 29, 'Among the listed medications, which one is a prodrug converted to its active metabolite, brimonidine, after ocular application?', 'Apraclonidine is a prodrug converted to brimonidine after ocular administration.', null),
  (md5('question:pharmacy-exam-prep:13:30')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 30, 'Which medication, used in glaucoma treatment, is an alpha-2 adrenergic receptor agonist that has a greater selectivity for the alpha-2 receptor subtype, thereby reducing systemic side effects?', 'Brimonidine has higher selectivity for alpha-2 adrenergic receptors, reducing systemic side effects.', null),
  (md5('question:pharmacy-exam-prep:13:31')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 31, 'Among the following, which medication is a derivative of prostaglandin F2-alpha used in glaucoma therapy?', 'Bimatoprost is a derivative of prostaglandin F2-alpha employed in glaucoma treatment.', null),
  (md5('question:pharmacy-exam-prep:13:32')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 32, 'What is the primary mechanism of action of Acetazolamide when used in glaucoma management?', 'Acetazolamide inhibits carbonic anhydrase, reducing aqueous humor production in the eye.', null),
  (md5('question:pharmacy-exam-prep:13:33')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 33, 'Among the listed sympathomimetic agents used in ophthalmology, which one can potentially cause rebound hyperemia upon discontinuation after prolonged use?', 'Brimonidine, upon discontinuation after prolonged use, can lead to rebound hyperemia.', null),
  (md5('question:pharmacy-exam-prep:13:34')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 34, 'Which medication, among the beta-blockers used in ophthalmology, has intrinsic sympathomimetic activity and is less likely to cause bradycardia compared to other non-selective beta-blockers?', 'Carteolol has intrinsic sympathomimetic activity, reducing the likelihood of bradycardia compared to non-selective beta-blockers.', null),
  (md5('question:pharmacy-exam-prep:13:35')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 35, 'Among the following drugs, which one is a quaternary ammonium compound and a cholinergic agonist used in glaucoma management?', 'Echothiophate is a quaternary ammonium compound used as a cholinergic agonist in glaucoma therapy.', null),
  (md5('question:pharmacy-exam-prep:13:36')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 36, 'Which medication, when used in ophthalmology, primarily enhances aqueous humor outflow by affecting the trabecular meshwork and Schlemm''s canal?', 'Pilocarpine primarily affects the trabecular meshwork and Schlemm''s canal to enhance aqueous humor outflow.', null),
  (md5('question:pharmacy-exam-prep:13:37')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 37, 'Among the listed drugs, which one is a dual-action alpha-2 adrenergic receptor agonist and a presynaptic alpha-2 adrenergic receptor antagonist used in glaucoma therapy?', 'Apraclonidine functions as a dual-action alpha-2 adrenergic receptor agonist and presynaptic alpha-2 adrenergic receptor antagonist.', null),
  (md5('question:pharmacy-exam-prep:13:38')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 38, 'What is the primary action of Brimonidine, an alpha-2 adrenergic receptor agonist used in glaucoma treatment, apart from reducing aqueous humor production?', 'Brimonidine also increases uveoscleral outflow, aiding in lowering IOP.', null),
  (md5('question:pharmacy-exam-prep:13:39')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 39, 'Among the following prostaglandin analogs used in glaucoma, which one has the shortest duration of action and requires twice-daily dosing?', 'Tafluprost has a shorter duration of action, necessitating twice-daily dosing compared to other prostaglandin analogs.', null),
  (md5('question:pharmacy-exam-prep:13:40')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 40, 'Which medication, used in glaucoma treatment, is a reversible acetylcholinesterase inhibitor with a tertiary amine structure that increases outflow of aqueous humor?', 'Demecarium is a reversible acetylcholinesterase inhibitor that enhances aqueous humor outflow.', null),
  (md5('question:pharmacy-exam-prep:13:41')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 41, 'A patient comes to the pharmacy complaining of redness and irritation in their eyes due to seasonal allergies. Which OTC medication would you recommend to alleviate their symptoms?', 'Antihistamine eye drops are suitable for managing allergic symptoms in the eyes.', null),
  (md5('question:pharmacy-exam-prep:13:42')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 42, 'A customer wants relief from dry eyes and asks for a recommendation for an OTC product to provide moisture and relief. Which product would be most appropriate to suggest?', 'Artificial tears are designed to provide moisture and relieve dry eyes.', null),
  (md5('question:pharmacy-exam-prep:13:43')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 43, 'A patient is experiencing mild eye strain and wants an OTC solution for relief. Which recommendation would be most appropriate to reduce eye strain?', 'Lubricating eye gel can help relieve mild eye strain and discomfort.', null),
  (md5('question:pharmacy-exam-prep:13:44')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 44, 'A customer presents with symptoms of minor eye itching and asks for an OTC option to soothe the irritation. What would be the most suitable recommendation?', 'Artificial tears can help soothe minor eye itching and irritation.', null),
  (md5('question:pharmacy-exam-prep:13:45')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 45, 'A patient seeks advice for their child with conjunctivitis symptoms. Which OTC eye medication would you suggest as a suitable option for bacterial conjunctivitis in children?', 'Antibiotic eye ointment is suitable for bacterial conjunctivitis in children.', null),
  (md5('question:pharmacy-exam-prep:13:46')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 46, 'A customer reports excessive eye redness after prolonged screen time. What OTC eye product can help reduce redness caused by eye strain?', 'Artificial tears can help alleviate redness caused by eye strain.', null),
  (md5('question:pharmacy-exam-prep:13:47')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 47, 'A patient experiences watery eyes due to exposure to wind and seeks an OTC solution. What would be the most appropriate recommendation to alleviate the watery eyes?', 'Artificial tears can help alleviate watery eyes caused by wind exposure.', null),
  (md5('question:pharmacy-exam-prep:13:48')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 48, 'A customer seeks relief from eye redness due to mild irritation from swimming in a chlorinated pool. What OTC eye product would be most suitable to reduce the redness?', 'Artificial tears can help reduce redness from mild irritation caused by swimming in a chlorinated pool.', null),
  (md5('question:pharmacy-exam-prep:13:49')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 49, 'A patient complains of eye discomfort and a gritty sensation due to prolonged contact lens wear. What OTC eye product can provide relief from these symptoms?', 'Artificial tears can provide relief from discomfort and a gritty sensation caused by contact lens wear.', null),
  (md5('question:pharmacy-exam-prep:13:50')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 50, 'A customer seeks an OTC recommendation for minor eye itching caused by exposure to dust. What product would be most appropriate to alleviate this symptom?', 'Artificial tears can help alleviate minor itching caused by dust exposure.', null),
  (md5('question:pharmacy-exam-prep:13:51')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 51, 'A patient presents with symptoms of mild eye irritation after exposure to smoke. What would be an appropriate suggestion to alleviate discomfort from smoke exposure?', 'Artificial tears can help alleviate mild discomfort from smoke exposure.', null),
  (md5('question:pharmacy-exam-prep:13:52')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 52, 'A customer asks for an OTC recommendation to relieve eye dryness caused by central heating in their home. What product would be most suitable to alleviate this dryness?', 'Lubricating eye gel can help relieve dryness caused by central heating.', null),
  (md5('question:pharmacy-exam-prep:13:53')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 53, 'A patient seeks advice for minor eye redness and discomfort due to exposure to pollen. What OTC eye product would be most appropriate to alleviate these symptoms?', 'Artificial tears can help alleviate minor redness and discomfort caused by pollen exposure.', null),
  (md5('question:pharmacy-exam-prep:13:54')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 54, 'A customer complains of mild eye irritation and discomfort after working on a computer for several hours. What OTC eye product can provide relief from this discomfort?', 'Artificial tears can help alleviate discomfort from prolonged computer use.', null),
  (md5('question:pharmacy-exam-prep:13:55')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 55, 'A patient reports minor eye redness and itching after exposure to pet dander. What OTC eye product would be most appropriate to alleviate these symptoms?', 'Artificial tears can help alleviate redness and itching caused by pet dander exposure.', null),
  (md5('question:pharmacy-exam-prep:13:56')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 56, 'A customer seeks advice for eye discomfort and redness after a day of swimming in a freshwater lake. What OTC eye product would be most suitable to alleviate these symptoms?', 'Artificial tears can help alleviate discomfort and redness after swimming in a freshwater lake.', null),
  (md5('question:pharmacy-exam-prep:13:57')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 57, 'A patient presents with minor eye irritation and discomfort due to exposure to cold wind. What OTC eye product would be most appropriate to alleviate these symptoms?', 'Artificial tears can help alleviate irritation caused by exposure to cold wind.', null),
  (md5('question:pharmacy-exam-prep:13:58')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 58, 'A customer asks for an OTC recommendation to soothe mild eye redness after wearing eye makeup all day. What product would be most suitable to alleviate this redness?', 'Artificial tears can help soothe mild redness caused by wearing eye makeup.', null),
  (md5('question:pharmacy-exam-prep:13:59')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 59, 'Among patients with a history of sulfa allergy, which ocular medication should be avoided due to its chemical structure?', 'Dorzolamide, due to its sulfa-based structure, should be avoided in patients with sulfa allergy.', null),
  (md5('question:pharmacy-exam-prep:13:60')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 60, 'Which ocular medication is contraindicated in patients with a history of bronchospasm or asthma due to its potential to exacerbate these conditions?', 'Timolol, a non-selective beta-blocker, is contraindicated in patients with bronchospasm or asthma.', null),
  (md5('question:pharmacy-exam-prep:13:61')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 61, 'Among patients with a history of severe cardiovascular diseases such as heart block or bradycardia, which ocular medication is contraindicated due to its systemic effects on heart rate and rhythm?', 'Timolol, as a beta-blocker, can affect heart rate and is contraindicated in severe cardiovascular conditions.', null),
  (md5('question:pharmacy-exam-prep:13:62')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 62, 'Which ocular medication should be avoided in individuals with a known hypersensitivity to prostaglandins, as it is a prostaglandin analog itself?', 'Latanoprost, being a prostaglandin analog, should be avoided in those hypersensitive to prostaglandins.', null),
  (md5('question:pharmacy-exam-prep:13:63')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 63, 'Among patients with a history of depression or severe mood disorders, which ocular medication is contraindicated due to its potential to cause central nervous system effects?', 'Brimonidine is contraindicated in individuals with a history of severe mood disorders or depression due to its potential CNS effects.', null),
  (md5('question:pharmacy-exam-prep:13:64')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 64, 'Which ocular medication should be avoided in patients with a known allergy to beta-blockers due to its potential cross-reactivity?', 'Timolol, a beta-blocker, should be avoided in patients allergic to beta-blockers due to potential cross-reactivity.', null),
  (md5('question:pharmacy-exam-prep:13:65')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 65, 'Among patients with a history of urinary retention or bladder obstruction, which ocular medication is contraindicated due to its potential systemic effects on urinary function?', 'Pilocarpine is contraindicated in individuals with urinary retention or bladder obstruction due to its potential systemic effects on urinary function.', null),
  (md5('question:pharmacy-exam-prep:13:66')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 66, 'Which ocular medication is contraindicated in patients with severe renal impairment due to its potential to exacerbate renal dysfunction?', 'Dorzolamide is contraindicated in severe renal impairment as it can exacerbate renal dysfunction.', null),
  (md5('question:pharmacy-exam-prep:13:67')::uuid, md5('quiz:pharmacy-exam-prep:13')::uuid, 67, 'Among patients with a history of severe liver disease or hepatic impairment, which ocular medication is contraindicated due to its potential to worsen liver function?', 'Dorzolamide is contraindicated in severe liver disease or hepatic impairment due to its potential to worsen liver function.', null),
