  (md5('quiz:pharmacy-exam-prep:14')::uuid, md5('chapter:pharmacy-exam-prep:14')::uuid, 'Ear, Nose and Throat', 1, false)
insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('question:pharmacy-exam-prep:14:1')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 1, 'Which medication, used to treat allergic rhinitis, functions as a second-generation H1 antihistamine with minimal sedative effects?', 'Loratadine is a second-generation H1 antihistamine with minimal sedative effects.', null),
  (md5('question:pharmacy-exam-prep:14:2')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 2, 'Among the listed intranasal corticosteroids used in allergic rhinitis, which one has a longer duration of action, reducing the need for frequent dosing?', 'Fluticasone has a longer duration of action, reducing the need for frequent dosing.', null),
  (md5('question:pharmacy-exam-prep:14:3')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 3, 'Which medication is a decongestant used in nasal sprays or drops for short-term relief of nasal congestion but is cautioned against prolonged use due to the risk of rebound congestion?', 'Oxymetazoline is a decongestant cautioned against prolonged use due to rebound congestion risk.', null),
  (md5('question:pharmacy-exam-prep:14:4')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 4, 'Among the following, which medication is a muscarinic antagonist used in nasal sprays for its drying effect on nasal secretions in allergic rhinitis and rhinorrhea?', 'Ipratropium is a muscarinic antagonist used for its drying effect on nasal secretions.', null),
  (md5('question:pharmacy-exam-prep:14:5')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 5, 'Which medication, used in chronic rhinosinusitis, is a macrolide antibiotic known for its anti-inflammatory and immunomodulatory effects rather than its antimicrobial action?', 'Azithromycin is a macrolide antibiotic with anti-inflammatory and immunomodulatory effects.', null),
  (md5('question:pharmacy-exam-prep:14:6')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 6, 'Among the listed systemic decongestants used for nasal congestion, which one is cautioned against in patients with hypertension or cardiovascular diseases due to its potential to increase blood pressure?', 'Pseudoephedrine is cautioned against in patients with hypertension or cardiovascular diseases due to its potential to increase blood pressure.', null),
  (md5('question:pharmacy-exam-prep:14:7')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 7, 'Which medication is an anticholinergic agent used as an adjunct therapy in allergic rhinitis and chronic rhinosinusitis to reduce nasal secretions and improve symptoms?', 'Ipratropium is an anticholinergic agent used to reduce nasal secretions.', null),
  (md5('question:pharmacy-exam-prep:14:8')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 8, 'Among the listed systemic antihistamines used for allergic rhinitis, which one is known for its sedative effect and is often recommended for nighttime use due to its drowsiness-inducing properties?', 'Chlorphenamine is known for its sedative effect and is often recommended for nighttime use.', null),
  (md5('question:pharmacy-exam-prep:14:9')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 9, 'Which medication is an aminoglycoside antibiotic often used in topical preparations for its efficacy against Gram-negative bacteria in otitis externa?', 'Neomycin is an aminoglycoside used in topical preparations for otitis externa.', null),
  (md5('question:pharmacy-exam-prep:14:10')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 10, 'Among the following topical antifungal agents, which one is commonly used in otomycosis for its efficacy against fungal infections in the external auditory canal?', 'Clotrimazole is commonly used in otomycosis for its antifungal properties.', null),
  (md5('question:pharmacy-exam-prep:14:11')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 11, 'Which medication, used in allergic rhinitis, is a leukotriene receptor antagonist blocking the effects of leukotrienes, thereby reducing nasal symptoms?', 'Montelukast is a leukotriene receptor antagonist used in allergic rhinitis.', null),
  (md5('question:pharmacy-exam-prep:14:12')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 12, 'Among the listed topical corticosteroids used in otitis externa, which one is known for its potent anti-inflammatory action and reduced potential for systemic side effects?', 'Hydrocortisone is known for its potent anti-inflammatory action and reduced systemic side effects in otitis externa.', null),
  (md5('question:pharmacy-exam-prep:14:13')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 13, 'Which medication, used in allergic rhinitis and vasomotor rhinitis, is an intranasal antihistamine with minimal systemic absorption, thus reducing the risk of systemic side effects?', 'Azelastine, as an intranasal antihistamine, has minimal systemic absorption, reducing systemic side effects.', null),
  (md5('question:pharmacy-exam-prep:14:14')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 14, 'Among the listed mucolytic agents used in ENT conditions, which one is an N-acetylcysteine derivative used to facilitate mucus clearance in chronic respiratory conditions?', 'Carbocisteine, a derivative of N-acetylcysteine, is used as a mucolytic agent in chronic respiratory conditions.', null),
  (md5('question:pharmacy-exam-prep:14:15')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 15, 'Which medication, used in allergic rhinitis, functions as a mast cell stabilizer, inhibiting the release of inflammatory mediators from mast cells in the nasal mucosa?', 'Cromolyn functions as a mast cell stabilizer in allergic rhinitis.', null),
  (md5('question:pharmacy-exam-prep:14:16')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 16, 'Among the listed systemic antihistamines used in allergic rhinitis, which one is known for its non-sedating properties and reduced potential for causing drowsiness?', 'Fexofenadine is known for its non-sedating properties in allergic rhinitis.', null),
  (md5('question:pharmacy-exam-prep:14:17')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 17, 'Which medication is a sympathomimetic agent used in nasal decongestants, cautioning against prolonged use due to the risk of rhinitis medicamentosa or rebound congestion?', 'Xylometazoline is a sympathomimetic agent cautioning against prolonged use.', null),
  (md5('question:pharmacy-exam-prep:14:18')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 18, 'Among the listed systemic antihistamines used in allergic rhinitis, which one is considered to have minimal sedative effects, making it suitable for daytime use?', 'Fexofenadine is known for its minimal sedative effects, suitable for daytime use in allergic rhinitis.', null),
  (md5('question:pharmacy-exam-prep:14:19')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 19, 'Which medication, used in allergic rhinitis and vasomotor rhinitis, is an intranasal antihistamine with rapid onset of action, providing quick relief from nasal symptoms?', 'Azelastine, as an intranasal antihistamine, provides rapid relief from nasal symptoms.', null),
  (md5('question:pharmacy-exam-prep:14:20')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 20, 'Among the following anticholinergic agents used in rhinorrhea, which one is administered intranasally and is effective in reducing excessive nasal secretions?', 'Ipratropium, administered intranasally, reduces excessive nasal secretions as an anticholinergic agent.', null),
  (md5('question:pharmacy-exam-prep:14:21')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 21, 'Which medication is a macrolide antibiotic often used in the treatment of otitis media due to its efficacy against Streptococcus pneumoniae and Haemophilus influenzae?', 'Azithromycin, a macrolide antibiotic, is effective against common pathogens in otitis media.', null),
  (md5('question:pharmacy-exam-prep:14:22')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 22, 'Among the listed systemic decongestants used for nasal congestion, which one is cautioned against in patients with hyperthyroidism due to its potential to exacerbate thyroid-related symptoms?', 'Pseudoephedrine is cautioned against in patients with hyperthyroidism due to potential exacerbation of symptoms.', null),
  (md5('question:pharmacy-exam-prep:14:23')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 23, 'Which medication, used in chronic rhinosinusitis, is a tetracycline antibiotic with anti-inflammatory properties, making it effective in treating chronic inflammatory conditions of the sinuses?', 'Doxycycline, a tetracycline antibiotic, has anti-inflammatory properties effective in chronic rhinosinusitis.', null),
  (md5('question:pharmacy-exam-prep:14:24')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 24, 'Among the listed topical antifungal agents used in otitis externa, which one is commonly prescribed for its broad-spectrum activity against fungal infections in the ear canal?', 'Clotrimazole is commonly prescribed for its broad-spectrum activity against fungal infections in otitis externa.', null),
  (md5('question:pharmacy-exam-prep:14:25')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 25, 'Which medication, used in allergic rhinitis, is a mast cell stabilizer, preventing the release of histamine and other inflammatory mediators from mast cells in the nasal mucosa?', 'Cromolyn acts as a mast cell stabilizer in allergic rhinitis, preventing the release of inflammatory mediators.', null),
  (md5('question:pharmacy-exam-prep:14:26')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 26, 'Among the listed systemic antihistamines used in allergic rhinitis, which one is known for its quick onset of action, providing relief within 15-30 minutes after administration?', 'Cetirizine has a quick onset of action, providing relief within 15-30 minutes in allergic rhinitis.', null),
  (md5('question:pharmacy-exam-prep:14:27')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 27, 'Which medication is an aminoglycoside antibiotic used in topical formulations for its efficacy against Pseudomonas aeruginosa in otitis externa?', 'Gentamicin is an aminoglycoside effective against Pseudomonas aeruginosa in otitis externa.', null),
  (md5('question:pharmacy-exam-prep:14:28')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 28, 'Among the listed topical corticosteroids used in otitis externa, which one is commonly recommended for its broad anti-inflammatory effects and safety in otic preparations?', 'Hydrocortisone is commonly recommended for its broad anti-inflammatory effects and safety in otic preparations.', null),
  (md5('question:pharmacy-exam-prep:14:29')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 29, 'Which medication, used in allergic rhinitis, is an intranasal antihistamine with a rapid onset of action, providing relief within 15 minutes after administration?', 'Azelastine, as an intranasal antihistamine, provides rapid relief within 15 minutes in allergic rhinitis.', null),
  (md5('question:pharmacy-exam-prep:14:30')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 30, 'Among the listed mucolytic agents used in ENT conditions, which one is a derivative of bromhexine and is effective in facilitating mucus clearance?', 'Carbocisteine, a derivative of bromhexine, is used as a mucolytic agent in ENT conditions.', null),
  (md5('question:pharmacy-exam-prep:14:31')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 31, 'Which medication, used in allergic rhinitis, is a leukotriene receptor antagonist known for its efficacy in reducing nasal congestion and inflammation?', 'Montelukast, a leukotriene receptor antagonist, is effective in reducing nasal congestion and inflammation in allergic rhinitis.', null),
  (md5('question:pharmacy-exam-prep:14:32')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 32, 'Among the listed topical antifungal agents used in otitis externa, which one is effective against Candida species commonly implicated in fungal ear infections?', 'Clotrimazole is effective against Candida species commonly involved in fungal ear infections.', null),
  (md5('question:pharmacy-exam-prep:14:33')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 33, 'Which medication, used in allergic rhinitis, is an intranasal antihistamine with minimal systemic absorption, reducing the risk of systemic side effects?', 'Azelastine, as an intranasal antihistamine, has minimal systemic absorption, reducing systemic side effects.', null),
  (md5('question:pharmacy-exam-prep:14:34')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 34, 'Among the listed systemic antihistamines used in allergic rhinitis, which one is known for its long duration of action, providing relief for up to 24 hours after a single dose?', 'Fexofenadine has a long duration of action, providing relief for up to 24 hours after a single dose in allergic rhinitis.', null),
  (md5('question:pharmacy-exam-prep:14:35')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 35, 'Which medication, used in chronic rhinosinusitis, is a macrolide antibiotic known for its anti-inflammatory properties and its effect on biofilms in the sinuses?', 'Azithromycin, a macrolide antibiotic, has anti-inflammatory properties and impacts sinuses'' biofilms in chronic rhinosinusitis.', null),
  (md5('question:pharmacy-exam-prep:14:36')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 36, 'Among the listed systemic decongestants used for nasal congestion, which one is cautioned against in patients with glaucoma due to its potential to increase intraocular pressure?', 'Pseudoephedrine is cautioned against in patients with glaucoma due to potential increased intraocular pressure.', null),
  (md5('question:pharmacy-exam-prep:14:37')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 37, 'Which medication, used in allergic rhinitis, is an intranasal antihistamine effective in reducing both nasal symptoms and ocular symptoms associated with allergies?', 'Olopatadine, as an intranasal antihistamine, reduces both nasal and ocular symptoms associated with allergies.', null),
  (md5('question:pharmacy-exam-prep:14:38')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 38, 'Among the listed mucolytic agents used in ENT conditions, which one works by increasing respiratory tract fluid and decreasing mucus viscosity?', 'Guaifenesin increases respiratory tract fluid and decreases mucus viscosity as a mucolytic agent in ENT conditions.', null),
  (md5('question:pharmacy-exam-prep:14:39')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 39, 'Which medication, used in allergic rhinitis, is an intranasal antihistamine with a longer duration of action, providing relief for up to 12 hours after administration?', 'Olopatadine has a longer duration of action, providing relief for up to 12 hours after administration in allergic rhinitis.', null),
  (md5('question:pharmacy-exam-prep:14:40')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 40, 'Among the listed systemic antihistamines used in allergic rhinitis, which one is known for its minimal sedative effects and suitability for daytime use?', 'Fexofenadine is known for minimal sedative effects, making it suitable for daytime use in allergic rhinitis.', null),
  (md5('question:pharmacy-exam-prep:14:41')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 41, 'Which medication, used in chronic rhinosinusitis, is a fluoroquinolone antibiotic effective against both Gram-positive and Gram-negative bacteria commonly involved in sinus infections?', 'Ciprofloxacin, a fluoroquinolone antibiotic, is effective against a wide spectrum of bacteria in chronic rhinosinusitis.', null),
  (md5('question:pharmacy-exam-prep:14:42')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 42, 'Among the listed systemic decongestants used for nasal congestion, which one is cautioned against in patients with hyperthyroidism due to its potential to exacerbate thyroid-related symptoms?', 'Pseudoephedrine is cautioned against in patients with hyperthyroidism due to potential exacerbation of symptoms.', null),
  (md5('question:pharmacy-exam-prep:14:43')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 43, 'Which medication, used in chronic rhinosinusitis, is a macrolide antibiotic with anti-inflammatory properties and immune-modulatory effects in addition to its antimicrobial action?', 'Azithromycin, a macrolide antibiotic, has anti-inflammatory and immune-modulatory effects in chronic rhinosinusitis.', null),
  (md5('question:pharmacy-exam-prep:14:44')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 44, 'Among the listed topical antifungal agents used in otitis externa, which one is effective against various fungi including Candida species and Aspergillus?', 'Amphotericin B is effective against various fungi, including Candida species and Aspergillus, in otitis externa.', null),
  (md5('question:pharmacy-exam-prep:14:45')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 45, 'Which medication, used in allergic rhinitis, functions as a mast cell stabilizer, inhibiting the release of histamine and other inflammatory mediators from mast cells in the nasal mucosa?', 'Cromolyn acts as a mast cell stabilizer in allergic rhinitis, preventing the release of inflammatory mediators.', null),
  (md5('question:pharmacy-exam-prep:14:46')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 46, 'Among the listed systemic antihistamines used in allergic rhinitis, which one is known for its quick onset of action, providing relief within 15-30 minutes after administration?', 'Cetirizine has a quick onset of action, providing relief within 15-30 minutes in allergic rhinitis.', null),
  (md5('question:pharmacy-exam-prep:14:47')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 47, 'Which medication, used in otitis externa, is an aminoglycoside antibiotic effective against Pseudomonas aeruginosa and other Gram-negative bacteria commonly implicated in ear infections?', 'Gentamicin is an aminoglycoside effective against Pseudomonas aeruginosa and Gram-negative bacteria in otitis externa.', null),
  (md5('question:pharmacy-exam-prep:14:48')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 48, 'Among the listed topical corticosteroids used in otitis externa, which one is commonly recommended for its broad anti-inflammatory effects and safety in otic preparations?', 'Hydrocortisone is commonly recommended for its broad anti-inflammatory effects and safety in otic preparations.', null),
  (md5('question:pharmacy-exam-prep:14:49')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 49, 'Which medication, used in allergic rhinitis, is an intranasal antihistamine with a rapid onset of action, providing relief within 15 minutes after administration?', 'Azelastine, as an intranasal antihistamine, provides rapid relief within 15 minutes in allergic rhinitis.', null),
  (md5('question:pharmacy-exam-prep:14:50')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 50, 'Among the listed mucolytic agents used in ENT conditions, which one is a derivative of bromhexine and is effective in facilitating mucus clearance?', 'Carbocisteine, a derivative of bromhexine, is used as a mucolytic agent in ENT conditions.', null),
  (md5('question:pharmacy-exam-prep:14:51')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 51, 'Which medication, used in allergic rhinitis, is a leukotriene receptor antagonist known for its efficacy in reducing nasal congestion and inflammation?', 'Montelukast, a leukotriene receptor antagonist, is effective in reducing nasal congestion and inflammation in allergic rhinitis.', null),
  (md5('question:pharmacy-exam-prep:14:52')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 52, 'Among the listed topical antifungal agents used in otitis externa, which one is effective against Candida species commonly implicated in fungal ear infections?', 'Clotrimazole is effective against Candida species commonly involved in fungal ear infections.', null),
  (md5('question:pharmacy-exam-prep:14:53')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 53, 'Which medication, used in allergic rhinitis, is an intranasal antihistamine with minimal systemic absorption, reducing the risk of systemic side effects?', 'Azelastine, as an intranasal antihistamine, has minimal systemic absorption, reducing systemic side effects.', null),
  (md5('question:pharmacy-exam-prep:14:54')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 54, 'Among the listed systemic antihistamines used in allergic rhinitis, which one is known for its long duration of action, providing relief for up to 24 hours after a single dose?', 'Fexofenadine has a long duration of action, providing relief for up to 24 hours after a single dose in allergic rhinitis.', null),
  (md5('question:pharmacy-exam-prep:14:55')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 55, 'Which medication, used in chronic rhinosinusitis, is a macrolide antibiotic known for its anti-inflammatory properties and its effect on biofilms in the sinuses?', 'Azithromycin, a macrolide antibiotic, has anti-inflammatory properties and impacts sinuses'' biofilms in chronic rhinosinusitis.', null),
  (md5('question:pharmacy-exam-prep:14:56')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 56, 'Among the listed systemic decongestants used for nasal congestion, which one is cautioned against in patients with glaucoma due to its potential to increase intraocular pressure?', 'Pseudoephedrine is cautioned against in patients with glaucoma due to potential increased intraocular pressure.', null),
  (md5('question:pharmacy-exam-prep:14:57')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 57, 'Which medication, used in allergic rhinitis, is an intranasal antihistamine effective in reducing both nasal symptoms and ocular symptoms associated with allergies?', 'Olopatadine, as an intranasal antihistamine, reduces both nasal and ocular symptoms associated with allergies.', null),
  (md5('question:pharmacy-exam-prep:14:58')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 58, 'Among the listed mucolytic agents used in ENT conditions, which one works by increasing respiratory tract fluid and decreasing mucus viscosity?', 'Guaifenesin increases respiratory tract fluid and decreases mucus viscosity as a mucolytic agent in ENT conditions.', null),
  (md5('question:pharmacy-exam-prep:14:59')::uuid, md5('quiz:pharmacy-exam-prep:14')::uuid, 59, 'Which medication, used in allergic rhinitis, is a mast cell stabilizer, inhibiting the release of histamine and other inflammatory mediators from mast cells in the nasal mucosa?', 'Cromolyn acts as a mast cell stabilizer in allergic rhinitis, preventing the release of inflammatory mediators.', null)
