insert into public.chapters (id, course_id, position, title) values
  (md5('chapter:pharmacy-exam-prep:15')::uuid, md5('course:pharmacy-exam-prep')::uuid, 15, 'Anaesthesia')
insert into public.quizzes (id, chapter_id, title, position, is_preview) values
  (md5('quiz:pharmacy-exam-prep:15')::uuid, md5('chapter:pharmacy-exam-prep:15')::uuid, 'Anaesthesia', 1, false)
insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('question:pharmacy-exam-prep:15:1')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 1, 'Which anaesthetic medication is commonly used for induction and maintenance of general anesthesia and is known for its rapid onset and short duration of action?', 'Propofol is commonly used for induction and maintenance of general anesthesia due to its rapid onset and short duration of action.', null),
  (md5('question:pharmacy-exam-prep:15:2')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 2, 'Among the listed options, which anaesthetic medication is a volatile liquid inhalation agent used for the maintenance of general anesthesia and offers a smooth and rapid recovery?', 'Isoflurane is a volatile liquid inhalation agent used for the maintenance of general anesthesia, providing a smooth and rapid recovery.', null),
  (md5('question:pharmacy-exam-prep:15:3')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 3, 'Which anaesthetic medication is an inhalation agent frequently employed in pediatric anesthesia due to its minimal airway irritation and pleasant odor?', 'Sevoflurane is often used in pediatric anesthesia because it causes minimal airway irritation and has a pleasant odor.', null),
  (md5('question:pharmacy-exam-prep:15:4')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 4, 'Among the listed options, which anaesthetic medication is a barbiturate known for its rapid onset and short duration of action and is used for induction of anesthesia or sedation?', 'Thiopental, a barbiturate, is known for its rapid onset and short duration of action, commonly used for induction of anesthesia or sedation.', null),
  (md5('question:pharmacy-exam-prep:15:5')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 5, 'Which anaesthetic medication is an intravenous agent utilized for induction of anesthesia and sedation, known for its minimal cardiovascular and respiratory depression?', 'Etomidate, an intravenous agent, is used for induction of anesthesia and sedation due to its minimal cardiovascular and respiratory depression.', null),
  (md5('question:pharmacy-exam-prep:15:6')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 6, 'Among the following anaesthetic medications, which one is primarily used for intravenous anesthesia induction and maintenance, often referred to as the ''milk of amnesia''?', 'Propofol is recognized as the ''milk of amnesia'' and is primarily used for intravenous anesthesia induction and maintenance.', null),
  (md5('question:pharmacy-exam-prep:15:7')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 7, 'Which anaesthetic medication is known for its bronchodilator properties and is commonly used in anesthesia for patients with reactive airway disease?', 'Ketamine is an anaesthetic known for its bronchodilator properties and is frequently used in anesthesia for patients with reactive airway disease.', null),
  (md5('question:pharmacy-exam-prep:15:8')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 8, 'Among the listed options, which anaesthetic medication is used as an induction agent and analgesic, and is recognized for its dissociative effects and minimal effects on cardiovascular function?', 'Ketamine is an anaesthetic used as an induction agent and analgesic, known for its dissociative effects and minimal impact on cardiovascular function.', null),
  (md5('question:pharmacy-exam-prep:15:9')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 9, 'Which anaesthetic medication is an intravenous agent with antiemetic properties, often used in anesthesia induction and postoperative nausea and vomiting prevention?', 'Propofol, an intravenous agent, is used in anesthesia induction and has antiemetic properties for postoperative nausea and vomiting prevention.', null),
  (md5('question:pharmacy-exam-prep:15:10')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 10, 'Among the following anaesthetic medications, which one is used for maintenance of general anesthesia and is known for its minimal effect on the cardiovascular system, making it suitable for patients with cardiac conditions?', 'Desflurane is used for maintenance of general anesthesia and has minimal impact on the cardiovascular system, making it suitable for patients with cardiac conditions.', null),
  (md5('question:pharmacy-exam-prep:15:11')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 11, 'Which anaesthetic medication is commonly used for maintenance of anesthesia and is known for its rapid recovery due to its low solubility in blood and tissues?', 'Desflurane is commonly used for maintenance of anesthesia and offers rapid recovery owing to its low solubility in blood and tissues.', null),
  (md5('question:pharmacy-exam-prep:15:12')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 12, 'Among the listed anaesthetic medications, which one is an intravenous agent commonly used for anesthesia induction, with a formulation containing soybean oil, egg yolk phospholipids, and glycerol as emulsifiers?', 'Propofol, an intravenous agent used for anesthesia induction, contains soybean oil, egg yolk phospholipids, and glycerol as emulsifiers.', null),
  (md5('question:pharmacy-exam-prep:15:13')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 13, 'Which anaesthetic medication is a volatile liquid inhalation agent commonly used for maintenance of anesthesia, with a relatively low blood-gas partition coefficient contributing to faster recovery?', 'Isoflurane, a volatile liquid inhalation agent used for maintenance of anesthesia, has a relatively low blood-gas partition coefficient leading to faster recovery.', null),
  (md5('question:pharmacy-exam-prep:15:14')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 14, 'Among the following anaesthetic medications, which one is commonly used for short-term procedures due to its rapid onset and recovery, as well as its amnestic properties?', 'Midazolam is commonly used for short-term procedures owing to its rapid onset and recovery and amnestic properties.', null),
  (md5('question:pharmacy-exam-prep:15:15')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 15, 'Which anaesthetic medication is an intravenous agent used for sedation and anesthesia induction, known for its anticonvulsant properties and amnesia effects?', 'Midazolam, an intravenous agent, is used for sedation and anesthesia induction, possessing anticonvulsant properties and amnesia effects.', null),
  (md5('question:pharmacy-exam-prep:15:16')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 16, 'Among the listed options, which anaesthetic medication is used for induction and maintenance of anesthesia, particularly in patients with compromised cardiac function due to its minimal myocardial depression?', 'Etomidate is used for induction and maintenance of anesthesia, especially in patients with compromised cardiac function, due to its minimal myocardial depression.', null),
  (md5('question:pharmacy-exam-prep:15:17')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 17, 'Which anaesthetic medication is commonly used for maintenance of anesthesia and is recognized for its low solubility in blood and tissues, facilitating rapid recovery and awakening?', 'Desflurane, used for maintenance of anesthesia, has low solubility in blood and tissues, leading to rapid recovery and awakening.', null),
  (md5('question:pharmacy-exam-prep:15:18')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 18, 'Among the listed anaesthetic medications, which one is an intravenous agent used for induction and maintenance of anesthesia, known for its antiemetic properties, especially in high-risk patients?', 'Propofol, an intravenous agent, is used for induction and maintenance of anesthesia and possesses antiemetic properties, particularly in high-risk patients.', null),
  (md5('question:pharmacy-exam-prep:15:19')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 19, 'Which anaesthetic medication is commonly used for maintenance of anesthesia and is known for its rapid elimination, making it suitable for outpatient surgeries?', 'Desflurane is commonly used for maintenance of anesthesia due to its rapid elimination, making it suitable for outpatient surgeries.', null),
  (md5('question:pharmacy-exam-prep:15:20')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 20, 'Which topical anaesthetic medication is commonly used for mucosal anesthesia, particularly in dentistry, and is available in gel or liquid form?', 'Benzocaine is commonly used for mucosal anesthesia in dentistry and is available in gel or liquid formulations.', null),
  (md5('question:pharmacy-exam-prep:15:21')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 21, 'Among the listed options, which topical anaesthetic medication is known for its rapid onset of action and is often used for short procedures, such as venipuncture or IV cannulation?', 'Lidocaine is known for its rapid onset of action and is commonly used for short procedures like venipuncture or IV cannulation.', null),
  (md5('question:pharmacy-exam-prep:15:22')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 22, 'Which topical anaesthetic medication is frequently used for ophthalmic procedures and is available in drops or gel formulations for ocular surface anesthesia?', 'Tetracaine is frequently used for ophthalmic procedures and is available in drops or gel formulations for ocular surface anesthesia.', null),
  (md5('question:pharmacy-exam-prep:15:23')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 23, 'Among the following topical anaesthetic medications, which one is commonly used for numbing the skin before minor medical procedures or for temporary relief of pain and itching?', 'Lidocaine is commonly used for numbing the skin before minor medical procedures or for temporary relief of pain and itching.', null),
  (md5('question:pharmacy-exam-prep:15:24')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 24, 'Which topical anaesthetic medication is often used in conjunction with a vasoconstrictor, such as epinephrine, to prolong its effect and reduce bleeding during procedures?', 'Lidocaine is frequently combined with a vasoconstrictor to prolong its effect and reduce bleeding during procedures.', null),
  (md5('question:pharmacy-exam-prep:15:25')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 25, 'Among the listed options, which topical anaesthetic medication is primarily used for its longer duration of action and is often employed for chronic pain management or as a dermal analgesic?', 'Lidocaine, known for its longer duration of action, is often used for chronic pain management or as a dermal analgesic.', null),
  (md5('question:pharmacy-exam-prep:15:26')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 26, 'Which topical anaesthetic medication is commonly used in tattooing and body piercing to alleviate pain during the procedure and is available as a cream or gel?', 'Lidocaine is commonly used in tattooing and body piercing to alleviate pain during the procedure and is available as a cream or gel.', null),
  (md5('question:pharmacy-exam-prep:15:27')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 27, 'Among the following topical anaesthetic medications, which one is commonly used for relief of itching and pain caused by minor burns, sunburns, or insect bites?', 'Benzocaine is commonly used for relief of itching and pain caused by minor burns, sunburns, or insect bites.', null),
  (md5('question:pharmacy-exam-prep:15:28')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 28, 'Which topical anaesthetic medication is often used in cosmetic procedures, such as laser hair removal, to reduce discomfort during the process and is available in various formulations?', 'Lidocaine is often used in cosmetic procedures like laser hair removal to reduce discomfort and is available in various formulations.', null),
  (md5('question:pharmacy-exam-prep:15:29')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 29, 'Among the listed topical anaesthetic medications, which one is frequently used for relief of pain and discomfort associated with minor skin irritations or teething in infants?', 'Benzocaine is frequently used for relief of pain and discomfort associated with minor skin irritations or teething in infants.', null),
  (md5('question:pharmacy-exam-prep:15:30')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 30, 'Which topical anaesthetic medication is known for its use in dentistry and is commonly employed for gingival or dental procedures, available in gel, paste, or spray forms?', 'Benzocaine is known for its use in dentistry and is commonly used for gingival or dental procedures in gel, paste, or spray forms.', null),
  (md5('question:pharmacy-exam-prep:15:31')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 31, 'Among the following topical anaesthetic medications, which one is used for temporary relief of discomfort associated with hemorrhoids or other anal conditions?', 'Lidocaine is used for temporary relief of discomfort associated with hemorrhoids or other anal conditions.', null),
  (md5('question:pharmacy-exam-prep:15:32')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 32, 'Which topical anaesthetic medication is often used for mucous membrane anesthesia, such as for intubation or endoscopy procedures, and is available in various forms, including sprays and gels?', 'Lidocaine is often used for mucous membrane anesthesia, such as for intubation or endoscopy procedures, and is available in sprays and gels.', null),
  (md5('question:pharmacy-exam-prep:15:33')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 33, 'Among the listed topical anaesthetic medications, which one is frequently used for reducing pain and discomfort associated with minor injuries or skin conditions like abrasions or scrapes?', 'Benzocaine is frequently used for reducing pain and discomfort associated with minor injuries or skin conditions like abrasions or scrapes.', null),
  (md5('question:pharmacy-exam-prep:15:34')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 34, 'Which topical anaesthetic medication is known for its use in dermatological procedures, such as skin biopsies or suturing, to minimize pain during the process?', 'Lidocaine is known for its use in dermatological procedures, such as skin biopsies or suturing, to minimize pain during the process.', null),
  (md5('question:pharmacy-exam-prep:15:35')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 35, 'Among the following topical anaesthetic medications, which one is commonly used in ear, nose, and throat procedures to alleviate discomfort and pain, available as drops or sprays?', 'Lidocaine is commonly used in ear, nose, and throat procedures to alleviate discomfort and pain and is available as drops or sprays.', null),
  (md5('question:pharmacy-exam-prep:15:36')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 36, 'Which topical anaesthetic medication is frequently used in tattooing, body piercing, or waxing to reduce pain during the procedure and is available in cream or gel forms?', 'Lidocaine is frequently used in tattooing, body piercing, or waxing to reduce pain and is available in cream or gel forms.', null),
  (md5('question:pharmacy-exam-prep:15:37')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 37, 'Among the listed topical anaesthetic medications, which one is commonly used for temporary relief of pain and itching associated with minor skin irritations or rashes?', 'Benzocaine is commonly used for temporary relief of pain and itching associated with minor skin irritations or rashes.', null),
  (md5('question:pharmacy-exam-prep:15:38')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 38, 'Which topical anaesthetic medication is often used in podiatry for numbing the skin before minor procedures or to relieve pain caused by corns or calluses?', 'Benzocaine is often used in podiatry for numbing the skin before minor procedures or to relieve pain caused by corns or calluses.', null),
  (md5('question:pharmacy-exam-prep:15:39')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 39, 'Which medication, when used concomitantly with inhalational anaesthetics, is known to increase the risk of severe arrhythmias and should be used cautiously or avoided during anesthesia?', 'Beta-blockers, when used with inhalational anaesthetics, can increase the risk of severe arrhythmias and should be used cautiously or avoided during anesthesia.', null),
  (md5('question:pharmacy-exam-prep:15:40')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 40, 'Among the listed medications, which one, when combined with certain anaesthetics, especially halogenated agents, can potentiate respiratory depression and should be used cautiously or adjusted in dosage?', 'Benzodiazepines, when combined with certain anaesthetics, particularly halogenated agents, can potentiate respiratory depression and should be used cautiously or adjusted in dosage.', null),
  (md5('question:pharmacy-exam-prep:15:41')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 41, 'Which medication, if used concurrently with inhalational anaesthetics, may increase the risk of hypotension and cardiovascular depression during anesthesia, requiring careful monitoring or adjustment in dosage?', 'Calcium channel blockers, when used with inhalational anaesthetics, may increase the risk of hypotension and cardiovascular depression during anesthesia, requiring careful monitoring or adjustment in dosage.', null),
  (md5('question:pharmacy-exam-prep:15:42')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 42, 'Among the following medications, which one, when combined with general anaesthetics, particularly propofol, may increase the risk of CNS depression and respiratory depression, necessitating cautious use or dosage adjustment?', 'Opioids, when combined with general anaesthetics like propofol, may increase the risk of CNS depression and respiratory depression, necessitating cautious use or dosage adjustment.', null),
  (md5('question:pharmacy-exam-prep:15:43')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 43, 'Which medication, if used concurrently with certain anaesthetics like ketamine or inhalational agents, may lead to increased CNS excitation, agitation, or hallucinations, warranting careful monitoring or dosage adjustment?', 'Antihistamines, when used with certain anaesthetics like ketamine or inhalational agents, may lead to increased CNS excitation, agitation, or hallucinations, necessitating careful monitoring or dosage adjustment.', null),
  (md5('question:pharmacy-exam-prep:15:44')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 44, 'Among the listed medications, which one, if used alongside volatile anaesthetics, may enhance the neuromuscular-blocking effects and increase the risk of prolonged muscle relaxation during anesthesia?', 'Antiepileptics, if used alongside volatile anaesthetics, may enhance the neuromuscular-blocking effects and increase the risk of prolonged muscle relaxation during anesthesia.', null),
  (md5('question:pharmacy-exam-prep:15:45')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 45, 'Which medication, when combined with certain anaesthetics like sevoflurane or desflurane, may increase the risk of prolonged QT interval or cardiac arrhythmias, requiring cautious use or dose adjustments?', 'Antidepressants, when combined with certain anaesthetics like sevoflurane or desflurane, may increase the risk of prolonged QT interval or cardiac arrhythmias, necessitating cautious use or dose adjustments.', null),
  (md5('question:pharmacy-exam-prep:15:46')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 46, 'Among the following medications, which one, if used concurrently with certain anaesthetics, particularly volatile agents, may increase the risk of central nervous system depression, necessitating careful monitoring or dosage adjustment?', 'Antidepressants, if used with certain anaesthetics like volatile agents, may increase the risk of central nervous system depression, requiring careful monitoring or dosage adjustment.', null),
  (md5('question:pharmacy-exam-prep:15:47')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 47, 'Which medication, if used alongside certain anaesthetics like propofol or benzodiazepines, may potentiate sedation and respiratory depression, requiring cautious use or dosage adjustment during anesthesia?', 'Antihistamines, when used alongside certain anaesthetics like propofol or benzodiazepines, may potentiate sedation and respiratory depression, necessitating cautious use or dosage adjustment during anesthesia.', null),
  (md5('question:pharmacy-exam-prep:15:48')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 48, 'Among the listed medications, which one, if used concurrently with certain anaesthetics, may increase the risk of bleeding or alter coagulation parameters, necessitating careful monitoring or adjustment in dosage?', 'NSAIDs, if used with certain anaesthetics, may increase the risk of bleeding or alter coagulation parameters, requiring careful monitoring or adjustment in dosage.', null),
  (md5('question:pharmacy-exam-prep:15:49')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 49, 'Which medication, when combined with general anaesthetics like propofol or volatile agents, may lead to increased sedation, CNS depression, or respiratory depression, necessitating cautious use or dose adjustments during anesthesia?', 'Antipsychotics, if combined with general anaesthetics like propofol or volatile agents, may lead to increased sedation, CNS depression, or respiratory depression, necessitating cautious use or dose adjustments during anesthesia.', null),
  (md5('question:pharmacy-exam-prep:15:50')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 50, 'Among the following medications, which one, if used concurrently with certain anaesthetics, particularly volatile agents, may increase the risk of hypotension and cardiovascular depression during anesthesia, requiring careful monitoring or adjustment in dosage?', 'Antihistamines, if used with certain anaesthetics like volatile agents, may increase the risk of hypotension and cardiovascular depression during anesthesia, requiring careful monitoring or adjustment in dosage.', null),
  (md5('question:pharmacy-exam-prep:15:51')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 51, 'Which medication, if used alongside general anaesthetics, especially propofol or volatile agents, may exacerbate respiratory depression and CNS depression, warranting cautious use or dosage adjustment during anesthesia?', 'Opioids, if used alongside general anaesthetics like propofol or volatile agents, may exacerbate respiratory depression and CNS depression, necessitating cautious use or dosage adjustment during anesthesia.', null),
  (md5('question:pharmacy-exam-prep:15:52')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 52, 'Among the listed medications, which one, when combined with certain anaesthetics, particularly volatile agents, may lead to increased CNS depression and respiratory depression, necessitating cautious use or dosage adjustment?', 'Antiepileptics, when combined with certain anaesthetics like volatile agents, may lead to increased CNS depression and respiratory depression, necessitating cautious use or dosage adjustment.', null),
  (md5('question:pharmacy-exam-prep:15:53')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 53, 'Which medication, if used concurrently with certain anaesthetics like volatile agents, may lead to increased CNS excitation, agitation, or hallucinations, necessitating careful monitoring or dosage adjustment?', 'Antidepressants, if used with certain anaesthetics like volatile agents, may lead to increased CNS excitation, agitation, or hallucinations, necessitating careful monitoring or dosage adjustment.', null),
  (md5('question:pharmacy-exam-prep:15:54')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 54, 'Among the following medications, which one, if used alongside certain anaesthetics, particularly propofol or benzodiazepines, may lead to increased sedation and respiratory depression, requiring cautious use or dosage adjustment?', 'Antiepileptics, if used alongside certain anaesthetics like propofol or benzodiazepines, may lead to increased sedation and respiratory depression, necessitating cautious use or dosage adjustment.', null),
  (md5('question:pharmacy-exam-prep:15:55')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 55, 'Which medication, if used concurrently with certain anaesthetics like ketamine or inhalational agents, may lead to increased CNS excitation, agitation, or hallucinations, necessitating careful monitoring or dosage adjustment?', 'Antiepileptics, if used with certain anaesthetics like ketamine or inhalational agents, may lead to increased CNS excitation, agitation, or hallucinations, necessitating careful monitoring or dosage adjustment.', null),
  (md5('question:pharmacy-exam-prep:15:56')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 56, 'Among the listed medications, which one, when combined with certain anaesthetics like sevoflurane or desflurane, may increase the risk of prolonged QT interval or cardiac arrhythmias, requiring cautious use or dose adjustments?', 'Antiepileptics, when combined with certain anaesthetics like sevoflurane or desflurane, may increase the risk of prolonged QT interval or cardiac arrhythmias, necessitating cautious use or dose adjustments.', null),
  (md5('question:pharmacy-exam-prep:15:57')::uuid, md5('quiz:pharmacy-exam-prep:15')::uuid, 57, 'Which medication, if used alongside general anaesthetics like propofol or volatile agents, may lead to increased sedation, CNS depression, or respiratory depression, warranting cautious use or dose adjustments during anesthesia?', 'Antidepressants, if used with general anaesthetics like propofol or volatile agents, may lead to increased sedation, CNS depression, or respiratory depression, necessitating cautious use or dose adjustments during anesthesia.', null)
insert into public.quiz_answers (id, question_id, position, text, is_correct) values
  (md5('answer:pharmacy-exam-prep:15:1:1')::uuid, md5('question:pharmacy-exam-prep:15:1')::uuid, 1, 'Propofol', true),
  (md5('answer:pharmacy-exam-prep:15:1:2')::uuid, md5('question:pharmacy-exam-prep:15:1')::uuid, 2, 'Isoflurane', false),
