insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('question:pharmacy-exam-prep:16:1')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 1, 'Which type of vaccine is based on a weakened form of the pathogen that replicates in the host but causes a mild infection, stimulating an immune response without causing the disease?', 'Live attenuated vaccines contain weakened pathogens that replicate in the host, triggering an immune response without causing severe illness.', null),
  (md5('question:pharmacy-exam-prep:16:2')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 2, 'Among the following, which vaccine type uses a killed or inactivated form of the pathogen to induce an immune response without the risk of causing the disease in the host?', 'Inactivated vaccines employ killed or inactivated pathogens to prompt an immune response without the risk of causing the disease in the host.', null),
  (md5('question:pharmacy-exam-prep:16:3')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 3, 'Which vaccine type is composed of genetic material, instructing cells to produce a viral protein that triggers an immune response against the pathogen?', 'mRNA vaccines utilize genetic material to direct cells to produce viral proteins, eliciting an immune response against the pathogen.', null),
  (md5('question:pharmacy-exam-prep:16:4')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 4, 'Among the listed vaccine types, which one involves the use of a part of the pathogen, such as a protein or sugar, conjugated with a carrier protein to enhance the immune response, particularly in young children?', 'Conjugate vaccines consist of pathogen parts conjugated with a carrier protein, amplifying the immune response, especially in young children.', null),
  (md5('question:pharmacy-exam-prep:16:5')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 5, 'Which vaccine type is based on a toxoid, a chemically modified toxin of the pathogen, aimed at stimulating an immune response against the toxin produced by the pathogen rather than the pathogen itself?', 'Toxoid vaccines utilize chemically modified toxins to trigger an immune response against the toxin produced by the pathogen rather than the pathogen itself.', null),
  (md5('question:pharmacy-exam-prep:16:6')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 6, 'Among the following vaccines, which one is an example of a live attenuated vaccine commonly administered for measles, mumps, and rubella (MMR)?', 'The varicella vaccine is an example of a live attenuated vaccine administered for diseases like measles, mumps, and rubella (MMR).', null),
  (md5('question:pharmacy-exam-prep:16:7')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 7, 'Which vaccine type includes examples such as the influenza vaccine and the rabies vaccine, which utilize inactivated forms of the pathogens to trigger an immune response?', 'Inactivated vaccines, like the influenza and rabies vaccines, employ inactivated forms of pathogens to prompt an immune response.', null),
  (md5('question:pharmacy-exam-prep:16:8')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 8, 'Among the listed vaccines, which one involves the introduction of genetic material into cells to produce proteins that trigger an immune response, as seen in some COVID-19 vaccines?', 'mRNA vaccines introduce genetic material into cells to produce proteins that stimulate an immune response, as seen in certain COVID-19 vaccines.', null),
  (md5('question:pharmacy-exam-prep:16:9')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 9, 'Which vaccine type is designed to prevent diseases caused by bacterial infections, particularly those with polysaccharide capsules, by enhancing the immune response against the bacteria''s polysaccharide capsule?', 'Conjugate vaccines aim to prevent diseases caused by bacteria with polysaccharide capsules by boosting the immune response against the bacteria''s polysaccharide capsule.', null),
  (md5('question:pharmacy-exam-prep:16:10')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 10, 'Among the following vaccines, which one utilizes weakened or attenuated forms of the poliovirus to induce an immune response without causing the disease in the host?', 'The Oral Polio Vaccine (OPV) uses weakened or attenuated forms of the poliovirus to prompt an immune response without causing the disease.', null),
  (md5('question:pharmacy-exam-prep:16:11')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 11, 'Which vaccine type uses killed or inactivated forms of the pathogen to trigger an immune response without the risk of causing the disease in the host, as seen in some seasonal influenza vaccines?', 'Inactivated vaccines, like some seasonal influenza vaccines, employ killed or inactivated forms of pathogens to induce an immune response without causing the disease.', null),
  (md5('question:pharmacy-exam-prep:16:12')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 12, 'Among the listed vaccines, which one involves the use of a small, harmless piece of the pathogen, such as a protein or sugar, to trigger an immune response, as seen in the Hepatitis B vaccine?', 'Subunit vaccines, like the Hepatitis B vaccine, use harmless pieces of pathogens to elicit an immune response.', null),
  (md5('question:pharmacy-exam-prep:16:13')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 13, 'Which vaccine type is based on a toxoid, a chemically modified toxin of the pathogen, aimed at stimulating an immune response against the toxin produced by the pathogen rather than the pathogen itself, as observed in the diphtheria and tetanus vaccines?', 'Toxoid vaccines, like the diphtheria and tetanus vaccines, prompt an immune response against toxins produced by the pathogen rather than the pathogen itself.', null),
  (md5('question:pharmacy-exam-prep:16:14')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 14, 'Among the following vaccines, which one is an example of a live attenuated vaccine commonly administered for protection against measles, mumps, and rubella (MMR)?', 'The varicella vaccine is an example of a live attenuated vaccine administered for diseases like measles, mumps, and rubella (MMR).', null),
  (md5('question:pharmacy-exam-prep:16:15')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 15, 'Which vaccine type includes examples such as the influenza vaccine and the rabies vaccine, which utilize inactivated forms of the pathogens to trigger an immune response?', 'Inactivated vaccines, like the influenza and rabies vaccines, employ inactivated forms of pathogens to prompt an immune response.', null),
  (md5('question:pharmacy-exam-prep:16:16')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 16, 'Among the listed vaccines, which one involves the introduction of genetic material into cells to produce proteins that trigger an immune response, as seen in some COVID-19 vaccines?', 'mRNA vaccines introduce genetic material into cells to produce proteins that stimulate an immune response, as seen in certain COVID-19 vaccines.', null),
  (md5('question:pharmacy-exam-prep:16:17')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 17, 'Which vaccine type is designed to prevent diseases caused by bacterial infections, particularly those with polysaccharide capsules, by enhancing the immune response against the bacteria''s polysaccharide capsule?', 'Conjugate vaccines aim to prevent diseases caused by bacteria with polysaccharide capsules by boosting the immune response against the bacteria''s polysaccharide capsule.', null),
  (md5('question:pharmacy-exam-prep:16:18')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 18, 'Among the following vaccines, which one utilizes weakened or attenuated forms of the poliovirus to induce an immune response without causing the disease in the host?', 'The Oral Polio Vaccine (OPV) uses weakened or attenuated forms of the poliovirus to prompt an immune response without causing the disease.', null),
  (md5('question:pharmacy-exam-prep:16:19')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 19, 'Which vaccine type uses killed or inactivated forms of the pathogen to trigger an immune response without the risk of causing the disease in the host, as seen in some seasonal influenza vaccines?', 'Inactivated vaccines, like some seasonal influenza vaccines, employ killed or inactivated forms of pathogens to induce an immune response without causing the disease.', null),
  (md5('question:pharmacy-exam-prep:16:20')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 20, 'Among the listed vaccines, which one involves the use of a small, harmless piece of the pathogen, such as a protein or sugar, to trigger an immune response, as seen in the Hepatitis B vaccine?', 'Subunit vaccines, like the Hepatitis B vaccine, use harmless pieces of pathogens to elicit an immune response.', null),
  (md5('question:pharmacy-exam-prep:16:21')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 21, 'Which vaccine type is based on a toxoid, a chemically modified toxin of the pathogen, aimed at stimulating an immune response against the toxin produced by the pathogen rather than the pathogen itself, as observed in the diphtheria and tetanus vaccines?', 'Toxoid vaccines, like the diphtheria and tetanus vaccines, prompt an immune response against toxins produced by the pathogen rather than the pathogen itself.', null),
  (md5('question:pharmacy-exam-prep:16:22')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 22, 'At what age is the first dose of the DTaP/IPV/Hib/HepB vaccine typically administered to infants in the UK''s childhood vaccination schedule?', 'The first dose of DTaP/IPV/Hib/HepB vaccine is typically given at 2 months as part of the childhood vaccination schedule in the UK.', null),
  (md5('question:pharmacy-exam-prep:16:23')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 23, 'At what age do children usually receive the second dose of the DTaP/IPV/Hib/HepB vaccine in the UK''s childhood vaccination schedule?', 'The second dose of DTaP/IPV/Hib/HepB vaccine is typically administered at 4 months in the UK''s childhood vaccination schedule.', null),
  (md5('question:pharmacy-exam-prep:16:24')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 24, 'When do infants typically receive the third dose of the DTaP/IPV/Hib/HepB vaccine as per the UK''s childhood vaccination schedule?', 'The third dose of DTaP/IPV/Hib/HepB vaccine is usually given at 6 months in the UK''s childhood vaccination schedule.', null),
  (md5('question:pharmacy-exam-prep:16:25')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 25, 'At what age is the first dose of the MenB (Meningococcal B) vaccine typically administered to infants as part of the UK''s vaccination schedule?', 'The first dose of the MenB (Meningococcal B) vaccine is usually given at 2 months as part of the UK''s vaccination schedule.', null),
  (md5('question:pharmacy-exam-prep:16:26')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 26, 'When is the booster dose of the MenB (Meningococcal B) vaccine typically given to infants in the UK''s vaccination schedule?', 'The booster dose of the MenB (Meningococcal B) vaccine is typically administered at 4 months in the UK''s vaccination schedule.', null),
  (md5('question:pharmacy-exam-prep:16:27')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 27, 'At what age is the first dose of the MenACWY (Meningococcal ACWY) vaccine routinely given to adolescents in the UK?', 'The first dose of the MenACWY (Meningococcal ACWY) vaccine is typically given to adolescents at 12-13 years in the UK.', null),
  (md5('question:pharmacy-exam-prep:16:28')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 28, 'When do adolescents usually receive the booster dose of the MenACWY (Meningococcal ACWY) vaccine in the UK?', 'Adolescents typically receive the booster dose of the MenACWY (Meningococcal ACWY) vaccine at 16-18 years in the UK.', null),
  (md5('question:pharmacy-exam-prep:16:29')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 29, 'At what age is the first dose of the MMR (Measles, Mumps, Rubella) vaccine administered to children as part of the UK''s vaccination schedule?', 'The first dose of the MMR (Measles, Mumps, Rubella) vaccine is typically given at 1 year in the UK''s vaccination schedule.', null),
  (md5('question:pharmacy-exam-prep:16:30')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 30, 'When do children usually receive the second dose of the MMR (Measles, Mumps, Rubella) vaccine in the UK''s vaccination schedule?', 'The second dose of the MMR (Measles, Mumps, Rubella) vaccine is typically administered at 2 years in the UK''s vaccination schedule.', null),
  (md5('question:pharmacy-exam-prep:16:31')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 31, 'At what age is the first dose of the HPV (Human Papillomavirus) vaccine routinely given to adolescents in the UK?', 'The first dose of the HPV (Human Papillomavirus) vaccine is usually given to adolescents at 12-13 years in the UK.', null),
  (md5('question:pharmacy-exam-prep:16:32')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 32, 'When do adolescents typically receive the second dose of the HPV (Human Papillomavirus) vaccine in the UK?', 'Adolescents typically receive the second dose of the HPV (Human Papillomavirus) vaccine at 16-18 years in the UK.', null),
  (md5('question:pharmacy-exam-prep:16:33')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 33, 'At what age is the first dose of the Hib/MenC (Haemophilus influenzae type b/Meningococcal C) vaccine administered to infants in the UK''s vaccination schedule?', 'The first dose of the Hib/MenC (Haemophilus influenzae type b/Meningococcal C) vaccine is typically given at 2 months as part of the UK''s vaccination schedule.', null),
  (md5('question:pharmacy-exam-prep:16:34')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 34, 'When do infants usually receive the booster dose of the Hib/MenC (Haemophilus influenzae type b/Meningococcal C) vaccine in the UK?', 'Infants typically receive the booster dose of the Hib/MenC (Haemophilus influenzae type b/Meningococcal C) vaccine at 4 months in the UK''s vaccination schedule.', null),
  (md5('question:pharmacy-exam-prep:16:35')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 35, 'At what age is the first dose of the PCV (Pneumococcal Conjugate Vaccine) administered to infants in the UK''s vaccination schedule?', 'The first dose of the PCV (Pneumococcal Conjugate Vaccine) is typically given at 2 months as part of the UK''s vaccination schedule.', null),
  (md5('question:pharmacy-exam-prep:16:36')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 36, 'When do infants usually receive the second dose of the PCV (Pneumococcal Conjugate Vaccine) in the UK''s vaccination schedule?', 'Infants typically receive the second dose of the PCV (Pneumococcal Conjugate Vaccine) at 4 months in the UK''s vaccination schedule.', null),
  (md5('question:pharmacy-exam-prep:16:37')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 37, 'At what age is the first dose of the Rotavirus vaccine typically administered to infants in the UK''s vaccination schedule?', 'The first dose of the Rotavirus vaccine is typically given at 2 months as part of the UK''s vaccination schedule.', null),
  (md5('question:pharmacy-exam-prep:16:38')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 38, 'When do infants usually receive the second dose of the Rotavirus vaccine in the UK''s vaccination schedule?', 'Infants typically receive the second dose of the Rotavirus vaccine at 4 months in the UK''s vaccination schedule.', null),
  (md5('question:pharmacy-exam-prep:16:39')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 39, 'At what age is the first dose of the BCG (Bacillus Calmette-Guérin) vaccine given to newborns in the UK at higher risk of tuberculosis?', 'The first dose of the BCG (Bacillus Calmette-Guérin) vaccine is typically given at birth to newborns at higher risk of tuberculosis in the UK.', null),
  (md5('question:pharmacy-exam-prep:16:40')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 40, 'When do children typically receive the booster dose of the BCG (Bacillus Calmette-Guérin) vaccine in the UK?', 'Children typically receive the booster dose of the BCG (Bacillus Calmette-Guérin) vaccine at 1 year in the UK.', null),
  (md5('question:pharmacy-exam-prep:16:41')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 41, 'Which vaccine is recommended for individuals aged 65 and older to protect against pneumococcal infections, particularly pneumonia and meningitis?', 'The Pneumococcal polysaccharide vaccine (PPSV23) is recommended for individuals aged 65 and older to safeguard against pneumococcal infections.', null),
  (md5('question:pharmacy-exam-prep:16:42')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 42, 'Among the following vaccines, which one is recommended for individuals over 65 years old to prevent shingles caused by the varicella-zoster virus?', 'The Zoster (Shingles) vaccine is recommended for individuals over 65 years old to prevent shingles caused by the varicella-zoster virus.', null),
  (md5('question:pharmacy-exam-prep:16:43')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 43, 'Which vaccine is specifically advised for individuals with chronic liver disease, including hepatitis B and hepatitis C, to prevent serious complications?', 'The Hepatitis B vaccine is specifically recommended for individuals with chronic liver disease, including hepatitis B and hepatitis C, to prevent serious complications.', null),
  (md5('question:pharmacy-exam-prep:16:44')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 44, 'Among the listed vaccines, which one is recommended for individuals with diabetes to protect against pneumococcal infections, reducing the risk of complications?', 'The Pneumococcal polysaccharide vaccine (PPSV23) is recommended for individuals with diabetes to shield against pneumococcal infections and related complications.', null),
  (md5('question:pharmacy-exam-prep:16:45')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 45, 'Which vaccine is advised for individuals with chronic respiratory conditions, such as chronic obstructive pulmonary disease (COPD), to prevent exacerbations and complications?', 'The Influenza vaccine is recommended for individuals with chronic respiratory conditions like COPD to prevent exacerbations and related complications.', null),
  (md5('question:pharmacy-exam-prep:16:46')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 46, 'Among the following vaccines, which one is particularly advised for individuals with chronic heart conditions, such as heart failure or coronary artery disease, to prevent complications?', 'The Influenza vaccine is specifically recommended for individuals with chronic heart conditions to prevent complications.', null),
  (md5('question:pharmacy-exam-prep:16:47')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 47, 'Which vaccine is advised for individuals with compromised immune systems due to diseases like HIV/AIDS or certain medications to prevent severe infections?', 'The Pneumococcal polysaccharide vaccine (PPSV23) is advised for individuals with compromised immune systems to prevent severe infections.', null),
  (md5('question:pharmacy-exam-prep:16:48')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 48, 'Among the listed vaccines, which one is recommended for individuals on long-term steroid therapy or immunosuppressants to protect against pneumococcal infections?', 'The Pneumococcal polysaccharide vaccine (PPSV23) is recommended for individuals on long-term steroid therapy or immunosuppressants to prevent pneumococcal infections.', null),
  (md5('question:pharmacy-exam-prep:16:49')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 49, 'Which vaccine is advised for individuals over 65 years old, particularly those residing in long-term care facilities, to prevent influenza and related complications?', 'The Influenza vaccine is specifically recommended for individuals over 65 years old, especially those in long-term care facilities, to prevent influenza and related complications.', null),
  (md5('question:pharmacy-exam-prep:16:50')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 50, 'Among the following vaccines, which one is recommended for individuals traveling to regions with a high risk of hepatitis A infection to prevent the disease?', 'The Hepatitis A vaccine is advised for individuals traveling to high-risk regions to prevent hepatitis A infection.', null),
  (md5('question:pharmacy-exam-prep:16:51')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 51, 'Which vaccine is advised for individuals with chronic kidney disease, including those on dialysis, to prevent severe complications from infections?', 'The Pneumococcal polysaccharide vaccine (PPSV23) is recommended for individuals with chronic kidney disease, including those on dialysis, to prevent severe complications from infections.', null),
  (md5('question:pharmacy-exam-prep:16:52')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 52, 'Among the listed vaccines, which one is advised for individuals with sickle cell disease or asplenia to prevent infections from encapsulated bacteria?', 'The Pneumococcal polysaccharide vaccine (PPSV23) is advised for individuals with sickle cell disease or asplenia to prevent infections from encapsulated bacteria.', null),
  (md5('question:pharmacy-exam-prep:16:53')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 53, 'Which vaccine is recommended for individuals with a history of Guillain-Barré syndrome (GBS) or its associated risks to prevent influenza and related complications?', 'The Influenza vaccine is recommended for individuals with a history of Guillain-Barré syndrome (GBS) or its associated risks to prevent influenza and related complications.', null),
  (md5('question:pharmacy-exam-prep:16:54')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 54, 'Among the following vaccines, which one is recommended for individuals with chronic neurological conditions, such as multiple sclerosis, to prevent severe infections?', 'The Influenza vaccine is recommended for individuals with chronic neurological conditions to prevent severe infections.', null),
  (md5('question:pharmacy-exam-prep:16:55')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 55, 'Which vaccine is advised for individuals with chronic inflammatory conditions, like rheumatoid arthritis, to prevent infections and related complications?', 'The Influenza vaccine is advised for individuals with chronic inflammatory conditions like rheumatoid arthritis to prevent infections and related complications.', null),
  (md5('question:pharmacy-exam-prep:16:56')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 56, 'Among the listed vaccines, which one is recommended for individuals undergoing chemotherapy or radiation therapy to protect against influenza and related complications?', 'The Influenza vaccine is recommended for individuals undergoing chemotherapy or radiation therapy to prevent influenza and related complications.', null),
  (md5('question:pharmacy-exam-prep:16:57')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 57, 'Which vaccine is advised for individuals receiving immunosuppressive medications, like biologics, to prevent infections and severe complications?', 'The Influenza vaccine is advised for individuals receiving immunosuppressive medications to prevent infections and severe complications.', null),
  (md5('question:pharmacy-exam-prep:16:58')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 58, 'Among the following vaccines, which one is recommended for individuals with chronic lung conditions, like asthma, to prevent exacerbations and complications?', 'The Influenza vaccine is recommended for individuals with chronic lung conditions like asthma to prevent exacerbations and related complications.', null),
  (md5('question:pharmacy-exam-prep:16:59')::uuid, md5('quiz:pharmacy-exam-prep:16')::uuid, 59, 'Which vaccine is advised for individuals with chronic liver disease, including those with cirrhosis, to prevent infections and related complications?', 'The Influenza vaccine is advised for individuals with chronic liver disease, including those with cirrhosis, to prevent infections and related complications.', null)
