insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('question:pharmacy-exam-prep:17:1')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 1, 'Calculate the volume of a 15% w/v solution needed to prepare 500ml of a 5% solution.', 'V1C1 = V2C2; (V1 x 15%) = (500ml x 5%); V1 = 166.67ml.', null),
  (md5('question:pharmacy-exam-prep:17:2')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 2, 'If a patient is prescribed 25mcg/kg of Drug X and weighs 80kg, how many 100mcg tablets should they receive per dose?', 'Dose = 25mcg/kg x 80kg = 2000mcg; Tablets = 2000mcg / 100mcg/tablet = 0.2 tablets.', null),
  (md5('question:pharmacy-exam-prep:17:3')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 3, 'A solution contains 250mg of medication in 100ml. How many milliliters are needed for a 75mg dose?', '250mg in 100ml; 75mg needs X ml; X = (75mg x 100ml) / 250mg = 30ml.', null),
  (md5('question:pharmacy-exam-prep:17:4')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 4, 'A patient requires a 0.04% solution. How much solute is needed for 250ml of solution?', '0.04% = 0.04g/100ml; For 250ml: 0.04g/100ml x 250ml = 0.1g.', null),
  (md5('question:pharmacy-exam-prep:17:5')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 5, 'A child is to be given 8mg/kg of a drug per day in 2 doses. If the child weighs 25kg, how much drug is needed per dose?', 'Daily dose = 8mg/kg x 25kg = 200mg; Per dose = 200mg / 2 = 100mg.', null),
  (md5('question:pharmacy-exam-prep:17:6')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 6, 'A 0.5% eye drop solution is prescribed. Each drop is 0.05ml. How many grams of medication is in 15 drops?', '0.5% = 0.5g/100ml; 0.05ml x 15 drops = 0.75ml; 0.5g/100ml x 0.75ml = 0.00375g.', null),
  (md5('question:pharmacy-exam-prep:17:7')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 7, 'For a 60kg patient, a drug is prescribed at 2mg/kg/day in 3 divided doses. How many mg per dose?', 'Total daily dose = 2mg/kg x 60kg = 120mg; Per dose = 120mg / 3 = 40mg.', null),
  (md5('question:pharmacy-exam-prep:17:8')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 8, 'A cream is 0.1% w/w aloe vera. How much aloe vera is in a 200g tube?', '0.1% w/w = 0.1g/100g; For 200g cream: 0.1g/100g x 200g = 0.2g.', null),
  (md5('question:pharmacy-exam-prep:17:9')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 9, 'A suspension has 200mg/5ml concentration. How many ml for a 600mg dose?', '200mg in 5ml; 600mg needs X ml; X = (600mg x 5ml) / 200mg = 15ml.', null),
  (md5('question:pharmacy-exam-prep:17:10')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 10, 'A patient is to receive 50mg of a drug every 8 hours. If each vial contains 250mg, how many vials are needed for a day?', 'Doses per day = 24 hours / 8 hours = 3 doses; Total daily dose = 50mg x 3 = 150mg; Vials needed = 150mg / 250mg/vial = 0.6 vials.', null),
  (md5('question:pharmacy-exam-prep:17:11')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 11, 'If a medication bottle contains 120ml of syrup and the dose is 10ml three times a day, how many days will the bottle last?', 'Total daily dose = 10ml x 3 = 30ml; Days = 120ml / 30ml/day = 4 days.', null),
  (md5('question:pharmacy-exam-prep:17:12')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 12, 'A patient is prescribed 250mg of a drug every 6 hours. How many mg are taken in one day?', 'Doses per day = 24 hours / 6 hours = 4 doses; Total = 250mg x 4 = 1000mg.', null),
  (md5('question:pharmacy-exam-prep:17:13')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 13, 'A cream is 1.5% w/w. How much active ingredient is in a 50g tube?', '1.5% w/w = 1.5g/100g; For 50g cream: 1.5g/100g x 50g = 0.75g.', null),
  (md5('question:pharmacy-exam-prep:17:14')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 14, 'A 500mg tablet is to be split into quarters. How much drug is in each quarter?', 'Total per tablet = 500mg; Per quarter = 500mg / 4 = 125mg.', null),
  (md5('question:pharmacy-exam-prep:17:15')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 15, 'A solution contains 20mg of medication per 2ml. How many mg are in 10ml of this solution?', '20mg in 2ml; For 10ml: 20mg/2ml x 10ml = 100mg.', null),
  (md5('question:pharmacy-exam-prep:17:16')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 16, 'How many 200mg tablets are needed for a 600mg dose?', 'Required dose = 600mg; Tablets = 600mg / 200mg/tablet = 3.', null),
  (md5('question:pharmacy-exam-prep:17:17')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 17, 'A patient needs a 2% solution. How much solute (in g) should be added to 150ml of water?', '2% solution = 2g/100ml; For 150ml: 2g/100ml x 150ml = 3g.', null),
  (md5('question:pharmacy-exam-prep:17:18')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 18, 'An antibiotic suspension contains 250mg/5ml. How many ml for a 500mg dose?', '250mg in 5ml; 500mg needs X ml; X = (500mg x 5ml) / 250mg = 10ml.', null),
  (md5('question:pharmacy-exam-prep:17:19')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 19, 'If each capsule contains 150mg of a drug and the prescription is for 450mg, how many capsules are needed per dose?', 'Required dose = 450mg; Capsules = 450mg / 150mg/capsule = 3.', null),
  (md5('question:pharmacy-exam-prep:17:20')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 20, 'A patient is prescribed a medication at a dose of 0.5mg/kg and weighs 60kg. How much medication in mg is required per dose?', 'Dose = 0.5mg/kg x 60kg = 30mg.', null),
  (md5('question:pharmacy-exam-prep:17:21')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 21, 'A patient requires a medication infusion at a rate of 0.75mg/kg/hr. The patient weighs 90kg and the medication is supplied in 250mg/5ml. Calculate the infusion rate in ml/hr.', 'Calculate the total mg/hr (0.75mg/kg/hr x 90kg = 67.5mg/hr), then convert to ml (67.5mg x (5ml/250mg)).', null),
  (md5('question:pharmacy-exam-prep:17:22')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 22, 'A cream contains 0.05% w/w of an active ingredient. How much active ingredient in grams is in a 250g tube?', 'Calculate 0.05% of 250g (0.05/100 x 250g).', null),
  (md5('question:pharmacy-exam-prep:17:23')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 23, 'For a 0.2% saline IV, how much sodium chloride is needed to add to 500ml of water?', '0.2% saline = 0.2g/100ml. For 500ml: 0.2g/100ml x 500ml.', null),
  (md5('question:pharmacy-exam-prep:17:24')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 24, 'A patient needs a 4% dextrose solution. How much dextrose powder (in grams) should be added to 1000ml of water?', '4% solution = 4g/100ml. For 1000ml: 4g/100ml x 1000ml.', null),
  (md5('question:pharmacy-exam-prep:17:25')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 25, 'If a medication is dosed at 15mg/kg and the patient weighs 60kg, how many 100mg tablets are required for one dose?', 'Calculate dose (15mg/kg x 60kg), then divide by tablet strength (900mg / 100mg/tablet).', null),
  (md5('question:pharmacy-exam-prep:17:26')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 26, 'Calculate the amount of drug in a 30ml solution with a concentration of 2mg/ml.', 'Total drug = concentration x volume (2mg/ml x 30ml).', null),
  (md5('question:pharmacy-exam-prep:17:27')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 27, 'A 250ml IV bag contains 50mg of a drug. What is the concentration in mg/ml?', 'Concentration = total drug / total volume (50mg / 250ml).', null),
  (md5('question:pharmacy-exam-prep:17:28')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 28, 'A patient needs to be administered 500mg of a drug, available in a concentration of 10mg/ml. Calculate the required volume for administration.', 'Volume = dose / concentration (500mg / 10mg/ml).', null),
  (md5('question:pharmacy-exam-prep:17:29')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 29, 'A suspension contains 150mg of medication per 5ml. How many ml are needed for a 450mg dose?', 'Volume = dose / concentration (450mg / 150mg/5ml).', null),
  (md5('question:pharmacy-exam-prep:17:30')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 30, 'A syrup contains 120mg of drug per 10ml. Calculate the dose in ml for a 180mg dose.', 'Volume = dose / concentration (180mg / 120mg/10ml).', null),
  (md5('question:pharmacy-exam-prep:17:31')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 31, 'You have a tube containing 35g of a hydrocortisone cream. The packaging states that the cream contains 52mg of hydrocortisone acetate. What is the strength of the cream in %w/w?', '%w/w = (52mg / 35,000mg) x 100 = 0.15%', null),
  (md5('question:pharmacy-exam-prep:17:32')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 32, 'Aseptically mix 50mL glucose 6%, 145mL glucose 20%, and 355mL of sodium chloride. What is the strength of glucose in %w/v of the resulting mixture?', 'Total volume = 550mL. Glucose = (50mL x 6%) + (145mL x 20%). %w/v = (Total glucose / 550mL) x 100.', null),
  (md5('question:pharmacy-exam-prep:17:33')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 33, 'Prepare 250g of an ointment with 45%w/w white soft paraffin, 35%w/w yellow soft paraffin, and 20%w/w calamine. How much yellow soft paraffin in grams is required?', '35% of 250g = 87.5g.', null),
  (md5('question:pharmacy-exam-prep:17:34')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 34, 'Prescribed 320g of an emollient containing 10%w/w calamine. Available: 18%w/w and 6%w/w calamine emollient. How many grams of the 6%w/w calamine emollient will you need?', 'Using the formula for dilution: x/(320-x) = (10%-6%)/(18%-10%), solve for x.', null),
  (md5('question:pharmacy-exam-prep:17:35')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 35, 'Prepare a 20%w/w coal tar ointment from a 7%w/w coal tar ointment. How many grams of coal tar to add to 250g of 7% ointment?', 'Using the concentration formula: (Total weight of ointment x desired concentration) - (weight of 7% ointment x 7% concentration).', null),
  (md5('question:pharmacy-exam-prep:17:36')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 36, 'A patient needs a medication at a specific dose of 0.05mg/kg every 5 hours. The patient weighs 72kg. The medication comes in a concentration of 10mg/ml. Calculate the exact volume needed per dose.', 'Dose = 0.05mg/kg x 72kg; Volume = Dose / Concentration.', null),
  (md5('question:pharmacy-exam-prep:17:37')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 37, 'An IV infusion requires a drug concentration of 0.2mg/ml at a rate of 5ml/hr. The drug is supplied in vials of 100mg/2ml. How many vials are needed for 24 hours?', 'Daily requirement = 5ml/hr x 24hrs; Total drug needed = Concentration x Volume; Vials = Total drug / Vial concentration.', null),
  (md5('question:pharmacy-exam-prep:17:38')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 38, 'A topical cream is 1.25% w/w. A patient is prescribed a thin layer covering 200cm² skin, assuming 2mg/cm². Calculate the weight of cream needed.', 'Area x Application rate; Convert % w/w to mg/g to find weight.', null),
  (md5('question:pharmacy-exam-prep:17:39')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 39, 'Compound a 500ml solution with a final concentration of 2mg/ml using a stock solution of 10mg/ml and a diluent. Calculate the volume of stock solution and diluent needed.', 'V1C1 = V2C2 for stock solution; Subtract from total for diluent.', null),
  (md5('question:pharmacy-exam-prep:17:40')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 40, 'A pediatric patient requires 15mg/kg/day of a medication divided into three equal doses. The child weighs 20kg. The medicine is available in a 10mg/ml suspension. Calculate the volume per dose.', 'Total daily dose = Weight x Dosage; Volume per dose = Total daily dose / 3 / Concentration.', null),
  (md5('question:pharmacy-exam-prep:17:41')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 41, 'A medication''s half-life is 8 hours. A patient receives an initial dose of 100mg. How much of the drug remains in the body after 24 hours?', 'Half-life calculation: 100mg → 50mg (8 hrs) → 25mg (16 hrs) → 12.5mg (24 hrs).', null),
  (md5('question:pharmacy-exam-prep:17:42')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 42, 'Prepare 200ml of a 5% solution using two solutions of 10% and 2% strengths. Calculate the volume of each solution required.', 'Using Alligation method: (5-2)/(10-5) = Volume of 10% solution / Total Volume.', null),
  (md5('question:pharmacy-exam-prep:17:43')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 43, 'A patient requires a continuous IV drip of 0.4mg/kg/hr of Drug Y. The patient weighs 55kg, and the drug is available in 250mg/5ml. Determine the infusion rate in ml/hr.', 'Dose = 0.4mg/kg/hr x 55kg; Infusion rate = Dose / Concentration.', null),
  (md5('question:pharmacy-exam-prep:17:44')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 44, 'Convert a 3% w/v solution to mg/ml. Then, determine how many ml are needed for a 450mg dose.', '3% w/v = 30mg/ml; Volume for dose = Dose / Concentration.', null),
  (md5('question:pharmacy-exam-prep:17:45')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 45, 'A solution contains 250mg of medication in 100ml. A dose of 50mg/kg/day is prescribed for a child weighing 18kg, divided into 4 doses. Calculate the volume for each dose.', 'Daily dose = Dose x Weight; Volume per dose = Daily dose / 4 / Concentration.', null),
  (md5('question:pharmacy-exam-prep:17:46')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 46, 'Calculate the volume of 0.9% saline solution needed to dilute 10ml of a 50% dextrose solution to a 5% concentration.', 'Using dilution formula C1V1 = C2V2; 50% x 10ml = 5% x V2. Solve for V2.', null),
  (md5('question:pharmacy-exam-prep:17:47')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 47, 'A patient requires an infusion at 2mg/min. The drug is supplied as 500mg in 250ml. Calculate the infusion rate in ml/hr.', 'Infusion rate = (2mg/min x 60min/hr) / (500mg/250ml).', null),
  (md5('question:pharmacy-exam-prep:17:48')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 48, 'Prepare a 200ml solution of 0.2% w/v from a stock solution of 1% w/v. How much stock solution and water are needed?', 'Use C1V1 = C2V2; 1% x V1 = 0.2% x 200ml. Solve for V1.', null),
  (md5('question:pharmacy-exam-prep:17:49')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 49, 'A drug''s elimination half-life is 4 hours. How much of a 400mg dose remains after 12 hours?', 'Half-life calculations: 400mg → 200mg (4 hrs) → 100mg (8 hrs) → 50mg (12 hrs).', null),
  (md5('question:pharmacy-exam-prep:17:50')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 50, 'A 70kg patient requires a 0.03mg/kg dose of a medication. The medication is available in 2mg/ml. Calculate the volume needed.', 'Dose = 0.03mg/kg x 70kg; Volume = Dose / Concentration.', null),
  (md5('question:pharmacy-exam-prep:17:51')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 51, 'A solution contains 120mg of drug per 10ml. If a patient requires a 360mg dose, how many ml are needed?', 'Volume = Dose / Concentration; 360mg / (120mg/10ml).', null),
  (md5('question:pharmacy-exam-prep:17:52')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 52, 'An ointment is 2.5% w/w. Calculate the amount of active ingredient in a 150g tube.', '2.5% of 150g = 2.5/100 x 150g.', null),
  (md5('question:pharmacy-exam-prep:17:53')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 53, 'A medication is administered at a rate of 5mcg/kg/min for a 60kg patient. The medication is supplied as 10mg in 100ml. Calculate the infusion rate in ml/hr.', 'Infusion rate = (5mcg/kg/min x 60kg x 60min/hr) / (10mg/100ml).', null),
  (md5('question:pharmacy-exam-prep:17:54')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 54, 'A patient needs a 1.5% solution. How much solute is needed to make 500ml of solution?', '1.5% = 1.5g/100ml; For 500ml: 1.5g/100ml x 500ml.', null),
  (md5('question:pharmacy-exam-prep:17:55')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 55, 'A 500ml IV bag contains 250mg of a drug. A dose of 50mg/hr is required. Calculate the infusion rate in ml/hr.', 'Infusion rate = Dose / Concentration; 50mg/hr / (250mg/500ml).', null),
  (md5('question:pharmacy-exam-prep:17:56')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 56, 'A prescription calls for 15% of Drug A and 85% of Drug B to make a 100g ointment. How much of each drug is needed?', '15% of 100g for Drug A and 85% of 100g for Drug B.', null),
  (md5('question:pharmacy-exam-prep:17:57')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 57, 'A 0.25% hydrocortisone cream is prescribed. How many grams of hydrocortisone are in a 30g tube?', '0.25% of 30g = 0.25/100 x 30g.', null),
  (md5('question:pharmacy-exam-prep:17:58')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 58, 'If 500ml of a 10% solution is diluted to make a 2% solution, what is the final volume?', 'Use C1V1 = C2V2; 10% x 500ml = 2% x V2. Solve for V2.', null),
  (md5('question:pharmacy-exam-prep:17:59')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 59, 'A patient is prescribed a medication at 1mg/kg/day in two divided doses. If the patient weighs 50kg, how much medication is needed for each dose?', 'Total daily dose = 1mg/kg x 50kg; Each dose = Total dose / 2.', null),
  (md5('question:pharmacy-exam-prep:17:60')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 60, 'How many ml of a 4% solution can be made from 200ml of a 10% solution?', 'Use dilution formula C1V1 = C2V2; 10% x 200ml = 4% x V2. Solve for V2.', null),
  (md5('question:pharmacy-exam-prep:17:61')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 61, 'Calculate the volume of medication needed for a dose of 0.2mg/kg in a patient weighing 80kg from a solution of 50mg/ml.', 'Dose = 0.2mg/kg x 80kg; Volume = Dose / Concentration.', null),
  (md5('question:pharmacy-exam-prep:17:62')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 62, 'An IV contains 500mg of a drug in 250ml. What is the concentration in mg/ml?', 'Concentration = Total drug / Total volume.', null),
  (md5('question:pharmacy-exam-prep:17:63')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 63, 'A cream is 0.3% w/w lidocaine. How much lidocaine is there in a 45g tube?', '0.3% of 45g = 0.3/100 x 45g.', null),
  (md5('question:pharmacy-exam-prep:17:64')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 64, 'A patient is to receive 3mg/kg of Drug X. The patient weighs 60kg. The drug is available in 15mg/ml concentration. Calculate the required volume.', 'Dose = 3mg/kg x 60kg; Volume = Dose / Concentration.', null),
  (md5('question:pharmacy-exam-prep:17:65')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 65, 'If a 0.5g of a drug is to be administered over a 4-hour period and the drug comes in 250mg/5ml, calculate the infusion rate in ml/hr.', 'Total volume = 0.5g / (250mg/5ml); Infusion rate = Total volume / 4 hours.', null),
  (md5('question:pharmacy-exam-prep:17:66')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 66, 'If the displacement volume of Ceftriaxone is 0.18ml per 250mg, what is the final volume after reconstituting a 1g dose with 10ml of diluent?', '1g = 4 x 250mg, so displacement = 4 x 0.18ml = 0.72ml. Total volume = 10ml + 0.72ml.', null),
  (md5('question:pharmacy-exam-prep:17:67')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 67, 'A vial of Penicillin contains 500mg and has a displacement volume of 0.21ml/500mg. How much diluent should be added for reconstitution to achieve a final volume of 10ml?', 'Subtract the displacement volume from the desired final volume: 10ml - 0.21ml.', null),
  (md5('question:pharmacy-exam-prep:17:68')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 68, 'Calculate the final volume when 30ml of water is added to reconstitute a powder with a displacement volume of 0.4ml/g for a 1g dose.', 'Displacement volume for 1g = 0.4ml. Total volume = 30ml + 0.4ml.', null),
  (md5('question:pharmacy-exam-prep:17:69')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 69, 'A medication with a displacement value of 0.15ml/100mg is reconstituted with 5ml of water. What is the final volume for a 200mg dose?', 'Displacement volume = 0.15ml/100mg x 200mg = 0.3ml. Total volume = 5ml + 0.3ml.', null),
  (md5('question:pharmacy-exam-prep:17:70')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 70, 'When reconstituting a 750mg dose of a drug with a displacement volume of 0.25ml/250mg, how much diluent is needed to achieve a final volume of 15ml?', 'Displacement volume for 750mg = 3 x 0.25ml = 0.75ml. Required diluent = 15ml - 0.75ml.', null),
  (md5('question:pharmacy-exam-prep:17:71')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 71, 'A 2g vial of a drug has a displacement volume of 0.5ml/g. Calculate the final volume after adding 20ml of diluent.', 'Displacement volume for 2g = 2 x 0.5ml = 1ml. Total volume = 20ml + 1ml.', null),
  (md5('question:pharmacy-exam-prep:17:72')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 72, 'If a 400mg vial of medication has a displacement volume of 0.2ml/100mg, what will be the final volume after adding 8ml of diluent?', 'Displacement volume for 400mg = 4 x 0.2ml = 0.8ml. Total volume = 8ml + 0.8ml.', null),
  (md5('question:pharmacy-exam-prep:17:73')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 73, 'For a 1.5g dose of a drug with a displacement volume of 0.3ml/500mg, how much diluent should be added to achieve a final volume of 12ml?', 'Displacement volume for 1.5g = 3 x 0.3ml = 0.9ml. Required diluent = 12ml - 0.9ml.', null),
  (md5('question:pharmacy-exam-prep:17:74')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 74, 'Calculate the final volume after adding 6ml of water to reconstitute a 500mg dose of a drug with a displacement volume of 0.12ml/250mg.', 'Displacement volume for 500mg = 2 x 0.12ml = 0.24ml. Total volume = 6ml + 0.24ml.', null),
  (md5('question:pharmacy-exam-prep:17:75')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 75, 'A drug has a displacement volume of 0.2ml/100mg and is available in a 250mg vial. If 5ml of diluent is added, what is the final volume?', 'Displacement volume for 250mg = 2.5 x 0.2ml = 0.5ml. Total volume = 5ml + 0.5ml.', null),
  (md5('question:pharmacy-exam-prep:17:76')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 76, 'A 600mg dose of a drug has a displacement volume of 0.2ml/100mg. How much diluent is needed for a final volume of 10ml?', 'Displacement volume for 600mg = 6 x 0.2ml = 1.2ml. Required diluent = 10ml - 1.2ml.', null),
  (md5('question:pharmacy-exam-prep:17:77')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 77, 'Calculate the final volume when adding 7ml of diluent to a 300mg vial of medication with a displacement volume of 0.15ml/100mg.', 'Displacement volume for 300mg = 3 x 0.15ml = 0.45ml. Total volume = 7ml + 0.45ml.', null),
  (md5('question:pharmacy-exam-prep:17:78')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 78, 'If a 1g vial of a drug has a displacement volume of 0.3ml/500mg, how much diluent is needed for a final volume of 15ml?', 'Displacement volume for 1g = 2 x 0.3ml = 0.6ml. Required diluent = 15ml - 0.6ml.', null),
  (md5('question:pharmacy-exam-prep:17:79')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 79, 'A drug with a displacement volume of 0.25ml/g is reconstituted with 12ml of water for a 750mg dose. What is the final volume?', 'Displacement volume for 750mg = 0.75g x 0.25ml/g. Total volume = 12ml + displacement volume.', null),
  (md5('question:pharmacy-exam-prep:17:80')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 80, 'Calculate the volume of diluent to add to a 400mg vial of medication with a displacement volume of 0.1ml/100mg for a 5ml final volume.', 'Displacement volume for 400mg = 4 x 0.1ml. Required diluent = 5ml - displacement volume.', null),
  (md5('question:pharmacy-exam-prep:17:81')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 81, 'A patient needs a drug reconstituted from a 2g vial with a displacement volume of 0.4ml/500mg. How much diluent for a final volume of 20ml?', 'Displacement volume for 2g = 4 x 0.4ml. Required diluent = 20ml - displacement volume.', null),
  (md5('question:pharmacy-exam-prep:17:82')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 82, 'For a 500mg dose of a drug with a displacement volume of 0.2ml/250mg, calculate the final volume after adding 8ml of diluent.', 'Displacement volume for 500mg = 2 x 0.2ml. Total volume = 8ml + displacement volume.', null),
  (md5('question:pharmacy-exam-prep:17:83')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 83, 'A vial containing 1.5g of medication has a displacement volume of 0.5ml/750mg. How much diluent is needed for a final volume of 25ml?', 'Displacement volume for 1.5g = 0.5ml. Required diluent = 25ml - displacement volume.', null),
  (md5('question:pharmacy-exam-prep:17:84')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 84, 'What is the final volume after adding 6ml of water to a 250mg vial of medication with a displacement volume of 0.3ml/500mg?', 'Displacement volume for 250mg = 0.15ml. Total volume = 6ml + displacement volume.', null),
  (md5('question:pharmacy-exam-prep:17:85')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 85, 'If a 3g vial of a drug has a displacement volume of 0.2ml/500mg, calculate the final volume after adding 30ml of diluent.', 'Displacement volume for 3g = 6 x 0.2ml. Total volume = 30ml + displacement volume.', null),
  (md5('question:pharmacy-exam-prep:17:86')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 86, 'Calculate the bioavailability of a drug given orally at 500mg, resulting in a systemic circulation concentration of 200mg.', 'Bioavailability = Amount in systemic circulation / Dose = 200mg / 500mg.', null),
  (md5('question:pharmacy-exam-prep:17:87')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 87, 'A drug with a half-life of 4 hours is administered. How much of the drug remains after 12 hours?', 'After each half-life, the drug amount halves; after 3 half-lives (12 hours), 12.5% remains.', null),
  (md5('question:pharmacy-exam-prep:17:88')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 88, 'Determine the volume of distribution for a drug administered at 200mg, achieving a plasma concentration of 2mg/L.', 'Vd = Dose / Plasma concentration = 200mg / 2mg/L.', null),
  (md5('question:pharmacy-exam-prep:17:89')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 89, 'Calculate the clearance rate if 500mg of a drug results in a steady-state concentration of 5mg/L, given over 4 hours.', 'Clearance = Dose / (Concentration x Time) = 500mg / (5mg/L x 4hr).', null),
  (md5('question:pharmacy-exam-prep:17:90')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 90, 'If a drug is 80% protein-bound and the total concentration is 50mg/L, what is the free drug concentration?', 'Free drug = Total drug x (1 - Protein binding) = 50mg/L x 20%.', null),
  (md5('question:pharmacy-exam-prep:17:91')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 91, 'Calculate the loading dose required to achieve a target concentration of 5mg/L for a drug with a Vd of 0.7 L/kg for a 70kg patient.', 'Loading Dose = Vd x Target concentration x Weight.', null),
  (md5('question:pharmacy-exam-prep:17:92')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 92, 'A patient requires a maintenance dose of a drug with a clearance of 0.1 L/hr/kg and a target concentration of 4mg/L. If the patient weighs 60kg, calculate the dose.', 'Maintenance Dose = Clearance x Target concentration x Weight.', null),
  (md5('question:pharmacy-exam-prep:17:93')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 93, 'Find the elimination rate constant for a drug with a half-life of 6 hours.', 'k = 0.693 / t1/2.', null),
  (md5('question:pharmacy-exam-prep:17:94')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 94, 'Determine the time required for a drug concentration to drop from 100mg/L to 25mg/L, given a half-life of 8 hours.', 'Number of half-lives to reduce from 100mg/L to 25mg/L = 2; Total time = 2 x 8 hours.', null),
  (md5('question:pharmacy-exam-prep:17:95')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 95, 'Calculate the peak plasma concentration after administering a 300mg dose of a drug intravenously with a bioavailability of 1 and a Vd of 50L.', 'Concentration = Dose / Vd = 300mg / 50L.', null),
  (md5('question:pharmacy-exam-prep:17:96')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 96, 'Calculate the half-life of a drug with an elimination rate constant (k) of 0.138 hr⁻¹.', 't1/2 = 0.693 / k.', null),
  (md5('question:pharmacy-exam-prep:17:97')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 97, 'If a patient is administered a drug intravenously with a bioavailability of 0.8 and a Vd of 40L, calculate the peak plasma concentration after a 500mg dose.', 'C = Dose / (Vd x bioavailability) = 500mg / (40L x 0.8).', null),
  (md5('question:pharmacy-exam-prep:17:98')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 98, 'Determine the loading dose for a drug with a Vd of 0.6 L/kg for a 70kg patient to achieve a target concentration of 8mg/L.', 'LD = Vd x Target concentration x Weight.', null),
  (md5('question:pharmacy-exam-prep:17:99')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 99, 'Calculate the steady-state concentration of a drug administered at 20mg/hr with a clearance of 0.05 L/hr/kg for an 80kg patient.', 'Css = Dose rate / (Clearance x Weight).', null),
  (md5('question:pharmacy-exam-prep:17:100')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 100, 'A drug is 90% protein-bound and has a total concentration of 60mg/L. Find the free drug concentration.', 'Free drug = Total drug x (1 - Protein binding) = 60mg/L x 10%.', null),
  (md5('question:pharmacy-exam-prep:17:101')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 101, 'For a drug with a half-life of 3 hours, calculate the amount remaining after 9 hours from an initial dose of 200mg.', 'Remaining amount reduces by half every 3 hours; after 9 hours, it''s 1/8th.', null),
  (md5('question:pharmacy-exam-prep:17:102')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 102, 'If 250ml of a 4% solution is diluted to make a 0.5% solution, what is the final volume?', 'Use C1V1 = C2V2; 4% x 250ml = 0.5% x V2.', null),
  (md5('question:pharmacy-exam-prep:17:103')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 103, 'Calculate the volume of distribution for a drug administered at 300mg, achieving a plasma concentration of 3mg/L.', 'Vd = Dose / Plasma concentration.', null),
  (md5('question:pharmacy-exam-prep:17:104')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 104, 'Determine the clearance rate if 400mg of a drug results in a steady-state concentration of 4mg/L, given over 6 hours.', 'Clearance = Dose / (Concentration x Time).', null),
  (md5('question:pharmacy-exam-prep:17:105')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 105, 'Calculate the bioavailability of a drug given orally at 600mg, resulting in a systemic circulation concentration of 180mg.', 'Bioavailability = Amount in systemic circulation / Dose.', null),
  (md5('question:pharmacy-exam-prep:17:106')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 106, 'Determine the elimination rate constant for a drug with a half-life of 3 hours.', 'k = 0.693 / t1/2.', null),
  (md5('question:pharmacy-exam-prep:17:107')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 107, 'Calculate the bioavailability of an oral drug given at 400mg with 160mg reaching systemic circulation.', 'Bioavailability = Systemic circulation / Dose.', null),
  (md5('question:pharmacy-exam-prep:17:108')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 108, 'For a drug with a Vd of 0.8 L/kg, calculate the volume of distribution for a 60kg patient.', 'Vd = 0.8 L/kg x 60kg.', null),
  (md5('question:pharmacy-exam-prep:17:109')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 109, 'If a drug''s plasma concentration decreases from 120mg/L to 30mg/L in 8 hours, what is its half-life?', 'Use the half-life formula based on concentration reduction.', null),
  (md5('question:pharmacy-exam-prep:17:110')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 110, 'Find the loading dose needed to achieve a target plasma concentration of 6mg/L for a drug with a Vd of 0.5 L/kg in a 70kg patient.', 'LD = Vd x Target concentration x Weight.', null),
  (md5('question:pharmacy-exam-prep:17:111')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 111, 'Calculate the maintenance dose rate for a drug with a clearance of 0.04 L/hr/kg and a target concentration of 5mg/L in an 80kg patient.', 'MD = Clearance x Target concentration x Weight.', null),
  (md5('question:pharmacy-exam-prep:17:112')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 112, 'If 30% of a drug is protein-bound and its total plasma concentration is 50mg/L, determine the free drug concentration.', 'Free drug = Total concentration x (1 - Protein binding).', null),
  (md5('question:pharmacy-exam-prep:17:113')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 113, 'A 200mg dose of a drug is administered, resulting in a steady-state concentration of 2mg/L. Calculate its volume of distribution.', 'Vd = Dose / Steady-state concentration.', null),
  (md5('question:pharmacy-exam-prep:17:114')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 114, 'Determine the time for a drug concentration to reduce from 100mg/L to 12.5mg/L, given a half-life of 6 hours.', 'Use half-life formula; concentration is reduced to 1/8th in three half-lives.', null),
  (md5('question:pharmacy-exam-prep:17:115')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 115, 'Calculate the clearance for a drug given at a rate of 50mg/hr, reaching a steady-state concentration of 10mg/L.', 'Clearance = Dose rate / Steady-state concentration.', null),
  (md5('question:pharmacy-exam-prep:17:116')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 116, 'If a drug''s half-life is 6 hours and a patient receives a 300mg dose, how much remains after 24 hours?', '300mg → 150mg (6 hrs) → 75mg (12 hrs) → 37.5mg (18 hrs) → 18.75mg (24 hrs).', null),
  (md5('question:pharmacy-exam-prep:17:117')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 117, 'Calculate the steady-state concentration for a drug given at 10mg/hr with a clearance of 0.2 L/hr/kg in a 70kg patient.', 'Css = Dose rate / (Clearance x Weight) = 10mg/hr / (0.2 L/hr/kg x 70kg).', null),
  (md5('question:pharmacy-exam-prep:17:118')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 118, 'Determine the volume of distribution for a drug given at 250mg, achieving a plasma concentration of 10mg/L.', 'Vd = Dose / Plasma concentration = 250mg / 10mg/L.', null),
  (md5('question:pharmacy-exam-prep:17:119')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 119, 'A drug with a bioavailability of 0.5 is given orally at 400mg. Calculate the amount reaching systemic circulation.', 'Systemic circulation = Dose x Bioavailability = 400mg x 0.5.', null),
  (md5('question:pharmacy-exam-prep:17:120')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 120, 'For a drug with a Vd of 0.7 L/kg, calculate the loading dose to achieve a target concentration of 15mg/L in a 60kg patient.', 'LD = Vd x Target concentration x Weight = 0.7 L/kg x 15mg/L x 60kg.', null),
  (md5('question:pharmacy-exam-prep:17:121')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 121, 'If 40% of a drug is protein-bound and its total concentration is 80mg/L, find the free concentration.', 'Free concentration = Total concentration x (1 - Protein binding) = 80mg/L x 60%.', null),
  (md5('question:pharmacy-exam-prep:17:122')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 122, 'Calculate the elimination rate constant for a drug with a half-life of 4 hours.', 'k = 0.693 / t1/2 = 0.693 / 4 hr.', null),
  (md5('question:pharmacy-exam-prep:17:123')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 123, 'Determine the maintenance dose for a drug with a clearance of 0.1 L/hr/kg, a target concentration of 4mg/L, and a patient weight of 50kg.', 'MD = Clearance x Target concentration x Weight = 0.1 L/hr/kg x 4mg/L x 50kg.', null),
  (md5('question:pharmacy-exam-prep:17:124')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 124, 'Calculate the time to reach a drug concentration of 5mg/L from 40mg/L, given a half-life of 2 hours.', 'Concentration halves every 2 hours; from 40mg/L to 5mg/L takes three half-lives (6 hours).', null),
  (md5('question:pharmacy-exam-prep:17:125')::uuid, md5('quiz:pharmacy-exam-prep:17')::uuid, 125, 'Find the volume of distribution for a 500mg dose of a drug resulting in a plasma concentration of 5mg/L.', 'Vd = Dose / Plasma concentration = 500mg / 5mg/L.', null)
